window.__D("text/zohar-hebrew-translation/c036",{"p":[[9522012586,"<p>שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, זֶהוּ יִחוּד אֶחָד. בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, זֶהוּ יִחוּד אַחֵר, לִהְיוֹת שְׁמוֹ סוֹד אֶחָד. וְסוֹד זֶה – ה' הוּא הָאֱלֹהִים, זֶה כָּתוּב כְּשֶׁהֵם בְּיִחוּד אֶחָד.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ כְּמוֹ שֶׁכָּתוּב <Nonesmall>[זכריה יד]</small> ה' אֶחָד וּשְׁמוֹ אֶחָד, לֹא הִיא ה' הוּא הָאֱלֹהִים. שֶׁאִם כָּתוּב ה' וּשְׁמוֹ הוּא אֶחָד, הָיִיתִי אוֹמֵר כָּךְ. לֹא כָתוּב אֶלָּא ה' אֶחָד וּשְׁמוֹ אֶחָד, וְצָרִיךְ לוֹמַר בְּגָוֶן זֶה, ה' הוּא הָאֱלֹהִים הוּא, וְיֵרָאֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>אֶלָּא הַכֹּל אֶחָד. שֶׁכְּשֶׁמִּתְאַחֲדִים שְׁנֵי הַשֵּׁמוֹת הַלָּלוּ, זֶה בְּיִחוּד זֶה, וְזֶה בְּיִחוּד אֶחָד, אָז שְׁנֵי הַשֵּׁמוֹת הָאֵלֶּה נַעֲשִׂים אֶחָד וְנִכְלָלִים זֶה בָּזֶה, וְנִהְיָה הַכֹּל שֵׁם שָׁלֵם בְּיִחוּד אֶחָד, וְאָז ה' הוּא הָאֱלֹהִים, שֶׁהֲרֵי אָז נִכְלָל הַכֹּל זֶה בָּזֶה לִהְיוֹת אֶחָד, וְעַד שֶׁהִתְיַחֲדוּ כָּל אֶחָד, זֶה בִּלְבַדּוֹ וְזֶה בִּלְבַדּוֹ, לֹא נִכְלְלוּ זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>כְּלַל כָּל הַתּוֹרָה כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי הַתּוֹרָה הִיא תּוֹרָה שֶׁבִּכְתָב, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָב זֶהוּ שֶׁכָּתוּב ה'. תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁכָּתוּב הָאֱלֹהִים. וּמִשּׁוּם שֶׁהַתּוֹרָה הִיא סוֹד הַשֵּׁם הַקָּדוֹשׁ, נִקְרֵאת כָּךְ.</p>\n<p>תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, זֶה כְּלָל וְזֶה פְּרָט. הַכְּלָל צָרִיךְ אֶת הַפְּרָט, וְהַפְּרָט צָרִיךְ אֶת הַכְּלָל, וְהִתְיַחֲדוּ זֶה בָּזֶה וְנִהְיָה הַכֹּל אֶחָד. וְעַל זֶה כְּלַל הַתּוֹרָה הוּא כְּלָל שֶׁלְּמַעְלָה וּמַטָּה, מִשּׁוּם שֶׁשֵּׁם זֶה לְמַעְלָה, וְשֵׁם זֶה לְמַטָּה. זֶה סוֹד הָעוֹלָם הָעֶלְיוֹן, וְזֶה סוֹד הָעוֹלָם הַתַּחְתּוֹן. וְעַל זֶה כָּתוּב אַתָּה הָרְאֵתָ לָדַעַת כִּי ה' הוּא הָאֱלֹהִים. זֶה הַכְּלָל שֶׁל הַכֹּל. וְכָל זֶה שֶׁאָמַרְנוּ צָרִיךְ אָדָם לָדַעַת בָּעוֹלָם הַזֶּה.</p>\n<p>וְאִם תֹּאמַר, מִצְווֹת הַתּוֹרָה אֵיפֹה הֵן כָּאן בַּכְּלָל הַזֶּה? אֶלָּא זֶהוּ זָכוֹר וְזֶהוּ שָׁמוֹר. וְכָל מִצְווֹת הַתּוֹרָה בְּאֵלֶּה כְּלוּלִים, בְּסוֹד שֶׁל זָכוֹר וּבְסוֹד שֶׁל שָׁמוֹר, וְהַכֹּל הוּא אֶחָד.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, זֶה שֶׁשָּׁנִינוּ שֶׁתְּפִלַּת עַרְבִית הִיא חוֹבָה, וַדַּאי מִשּׁוּם שֶׁקְּרִיאַת שְׁמַע שֶׁל עַרְבִית חוֹבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְיַחֵד בַּלַּיְלָה כְּמוֹ שֶׁמִּתְיַחֵד בַּיּוֹם. וּמִדַּת לַיְלָה נִכְלֶלֶת בַּיּוֹם, וּמִדַּת יוֹם נִכְלֶלֶת בַּלַּיְלָה, וְנַעֲשֶׂה יִחוּד. וּמִי שֶׁאָמַר רְשׁוּת, מִשּׁוּם אֵמוּרִים וּפְדָרִים שֶׁמִּתְעַכְּלִים בַּלַּיְלָה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>שֶׁכָּתוּב וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. פָּסוּק זֶה בֵּאַרְנוּ, וּפֵרְשׁוּהוּ הַחֲבֵרִים. אֲבָל יֵשׁ לִשְׁאֹל, אִם בַּיִּחוּד הַזֶּה שֶׁל שְׁמַע יִשְׂרָאֵל נִכְלָל הַכֹּל, יָמִין וּשְׂמֹאל, לָמָּה כָּתוּב אַחַר כָּךְ וְאָהַבְתָּ, וְהָיָה אִם שָׁמוֹעַ, שֶׁהֲרֵי בַּיִּחוּד נִכְלְלוּ? אֶלָּא שָׁם בִּכְלָל, כָּאן בִּפְרָט, וְכָךְ צָרִיךְ.</p>\n<p>וּבְסוֹד הַיִּחוּד שֶׁהֲרֵי הִתְעוֹרַרְנוּ בוֹ, יִחוּד הוּא כְּמוֹ תְפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ. בִּתְפִלִּין שֶׁל רֹאשׁ יֵשׁ אַרְבַּע פָּרָשִׁיּוֹת, וַהֲרֵי נִתְבָּאֵר. וְכָאן שְׁלֹשָׁה שֵׁמוֹת הֵם. שָׁם אַרְבַּע פָּרָשִׁיּוֹת, וְכָל אַחַת וְאַחַת בִּלְבַדָּהּ. וְכָאן שָׁלֹשׁ שֵׁמוֹת. מַה בֵּין זֶה לָזֶה?</p>"],[9522012587,"<p>אֶלָּא בְּאוֹתָן אַרְבַּע פָּרָשִׁיּוֹת הֲרֵי הִתְעוֹרְרוּ בָהֶן, אַחַת נְקֻדָּה <Nonesmall>[עליונה]</small> רִאשׁוֹנָה, וְאַחַת סוֹד הָעוֹלָם הַבָּא, וְאַחַת יָמִין, וְאַחַת שְׂמֹאל. אֵלֶּה סוֹד תְּפִלִּין שֶׁל רֹאשׁ. וְכָאן בְּסוֹד זֶה, יִחוּד זֶה שְׁלֹשָׁה שֵׁמוֹת עֶלְיוֹנִים הֵם כְּמוֹ אוֹתָן אַרְבַּע פָּרָשִׁיּוֹת. ה' הָרִאשׁוֹן זוֹ נְקֻדָּה עֶלְיוֹנָה, רֵאשִׁית הַכֹּל. אֱלֹהֵינוּ, סוֹד הָעוֹלָם הַבָּא. ה' הָאַחֲרוֹן, כְּלָל שֶׁל יָמִין וּשְׂמֹאל כְּאֶחָד, בִּכְלָל אֶחָד, וְאֵלֶּה הֵם תְּפִלָּה שֶׁל רֹאשׁ, וְזֶהוּ יִחוּד רִאשׁוֹן.</p>\n<p>תְּפִלִּין שֶׁל זְרוֹעַ כְּלָל <Nonesmall>[תוך תפלין של זרוע]</small> שֶׁל כָּל הָאֵלֶּה כְאֶחָד, וְזֶהוּ סוֹד בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּאן כְּלָל שֶׁל אוֹתָן תְּפִלִּין שֶׁל רֹאשׁ שֶׁנִּכְלְלוּ בְתוֹךְ תְּפִלִּין שֶׁל זְרוֹעַ.</p>\n<p>וְסוֹד זֶה, בָּרוּךְ – זֶה סוֹד שֶׁל נְקֻדָּה עֶלְיוֹנָה, שֶׁהוּא בָּרוּךְ, שֶׁכָּל הַבְּרָכוֹת נוֹבְעוֹת מִשָּׁם. וְאִם תֹּאמַר, הָעוֹלָם הַבָּא נִקְרָא בָּרוּךְ – לֹא כָּךְ, שֶׁהֲרֵי נְקֻדָּה עֶלְיוֹנָה הִיא זָכָר, עוֹלָם הַבָּא נְקֵבָה. הוּא בָּרוּךְ וְהִיא בְּרָכָה. בָּרוּךְ זָכָר, בְּרָכָה נְקֵבָה. וְעַל זֶה בָּרוּךְ הוּא נְקֻדָּה עֶלְיוֹנָה. שֵׁם – זֶה הָעוֹלָם הַבָּא, שֶׁהוּא שֵׁם גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[יהושע ז]</small> וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. כְּבוֹד – זֶה כָּבוֹד עֶלְיוֹן, שֶׁהוּא יָמִין וּשְׂמֹאל, וְכֻלָּם כְלוּלִים בִּתְפִלָּה זוֹ שֶׁל יָד, שֶׁהִיא מַלְכוּתוֹ. וְלוֹקֵחַ הַכֹּל לְתוֹכָהּ, וּבָזֶה נִכְלָלִים בַּמַּלְכוּת הַזֹּאת כָּל הָעוֹלָמוֹת לָזוּן אוֹתָם וּלְהַנּוֹת אוֹתָם בְּמַה שֶּׁהִצְטָרְכוּ.</p>\n<p>וְזְהִוּ יִחוּד שֶׁל תְּפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ, כְּמוֹ סוֹד הַיִּחוּד שֶׁל תְּפִלִּין, כָּךְ הוּא יִחוּד הַכֹּל, וְזֶהוּ בֵּרוּר הַדָּבָר. וַהֲרֵי סִדַּרְנוּ יִחוּד זֶה לִפְנֵי הַמְּנוֹרָה הַקְּדוֹשָׁה, וְאָמַר לִי שֶׁהֲרֵי בְּאַרְבָּעָה גְוָנִים הִסְתַּדֵּר הַיִּחוּד, וְזֶה הַבֵּרוּר שֶׁל כֻּלָּם. וְכָךְ הוּא בְּוַדַּאי, וְכֻלָּם סוֹד הַיִּחוּד. אֲבָל סִדּוּר הַתְּפִלִּין זֶהוּ יִחוּד עֶלְיוֹן כָּרָאוּי.</p>\n<p>וּמִתּוֹךְ שֶׁנִּכְלְלוּ יָמִין וּשְׂמֹאל בְּסוֹד שֶׁל שֵׁם אֶחָד בְּדֶרֶךְ כְּלָל, צָרִיךְ אַחַר כָּךְ לְהוֹצִיא אוֹתָם בְּדֶרֶךְ פְּרָט, אֲבָל לֹא בְּדֶרֶךְ יִחוּד, שֶׁהֲרֵי הַיִּחוּד הוּא בַּפְּסוּקִים הָרִאשׁוֹנִים, לִהְיוֹת ה' אֶחָד, בִּתְפִלִּין שֶׁל רֹאשׁ. וּשְׁמוֹ אֶחָד, בִּתְפִלִּין שֶׁל זְרוֹעַ. וְנִהְיָה הַכֹּל אֶחָד. כֵּיוָן שֶׁהַיִּחוּד הִסְתַּדֵּר הַכֹּל בִּכְלָל מֵרֹאשׁ הַנְּקֻדָּה הָעֶלְיוֹנָה, צָרִיךְ אַחַר כָּךְ לְהִתְעַטֵּר מֵהָרֹאשׁ שֶׁל הָאוֹר הָרִאשׁוֹן, שֶׁהוּא רֹאשׁ הַכֹּל. <Nonesmall>[ע\"כ רעיא מהימנא]</small>.</p>\n<p>חָקַק וְהִתְקִין מֹשֶׁה כ\"ה אוֹתִיּוֹת בְּסוֹד שֶׁל הַפָּסוּק שֶׁל הַיִּחוּד, שֶׁכָּתוּב שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וְהֵן כ\"ה אוֹתִיּוֹת חֲקוּקוֹת מְחֻקָּקוֹת בְּסוֹד שֶׁלְּמַעְלָה. יַעֲקֹב רָצָה לְהַתְקִין לְמַטָּה בְּסוֹד הַיִּחוּד, וְהִתְקִין בְּכ\"ד אוֹתִיּוֹת, וְהֵן: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְלֹא הִשְׁלִים לְכ\"ה אוֹתִיּוֹת, מִשּׁוּם שֶׁעֲדַיִן לֹא הִתְתַּקֵּן הַמִּשְׁכָּן. כֵּיוָן שֶׁנִּתְתַּקֵּן הַמִּשְׁכָּן וְהִשְׁתַּלֵּם דָּבָר שֶׁהָיָה יוֹצֵא מִמֶּנּוּ, כְּשֶׁהִשְׁתַּלֵּם לֹא דִבֵּר אֶלָּא בְּכ\"ה אוֹתִיּוֹת, לְהַרְאוֹת שֶׁהֲרֵי זֶה הֻשְׁלַם כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב <Nonesmall>[ויקרא א]</small> וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. הֲרֵי כ\"ה אוֹתִיּוֹת.</p>\n<p>וְעַל זֶה כ\"ה מִינִים לְהַשְׁלִים תִּקּוּן הַמִּקְדָּשׁ, וְכָל הָאוֹתִיּוֹת הַלָּלוּ בֵּאַרְנוּ בְּאוֹתָן אוֹתִיּוֹת חֲקוּקוֹת שֶׁלָּמַדְנוּ מִמַּר. וּמִשּׁוּם שֶׁהַמִּשְׁכָּן הִשְׁתַּלֵּם בַּסּוֹדוֹת הַלָּלוּ, נִקְרָא כ\"ה בַּיִּחוּד שֶׁל שְׁלֵמוּת הַמִּשְׁכָּן, וְעַל זֶה כָּתוּב <Nonesmall>[תהלים קמה]</small> וַחֲסִידֶיךְ יְבָרְכוּכָה, סוֹד הַשְּׁלֵמוּת שֶׁל כָּל הַמִּשְׁכָּן וְתִקּוּנוֹ.</p>\n<p>כ\"ה כְּנֶגֶד כ\"ב אוֹתִיּוֹת הַתּוֹרָה, וְתוֹרָה וּנְבִיאִים וּכְתוּבִים, שֶׁהֵם כְּלָל אֶחָד, סוֹד אֶחָד. בְּשָׁעָה שֶׁיִּשְׂרָאֵל מְיַחֲדִים יִחוּד בְּפָסוּק זֶה בְּסוֹד כ\"ה אוֹתִיּוֹת, שֶׁהֵם שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, וּבָרוּךְ שֵׁם כְּבוֹד כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, שֶׁהֵם כ\"ד אוֹתִיּוֹת, וִיכַוֵּן כָּל אֶחָד בָּהֶם, הָאוֹתִיּוֹת כֻּלָּן מִתְחַבְּרוֹת כְּאַחַת, וְעוֹלוֹת לְחִבּוּר אֶחָד, אַרְבָּעִים וְתִשְׁעָה שְׁעָרִים בְּסוֹד הַיּוֹבֵל. וְאָז צָרִיךְ לַעֲלוֹת וָעֶד, לֹא יוֹתֵר. וְאָז נִפְתָּחִים הַשְּׁעָרִים, וּמַחֲשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ אָדָם כְּאִלּוּ קִיֵּם אֶת כָּל הַתּוֹרָה, שֶׁהִיא בָּאָה בְּמ\"ט פָּנִים בַּכֹּל.</p>\n<p>וְעַל זֶה צָרִיךְ לְכַוֵּן רָצוֹן בְּעֶשְׂרִים וְחָמֵשׁ וּבְעֶשְׂרִים וְאַרְבַּע לְהַעֲלוֹתָן בִּרְצוֹן הַלֵּב בְּאַרְבָּעִים וְתִשְׁעָה שְׁעָרִים שֶׁאָמַרְנוּ. כֵּיוָן שֶׁהִתְכַּוֵּן בָּזֶה, יִתְכַּוֵּן בְּאוֹתוֹ יִחוּד שֶׁאָמַר מַר, שְׁמַע יִשְׂרָאֵל וְגוֹ' בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, כְּלָל שֶׁל כָּל הַתּוֹרָה כֻּלָּהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיִּתְכַּוֵּן בָּהֶן, וַדַּאי כְּלָל הוּא שֶׁל כָּל הַתּוֹרָה שֶׁלְּמַעְלָה וּמַטָּה. וְזֶהוּ סוֹד שֶׁל אָדָם, שְׁלֵמוּת שֶׁל זָכָר וּנְקֵבָה, וְסוֹד כָּל הָאֱמוּנָה. <Nonesmall>[עד כאן]</small></p>\n<p>רַבִּי אַבָּא שָׁלַח לוֹ לְרַבִּי שִׁמְעוֹן וְאָמַר לוֹ, זֶה שֶׁבֵּאֵר מַר, בַּתְּפִלִּין שֶׁל רִבּוֹן הָעוֹלָם אַרְבַּע פָּרָשִׁיּוֹת הֵן קֹדֶשׁ הַקְּדָשִׁים – יָפֶה. עוֹר שֶׁעַל הַתְּפִלִּין, וְאוֹתָן רְצוּעוֹת נִקְרָאוֹת קְדֻשָּׁה, אַסְמַכְתָּא מִנַּיִן לָנוּ? שָׁלַח לוֹ, <Nonesmall>[בראשית ג]</small> וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ וְגוֹ' דַּוְקָא, וְכָךְ בֵּאֲרוֹ רַב הַמְנוּנָא סָבָא. וְאֵלֶּה אוֹתָם שֶׁל רֹאשׁ, וּזְרוֹעַ יָדְכָה בְּהֵ\"א, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יֵשׁ מִי שֶׁשּׁוֹנֶה בְּצוּרָה זוֹ: וְהָיָה – זְרוֹעַ שְׂמֹאל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרֵאת גְּבוּרָה, אִם כָּךְ לֹא נִשְׁאֲרוּ בָּרֹאשׁ אֶלָּא שָׁלֹשׁ, וְהֵן אַרְבַּע. אֲבָל שְׁתֵּי מֶרְכָּבוֹת קְדוֹשׁוֹת הֵן, זֶה נִקְשָׁר בַּלֵּב וְזֶה נִקְשָׁר בַּמֹּחַ. וְהַלֵּב וְהַמֹּחַ נִקְשְׁרוּ זֶה בָזֶה, וְזִוּוּג אֶחָד לָהֶם, וְיָפֶה אָמְרוּ הַחֲבֵרִים. וְהָיָה לְאוֹת עַל יָדְכָה, כְּמוֹ שֶׁנֶּאֱמַר, וְלֹא נִקְרָא אֶלָּא אוֹת.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהָאָדָם מַקְדִּים בַּחֲצוֹת הַלַּיְלָה וְקָם וּמִשְׁתַּדֵּל בַּתּוֹרָה עַד שֶׁמֵּאִיר הַבֹּקֶר, בַּבֹּקֶר מֵנִיחַ תְּפִלִּין בְּרֹאשׁוֹ וּתְפִלִּין בְּרֹשֶׁם קָדוֹשׁ בִּזְרוֹעוֹ וּמִתְעַטֵּף בְּעִטּוּף שֶׁל מִצְוָה וּבָא לָצֵאת מִשַּׁעַר בֵּיתוֹ, פּוֹגֵשׁ אֶת הַמְּזוּזָה, רֹשֶׁם הַקָּדוֹשׁ בְּשַׁעַר בֵּיתוֹ, אַרְבָּעָה מַלְאָכִים קְדוֹשִׁים מִזְדַּוְּגִים עִמּוֹ וְיוֹצְאִים עִמּוֹ מִשַּׁעַר בֵּיתוֹ וּמְלַוִּים אוֹתוֹ לְבֵית הַכְּנֶסֶת, וּמַכְרִיזִים לְפָנָיו: תְּנוּ כָבוֹד לִדְמוּת הַמֶּלֶךְ הַקָּדוֹשׁ! תְּנוּ כָבוֹד לְבֶן הַמֶּלֶךְ, לַפַּרְצוּף הַיָּקָר שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ! רוּחַ קְדוֹשָׁה שׁוֹרָה עָלָיו, מַכְרִיזָה וְאוֹמֶרֶת: <Nonesmall>[ישעיה מט]</small> יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>אָז אוֹתָהּ רוּחַ קְדוֹשָׁה עוֹלָה לְמַעְלָה, וּמְעִידָה עָלָיו לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְאָז מְצַוֶּה הַמֶּלֶךְ הָעֶלְיוֹן לִכְתֹּב לְפָנָיו אֶת כָּל אוֹתָם בְּנֵי הֵיכָלוֹ, כָּל אֵלּוּ הַנּוֹדָעִים לְפָנָיו. זֶהוּ שֶׁכָּתוּב <Nonesmall>[מלאכי ג]</small> וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחֹשְׁבֵי שְׁמוֹ. מַה זֶּה וּלְחֹשְׁבֵי שְׁמוֹ? כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שמות לה]</small> <Nonesmall>[חשב האפוד]</small> וְחֹשְׁבֵי מַחֲשָׁבוֹת, אוֹתָם שֶׁעוֹשִׂים לִשְׁמוֹ אָמָּנוּת בַּכֹּל. אָמָּנוּת הַתְּפִלִּין – בְּבָתֵּיהֶן, בִּרְצוּעוֹתֵיהֶן וּכְתִיבָתָן. אָמָּנוּת הַצִּיצִית – בְּחוּטֵיהֶן בְּחוּט הַתְּכֵלֶת. אָמָּנוּת הַמְּזוּזָה. וְאֵלֶּה הֵם חֹשְׁבֵי שְׁמוֹ, וְכָתוּב <Nonesmall>[שם]</small> וְחֹשְׁבֵי מַחֲשָׁבוֹת.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ וּמַכְרִיז עָלָיו בְּכָל הָעוֹלָמוֹת: רְאוּ אֵיזוֹ בְּרִיָּה בָּרָאתִי בְּעוֹלָמִי! וּמִי שֶׁיִּכָּנֵס לְפָנָיו לְבֵית הַכְּנֶסֶת, כְּשֶׁיּוֹצֵא מֵהַשַּׁעַר שֶׁלּוֹ וְאֵין תְּפִלִּין בְּרֹאשׁוֹ וְצִיצִית בִּלְבוּשׁוֹ, וְאוֹמֵר <Nonesmall>[תהלים ה]</small> אֶשְׁתַּחֲוֶה אֶת הֵיכַל קָדְשְׁךְ בְּיִרְאָתֶךְ – הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר: אַיֵּה הוּא מוֹרָאִי? הֲרֵי מֵעִיד עֵדוּת שֶׁקֶר!</p>\n<p>אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁכָּאן אָמַר אֱלֹהֵינוּ <Nonesmall>[אלהיך]</small>. שֶׁאָמַר רַבִּי שִׁמְעוֹן, מֹשֶׁה נֶאֱחַז בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה עַל שְׁאָר הַנְּבִיאִים הַנֶּאֱמָנִים. וְאָמַר רַבִּי שִׁמְעוֹן, אִלְמָלֵא הָיוּ יוֹדְעִים בְּנֵי אָדָם דִּבְרֵי תוֹרָה, שֶׁיֵּדְעוּ שֶׁהֲרֵי אֵין שׁוּם דָּבָר אוֹ אוֹת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים.</p>"],[9522012588,"<p>בֹּא וּרְאֵה, כָּתוּב <Nonesmall>[שמות יט]</small> מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. וְשָׁנִינוּ, מַה זֶּה בְקוֹל? בְּקוֹלוֹ שֶׁל מֹשֶׁה. וְיָפֶה הוּא. דַּוְקָא בְּקוֹלוֹ שֶׁל מֹשֶׁה, בְּאוֹתוֹ קוֹל שֶׁהוּא אָחוּז בּוֹ עַל כָּל שְׁאָר הַנְּבִיאִים. <Nonesmall>[משם משה נזון על כלם]</small> וּמִשּׁוּם שֶׁהוּא נֶאֱחָז עַל כֻּלָם בְּאוֹתוֹ קוֹל, דַּרְגָּה עֶלְיוֹנָה, הָיָה אוֹמֵר לְיִשְׂרָאֵל: ה' אֱלֹהֶיךְ. הִיא דַּרְגָּה שֶׁנִּקְרֵאת שְׁכִינָה, שֶׁשּׁוֹרָה בְתוֹכָם. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ, קְלָלוֹת שֶׁבְּתוֹרַת כֹּהֲנִים – מֹשֶׁה מִפִּי הַגְּבוּרָה אֲמָרָן, וְשֶׁבְּמִשְׁנֵה תוֹרָה – מֹשֶׁה מִפִּי עַצְמוֹ אֲמָרָן. מַה זֶּה מִפִּי עַצְמוֹ? וְכִי תַעֲלֶה בְדַעְתְּךְ שֶׁאֲפִלּוּ אוֹתוֹ קְטַנָּה בַּתּוֹרָה אָמַר אוֹתָהּ מֹשֶׁה מֵעַצְמוֹ?!</p>\n<p>אֶלָּא יָפֶה הוּא, וַהֲרֵי הִתְעוֹרַרְנוּ. לֹא שָׁנִינוּ מֵעַצְמוֹ, אֶלָּא מִפִּי עַצְמוֹ, וּמַהוּ? אוֹתוֹ קוֹל שֶׁהוּא אָחוּז בּוֹ. וְעַל זֶה, הַלָּלוּ מִפִּי הַגְּבוּרָה, וְהַלָּלוּ מִפִּי עַצְמוֹ, מִפִּי אוֹתָהּ דַּרְגָּה שֶׁנִּקְשַׁר בָּהּ עַל שְׁאָר נְבִיאִים הַנֶּאֱמָנִים. וְעַל זֶה בְּכָל מָקוֹם אֱלֹהֶיךְ, וְכָאן אֱלֹהֵינוּ.</p>\n<p>בֹּא וּרְאֵה כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לִשְׁמֹר דַּרְכֵיהֶם כְּדֵי שֶׁיִּשְׁתַּדְּלוּ בַּעֲבוֹדַת רִבּוֹנָם וְיִזְכּוּ לְחַיֵּי הָעוֹלָמִים. תַּחַת כִּסֵּא הַמֶּלֶךְ הַקָּדוֹשׁ יֵשׁ מָדוֹרִים עֶלְיוֹנִים, וּבְאוֹתוֹ מָקוֹם שֶׁל הַכִּסֵּא נִקְשֶׁרֶת מְזוּזָה לְהִנָּצֵל מִכַּמָּה בַּעֲלֵי דִינִים שֶׁעֲתִידִים לְהִתְעוֹרֵר בָּהֶם בִּבְנֵי הָאָדָם בְּאוֹתוֹ הָעוֹלָם. כְּמוֹ זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, וְנָתַן לָהֶם מִצְווֹת הַתּוֹרָה כְּדֵי שֶׁיִּשְׁתַּדְּלוּ בָהּ, וְיִנָּצְלוּ בָּעוֹלָם הַזֶּה מִכַּמָּה בַּעֲלֵי דִינִים וּמִכַּמָּה מְקַטְרְגִים שֶׁמִּזְדַּמְּנִים לִבְנֵי אָדָם בְּכָל יוֹם.</p>"],[9522012589,"<p>רַבִּי חִיָּיא אָמַר, זֶה מִי שֶׁרוֹצֶה שֶׁיִּשָּׁמֵר דְּרָכָיו, לֹא יַעֲבֹר עַל מַיִם שֶׁשָּׁפְכוּ לִפְנֵי הַפֶּתַח, כִּי שָׁם שׁוֹרֶה שֵׁד אֶחָד, וְהוּא בֵּין שְׁנֵי מַשְׁקוֹפֵי הַפֶּתַח, וּפָנָיו כְּנֶגֶד הַפֶּתַח, וּמִסְתַּכֵּל עַל כָּל מַה שֶּׁעוֹשִׂים בַּבַּיִת, וְלֹא צָרִיךְ לָאָדָם לִשְׁפֹּךְ מַיִם בֵּין בְּנֵי שְׁעָרִים. רַבִּי יִצְחָק אָמַר, אֵין לָנוּ עֵסֶק בְּמַיִם צְלוּלִים, וְהוּא שֶׁלֹּא יִשְׁפֹּךְ אוֹתָם בְּדֶרֶךְ קָלוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַזִּיק. וְלֹא עוֹד, אֶלָּא שֶׁיַּחֲזִיר רֹאשׁוֹ כְּנֶגֶד הַבַּיִת, וּבְכָל מַה שֶּׁמִּסְתַּכֵּל – מִתְקַלֵּל.</p>\n<p>יִשִׁ לוֹ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה שַׁמָּשִׁים כְּמִנְיַן יְמוֹת הַשָּׁנָה, שֶׁהוּא שׁוֹלֵט עֲלֵיהֶם, וְכֻלָּם יוֹצְאִים עִם הָאָדָם כְּשֶׁיּוֹצֵא מִשַּׁעַר בֵּיתוֹ. אָמַר רַבִּי אֶלְעָזָר, כָּל זֶה רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת יִשְׂרָאֵל, וְהִתְקִין שְׁמוֹ הַקָּדוֹשׁ לְמַעְלָה, שֶׁהִיא הַתּוֹרָה, וְהַתּוֹרָה כֻּלָּהּ הִיא שֵׁם קָדוֹשׁ אֶחָד, וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה מִשְׁתַּדֵּל בִּשְׁמוֹ.</p>\n<p>בֹּא וּרְאֵה, צָרִיךְ אָדָם לִרְשֹׁם בְּפֶתַח בֵּיתוֹ שֵׁם הַקָּדוֹשׁ, שֶׁהוּא אֱמוּנַת הַכֹּל. שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁהַשֵּׁם הַקָּדוֹשׁ נִמְצָא, לֹא נִמְצָאִים שָׁם מִינִים רָעִים, וְלֹא יְכוֹלִים לְקַטְרֵג לָאָדָם, שֶׁכָּתוּב <Nonesmall>[תהלים לא]</small> לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְגוֹ'.</p>\n<p><Nonesmall>[מזוזה נקראת]</small> מָקוֹם שֶׁפֶּתַח הַבַּיִת שׁוֹרֶה, כְּדֻגְמָא שֶׁלְּמַעְלָה, מָקוֹם שֶׁפֶּתַח הַבַּיִת הָעֶלְיוֹן שׁוֹרֶה נִקְרָא מְזוּזָה, שֶׁהוּא תִּקּוּן הַבַּיִת וּפֶתַח הַבַּיִת. מֵאוֹתָהּ מְזוּזָה בּוֹרְחִים בַּעֲלֵי שְׁמִירַת הַחֻקִּים. בַּעֲלֵי הַדִּינִים לֹא נִמְצָאִים לְפָנֶיהָ. וּכְנֶגֶד זֶה לְמַטָּה, כְּשֶׁאָדָם מַתְקִין מְזוּזָה לַבַּיִת וְהַשֵּׁם הַקָּדוֹשׁ הַזֶּה רָשׁוּם בְּאוֹתִיּוֹתָיו, הָאָדָם הַזֶּה מִתְעַטֵּר בְּעַטְרוֹת רִבּוֹנוֹ, וְלֹא קְרֵבִים לְפֶתַח בֵּיתוֹ מִינִים רָעִים וְלֹא נִמְצָאִים שָׁם.</p>\n<p>רַבִּי אַבָּא הָיָה בָּא מִלִּרְאוֹת אֶת רַבִּי שִׁמְעוֹן, פָּגַע בּוֹ רַבִּי יִצְחָק, אָמַר לוֹ, מֵאַיִן בָּאתָ בַּעַל הָאוֹר? אִישׁ שֶׁנִּדְבָּק בְּאֵשׁ אוֹכֶלֶת כָּל יוֹם, הֲרֵי הָאוֹר שׁוֹרֶה עִמּוֹ. אָמַר לוֹ, שָׁנִינוּ שֶׁחִיּוּב עַל הָאָדָם לְקַבֵּל פְּנֵי שְׁכִינָה בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת, וּמִיהוּ? רַבּוֹ. כָּל שֶׁכֵּן מְנוֹרָה הָעֶלְיוֹנָה הַקְּדוֹשָׁה שֶׁכָּל בְּנֵי הָעוֹלָם רוֹצִים לְקַבֵּל פָּנָיו. אָמַר רַבִּי יִצְחָק, אֶחֱזֹּר עִמְּךְ וַאֲקַבֵּל פְּנֵי הַשְּׁכִינָה, וְאֶטְעַם מֵאוֹתָם דְּבָרִים עֶלְיוֹנִים שֶׁטָּעַמְתָּ לְפָנָיו.</p>"],[9522012590,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, <Nonesmall>[שם קכג]</small> שִׁיר הַמַּעֲלוֹת אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי הַיֹּשְׁבִי בַּשָּׁמָיִם. שִׁיר זֶה לֹא כָתוּב מִי אֲמָרוֹ. אֶלָּא בְּכָל מָקוֹם שֶׁהוּא סָתוּם, רוּחַ הַקֹּדֶשׁ אָמְרָה עַל כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. הַיֹּשְׁבִי בַּשָּׁמָיִם?! הַיּוֹשֵׁב צָרִיךְ לוֹ לִכְתֹּב! מַה זֶּה הַיֹּשְׁבִי?</p>\n<p>אֶלָּא בֵּאַרְנוּ, מִי שֶׁרוֹצֶה לְהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, צָרִיךְ לְבַקֵּשׁ מֵעֹמֶק הַכֹּל לְהוֹרִיק בְּרָכוֹת לְמַטָּה, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[שם קל]</small> שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. וְיוֹ\"ד זוֹ הִיא יְתֵרָה, עֹמֶק הַכֹּל הִיא, וּבָזֶה צָרִיךְ לְבַקֵּשׁ בַּקָּשָׁתוֹ, לְהוֹרִיק בְּרָכוֹת לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, לְהָזִין מִמֶּנּוּ אֶת הַכֹּל. וְעַל זֶה הַיֹּשְׁבִי בַּשָּׁמָיִם, בַּשָּׁמַיִם מַמָּשׁ. שֶׁכְּשֶׁאוֹתָן בְּרָכוֹת שׁוֹפְעוֹת וְנִמְשָׁכוֹת מֵאוֹתוֹ מָקוֹם עֹמֶק הַכֹּל, וּמִתְיַשְּׁבִים בְּמָקוֹם שֶׁנִּקְרָא שָׁמַיִם, אָז בְּרָכוֹת נִמְצָאוֹת בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים.</p>\n<p>כְעֵינֵי עֲבָדִים אֶל יַד אֲדוֹנֵיהֶם, מַה זֶּה כְעֵינֵי עֲבָדִים? אֵלּוּ אוֹתָם שְׁאָר גְּדוֹלֵי הָעַמִּים שֶׁלֹּא נִזּוֹנִים אֶלָּא מִשְּׁיָרֵי <Nonesmall>[גוף]</small> נוֹף הָאִילָן שֶׁיִּשְׂרָאֵל נִדְבָּקִים בּוֹ. וּכְשֶׁיִּשְׂרָאֵל לוֹקְחִים בְּרָכוֹת מֵאוֹתוֹ מָקוֹם, כֻּלָּם מִתְבָּרְכִים מִיִּשְׂרָאֵל.</p>\n<p>כְּעֵינֵי שִׁפְחָה אֶל יַד גְּבִרְתָּהּ – זוֹהִי הַשִּׁפְחָה שֶׁבֵּאַרְנוּ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג אֶת הַכֹּחַ שֶׁלָּהּ בְּמִצְרַיִם, שֶׁהֲרֵי אֵין כֹּחַ שֶׁלָּהּ אֶלָּא רַק כְּשֶׁשּׁוֹפֵעַ מִתַּמְצִית שֶׁל אֶרֶץ יִשְׂרָאֵל. וְאֶרֶץ יִשְׂרָאֵל נִקְרֵאת גְּבִרְתָּהּ, וְעַל זֶה כָּתוּב <Nonesmall>[משלי ל]</small> תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ. אֵיזוֹ אֶרֶץ? זוֹ אֶרֶץ יִשְׂרָאֵל, כְּמוֹ שֶׁנִּתְבָּאֵר. תַּחַת עֶבֶד כִּי יִמְלוֹךְ – אֵלֶּה אוֹתָם עֲבָדִים שֶׁאָמַרְנוּ, כְּשֶׁנִּתָּן הַשִּׁלְטוֹן לְאֶחָד מֵהֶם. וְזֶהוּ שֶׁכָּתוּב אֲשֶׁר הוֹצֵאתִיךְ מֵאֶרֶץ מִצְרַיִם מִבֵּית עֲבָדִים. שִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ <Nonesmall>[מי היא]</small> – זוֹהִי שִׁפְחָה כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>בֹּא וּרְאֵה, מִצַּד הַשִּׁפְחָה הַזּוֹ יוֹצְאִים כַּמָּה שׁוֹמְרֵי חֹק בַּעֲלֵי דִינִים, מְקַטְרְגִים כְּנֶגֶד יִשְׂרָאֵל כְּדֵי לְקַטְרֵג עֲלֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְיִשְׂרָאֵל שְׁמִירָה כְּאָב שֶׁרוֹצֶה לִשְׁמֹר אֶת בְּנוֹ מֵהַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, כַּמָּה מְקַטְרְגִים מְזֻמָּנִים כְּנֶגְדְּכֶם, הִשְׁתַּדְּלוּ בַעֲבוֹדָתִי, וַאֲנִי אֶשְׁמֹר אֶתְכֶם מִבַּחוּץ, וְאַתֶּם תִּהְיוּ זְמִינִים בְּבָתֵּיהֶם בִּפְנִים וִישֵׁנִים בְּמִטּוֹתֵיכֶם, וַאֲנִי אֶשְׁמֹר אֶתְכֶם מִבַּחוּץ וּסְבִיב מִטּוֹתֵיכֶם.</p>\n<p>וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁאוֹתָם מִינִים רָעִים קְרֵבִים לְפִתְחוֹ שֶׁל הָאָדָם, זוֹקְפִים רֹאשׁ וּמִסְתַּכְּלִים בַּשֵּׁם הַקָּדוֹשׁ שֶׁנִּרְאֶה בַחוּץ, שֶׁהוּא שַׁדַּי, שֶׁמִּתְעַטֵּר בְּעַטְרוֹתָיו. שֵׁם זֶה שׁוֹלֵט עַל כֻּלָּם, מִמֶּנּוּ הֵם פּוֹחֲדִים וּבוֹרְחִים, וְלֹא קְרֵבִים לְפֶתַח הָאָדָם.</p>\n<p>אָמַר לוֹ רַבִּי יִצְחָק, אִם כָּךְ, שֶׁיִּרְֹשם הָאָדָם שֵׁם זֶה בְּפֶתַח הַבַּיִת וְלֹא יוֹתֵר. לָמָּה כָּל הַפָּרָשָׁה? אָמַר לוֹ, יָפֶה הוּא, שֶׁהֲרֵי שֵׁם זֶה לֹא מִתְעַטֵּר אֶלָּא בְּאוֹתָן אוֹתִיּוֹת כֻּלָּן, רְשׁוּמוֹת בְּרֹשֶׁם הַמֶּלֶךְ, וּכְשֶׁנִּכְתֶּבֶת כָּל הַפָּרָשָׁה, אָז שֵׁם זֶה מִתְעַטֵּר בְּעַטְרוֹתָיו, וְיוֹצֵא הַמֶּלֶךְ עִם כָּל חֵילוֹתָיו, כֻּלָּם רְשׁוּמִים בְּרֹשֶׁם הַמֶּלֶךְ, וְאָז פּוֹחֲדִים מִמֶּנּוּ וּבוֹרְחִים מִפָּנָיו.</p>\n<p>בֹּא וּרְאֵה, וְהָיָ\"ה שֵׁם קָדוֹשׁ מִלְּמַטָּה לְמַעְלָה, וְעַל זֶה שַׁדַּי נִרְשָׁם מִבַּחוּץ כְּנֶגֶד שֵׁם זֶה. וְהָיָ\"ה מִבִּפְנִים, שַׁדַּ\"י מִבַּחוּץ. שֶׁיִּהְיֶה הָאָדָם שָׁמוּר מִכָּל הַצְּדָדִים, מִבִּפְנִים וּמִבַּחוּץ. אָמַר רַבִּי אַבָּא, כַּמָּה חֲיָלוֹת קְדוֹשִׁים זְמִינִים בְּאוֹתָהּ שָׁעָה שֶׁמַּנִּיחַ אָדָם מְזוּזָה בַּשַּׁעַר שֶׁלּוֹ, כֻּלָּם מַכְרִיזִים וְאוֹמְרִים: <Nonesmall>[תהלים קיח]</small> זֶה הַשַּׁעַר לַה' וְגוֹ'.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, אָז נוֹדָעִים יִשְׂרָאֵל שֶׁהֵם בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁהֲרֵי כֻּלָּם נִרְשְׁמוּ מִמֶּנּוּ. נִרְשְׁמוּ בְגוּפָם בְּרֹשֶׁם קָדוֹשׁ, נִרְשְׁמוּ בִלְבוּשָׁם בְּעִטּוּפָם שֶׁל מִצְוָה, נִרְשְׁמוּ בְרָאשֵׁיהֶם בְּבָתֵּי הַתְּפִלִּין בְּשֵׁם רִבּוֹנָם, נִרְשְׁמוּ בִידֵיהֶם בִּרְצוּעוֹת הַקְּדֻשָּׁה, נִרְשְׁמוּ בְנַעֲלֵיהֶם בְּנַעֲלֵי מִצְוָה, נִרְשְׁמוּ בַחוּץ בִּזְרִיעָה בִּקְצִירָה, נִרְשְׁמוּ בְּבָתֵּיהֶם בִּמְזוּזַת הַפֶּתַח. רְשׁוּמִים בַּכֹּל שֶׁהֵם בְּנֵי הַמֶּלֶךְ הָעֶלְיוֹן. אַשְׁרֵי חֶלְקָם.</p>"],[9522012591,"<p>עֵד שֶׁהָיוּ הוֹלְכִים אָמַר רַבִּי אַבָּא, מַה זֶּה שֶׁכָּתוּב <Nonesmall>[ירמיה ב]</small> אֹתִי עָזְבוּ מְקוֹר מַיִם חַיִּים לַחְצֹב לָהֶם בּארוֹת וְגוֹ'? אֹתִי עָזְבוּ – זֶהוּ מִי שֶׁמְּשַׁקֵּר בְּאוֹת הָרֹשֶׁם הַקָּדוֹשׁ. וּבַמֶּה מְשַׁקֵּר בּוֹ? שֶׁמַּכְנִיסוֹ בִּרְשׁוּת אַחֶרֶת, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[מלאכי ב]</small> וּבָעַל בַּת אֵל נֵכָר, שֶׁנִּקְרֵאת בּארוֹת נִשְׁבָּרִים. שֶׁהֲרֵי עַמִּים עוֹבְדֵי עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת נִקְרְאוּ בּוֹרוֹת נִשְׁבָּרִים.</p>\n<p>וְשֶׁל יִשְׂרָאֵל נִקְרֵאת בְּאֵר מְקוֹר מַיִם חַיִּים, זוֹ הָרְשׁוּת הַקְּדוֹשָׁה, הָאֱמוּנָה הַקְּדוֹשָׁה, וְנִקְרֵאת בְּאֵר נוֹבַעַת, שֶׁמַּיִם צְלוּלִים יוֹצְאִים וְנוֹזְלִים מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שיר ד]</small> וְנֹזְלִים מִן לְבָנוֹן. <Nonesmall>[משלי ה]</small> וְנוֹזְלִים מִתּוֹךְ בְּאֵרְךְ. וְכָתוּב <Nonesmall>[שיר ד]</small> מַעְיַן גַּנִּים בְּאֵר מַיִם חַיִּים. הַצַּד הָאַחֵר נִקְרָא בֹּארֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִלוּ הַמָּיִם. <Nonesmall>[מהו, ' אלא ההוא וכו']</small>.</p>\n<p>בֹּא וּרְאֵה, נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מַשְׁקֶה לְכָל הַגָּן <Nonesmall>[ומרוה לכל הגן]</small> וּמַרְוֶה לְכָל מָקוֹם וּמָקוֹם, כְּמוֹ שֶׁבֵּאַרְנוּ, עַד שֶׁמְּמַלֵּא <Nonesmall>[שמגיע]</small> אוֹתוֹ מָקוֹם בַּגָּן, שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים. וּמִשָּׁם נִזּוֹנִים עֶלְיוֹנִים וְתַחְתּוֹנִים <Nonesmall>[עולמות תחתונים]</small>, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[בראשית ב]</small> וּמִשָּׁם יִפָּרֵד.</p>\n<p>וְכָל אוֹתָם צְדָדִים שֶׁל צַד שְׂמֹאל לֹא מֻשְׁקִים מֵאוֹתָהּ נְבִיעַת הַמַּיִם הַנּוֹבְעִים, מִשּׁוּם שֶׁהֵם מִצַּד שְׁאָר הָעַמִּים, וְנִקְרְאוּ בּארֹת נִשְׁבָּרִים. וּמִי שֶׁמְּשַׁקֵּר בַּשֵּׁם <Nonesmall>[ברשם]</small> הַקָּדוֹשׁ בְּאוֹתוֹ צַד, נִדְבָּק בְּבֹארֹת נִשְׁבָּרִים אֲשֶׁר לֹא יָכִלוּ הַמָּיִם, וְלֹא נִכְנָסִים לְשָׁם. וְאוֹתוֹ שֶׁזּוֹכֶה לִשְׁמֹר אוֹתוֹ, זוֹכֶה לִהְיוֹת מֻשְׁקֶה מֵאוֹתוֹ מַבּוּעַ שֶׁל הַנַּחַל <Nonesmall>[בעולם הזה]</small> בָּעוֹלָם הַבָּא, וְזוֹכֶה שֶׁתִּתְמַלֵּא אוֹתָהּ בְּאֵר עֶלְיוֹנָה לְהַשְׁפִּיעַ בְּרָכוֹת לְמַעְלָה וּלְמַטָּה. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל זֶה כָּתוּב, <Nonesmall>[ישעיה נח]</small> וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו.</p>\n<p>אוֹי לְמִי שֶׁמְּשַׁקֵּר בָּרֹשֶׁם הַקָּדוֹשׁ, שֶׁהֲרֵי מְשַׁקֵּר בַּשֵּׁם הָעֶלְיוֹן, וְלֹא עוֹד, אֶלָּא שֶׁגּוֹרֵם לַבְּאֵר הַזֹּאת שֶׁלֹּא תִתְבָּרֵךְ, וְקוֹרְאִים עָלָיו <Nonesmall>[דברים כב]</small> כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. בְּתוּלַת יִשְׂרָאֵל דַּוְקָא. וּבֵאֲרוֹ רַבִּי שִׁמְעוֹן בִּמְקוֹמוֹ, מִי שֶׁשָּׂם עֲלִילוֹת דְּבָרִים עַל אִשְׁתּוֹ הָרִאשׁוֹנָה וּמוֹצִיא עָלֶיהָ שֵׁם רַע – כְּמוֹ שֶׁהוֹצִיא לְמַעְלָה, שֶׁכָּתוּב כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל סְתָם.</p>\n<p>וְהָלַךָ זֶה, כְּמוֹ זֶה שֶׁאָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, בְּתוּלָה יָרְשָׁה שֶׁבַע בְּרָכוֹת, שֶׁמִּתְבָּרֶכֶת בְּשֶׁבַע, מִשּׁוּם שֶׁבְּתוּלַת יִשְׂרָאֵל יָרְשָׁה שֶׁבַע בְּרָכוֹת, וְעַל זֶה נִקְרֵאת בַּת שֶׁבַע.</p>\n<p>וְאִשָּׁה אַחֶרֶת, מִי הַבְּרָכוֹת שֶׁלָּהּ? בִּרְכַּת בּעַז וְרוּת, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[רות ד]</small> וַיּאמְרוּ כָּל הָעָם אֲשֶׁר בַּשַּׁעַר וְהַזְּקֵנִים עֵדִים יִתֵּן ה' אֶת וְגוֹ'. שֶׁוַּדַּאי בְּתוּלָה מִתְבָּרֶכֶת בְּשֶׁבַע, וְלֹא אִשָּׁה אַחֶרֶת בְּסוֹד זֶה. כֵּיוָן שֶׁהִגִּיעוּ לְשָׂדֶה אֶחָד, רָאוּ אִילָנוֹת וְיָשְׁבוּ תַחְתֵּיהֶם. אָמַר רַבִּי אַבָּא, הֲרֵי צַחוּת שֶׁל דִּבְרֵי תוֹרָה. נֵשֵׁב.</p>"],[9522012592,"<p>פָּתַח וְאָמַר, <Nonesmall>[ישעיה כז]</small> וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְגוֹ'. וְהָיָה בַּיּוֹם הַהוּא, מַה זֶּה בַּיּוֹם הַהוּא? אֶלָּא אוֹתוֹ יוֹם הַיָּדוּעַ לַקָּדוֹשׁ־בָּרוּךְ־הוּא, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[זכריה יד]</small> וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה'. עוֹד בַּיּוֹם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[יחזקאל לח]</small> בְּיוֹם בֹּא גּוֹג עַל אַדְמַת יִשְׂרָאֵל.</p>\n<p>יִתָּקַע בְּשׁוֹפָר גָּדוֹל. מַה לָּנוּ בּוֹ אִם הוּא גָּדוֹל אוֹ קָטָן? אֶלָּא אוֹתוֹ הַשּׁוֹפָר הָעֶלְיוֹן שֶׁבּוֹ יוֹצְאִים הָעֲבָדִים לַחֵרוּת תָּמִיד, וְזֶהוּ הַיּוֹבֵל, שֶׁהַיּוֹבֵל עֶלְיוֹן וְגָדוֹל הוּא. וּכְשֶׁזֶּה מִתְעוֹרֵר, כָּל הַחֵרוּת שֶׁל הָעוֹלָמוֹת מִתְעוֹרְרִים בּוֹ, וְהַהוּא נִקְרָא שׁוֹפָר גָּדוֹל.</p>\n<p>וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר. הָאֲבוּדִים צָרִיךְ הָיָה לוֹ לִכְתֹּב!, אוֹ הַנֶּאֱבָדִים. מַה זֶּה הָאֹבְדִים? הָאוֹבְדִים מַמָּשׁ, מִשּׁוּם שֶׁהֵם בְּאֶרֶץ אַחֶרֶת, וּמִי שֶׁשָּׁרוּי בְּאֶרֶץ אַחֶרֶת יוֹנֵק מֵרְשׁוּת אַחֶרֶת, וּכְאִלּוּ לֹא שָׁרוּי בָּאֱמוּנָה, מִשּׁוּם כָּךְ נִקְרָאִים אוֹבְדִים. הֵם אוֹבְדִים בְּכָל הַצְּדָדִים, שֶׁכַּאֲשֶׁר יִשְׂרָאֵל שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה, הֵם צַדִּיקִים, צַדִּיקִים תָּמִיד בַּכֹּל, צַדִּיקִים לְמַעְלָה וּלְמַטָּה.</p>\n<p>דָּבָר אַחֵר וּבָאוּ הָאֹבְדִים, מִי הֵם? אֵלּוּ הַצַּדִּיק וּכְנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרָאִים אוֹבְדִים. מִנַּיִן לָנוּ? כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב <Nonesmall>[ירמיה ט]</small> עַל מָה אָבְדָה הָאָרֶץ. לֹא כָתוּב אֲבוּדָה אוֹ נֶאֱבֶדֶת, אֶלָּא אָבְדָה הָאָרֶץ, זוֹ כְּנֶסֶת יִשְׂרָאֵל. הַצַּדִּיק, שֶׁכָּתוּב <Nonesmall>[ישעיה נז]</small> הַצַּדִּיק אָבָד. לֹא כָתוּב אָבוּד אוֹ נֶאֱבָד, אֶלָּא אָבָד, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְאִם תֹּאמַר, וּבָאוּ, מֵאֵיזֶה מָקוֹם בָּאִים הָאוֹבְדִים הַלָּלוּ? אֶלָּא כְּנֶסֶת יִשְׂרָאֵל, מִן הַגָּלוּת. וְהַצַּדִּיק, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב <Nonesmall>[תהלים קכו]</small> בְּשׁוּב ה' אֶת שִׁיבַת צִיּוֹן, כְּדֵי שֶׁיָּשׁוּב לִמְקוֹמוֹ וְיָבֹא לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. וְעַל כֵּן, וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר, וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלם. מַה זֶּה אוֹמֵר? אֶלָּא הַדָּבָר הַזֶּה שֶׁהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם, כִּבְיָכוֹל לֹא יָצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת אֶלָּא עִם הַשְּׁכִינָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְאוֹתָם נִדָּחִים הִשְׁתַּחֲווּ לַה'.</p>"],[9522012593,"<p>עוֹד אָמַר רַבִּי אַבָּא, כָּתוּב <Nonesmall>[שם קכא]</small> ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. יִשְׁמָר צֵאתְךְ בָּרוּר, אֶלָּא וּבוֹאֶךְ מַה זֶּה אוֹמֵר? שֶׁהֲרֵי מִי שֶׁנִּכְנָס לְבֵיתוֹ אֵינוֹ פּוֹחֵד. אֶלָּא הָאָדָם הַזֶּה שֶׁשָּׂם רֹשֶׁם קָדוֹשׁ לְבֵיתוֹ בַּדְּבָרִים שֶׁל הַשֵּׁם הָעֶלְיוֹן, זֶה נִשְׁמָר מֵהַכֹּל. וּכְשֶׁיּוֹצֵא הַהוּא שֶׁמְּדוֹרוֹ לְשַׁעַר בֵּיתוֹ, זוֹקֵף וְרוֹאֶה אֶת הַשֵּׁם הַקָּדוֹשׁ וּמְעַיֵּן <Nonesmall>[נעוץ]</small> בְּפִתְחוֹ. כְּשֶׁיּוֹצֵא הָאָדָם, הוּא מְלַוֶּה אוֹתוֹ וְשׁוֹמֵר אוֹתוֹ. כְּשֶׁנִּכְנָס לְבֵיתוֹ הוּא מַכְרִיז לְפָנָיו: הִזָּהֲרוּ בַדְּיוֹקָן שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ! וְכָל זֶה מִשּׁוּם אוֹתוֹ הָרֹשֶׁם שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּרְשָׁם בַּשַּׁעַר שֶׁלּוֹ.</p>\n<p>וְלֹא דַי לוֹ לָאָדָם שֶׁנִּשְׁמָר בְּבֵיתוֹ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ כְּשֶׁנִּכְנָס וּכְשֶׁיּוֹצֵא, שֶׁכָּתוּב ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא וּרְאֵה, הָרוּחַ הָרָעָה הַזּוֹ שֶׁשְּׁרוּיָה בֵּין הַשְּׁעָרִים, אוֹי לוֹ לָאָדָם שֶׁלֹּא יוֹדֵעַ לְהִזָּהֵר מִמֶּנּוּ וְלֹא רוֹשֵׁם עַל פֶּתַח בֵּיתוֹ אֶת הַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ שֶׁיִּמָּצֵא עִמּוֹ, שֶׁהֲרֵי יֵשׁ לוֹ שְׁלֹשׁ מֵאוֹת שִׁשִּׁים וַחֲמִשָּׁה שַׁמָּשִׁים רָעִים שֶׁמְּקַטְרְגִים, כָּל אֶחָד מְשַׁמֵּשׁ בְּיוֹמוֹ, וְכֻלָּם נִמְצָאִים עִמּוֹ כָּל יְמוֹת הַשָּׁנָה וּמְקַטְרְגִים עָלָיו לְמַעְלָה וּלְמַטָּה, וְכֻלָּם נִמְצָאִים עִמּוֹ בַּיּוֹם וּבַלַּיְלָה. בַּיּוֹם לְקַטְרֵג לוֹ, בַּלַּיְלָה לְצַעֵר אוֹתוֹ בַּחֲלוֹמוֹ.</p>\n<p>כְּשֶׁיּוֹצֵא לְקַטְרֵג עָלָיו, כְּשֶׁנִּכְנָס, שָׂמִים יְדֵיהֶם עַל כְּתֵפוֹ וְאוֹמְרִים לוֹ: אוֹי לוֹ לִפְלוֹנִי שֶׁיָּצָא מֵרְשׁוּת אֲדוֹנוֹ! אוֹי לוֹ לִפְלוֹנִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא! מִשּׁוּם כָּךְ צְרִיכִים בְּנֵי הָאֱמוּנָה לִהְיוֹת רְשׁוּמִים בַּכֹּל, לִהְיוֹת רְשׁוּמִים בָּרֹשֶׁם שֶׁל רִבּוֹנָם, שֶׁיִּזְדַּעְזְעוּ מֵהֶם כָּל הַצְּדָדִים הַמִּינִים הָרָעִים, שֶׁיִּהְיוּ שְׁמוּרִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, עֲלֵיהֶם כָּתוּב <Nonesmall>[ישעיה ס]</small> וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'.</p>"],[9522012594,"<p>וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. רַבִּי יוֹסֵי פָּתַח, <Nonesmall>[שם נב]</small> וְעַתָּה מַה לִּי פֹה נְאֻם ה' כִּי לֻקַּח עַמִּי חִנָּם וְגוֹ'. בֹּא וּרְאֵה אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל, אַף עַל גַּב שֶׁחֲטָאֵיהֶם גָּרְמוּ לְהִסְתַּלֵּק מִבֵּינֵיהֶם וְהִתְפַּזְּרוּ בֵּין הָעַמִּים, הוּא תּוֹבֵעַ אֶת עֶלְבּוֹנָם. וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּאַרְצָם, הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּגַנּוֹ וּמִתְקָרֵב לְיִשְׂרָאֵל, וְשׁוֹמֵעַ קוֹלָם וּמִשְׁתַּבֵּחַ בָּהֶם.</p>\n<p>כֵּיוָן שֶׁגָּרְמוּ חֲטָאֵיהֶם וְהֻגְלוּ יִשְׂרָאֵל מֵהָאָרֶץ הַקְּדוֹשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִכְנָס לְגַנּוֹ וְלֹא מִשְׁתַּעֲשֵׁעַ בּוֹ. וְלֹא עוֹד, אֶלָּא שֶׁהוּא צוֹוֵחַ וְאוֹמֵר, וְעַתָּה מַה לִּי פֹה נְאֻם ה'? וְכָתוּב שָׁם, <Nonesmall>[תהלים קלב]</small> פֹּה אֵשֵׁב כִּי אִוִּתִיהָ. כִּי לֻקַּח עַמִּי חִנָּם, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[ישעיה נב]</small> חִנָּם נִמְכַּרְתֶּם.</p>\n<p>וּמֵאוֹתוֹ יוֹם שֶׁגָּלוּ יִשְׂרָאֵל מֵאַרְצָם לֹא נִמְצֵאת שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה נ]</small> אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. וְכָל זֶה מִשּׁוּם אַהֲבָתָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתָם, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[מלאכי א]</small> אָהַבְתִּי אֶתְכֶם אָמַר ה'. <Nonesmall>[ועל זה]</small> וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. וְאָהַבְתָּ, שֶׁצָּרִיךְ אָדָם לְהִתְקַשֵּׁר עִמּוֹ בְּאַהֲבָה עֶלְיוֹנָה. שֶׁכָל עֲבוֹדָה שֶׁאָדָם צָרִיךְ לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁיַּעֲבֹד בְּאַהֲבָה, שֶׁאֵין לְךְ עֲבוֹדָה כְּמוֹ אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אַבָּא אָמַר, הַדְּבָרִים הַלָּלוּ הֵם הַכְּלָל שֶׁל הַתּוֹרָה, מִשּׁוּם שֶׁעֶשֶׂר הָאֲמִירוֹת שֶׁל הַתּוֹרָה כָּאן נִכְלְלוּ, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>בֹּא וּרְאֵה, אֵין לְךְ דָּבָר בַּחֲבִיבוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמִי שֶׁאוֹהֵב אוֹתוֹ כָּרָאוּי. וּמַה הוּא? כַּכָּתוּב בְּכָל לְבָבְךְ. בְּכָל, מַה זֶּה אוֹמֵר? הָיָה צָרִיךְ לוֹ לִכְתֹּב בִּלְבָבְךְ, בְּנַפְשְׁךְ, בִּמְאֹדֶךְ. מַהוּ בְּכָל לְבָבְךְ? אֶלָּא לְהַכְלִיל שְׁנֵי לְבָבוֹת, אֶחָד טוֹב וְאֶחָד רַע. בְּכָל נַפְשְׁךְ, אֶחָד טוֹב וְאֶחָד רַע. בְּכָל מְאֹדֶךְ, זֶה לֹא בָא לִדְרָשָׁה. אָמַר רַבִּי אֶלְעָזָר, וַאֲפִלּוּ זֶה הוּא לִדְרָשָׁה. מָה הַטַּעַם? בֵּין שֶׁנָּפַל לוֹ מָמוֹן מִירֻשָּׁה, אוֹ מִצַּד אַחֵר, אוֹ בֵּין שֶׁהוּא הִרְוִיחַ אוֹתוֹ, וְעַל זֶה כָּתוּב בְּכָל מְאֹדֶךְ.</p>\n<p>אָמַר רַבִּי אַבָּא, חָזַרְנוּ לַפָּסוּק שֶׁל וְאָהַבְתָּ. מִי שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִתְעַטֵּר בְּחֶסֶד מִכָּל הַצְּדָדִים וְעוֹשֶׂה חֶסֶד עִם הַכֹּל, וְלֹא חָס עַל גּוּפוֹ וְעַל מָמוֹנוֹ. מִנַּיִן לָנוּ? מֵאַבְרָהָם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי לֹא חָס בְּאַהֲבַת רִבּוֹנוֹ עַל לִבּוֹ <Nonesmall>[שהוא יצרו]</small> וְעַל נַפְשׁוֹ וְעַל מָמוֹנוֹ.</p>\n<p>עַל לִבּוֹ לֹא הִשְׁגִּיחַ, עַל רְצוֹנוֹ, מִשּׁוּם אַהֲבַת רִבּוֹנוֹ. עַל נַפְשׁוֹ – שֶׁלֹּא חָס עַל בְּנוֹ וְעַל אִשְׁתּוֹ בִּשְׁבִיל אַהֲבַת רִבּוֹנוֹ. עַל מָמוֹנוֹ – שֶׁהָיָה עוֹמֵד בְּפָרָשַׁת דְּרָכִים וּמְתַקֵּן מְזוֹנוֹת לְכָל הָעוֹלָם. מִשּׁוּם כָּךְ הִתְעַטֵּר בַּעֲטָרָה שֶׁל חֶסֶד, כַּכָּתוּב <Nonesmall>[מיכה ז]</small> חֶסֶד לְאַבְרָהָם. וּמִי שֶׁמִּתְקַשֵּׁר בְּאַהֲבַת רִבּוֹנוֹ זוֹכֶה לָזֶה, וְלֹא עוֹד, אֶלָּא שֶׁכָּל הָעוֹלָמוֹת מִתְבָּרְכִים בִּגְלָלוֹ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[תהלים קמה]</small> וַחֲסִידֶיךְ יְבָרְכוּכָה. אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹ\"ה. <Nonesmall>[שכתוב <Nonesmall>[בראשית יב]</small> ונברכו בך כל משפחות האדמה]</small>.</p>\n<p>יוֹם אֶחָד הָיָה חַלָּשׁ רַבִּי יוֹסֵי, נִכְנְסוּ אֵלָיו רַבִּי אַבָּא וְרַבִּי יְהוּדָה וְרַבִּי יִצְחָק, רָאוּ אוֹתוֹ שֶׁהָיָה נוֹפֵל עַל פָּנָיו וְיָשֵׁן. יָשְׁבוּ. כְּשֶׁהִתְעוֹרֵר, רָאוּ שֶׁפָּנָיו מְחַיְּכוֹת. אָמַר לוֹ רַבִּי אַבָּא, דָּבָר חָדָשׁ רָאִיתָ? אָמַר לוֹ, וַדַּאי, שֶׁעַכְשָׁו עָלְתָה נַפְשִׁי, וְרָאִיתִי אֶת הַכָּבוֹד שֶׁל אוֹתָם שֶׁמָּסְרוּ עַצְמָם עַל קְדֻשַּׁת רִבּוֹנָם, שֶׁהָיוּ נִכְנָסִים בִּשְׁלֹשָׁה עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן טָהוֹר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִמָּם, וְרָאִיתִי מַה שֶּׁלֹּא נָתְנוּ לִי רְשׁוּת לוֹמַר. וְשָׁאַלְתִּי אוֹתָם, אָמַרְתִּי שֶׁל מִי הַכָּבוֹד הַזֶּה? אָמְרוּ לִי, שֶׁל אוֹתָם שֶׁאָהֲבוּ אֶת רִבּוֹנָם בְּאוֹתוֹ הָעוֹלָם. וּמִמַּה שֶּׁרָאִיתִי הוּאֲרוּ נַפְשִׁי וְלִבִּי, וְעַל כֵּן פָּנַי מְחַיְּכוֹת.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, אַשְׁרֵי חֶלְקְךְ, אֲבָל הַתּוֹרָה מְעִידָה עֲלֵיהֶם, שֶׁכָּתוּב <Nonesmall>[ישעיה סד]</small> עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. אָמַר לוֹ רַבִּי יְהוּדָה, הֲרֵי שָׁאֲלוּ הַחֲבֵרִים, זֶה שֶׁכָּתוּב יַעֲשֶׂה, הָיָה צָרִיךְ לוֹ לִהְיוֹת תַּעֲשֶׂה!</p>\n<p>אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, אֲבָל סוֹד הַדָּבָר הַיְנוּ שֶׁכָּתוּב <Nonesmall>[תהלים כז]</small> לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. וּפֵרְשׁוּהָ, נֹעַם ה', אוֹתוֹ שֶׁבָּא מֵהָעַתִּיק הַקָּדוֹשׁ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בּוֹ, שֶׁהֲרֵי אוֹתוֹ נֹעַם יוֹצֵא מֵהָעַתִּיק. וּלְבַקֵּר בְּהֵיכָלוֹ, בַּהֵיכָל הָעֶלְיוֹן עַל הַכֹּל. אַף כָּאן, עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה – מִי? אוֹתוֹ הָעַתִּיק הַנִּסְתָּר שֶׁל הַכֹּל, שֶׁהֲרֵי בּוֹ תָּלוּי. אָמַר לוֹ, וַדַּאי כָּךְ הוּא. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁבְּאַהֲבַת רִבּוֹנָם נִדְבָּקִים בָּהֶם, לְאֵלֶּה אֵין שִׁעוּר לְחֶלְקָם בָּעוֹלָם הַהוּא.</p>\n<p>אָמַר רַבִּי יִצְחָק, כַּמָּה מְדוֹרִים עַל מְדוֹרִים יֵשׁ לַצַּדִּיקִים בָּעוֹלָם הַהוּא, וְהַמָּדוֹר הָעֶלְיוֹן שֶׁל הַכֹּל – אוֹתָם שֶׁנִּקְשְׁרָה בָהֶם אַהֲבַת רִבּוֹנָם, שֶׁהֲרֵי מְדוֹרָם נִקְשָׁר לַהֵיכָל שֶׁעוֹלֶה עַל הַכֹּל. מָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בָּזֶה.</p>\n<p>בֹּא וּרְאֵה, <Nonesmall>[הכל אהבה]</small> הַהֵיכָל הַזֶּה נִקְרָא אַהֲבָה, וּבִשְׁבִיל הָאַהֲבָה הַכֹּל קַיָּם, כַּכָּתוּב <Nonesmall>[שיר השירים ח]</small> מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה. וְהַכֹּל קַיָּם בְּאַהֲבָה, שֶׁהֲרֵי הַשֵּׁם הַקָּדוֹשׁ כָּךְ נִמְצָא, שֶׁהֲרֵי פֵּרְשׁוּהָ, י' לֹא נִפְרָד הַקּוֹץ שֶׁלְּמַעְלָה מִן י' לְעוֹלָמִים, שֶׁהֲרֵי בְּאַהֲבָה שׁוֹרֶה עָלָיו, וְלֹא נִפְרָד מִמֶּנּוּ לְעוֹלָמִים. ה' הֲרֵי פֵּרְשׁוּהָ, שֶׁי' לֹא נִפְרֶדֶת מִמֶּנָּה, וְנִמְצָאוֹת יַחַד בַּחֲבִיבוּת, לֹא נִפְרָדוֹת זוֹ מִזּוֹ. כְּמוֹ כֵן ה', וַהֲרֵי נִתְבָּאֵר, כְּמוֹ שֶׁכָּתוּב <Nonesmall>[בראשית ב]</small> וְנָהָר יֹצֵא מֵעֵדֶן, יוֹצֵא תָמִיד לְעוֹלָמִים, נִדְבָּקִים בַּחֲבִיבוּת.</p>\n<p>ו\"ה כְּשֶׁנִּדְבָּקוֹת זוֹ בָּזוֹ, נִדְבָּקוֹת יַחַד בַּחֲבִיבוּת, חָתָן עִם כַּלָּה, שֶׁדַּרְכָּן תָּמִיד נִמְצֵאת בַּחֲבִיבוּת. י' עִם ה', ה' עִם ו', ו' עִם ה', וְזוֹ עִם זוֹ נִקְשָׁרוֹת בַּחֲבִיבוּת, וְהַכֹּל נִקְרָא אַהֲבָה. וְעַל כֵּן מִי שֶׁאוֹהֵב אֶת הַמֶּלֶךְ, הֲרֵי הוּא נִקְשָׁר בְּאוֹתָהּ הָאַהֲבָה, וּמִשּׁוּם כָּךְ וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ.</p>"],[9522012595,"<p>וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ'. רַבִּי יִצְחָק פָּתַח, <Nonesmall>[תהלים לה]</small> כָּל עַצְמֹתַי תֹּאמַרְנָה ה' מִי כָמוֹךְ מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ וְעָנִי וְאֶבְיוֹן מִגֹּזְלוֹ. פָּסוּק זֶה אָמַר אוֹתוֹ דָּוִד בְּרוּחַ הַקֹּדֶשׁ. כָּל עַצְמֹתַי תֹּאמַרְנָה, וְכִי מִי רָאָה עֲצָמוֹת שֶׁאוֹמְרוֹת שִׁירָה? אֶלָּא הַפָּסוּק הַזֶּה בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַחֲיוֹת אֶת הַמֵּתִים, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַתְקִין הָעֲצָמוֹת וּלְקָרֵב כָּל אַחַת וְאַחַת לִמְקוֹמָן, שֶׁכָּתוּב <Nonesmall>[יחזקאל לז]</small> וַתִּקְרְבוּ עֲצָמוֹת עֶצֶם אֶל עַצְמוֹ, וְכָתוּב <Nonesmall>[ישעיה נח]</small> וְעַצְמֹתֶיךְ יַחֲלִיץ. אָז עֲתִידוֹת הֵן לוֹמַר שִׁירָה.</p>\n<p>אֵיזוֹ שִׁירָה אוֹמְרוֹת? ה' מִי כָמוֹךְ <Nonesmall>[מקדימים]</small>, וְזוֹ הַשִּׁירָה הַמְעֻלָּה מִמַּה שֶּׁאָמְרוּ יִשְׂרָאֵל עַל הַיָּם, שֶׁהֲרֵי הֵם לֹא הִזְכִּירוּ אֶת הַשֵּׁם הַקָּדוֹשׁ אֶלָּא אַחֲרֵי שָׁלֹשׁ מִלִּים, שֶׁכָּתוּב <Nonesmall>[שמות טו]</small> מִי כָמֹכָה בָּאֵלִם ה'. וְכָאן הֵם מַקְדִּימִים אֶת הַשֵּׁם הַקָּדוֹשׁ, שֶׁכָּתוּב ה' מִי כָמוֹךְ. מַצִּיל עָנִי מֵחָזָק מִמֶּנּוּ – זֶה יֵצֶר טוֹב מִיֵּצֶר הָרָע, מִשּׁוּם שֶׁיֵּצֶר הָרָע תַּקִּיף הוּא כְּמוֹ אֶבֶן, כַּכָּתוּב <Nonesmall>[יחזקאל לו]</small> וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן, וְיֵצֶר הַטּוֹב הוּא בָּשָׂר, שֶׁכָּתוּב וְנָתַתִּי לָכֶם לֵב בָּשָׂר.</p>"],[9522012596,"<p>בֹּא וּרְאֵה, יֵצֶר הָרָע לְמָה הוּא דּוֹמֶה? בְּשָׁעָה שֶׁהוּא בָּא לְהִזְדַּוֵּג עִם הָאָדָם הוּא כְּמוֹ בַּרְזֶל, עַד שֶׁמַּכְנִיסִים אוֹתוֹ לָאֵשׁ. אַחַר שֶׁיִּתְחַמֵּם, הַכֹּל חוֹזֵר כָּאֵשׁ.</p>\n<p>רַבִּי חִיָּיא אָמַר, כְּשֶׁבָּא יֵצֶר הָרָע לְהִזְדַּוֵּג עִם הָאָדָם, דּוֹמֶה לְאִישׁ שֶׁקָּרֵב לְפֶתַח וְרוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, נִכְנָס לַבַּיִת וְנַעֲשֶׂה לוֹ אוֹרֵחַ. רוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, וְיֵלֵךְ לוֹ לְדַרְכּוֹ. כֵּיוָן שֶׁנִּכְנָס לַבַּיִת וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ, מִתְמַנֶּה עָלָיו וְנַעֲשֶׂה בַּעַל הַבַּיִת, עַד שֶׁנִּמְצָא שֶׁכָּל הַבַּיִת עוֹמֵד לִרְשׁוּתוֹ.</p>\n<p>מִמִּי לָמַדְנוּ? מִפָּרָשַׁת דָּוִד לָמַדְנוּ. מַה כָּתוּב? <Nonesmall>[שמואל ב יב]</small> וַיָּבֹא הֵלֶךְ לְאִישׁ הֶעָשִׁיר. הֵלֶךְ שֶׁקָּרֵב לַפֶּתַח וְלֹא רוֹצֶה לְהִתְעַכֵּב שָׁם, אֶלָּא לָלֶכֶת לְדַרְכּוֹ. כָּךְ הוּא יֵצֶר הָרָע, כְּמוֹ שֶׁקָּרֵב לַבַּיִת מִתְקָרֵב לָאָדָם. מִתְעוֹרֵר עָלָיו בְּחֵטְא קָטָן, זֶהוּ אוֹרֵחַ עֲרַאי. רוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, מַה כָּתוּב? לַעֲשׂוֹת לָאֹרֵחַ הַבָּא לוֹ [אליו], נַעֲשֶׂה לוֹ אוֹרֵחַ אַכְסְנַאי בַּבַּיִת, מִתְעוֹרֵר עָלָיו בְּחֵטְא יוֹתֵר, יוֹם אֶחָד אוֹ יוֹמַיִם, כָּאוֹרֵחַ הַזֶּה שֶׁמַּשְׁהִים אוֹתוֹ בַּבַּיִת יוֹם אֶחָד אוֹ יוֹמַיִם, <Nonesmall>[בגלל שהוא אורח]</small> כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין מִי שֶׁמּוֹחֶה בְיָדוֹ, מַה כָּתוּב? <Nonesmall>[שם]</small> וַיַּעֲשֶׂ [ה] לָאִישׁ הַבָּא אֵלָיו, נַעֲשָׂה בַּעַל הַבַּיִת, כְּמוֹ שֶׁנֶּאֱמר <Nonesmall>[בראשית מב]</small> הָאִישׁ אֲדנֵי הָאָרֶץ. <Nonesmall>[רות א]</small> אִישׁ נָעֳמִי. כָּךְ הוּא יֵצֶר הָרָע, נַעֲשֶׂה כְנֶגֶד הָאָדָם אִישׁ, בַּעַל הַבַּיִת, וְהִנֵּה נִקְשָׁר הָאָדָם לַעֲבוֹדָתוֹ, וְהוּא עוֹשֶׂה בּוֹ כִּרְצוֹנוֹ.</p>\n<p>וְעַל כֵּן צָרִיךְ אָדָם לָשִׂים דִּבְרֵי תוֹרָה עָלָיו תָּמִיד, כְּדֵי שֶׁיִּהְיֶה אוֹתוֹ יֵצֶר הָרָע שָׁבוּר בָּהֶם, שֶׁאֵין לַיֵּצֶר הָרָע מְקַטְרֵג פְּרָט לְדִבְרֵי תוֹרָה, וְעַל כֵּן כָּתוּב וְהָיוּ הַדְּבָרִים הָאֵלֶּה וְגוֹ', עַל לְבָבְךְ – עַל שְׁנֵי יְצָרֶיךְ, שֶׁיֵּצֶר הַטּוֹב מִתְעַטֵּר בָּהֶם, וְיֵצֶר הָרָע נִכְנָע בָּהֶם. אָמַר רַבִּי יְהוּדָה, מַה יֵּצֶר הַטּוֹב צָרִיךְ דִּבְרֵי תוֹרָה? אָמַר לוֹ, יֵצֶר הַטּוֹב מִתְעַטֵּר בָּהֶם. וְיֵצֶר הָרָע, כֵּיוָן שֶׁרוֹאֶה שֶׁאָדָם לֹא שָׁב וְלֹא רוֹצֶה לְהִשְׁתַּדֵּל בַּתּוֹרָה, אָז הוּא עוֹלֶה לְמַעְלָה וּמְלַמֵּד עָלָיו חוֹבָה, זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי ג]</small> וּכְסִילִים מֵרִים קָלוֹן.</p>"],[9522012597,"<p>כְּשֶׁבָּא רַבִּי שִׁמְעוֹן, אָמַר, הֲרֵי וַדַּאי פָּרָשַׁת קְרִיאַת שְׁמַע רְמוּזָה בּוֹ עֶשֶׂר אֲמִירוֹת כְּמוֹ שֶׁבֵּאֲרוּהָ, וְכָךְ הוּא וַדַּאי. וְהָיוּ הַדְּבָרִים הָאֵלֶּה, הֵם הַכְּלָל שֶׁל עֶשֶׂר הָאֲמִירוֹת, וּמִשּׁוּם כָּךְ יֵשׁ כָּאן עֶשֶׂר מִצְווֹת, כְּנֶגֶד עֶשֶׂר מִצְווֹת שֶׁל הַתּוֹרָה. וּמִי הֵן? וְשִׁנַּנְתָּם לְבָנֶיךְ. וְדִבַּרְתָּ בָּם. בְּשִׁבְתְּךְ בְּבֵיתֶךְ. וּבְלֶכְתְּךְ בַדֶּרֶךְ. וּבְשָׁכְבְּךְ. וּבְקוּמֶךְ. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךְ. וְהָיוּ לְ טָפֹת בֵּין עֵינֶיךְ. וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךְ. וּבִשְׁעָרֶיךְ. הֲרֵי עֶשֶׂר כְּנֶגֶד עֶשֶׂר אֲמִירוֹת. וְעַל כֵּן הַפָּרָשִׁיּוֹת הַלָּלוּ הֵן כְּלָל גָּדוֹל בַּתּוֹרָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמַּשְׁלִים אוֹתוֹ בְּכָל יוֹם פַּעֲמַיִם, שֶׁהֲרֵי הִתְקַדֵּשׁ בְּפִיו הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי.</p>\n<p>רַבִּי אָחָא הָיָה עוֹמֵד עִם רַבִּי אֶלְעָזָר לַיְלָה אֶחָד אַחֲרֵי חֲצוֹת הַלַּיְלָה, וְהָיוּ עוֹסְקִים בַּתּוֹרָה. פָּתַח רַבִּי אֶלְעָזָר <Nonesmall>[רבי אחא]</small> וְאָמַר, <Nonesmall>[דברים ל]</small> כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ וְגוֹ'. בֹּא וּרְאֵה, עַל כָּל הַתְּנָאִים <Nonesmall>[המצוות]</small> שֶׁגָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנִּכְנְסוּ לְאֶרֶץ יִשְׂרָאֵל, גְּזֵרַת הַתּוֹרָה הָיְתָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהַשְּׁכִינָה לֹא מִתְיַשֶּׁבֶת בָּאָרֶץ אֶלָּא בַּתּוֹרָה, וְלֹא מִתְיַשֶּׁבֶת לְמַעְלָה אֶלָּא בַּתּוֹרָה.</p>"],[9522012598,"<p>שֶׁכָּךָ אָמַר <Nonesmall>[רבי שמעון]</small> אַבָּא, תּוֹרָה שֶׁבְּעַל פֶּה לֹא נוֹדַעַת, אֶלָּא בִּשְׁבִיל תּוֹרָה שֶׁבִּכְתָב. הַשְּׁכִינָה לֹא מִתְיַשֶּׁבֶת לְמַעְלָה וּלְמַטָּה, אֶלָּא עִם הַתּוֹרָה שֶׁלְּמַטָּה. שֶׁכָּל זְמַן שֶׁהַתּוֹרָה נִמְצֵאת עִמּוֹ, יָכוֹל לַעֲמֹד בָּעוֹלָם. <Nonesmall>[תורה שבכתב לא נודעת אלא משום תורה שבעל פה, ותורה שבעל פה לא נודעת אלא מתורה שבכתב. ודאי כלל הצריך לפרט, ופרט הצריך לכלל. השכינה לא מתישבת למעלה אלא בתורה שלמטה. שכל זמן שהתורה נמצאת, יכולה להתקים בעולם]</small> זֶהוּ שֶׁכָּתוּב כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ לָשֶׁבֶת עַל הָאֲדָמָה. עַל הָאֲדָמָה סְתָם. וְאִם לֹא שֶׁמַּפְסִיק דִּבְרֵי תוֹרָה, לֹא יָכוֹל לַעֲמֹד, שֶׁכָּתוּב <Nonesmall>[ירמיה ט]</small> עַל מָה אָבְדָה הָאָרֶץ. וְכָתוּב, וַיֹּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי.</p>\n<p>בְּעוֹדָם יוֹשְׁבִים, הִנְמִיךְ רַבִּי שִׁמְעוֹן אֶת רֹאשׁוֹ וְאָמַר, וַדַּאי כָּךְ הוּא, וְזֶהוּ הַסּוֹד שֶׁמָּצָאנוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וּבֵאֵר הַפָּסוּק הַזֶּה בְּסוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב <Nonesmall>[שמות כא]</small> שְׁאֵרָהּ כְּסוּתָהּ וְעֹנָתָהּ לֹא יִגְרָע. וְאִם מוֹנְעִים מִמֶּנָּה, מַה כָּתוּב? וְיָצְאָה חִנָּם אֵין כָּסֶף, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[ישעיה נ]</small> אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. וְכָתוּב <Nonesmall>[שם נב]</small> חִנָּם נִמְכַּרְתֶּם וְלֹא בְכֶסֶף תִּגָּאֵלוּ. וּמִי שֶׁמּוֹנֵעַ מִמֶּנָּה תּוֹרָה, כְּמִי שֶׁלּוֹקֵחַ בַּעַל <Nonesmall>[שארה]</small> שֶׁל אִשָּׁה וּמוֹנֵעַ אוֹתוֹ מִמֶּנָּה. זוֹ נִשְׁאֶרֶת כְּאַלְמָנָה, וְלֹא אַלְמָנָה. זֶהוּ שֶׁכָּתוּב <Nonesmall>[איכה א]</small> הָיְתָה כְּאַלְמָנָה, וְלֹא אַלְמָנָה.</p>\n<p>יָשְׁבוּ וְהִתְעַסְּקוּ בַתּוֹרָה עַד שֶׁהֵאִיר הַיּוֹם. אַחַר שֶׁהֵאִיר הַיּוֹם, קָמוּ וְהָלְכוּ. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אִישׁ אֶחָד שֶׁהָיָה הוֹלֵךְ בַּדֶּרֶךְ וְרֹאשׁוֹ עָטוּף. קָרְבוּ אֵלָיו, וְהָיָה מְרַחֵשׁ בְּשִׂפְתוֹתָיו וְלֹא הֵשִׁיב לָהֶם דָּבָר. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי זֶה נִמְלָךְ בְּרִבּוֹנוֹ. יָשְׁבוּ רַבִּי אֶלְעָזָר וְרַבִּי אָחָא וְהִתְפַּלְלוּ תְפִלָּה, וְאוֹתוֹ הָאִישׁ עָמַד בִּמְקוֹמוֹ בְּמָקוֹם אַחֵר. אַחַר שֶׁסִּיְּמוּ הַתְּפִלָּה הָלְכוּ לַדֶּרֶךְ, וְאוֹתוֹ הָאִישׁ נִשְׁמַט מֵהֶם. אָמַר רַבִּי אֶלְעָזָר, הָאִישׁ הַזֶּה, אוֹ שֶׁהוּא טִפֵּשׁ, אוֹ שֶׁדְּרָכָיו לֹא יְשָׁרוֹת. אָמַר, נִתְעַסֵּק בַּתּוֹרָה, שֶׁהֲרֵי הַשָּׁעָה הִיא לָזֶה.</p>"],[9522012599,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, <Nonesmall>[משלי ג]</small> כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְסִילִים מֵרִים קָלוֹן. כָּבוֹד חֲכָמִים יִנְחָלוּ, אַשְׁרֵי אוֹתָם שֶׁמִּתְעַסְּקִים בַּתּוֹרָה. וְטֶרֶם שֶׁפָּתַח בַּדָּבָר, קָרַב אֲלֵיהֶם אוֹתוֹ אָדָם. אָמַר רַבִּי אֶלְעָזָר, אֵין לָנוּ לְהַפְסִיק בְּדִבְרֵי תוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, זוֹכֶה לָרֶשֶׁת יְרֻשָּׁה שֶׁל הַנַּחֲלָה שֶׁלְּמַעְלָה, בַּכָּבוֹד שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, וְזוֹכֶה לָרֶשֶׁת יְרֻשָּׁה שֶׁל נַחֲלָה בָּעוֹלָם הַזֶּה. וּמִי הִיא? אוֹתוֹ שֶׁנִּקְרָא כְּבוֹד ה', שֶׁלֹּא פוֹסֵק מֵהֶם לְעוֹלָם. זֶהוּ שֶׁכָּתוּב כָּבוֹד חֲכָמִים יִנְחָלוּ, הַהוּא שֶׁנִּקְרָא כְּבוֹד ה'.</p>\n<p>וּכְסִילִים מֵרִים קָלוֹן, מַה הוּא? בֹּא וּרְאֵה, כְּשֶׁאָדָם הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִשְׁתַּדֵּל בַּתּוֹרָה, הֲרֵי אוֹתוֹ כְּבוֹד ה' הוּא יוֹרֵשׁ לְעַצְמוֹ, וְכַמָּה אֶפִּיטְרוֹפְּסִים וְסָנֵגוֹרִים נִמְצָאִים לְמַעְלָה עַל הָאָדָם, וְכֻלָּם מְלַמְּדִים עָלָיו זְכוּת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. וְאִם אֵין הָאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה וְלֹא הוֹלֵךְ בְּדֶרֶךְ רִבּוֹנוֹ, הוּא נַעֲשֶׂה עָלָיו קָטֵגוֹר. וְאוֹתוֹ קָטֵגוֹר מְשׁוֹטֵט בָּאֲוִיר <Nonesmall>[והולך לו]</small>, וְלֹא עוֹלֶה לְמַעְלָה, אוּלַי יָשׁוּב הָאָדָם מֵחֶטְאוֹ. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין הָאָדָם שָׁב וְלֹא רוֹצֶה לְהִשְׁתַּדֵּל בַּתּוֹרָה, אָז הוּא עוֹלֶה לְמַעְלָה וּמְלַמֵּד עָלָיו חוֹבָה. זֶהוּ שֶׁכָּתוּב וּכְסִילִים מֵרִים קָלוֹן, וְעוֹלֶה לְמַעְלָה וְעוֹשֶׂה קִטְרוּג.</p>\n<p>פָּתַח וְאָמַר, <Nonesmall>[זכריה יד]</small> וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְלֹא עֲלֵיהֶם תִּהְיֶה הַמַּגֵּפָה וְגוֹ'. מַה שּׁוֹנֶה מִצְרַיִם כָּאן מִכָּל שְׁאָר הָעַמִּים, שֶׁהֲרֵי לְכֻלָּם כָּתוּב וְלֹא עֲלֵיהֶם יְהִי הַגָּשֶׁם, וְכָאן לֹא? אֶלָּא הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁהֲרֵי אֶרֶץ מִצְרַיִם אֵינָהּ צְרִיכָה מָטָר, וְעַל כֵּן אֵינָהּ בִּכְלַל אוֹתָן שֶׁצְּרִיכוֹת מָטָר, אֲבָל הֵם, דִּין אַחֵר עוֹלֶה עֲלֵיהֶם, וְיָפֶה אָמְרוּ.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב <Nonesmall>[דברים יא]</small> כִּי הָאָרֶץ אֲשֶׁר אַתָּה בָא שָׁמָּה לְרִשְׁתָּהּ לֹא כְאֶרֶץ מִצְרַיִם הִיא אֲשֶׁר יְצָאתֶם מִשָּׁם וְגוֹ'. שֶׁהֲרֵי הַנָּהָר הָעוֹלֶה, מִמֶּנּוּ מֻשְׁקֵית הָאָרֶץ, אֲבָל כָּאן – לִמְטַר הַשָּׁמַיִם תִּשְׁתֶּה מָּיִם, שֶׁהֲרֵי הָאָרֶץ הַקְּדוֹשָׁה מֻשְׁקֵית תָּמִיד מִן הַשָּׁמַיִם, וּכְשֶׁיִּשְׂרָאֵל הָיוּ עוֹסְקִים בַּתּוֹרָה, הָיְתָה מֻשְׁקֵית כָּרָאוּי. וּמִי שֶׁמּוֹנֵעַ מִמֶּנָּה תּוֹרָה, כְּאִלּוּ מוֹנֵעַ טוֹב מִכָּל הָעוֹלָם. נִכְנְסוּ לְתוֹךְ מְעָרָה אַחַת שֶׁהָיְתָה בַּדֶּרֶךְ, נִכְנַס עִמָּהֶם אוֹתוֹ הָאִישׁ. יָשְׁבוּ.</p>\n<p>פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, <Nonesmall>[שמות לג]</small> וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים כַּאֲשֶׁר יְדַבֵּר וְגוֹ'. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ, וְלֹא מִלָּה זוֹ כְּמִלָּה זוֹ. בַּתְּחִלָּה וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים – יָפֶה. אַחַר כָּךְ וְשָׁב אֶל הַמַּחֲנֶה, אַחַר כָּךְ וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, מַהוּ? אָמַר רַבִּי אֶלְעָזָר, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בִכְבוֹדֵנוּ, שֶׁכָּעֵת הַזִוּוּג שֶׁלָּנוּ עִם הַשְּׁכִינָה, וְהַשְּׁכִינָה לֹא סָרָה מֵעִמָּנוּ. מִי שֶׁפּוֹתֵחַ פֶּתַח, יֹאמַר דָּבָר.</p>"],[9522012600,"<p>פָּתַח וְאָמַר, וְדִבֶּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים, בְּכַמָּה דְרָגוֹת עֶלְיוֹנוֹת וְנִכְבָּדוֹת נִפְרָד מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם, שֶׁהֲרֵי כֻּלָּם כְּנֶגְדּוֹ כְּמוֹ קוֹף בִּפְנֵי בְּנֵי אָדָם. שְׁאָר הַנְּבִיאִים הָיוּ מִסְתַּכְּלִים בְּאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, וְעִם כָּל זֶה לֹא הָיוּ זוֹקְפִים פָּנִים לְמַעְלָה לְהִסְתַּכֵּל, אֶלָּא כְּמוֹ שֶׁכָּתוּב <Nonesmall>[דניאל י]</small> וַאֲנִי הָיִיתִי נִרְדָּם עַל פָּנַי וּפָנַי אָרְצָה. וְלֹא עוֹד, אֶלָּא שֶׁהַדְּבָרִים לֹא הָיוּ אֲלֵיהֶם בְּגָלוּי.</p>\n<p>וּמֹשֶׁה הַנָּבִיא הַנֶּאֱמָן לֹא כָּךְ, שֶׁהוּא הָיָה מִסְתַּכֵּל בְּאַסְפַּקְלַרְיָה הַמְּאִירָה וְעוֹמֵד בְּקִיּוּמוֹ, וְלֹא עוֹד, אֶלָּא שֶׁהָיָה זוֹקֵף רֹאשׁ לְהִסְתַּכֵּל, כְּמִי שֶׁאוֹמֵר לַחֲבֵרוֹ: זְקֹף רֹאשְׁךְ, וְיִסְתַּכְּלוּ פָנֶיךְ בְּפָנַי, כְּדֵי שֶׁתֵּדַע הַדְּבָרִים שֶׁלִּי. כָּךְ מֹשֶׁה, פָּנִים אֶל פָּנִים זוֹקֵף רֹאשׁ, בְּלִי פַחַד, פָּנִים זְקוּפוֹת, וּמִסְתַּכֵּל בְּזִיו הַכָּבוֹד הָעֶלְיוֹן, וְלֹא הִשְׁתַּנְּתָה דַעְתּוֹ וּפָנָיו כְּמוֹ שְׁאָר הַנְּבִיאִים, שֶׁכְּשֶׁהָיוּ מִתְנַבְּאִים <Nonesmall>[רוצים]</small> לְהִסְתַּכֵּל, יָצְאוּ מֵרְשׁוּתָם וּמִדַּעְתָּם וְהִשְׁתַּנָּה זִיו פְּנֵיהֶם, וְלֹא הָיוּ יוֹדְעִים מֵהָעוֹלָם הַזֶּה כְּלוּם.</p>\n<p>וּמֹשֶׁה לֹא כָּךְ, שֶׁמֹּשֶׁה הָיָה מִסְתַּכֵּל מַמָּשׁ בַּדַּרְגָּה הָעֶלְיוֹנָה הַהִיא, וְלֹא יָצָא מֵרְשׁוּתוֹ וּמִדַּעְתּוֹ, שֶׁהֲרֵי בְּשָׁעָה שֶׁהָיָה מִסְתַּכֵּל בְּזִיו הַכָּבוֹד הָעֶלְיוֹן, מִיָּד וְשָׁב אֶל הַמַּחֲנֶה, לְדַבֵּר עִמָּהֶם בְּכָל מַה שֶּׁהִצְטָרְכוּ, וְדַעְתּוֹ מִתְיַשֶּׁבֶת בּוֹ כְּבָרִאשׁוֹנָה, וְיוֹתֵר. וְזֶהוּ וְשָׁב אֶל הַמַּחֲנֶה. וּמְשָׁרֲתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר, וַדַּאי שֶׁהָיָה יוֹנֵק מִתּוֹךְ הָאֹהֶל, לָמַד לְהִסְתַּכֵּל בְּרוּחַ הַקֹּדֶשׁ, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[שמואל א ג]</small> וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת אֶת ה'.</p>\n<p>בֹּא וּרְאֵה, כָּל זְמַן שֶׁהָיָה יְהוֹשֻׁעַ אֵצֶל מֹשֶׁה, הָיָה לוֹמֵד וְיוֹנֵק מִתּוֹךְ הָאֹהֶל וְלֹא פוֹחֵד. אַחַר שֶׁנִּפְרַד מִמֹּשֶׁה וְהָיָה לְבַדּוֹ, מַה כָּתוּב? <Nonesmall>[יהושע ה]</small> וַיִּפֹּל יְהוֹשֻׁעַ אֶל פָּנָיו אַרְצָה וַיִּשְׁתָּחוּ. שֶׁלֹּא הָיָה יָכוֹל לְהִסְתַּכֵּל. וְזֶה מִשָּׁלִיחַ אֶחָד, כָּל שֶׁכֵּן מִמָּקוֹם אַחֵר.</p>\n<p>לְאָדָם אֶחָד שֶׁהִפְקִיד אֶצְלוֹ הַמֶּלֶךְ כְּלֵי זָהָב וַאֲבָנִים יְקָרוֹת. כָּל זְמַן שֶׁנִּמְצָאִים אֶצְלוֹ, הַשַּׁמָּשׁ שֶׁל בֵּיתוֹ אוֹחֵז בָּהֶם וּמִסְתַּכֵּל בָּהֶם. כֵּיוָן שֶׁהִסְתַּלֵּק אוֹתוֹ אָדָם מֵהָעוֹלָם, לֹא הִשְׁאִיר הַמֶּלֶךְ אֵצֶל הַשַּׁמָּשׁ כְּלוּם, וְאָחַז אֶת פִּקְדוֹנוֹ. אָמַר אוֹתוֹ שַׁמָּשׁ: אוֹי עַל מַה שֶּׁאִבַּדְתִּי. בִּימֵי אֲדוֹנִי הָיוּ כָּל אֵלֶּה בְּיָדִי.</p>\n<p>כָּךָ יְהוֹשֻׁעַ, בִּימֵי מֹשֶׁה הָיָה יוֹנֵק בְּכָל יוֹם מִתּוֹךְ הָאֹהֶל וְלֹא פוֹחֵד. אַחַר שֶׁנִּפְטַר, וַיִּפֹּל יְהוֹשֻׁעַ עַל פָּנָיו. וַאֲנִי, מִשּׁוּם שֶׁאֲנִי מָצוּי בְּתוֹכֲכֶם, אֶסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה וְלֹא אֶפְחַד. אַחַר שֶׁאֶפָּרֵד מִכֶּם, וְלֹא אוּכַל לְהִסְתַּכֵּל לְבַדִּי.</p>"],[9522012601,"<p>עוֹד פָּתַח וְאָמַר, וְשִׁנַּנְתָּם לְבָנֶיךְ וְדִבַּרְתָּ בָּם וְגוֹ'. כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[תהלים מה]</small> חִצֶּיךְ שְׁנוּנִים. שֶׁצָּרִיךְ אָדָם לְחַדֵּד דִּבְרֵי תוֹרָה לִבְנוֹ כַּחֶרֶב שֶׁהִיא שְׁנוּנָה בִּשְׁנֵי הַצְּדָדִים, כְּדֵי שֶׁיַּכְנִיס לוֹ הַחִדּוּד וְהַשִּׂמְחָה בַּתּוֹרָה, וְלֹא יִמָּצֵא לִבּוֹ בְּטִפְּשׁוּת. וְדִבַּרְתָּ בָּם, כָּל דִּבְרֵי הַתּוֹרָה, לְכָל אֶחָד וְאֶחָד יֵשׁ לוֹ דֶּרֶךְ לְבַדּוֹ. וְדִבַּרְתָּ בָּם?! וּתְדַבֵּר הָיָה צָרִיךְ לוֹ לִכְתֹּב! אֶלָּא צָרִיךְ אָדָם לְהַנְהִיג עַצְמוֹ בָּהֶם, וּלְהַנְהִיג עַצְמוֹ שֶׁלֹּא יִסְטֶה לְיָמִין וְלִשְׂמֹאל.</p>\n<p>בְּשִׁבְתְּךָ בְּבֵיתֶךְ, לְהַנְהִיג עַצְמוֹ בְּבֵיתוֹ בְּדֶרֶךְ יְשָׁרָה וּבְדֶרֶךְ תְּקִינָה, שֶׁיִּלְמְדוּ מִמֶּנּוּ בְּנֵי בֵיתוֹ לְהַנְהִיג עַצְמָם בְּנַחַת וּבְשִׂמְחָה, וְלֹא יַטִּיל פַּחַד בִּבְנֵי בֵיתוֹ יוֹתֵר, וְכָל מַעֲשָׂיו בְּבֵיתוֹ בְּדֶרֶךְ תְּקִינָה. וּבְלֶכְתְּךְ בַדֶּרֶךְ, לְהַנְהִיג בְּדִבְרֵי תוֹרָה, וּלְתַקֵּן אֶת עַצְמוֹ בָהֶם כְּמוֹ שֶׁצָּרִיךְ, וּלְהַנְהִיג עַצְמוֹ בְּדַרְכֵי הַתּוֹרָה. וּמַה הוּא? כְּמוֹ שֶׁיַּעֲקֹב, לְדוֹרוֹן, לִקְרָב וְלִתְפִלָּה. וְהַתְּפִלָּה צָרִיךְ לְהִתְפַּלֵּל לְרִבּוֹנוֹ, וּמֵעַל כֻּלָּם דִּבְרֵי תוֹרָה.</p>\n<p>וּבְשָׁכְבְּךָ, לְהַנְהִיג עַצְמוֹ בְּיִרְאַת רִבּוֹנוֹ, בִּקְדֻשָּׁה וּבַעֲנָוָה, שֶׁלֹּא יִמָּצֵא חָצוּף כְּנֶגֶד רִבּוֹנוֹ. וּבְקוּמֶךְ, לָתֵת תִּשְׁבָּחוֹת לְרִבּוֹנוֹ שֶׁהֵשִׁיב נִשְׁמָתוֹ. שֶׁהֲרֵי בְּכַמָּה חִיּוּבִים הוּא נִמְצָא לִפְנֵי רִבּוֹנוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה עִמּוֹ חֶסֶד וּמֵשִׁיב אוֹתָהּ לְגוּפוֹ. וּקְשַׁרְתָּם לְאוֹת עַל [ידך] יָדְכָה, הֲרֵי פֵּרְשׁוּהָ עַל יָד כֵּהָה, וְזוֹהִי הַשְּׂמֹאל. וּבְסֵפֶר הָאַגָּדָה אָמַר, עַל יַד כֹּ\"ה, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[בראשית טו]</small> כֹּ\"ה יִהְיֶה זַרְעֶךְ.</p>"],[9522012602,"<p>וַחֲבֵרֵינוּ יוֹשְׁבֵי הַדָּרוֹם פֵּרְשׁוּהָ בַּסּוֹד שֶׁלָּהֶם, אַרְבַּע בָּתֵּי הַתְּפִלִּין כְּמוֹ זֶה <Nonesmall>[בצורה אחרת]</small>. קַדֶּשׁ לִי כָל בְּכוֹר, סְתָם – כְּנֶגֶד הַכֶּתֶר הָעֶלְיוֹן שֶׁל הַכֹּל. וְהָיָה כִּי יְבִיאֲךְ – כְּנֶגֶד חָכְמָה. שְׁמַע יִשְׂרָאֵל וְאָהַבְתָּ – כְּנֶגֶד בִּינָה. וְהָיָה – כְּנֶגֶד חֶסֶד. אַחַר כָּךְ כְּלוּלִים כֻּלָּם בִּזְרוֹעַ שְׂמֹאל שֶׁנִּקְרֵאת עֹז, וְכָתוּב <Nonesmall>[ישעיה סב]</small> וּבִזְרוֹעַ עֻזּוֹ. וְאֵין עֹז אֶלָּא תּוֹרָה, וְאֵין עֹז אֶלָּא תְּפִלִּין.</p>\n<p>וְהַדְּבָרִים לֹא מְיֻשָּׁבִים אֶצְלֵנוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהַכֶּתֶר הָעֶלְיוֹן כּוֹלֵל הַכֹּל, שֶׁאֵינוֹ בְחֶשְׁבּוֹן. וְעוֹד, וְהָיָה כִּי יְבִיאֲךְ תָּלוּי בִּיצִיאַת מִצְרַיִם, אוֹתוֹ מָקוֹם שֶׁנִּמְצֵאת בּוֹ חֵרוּת לָעֲבָדִים, וְעַל כֵּן לֹא מְתֻקָּנִים בְּדַרְכֵיהֶם. וְאָנוּ שְׁרוּיִים מֵחָכְמָה, וְכָךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אוֹתָם; <Nonesmall>[וכן]</small> אַרְבַּע לְמַעְלָה, וְאַרְבַּע לְמַטָּה, וְאַרְבַּע בִּמְקוֹם הַמֹּחַ, וְאַרְבַּע בְּמָקוֹם שֶׁשָּׁרוּי הַלֵּב. מִשּׁוּם שֶׁזֶּה נִקְשָׁר בָּזֶה.</p>\n<p>וְצָרִיךָ הָאָדָם לְהִתְעַטֵּר בָּהֶם, מִשּׁוּם שֶׁהוּא שֵׁם קָדוֹשׁ עֶלְיוֹן, שֶׁכָּתוּב <Nonesmall>[דברים כח]</small> וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה' וְגוֹ'. וְכָל מִי שֶׁמִּתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה עֶלְיוֹנָה זוֹ, נִקְרָא מֶלֶךְ בָּאָרֶץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ בָּרָקִיעַ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שיר ז]</small> מֶלֶךְ אָסוּר בָּרְהָטִים. כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ לְמַעְלָה, כָּךְ גַּם הוּא מֶלֶךְ לְמַטָּה. וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךְ, כְּדֵי שֶׁיִּהְיֶה אָדָם שָׁלֵם בַּכֹּל, וְיִמָּצֵא שָׁלֵם בַּמִּצְווֹת שֶׁל רִבּוֹנוֹ, רָשׁוּם לְמַעְלָה רָשׁוּם לְמַטָּה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, שְׁנֵי פְסוּקִים מָצָאתִי, שֶׁאַף עַל גַּב שֶׁהַכֹּל תְּלוּיִים בְּדַרְגָּה אַחַת, אֵינָם מִדַּרְגָּה אַחַת. בְּפָסוּק אֶחָד כָּתוּב, <Nonesmall>[חגי א]</small> כֹּה אָמַר ה' צְבָאוֹת. וּבְפָסוּק אֶחָד כָּתוּב, כֹּה אָמַר ה' אֱלֹהִים. מַה בֵּין זֶה לָזֶה? אֶלָּא בִּזְמַן שֶׁכָּתוּב כֹּה אָמַר ה' צְבָאוֹת, אֲזַי הַדָּבָר בָּא בְרַחֲמִים. וּבִזְמַן שֶׁכָּתוּב כֹּה אָמַר ה' אֱלֹהִים, אֲזַי הַדָּבָר בָּא בְדִין.</p>\n<p>כֹּה אָמַר ה' צְבָאוֹת, מִשּׁוּם שֶׁהַכֹּה הַזּוֹ מִתְבָּרֶכֶת מִצַּדִּיק וּמִנֵּצַח וְהוֹד, שֶׁנִּקְרָא ה' צְבָאוֹת. וְאָז הַדָּבָר בָּא בְּהִתְבַּסְּמוּת, שֶׁהֲרֵי מֵהַמָּקוֹם הַזֶּה הוּא בָּא. כֹּה אָמַר ה' אֱלֹהִים, אָז הַכֹּה הַזּוֹ יוֹנֶקֶת מִצַּד הַדִּין מִמְּקוֹם הַגְּבוּרָה הָעֶלְיוֹנָה, וְלָמַדְנוּ מֵאַבָּא שֶׁהַדִּין הוּא בְּרַחֲמִים, מִשּׁוּם שֶׁכָּתוּב ה' אֱלֹהִים.</p>\n<p>שֶׁהֲרֵי אֱלֹהִים הוּא גְּבוּרָה בְּכָל מָקוֹם. אֲדנָי, גְּבוּרָה תַחְתּוֹנָה הִיא בְּכָל מָקוֹם. וְעַל כֵּן נוֹדָעִים הַדְּבָרִים מִפִּי הַנָּבִיא, וְהוּא הָיָה מִתְכַּוֵּן לוֹמַר דָּבָר מִמְּקוֹמוֹ. וְאָז הָיוּ יוֹדְעִים בְּנֵי הָאֱמוּנָה הַלָּלוּ, מֵאֵיזֶה מָקוֹם תָּלוּי הַדָּבָר.</p>"],[9522012603,"<p>פָּתַח רַבִּי אָחָא וְאָמַר, <Nonesmall>[שופטים ה]</small> אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ ה' וְגוֹ'. בּא וּרְאֵה, הַפָּסוּק הַזֶּה הוּא סוֹד בַּסּוֹדוֹת הָעֶלְיוֹנִים. בְּשָׁעָה שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ מָסַר אֶת בֵּיתוֹ בִּידֵי הַגְּבִירָה, כָּל כְּלֵי הַזַּיִן וְהָרְמָחִים וְהַבַּלִּיסְטְרָאוֹת שֶׁלּוֹ הִפְקִיד בְּיָדֶיהָ, וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב שֶׁלּוֹ הִפְקִיד עִמָּהּ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שיר השירים ג]</small> הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ מִגִּבֹּרֵי יִשְׂרָאֵל, וַהֲרֵי פֵּרְשׁוּהָ. וּכְשֶׁנִּלְחָם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּקְרָב, עִם אוֹתָם הַגִּבּוֹרִים לוֹחֲמֵי הַקְּרָב שֶׁאָמַרְנוּ הוּא נִלְחָם, וְהֵם נִקְרָאִים מְלֻמְּדֵי מִלְחָמָה.</p>\n<p>כָּתוּב <Nonesmall>[שופטים ה]</small> מִן שָׁמַיִם נִלְחָמוּ הַכּוֹכָבִים מִמְּסִלּוֹתָם נִלְחֲמוּ עִם סִיסְרָא וְגוֹ'. וְשָׁנִינוּ, בַּשָּׁעָה הַזּוֹ שֶׁהִתְנַדְּבוּ יִשְׂרָאֵל לְגַלּוֹת אֶת הָרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרָם, אָז זוֹ <Nonesmall>[ויקרא כו]</small> חֶרֶב נֹקֶמֶת נְקַם בְּרִית, כִּנְּסָה אֶת כָּל חֵילוֹתֶיהָ וְכָל כְּלֵי הַזַּיִן וְכָל אוֹתָם לוֹחֲמֵי הַקְּרָב לְהִלָּחֵם בִּקְרָב עִם <Nonesmall>[הלבנה]</small> סִיסְרָא, וְהַכּוֹכָבִים הָיוּ שׁוֹפְכִים אֵשׁ מִלְמַעְלָה. וְאָמַר רַבִּי שִׁמְעוֹן, כָּל כּוֹכָב וְכוֹכָב יֵשׁ לוֹ שֵׁם לְבַדּוֹ, וְכֻלָּם נִקְרָאִים בְּשֵׁמוֹת.</p>\n<p>אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, הִזְדַּמְּנוּ לִנְקֹם אֶת נִקְמַת בָּנַי. שְׁתֵּי נְקָמוֹת אֲנִי עָתִיד לְהִפָּרַע מֵהֶם. נְקָמָה אַחַת שֶׁל שֵׁשׁ מֵאוֹת מֶרְכָּבוֹת שֶׁהִלְוָה לַשַּׂר הַגָּדוֹל שֶׁל הַמִּצְרִים כְּדֵי לְהִלָּחֵם בִּקְרָב עִם יִשְׂרָאֵל, שֶׁכָּתוּב <Nonesmall>[שמות יד]</small> וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְכֹל רֶכֶב מִצְרָיִם. וּנְקָמָה אַחַת שֶׁל הַבָּנִים שֶׁלִּי, שֶׁהֵצִיקוּ לָהֶם עַד עַכְשָׁו. וּמִשּׁוּם כָּךְ נִדּוֹנוּ בִּשְׁנֵי דִינִים – אֶחָד בְּמַיִם וְאֶחָד בְּאֵשׁ. בְּמַיִם, שֶׁכָּתוּב <Nonesmall>[שופטים ה]</small> נַחַל קִישׁוֹן גְּרָפָם. בְּאֵשׁ, שֶׁכָּתוּב הַכּוֹכָבִים מִמְּסִלּוֹתָם.</p>\n<p>וּבְאוֹתָם הַכּוֹכָבִים יֵשׁ כּוֹכָב אֶחָד שֶׁלֹּא בָא לְאוֹתָהּ הַנְּקָמָה, וְהִתְקַלֵּל לְעוֹלָמִים, שֶׁכַּאֲשֶׁר מַתְחִיל לְהָאִיר, בָּאִים שְׁאָר הַכּוֹכָבִים וּבוֹלְעִים אוֹתוֹ וְאֶת כָּל סִיעָתוֹ, וְכֻלָּם אוֹבְדִים יַחַד, כְּמוֹ שֶׁנֶּאֱמַר אוֹרוּ מֵרוֹז אָמַר מַלְאַךְ ה'. וְכִי יֵשׁ רְשׁוּת לְמַלְאָךְ בָּזֶה? אֶלָּא זֶה הוּא הַמַּלְאָךְ שֶׁכָּתוּב בּוֹ <Nonesmall>[שמות יד]</small> וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְזֶה הוּא שֶׁכָּל הַקְּרָבוֹת הֵן שֶׁלּוֹ.</p>\n<p>כִּי לֹא בָאוּ לְעֶזְרַת ה' – כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. לְעֶזְרַת ה' בַּגִּבּוֹרִים – עִם אוֹתָם שִׁשִּׁים גִּבּוֹרִים שֶׁהִזְדַּמְּנוּ בַּקְּרָב עִם סִיסְרָא. וְהַמַּלְאָךְ הַזֶּה, הַסּוֹד שֶׁל כָּל הַדִּינִים וְהַקְּרָבוֹת שֶׁל הַמֶּלֶךְ הֵם בִּרְשׁוּתוֹ, וְעַל כֵּן אָמַר מַלְאַךְ ה', וְזֶהוּ שֶׁכָּתוּב <Nonesmall>[בראשית מח]</small> הַמַּלְאָךְ הַגֹּאֵל אֹתִי וְגוֹ', וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. וְזֶה עָתִיד לִהְיוֹת עֶלְיוֹן וְנִכְבָּד לֶעָתִיד לָבֹא, וּבָזֶה יִתְגַּדֵּל הַשֵּׁם הַקָּדוֹשׁ, וּבָזֶה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מֵהָעַמִּים עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב <Nonesmall>[יחזקאל לח]</small> וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'. הָלְכוּ עַד שֶׁהִגִּיעוּ אֶל רַבִּי שִׁמְעוֹן. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר רַבִּי שִׁמְעוֹן, הִנֵּה הַשְּׁכִינָה כָּאן, וַדַּאי צְרִיכִים אָנוּ לְהַחֲזִיק טוֹבָה לַפָּנִים שֶׁל הַשְּׁכִינָה.</p>"],[9522012604,"<p>פָּתַח וְאָמַר, <Nonesmall>[בראשית כט]</small> הֵן עוֹד הַיּוֹם גָּדוֹל וְגוֹ'. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, שֶׁכַּאֲשֶׁר יִשְׂרָאֵל יִתְעוֹרְרוּ בִתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בִּזְכוּת הַתּוֹרָה יָשׁוּבוּ לָאָרֶץ הַקְּדוֹשָׁה וְיִתְקַבְּצוּ מִן הַגָּלוּת. שֶׁהֲרֵי וַדַּאי יוֹם אֶחָד תִּהְיֶה גָלוּת לְיִשְׂרָאֵל, וְלֹא יוֹתֵר, זֶהוּ שֶׁכָּתוּב <Nonesmall>[איכה א]</small> נְתָנַנִי שּמֵמָה כָּל הַיּוֹם דָּוָה. וְאִם לֹא יָשׁוּבוּ, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה בְּלִי זְכוּת וּבְלִי מַעֲשִׂים כְּשֵׁרִים. אֲבָל רְפוּאָה אַחַת יֵשׁ לִי לָכֶם: הַשְׁקוּ הַצּאן, הִשְׁתַּדְּלוּ בַתּוֹרָה, שֶׁתֻּשְׁקוּ מֵהַמַּיִם שֶׁל הַתּוֹרָה, וּלְכוּ רְעוּ, לְמָקוֹם שֶׁל מְנוּחָה, לְמָקוֹם טוֹב וְכִסּוּף שֶׁל נַחֲלַתְכֶם.</p>\n<p>דָּבָר אַחֵר הֵן עוֹד הַיּוֹם גָּדוֹל – זֶהוּ הַיּוֹם שֶׁנִּקְרָא <Nonesmall>[ישעיה כב]</small> יוֹם מְהוּמָה וּמְבוּסָה וּמְבוּכָה, שֶׁבְּאוֹתוֹ הַיּוֹם נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנָפְלוּ יִשְׂרָאֵל בַּגָּלוּת. וּמִשּׁוּם הַמַּעֲשִׂים הָרָעִים, הַיּוֹם הַהוּא נִמְשַׁךְ וְהִתְגַּדֵּל. זֶהוּ שֶׁכָּתוּב, הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה, מִשּׁוּם שֶׁהֵם מוֹשְׁכִים אֶת אוֹתוֹ הַיּוֹם. הַשְׁקוּ הַצֹּאן, כְּמוֹ שֶׁנֶּאֱמַר בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי בִּזְכוּת הַתּוֹרָה יֵצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת.</p>\n<p>וּמַה יִּשְׂרָאֵל אוֹמְרִים? וַיֹּאמְרוּ לֹא נוּכַל עַד אֲשֶׁר יֵאָסְפוּ כָּל הָעֲדָרִים, עַד שֶׁיִּתְכַּנְּסוּ כָּל שְׁאָר הַיָּמִים הָעֶלְיוֹנִים, וְגָלֲלוּ אֶת הָאֶבֶן, וִיבַטְּלוּ אוֹתוֹ הַדִּין הַקָּשֶׁה שֶׁל אוֹתוֹ הַיּוֹם שֶׁשּׁוֹלֵט עַל פִּי הַבְּאֵר, וְנִמְצֵאת אוֹתָהּ הַבְּאֵר עִמָּנוּ בַּגָּלוּת. וּכְשֶׁמִּתְגַּלָּה הַבְּאֵר הַזּוֹ וְאוֹתָהּ הָאֶבֶן לֹא שׁוֹלֶטֶת עָלֶיהָ, מִיָּד וְהִשְׁקִינוּ הַצּאן.</p>\n<p>וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּסוֹף הַיָּמִים לְהַחֲזִיר אֶת יִשְׂרָאֵל לָאָרֶץ הַקְּדוֹשָׁה וּלְכַנֵּס אוֹתָם מִן הַגָּלוּת. וּמִי הֵם סוֹף הַיָּמִים? אוֹתָהּ שֶׁהִיא אַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים הַזּוֹ יִשְׂרָאֵל סָבְלוּ אֶת הַגָּלוּת. זֶהוּ שֶׁכָּתוּב, <Nonesmall>[דברים ד]</small> בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וְכָתוּב <Nonesmall>[שם לא]</small> וְקָרָאת אֶתְכֶם הָרָעָה בְּאַחֲרִית הַיָּמִים. בְּאַחֲרִית הַיָּמִים דַּוְקָא, וְזוֹ הִיא כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. וְעִם אַחֲרִית הַיָּמִים הַזּוֹ קִבְּלוּ עֹנֶשׁ בַּגָּלוּת, וּבָזוֹ יַעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת לְיִשְׂרָאֵל תָּמִיד. זֶהוּ שֶׁכָּתוּב <Nonesmall>[במדבר כד]</small> אֲשֶׁר יַעֲשֶׂה הָעָם הַזֶּה לְעַמְּךְ בְּאַחֲרִית הַיָּמִים. וּבְכָל מָקוֹם זֹּאת הִיא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לַהֲשִׁיבָהּ לִמְקוֹמָהּ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה ב]</small> וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה' וְגוֹ', וְזֶהוּ יוֹם.</p>\n<p>וּמִשֶּׁהִתְחִיל הָצֵּל לְהֵעָשׂוֹת בְּרֵאשִׁית הַיּוֹם הָאַחֵר, הָיָה כְּמוֹ בִּזְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, וְנָטָה הַצֵּל לְהִכָּנֵס. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ירמיה ו]</small> אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. יוֹם וָצֵל הוּא סוֹף הַגָּלוּת, וְהַשִּׁעוּר שֶׁל הַצֵּל הַזֶּה שִׁשָּׁה קְמָצִים וָחֵצִי, וְגוּדָל שֶׁל מִדָּה שֶׁל אָדָם, גֶּבֶר בֵּין גְּבָרִים. וְהַזִּכָּרוֹן שֶׁל הַסּוֹד הַזֶּה שֶׁבֵּין הַחֲבֵרִים, שֶׁכָּתוּב <Nonesmall>[איוב ח]</small> כִּי תְמוֹל אֲנַחְנוּ וְלֹא נֵדָע כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. כִּי תְמוֹל אֲנַחְנוּ – בַּגָּלוּת, וְלֹא הָיִינוּ יוֹדְעִים כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ, לְהַשְׁרוֹת אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵי אָרֶץ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ מִי שֶׁרוֹאֶה אוֹתוֹ, וְאַשְׁרֵי חֶלְקוֹ מִי שֶׁלֹּא רוֹאֶה אוֹתוֹ. אוֹי לְמִי שֶׁיִּזְדַּמֵּן כְּשֶׁיְּבַקֵּשׁ הָאַרְיֵה הַגָּדוֹל לְהִתְחַבֵּר עִם נְקֵבָתוֹ, כָּל שֶׁכֵּן כְּשֶׁיִּזְדַּוְּגוּ יַחַד. עַל אוֹתָהּ שָׁעָה כָּתוּב, <Nonesmall>[עמוס ג]</small> אַרְיֵה שָׁאָג מִי לֹא יִירָא וְגוֹ'.</p>\n<p>בֹּא וּרְאֵה, בַּהַתְחָלָה כָּתוּב <Nonesmall>[ירמיה כה]</small> שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וּבְאוֹתוֹ הַזְּמַן כְּשֶׁיֵּצֵא לְקַבֵּל אֶת בַּת זוּגוֹ, אֲזַי אַרְיֵה שָׁאָג מִי לֹא יִירָא ה' אֱלֹהִים דִּבֶּר מִי לֹא יִנָּבֵא. בְּאוֹתָהּ שָׁעָה כָּתוּב, <Nonesmall>[דברים ל]</small> וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְגוֹ'. מַה זֶּה וְשָׁב? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב אֶת כְּנֶסֶת יִשְׂרָאֵל מֵהַגָּלוּת, וְשָׁב הַצַּדִּיק לְהִזְדַּוֵּג בִּמְקוֹמוֹ. אֲזַי כָּתוּב, <Nonesmall>[תהלים קמ]</small> אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ.</p>"],[9522012605,"<p>מִשְׁנָה, לָכֶם בְּנֵי אָדָם, בַּעֲלֵי הַחָכְמָה, בַּעֲלֵי הַתְּבוּנָה, קוֹל קוֹרֵא: מִי מִכֶּם שֶׁהִתְחַכֵּם וְיוֹדֵעַ, בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן הִתְקִין הָרֹאשׁ, רָשׁוּם מִמַּעְלָה לְמַטָּה וּמִמַּטָּה לְמַעְלָה, הִתְקִין צַד הַצָּפוֹן בְּעִטּוּר שֶׁל אֲגַם מַיִם, בּוֹ רָשׁוּם הָעֹמֶק שֶׁל הַתְּהוֹם הָעֶלְיוֹן שֶׁעוֹלֶה וְיוֹרֵד בְּתוֹכוֹ, יָרְדָה דַרְגָּה טְמִירָה אַחַת בְּאֶלֶף וַחֲמֵשׁ מֵאוֹת רִשּׁוּמִים שֶׁל אֶלֶף וַחֲמֵשׁ מֵאוֹת עוֹלָמוֹת.</p>\n<p>תַּחְתָּיו בְּצִלּוֹ חוֹסָה חַיַּת בָּר אַחַת, <Nonesmall>[דניאל ז]</small> וְלָהּ עֶשֶׂר קַרְנַיִם, <Nonesmall>[שם]</small> וְאֵלּוּ עֵינַיִם כְּמוֹ עֵינֵי אֱנוֹשׁ לַחַיָּה, וּפֶה מְדַבֵּר גְּדוֹלוֹת. כְּשֶׁעוֹלָה, הוֹלֶכֶת בַּיּוֹם, נִסְתֶּרֶת בַּלַּיְלָה. כְּשֶׁיּוֹרֶדֶת, נִסְתֶּרֶת בַּיּוֹם, וְהוֹלֶכֶת בַּלַּיְלָה. כְּשֶׁנּוֹסַעַת, מִזְדַּעְזְעִים אַרְבַּע מַגְרֵפוֹת שֶׁאֲחוּזִים בְּיָדֶיהָ. וְנוֹסְעִים עִמָּהּ שִׁשִּׁים שִׁבְטֵי אֵשׁ, כָּל אֶחָד חֶרֶב שְׁנוּנָה עַל יְרֵכוֹ.</p>\n<p>עָלָה בְרָצוֹן, לְהוֹצִיא אָדָם שַׁלִּיט לְמַטָּה. הִתְקִין בַּחַיָּה הַזּוֹ עָפָר דַּקִּיק אֶחָד שֶׁכָּלוּל מֵהַכֹּל. נָשַׁב בּוֹ וְהִתְפַּשֵּׁט בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם. וְאַרְבַּע חֲתִיכוֹת הִתְגַּלְגְּלוּ, אַחַת לְמַעְלָה, אַחַת לְמַטָּה, אַחַת לַצָּפוֹן, אַחַת לַדָּרוֹם.</p>\n<p>אִילָן אֶחָד גָּדוֹל וְחָזָק הִתְחַבֵּר וְהִזְדַּוֵּג עִמָּהּ בְּעָנָף אֶחָד יָפֶה שֶׁמַּרְאֵהוּ שִׂמְחַת הַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[תהלים מח]</small> יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ. עִמּוֹ הִזְדַּוֵּג, הוֹצִיאוּ רוּחַ טְמִירָה אַחַת, וּמִלֵּא אוֹתָהּ עִסַּת הֶעָפָר, וְעָמַד עַל רַגְלָיו, וְהִמְלִיךְ אוֹתוֹ עַל כָּל הָעוֹלָם וְהִשְׁלִיט אוֹתוֹ עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שם ח]</small> תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךְ וְגוֹ'. נִצְטַוָּה עַל אוֹתוֹ הָאִילָן, לֹא שָׁמַר אֶת הַמִּצְוָה. הֵשִׁיב הַמֶּלֶךְ אֶת רוּחוֹ אֵלָיו, וְאוֹתָהּ הַחַיָּה לָקְחָה אוֹתוֹ.</p>\n<p>אָז הִזְמִינוּ כְּלִי אַחֵר וְעָמַד בֵּינֵיהֶם, בְּקֶשֶׁר הַחִקּוּקִים בֵּין מַלְאָכִים קְדוֹשִׁים שֶׁנֶּאֶחְזוּ בַּצִּיּוּר <Nonesmall>[בדפוס]</small> שֶׁל הָעִטּוּרִים.</p>\n<p>הַדּוֹרוֹת הָאַחֲרוֹנִים תְּפוּסִים בַּחֲטָאֵיהֶם. נִשְׁלְפָה רוּחָם מֵאוֹתוֹ הַכְּלִי שֶׁל הַלְּבוּשׁ, אַחַר כָּךְ נִגְנַז בֶּעָפָר בֵּין רִגְבֵי הַנַּחַל. נִטְמְנוּ וְנִגְנְזוּ בְּעֶצֶם קָשָׁה אַחַת שֶׁל אוֹתוֹ הַכְּלִי, וְיָקוּמוּ שֵׁנִית חֲיָלוֹת חֲיָלוֹת, מִתְעוֹרְרִים בָּאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לָלוּשׁ אוֹתוֹ הֶעָפָר הָרִאשׁוֹן שֶׁל אוֹתוֹ הַכְּלִי מַמָּשׁ, וּלְהַכְנִיס בּוֹ גְּבוּל דַּק כְּמוֹ הַשְּׂאוֹר הַזֶּה שֶׁל הָעִסָּה. וּמֵאוֹתָהּ עִסָּה, שֶׁהִיא הַצַּחוּת שֶׁלְּמַעְלָה, יִתְתַּקֵּן וְיִתְיַשֵּׁר כְּלִי כָּשֵׁר, כְּמוֹ שֶׁאָמַר הַכָּתוּב, <Nonesmall>[יואל ד]</small> וּמַעְיָן מִבֵּית ה' יֵצֵא וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים. מִשּׁוּם שֶׁאוֹתוֹ הַנַּחַל מַגְדִּיל הַחֲבִיבוּת <Nonesmall>[הזנות]</small> בָּעוֹלָם. וּכְשֶׁאוֹתוֹ הַמַּעְיָן הַקָּדוֹשׁ יֵצֵא וְיִכָּנֵס אֵלָיו, אֲזַי יִתְתַּקֵּן וְיִתְיַשֵּׁר, וְלֹא יִהְיֶה בְסִרְחוֹנוֹ כְבָרִאשׁוֹנָה.</p>\n<p>וְאוֹתָם שֶׁלֹּא זוֹכִים, יָקוּמוּ לְהִדּוֹן בַּדִּין שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב <Nonesmall>[דניאל יב]</small> וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת [ו] לְדִרְאוֹן עוֹלָם. וְאָז כָּתוּב, <Nonesmall>[ישעיה סו]</small> כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עֹשֶׂה עֹמְדִים לְפָנַי נְאֻם ה' כֵּן יַעֲמֹד זַרְעֲכֶם וְשִׁמְכֶם. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012606,"<p>וְהָיָה עֵקֶב תִּשְׁמְעוּן אֵת הַמִּשְׁפָּטִים הָאֵלֶּה וְגוֹ', וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ וְגוֹ'. מִצְוָה <Nonesmall>[י\"ח]</small> זוֹ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל כָּל מַה שֶּׁאוֹכֵל וְשׁוֹתֶה וְנֶהֱנֶה בָעוֹלָם הַזֶּה. וְאִם לֹא בֵרַךְ, נִקְרָא גַזְלָן לַקָּדוֹשׁ־בָּרוּךְ־הוּא, שֶׁכָּתוּב <Nonesmall>[משלי כח]</small> גּוֹזֵל אָבִיו וְאִמּוֹ. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. מִשּׁוּם שֶׁהַבְּרָכוֹת שֶׁמְּבָרֵךְ אָדָם אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאוֹת לְהַמְשִׁיךְ חַיִּים מִמְּקוֹר הַחַיִּים לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הַקָּדוֹשׁ, וּלְהָרִיק עָלָיו מֵאוֹתוֹ הַשֶּׁמֶן הָעֶלְיוֹן, וּבָא לְהַמְשִׁיךְ מִשָּׁם לְכָל הָעוֹלָם.</p>\n<p>וְכָתוּב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ. וְאוֹתָן הַבְּרָכוֹת מוֹרִיק אָדָם בְּאוֹתָם הַדְּבָרִים מֵאוֹתוֹ הַמָּקוֹר הָעֶלְיוֹן, וּמִתְבָּרְכִים כָּל אוֹתָן הַדְּרָגוֹת וְהַמְּקוֹרוֹת, וּמִתְמַלְּאִים לְהָרִיק עַל כָּל הָעוֹלָמוֹת, וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד.</p>\n<p>וְעַל זֶה צָרִיךְ אָדָם לָשִׂים רְצוֹנוֹ בְּסוֹד הַבְּרָכוֹת, כְּדֵי שֶׁיִּתְבָּרְכוּ אָבוֹת וּבָנִים, הַכֹּל כְּאֶחָד. וּמִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא – מִתְבָּרֵךְ, וְלוֹקֵחַ חֶלְקוֹ מֵאוֹתָן הַבְּרָכוֹת, בַּתְּחִלָּה שֶׁל כָּל הָעוֹלָם שֶׁלְּמַטָּה. כֵּיוָן שֶׁשְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְבָּרֵךְ מִשָּׁם, יוֹרֵד וְשׁוֹרֶה עַל רֹאשׁוֹ הַחֵלֶק הָרִאשׁוֹן. וַהֲרֵי בֵּאַרְנוּ שֶׁכָּתוּב, <Nonesmall>[שמות כ]</small> בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי אָבֹא אֵלֶיךְ וּבֵרַכְתִּיךְ. <Nonesmall>[אזכיר, כמו שנאמר <Nonesmall>[תהלים כ]</small> יזכר כל מנחתך]</small> כֵּיוָן שֶׁאוֹתָהּ בְּרָכָה בָּאָה וְשׁוֹרָה עַל רֹאשׁוֹ, מִשָּׁם מִתְפַּשֶּׁטֶת בְּכָל הָעוֹלָם.</p>\n<p>בְּשָׁעָה שֶׁאוֹתָן הַבְּרָכוֹת יוֹרְדוֹת, מִתְעַטְּרוֹת בְּתוֹךְ שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים, וּפוֹגְשׁוֹת בָּהֶן כַּמָּה דְרָגוֹת שֶׁל מְמֻנִּים בָּעוֹלָם, וְיוֹרְדוֹת עִמָּן, וְאוֹמְרוֹת וּמַכְרִיזוֹת: זֶהוּ הַדּוֹרוֹן שֶׁשָּׁלַח פְּלוֹנִי לַקָּדוֹשׁ־בָּרוּךְ־הוּא. מֵאֵיזֶה מָקוֹם יוֹרְדוֹת? לְאַחַר שֶׁיּוֹרְדוֹת מִמְּקוֹם רֹאשׁ אֶחָד שֶׁל הַצַּדִּיק, שָׁם עוֹלוֹת, מִתְעוֹרְרוֹת לְהוֹרִיד אֲחֵרוֹת מִלְמַעְלָה, וּמִתְמַלֵּא מִלְמַעְלָה וּמִלְּמַטָּה. זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי י]</small> בְּרָכוֹת לְרֹאשׁ צַדִּיק. כֵּיוָן שֶׁדַּרְגָּה זוֹ מִתְמַלֵּאת, מוֹרִיקָה לַכַּלָּה הַזּוֹ, וּמִשָּׁם שׁוֹפְעוֹת וְנִמְשָׁכוֹת לְמַטָּה.</p>\n<p>כְּשֶׁעוֹלוֹת אוֹתָן הַבְּרָכוֹת מִלְּמַטָּה, אֵין פֶּתַח וּפֶתַח לְמַעְלָה, וְאֵין מְמֻנֶּה לְמַעְלָה שֶׁלֹּא פוֹתֵחַ אֶת כָּל אוֹתָם הַפְּתָחִים. וּמַכְרִיזִים וְאוֹמְרִים בְּכָל אוֹתָם הָרְקִיעִים: זֶהוּ דּוֹרוֹן שֶׁל הַמֶּלֶךְ שֶׁשָּׁלַח פְּלוֹנִי, זֶהוּ דּוֹרוֹן בְּקִיּוּם כָּרָאוּי. וּמִי הוּא? הַבְּרָכָה שֶׁהֵשִׁיבוּ עָלֶיהָ אָמֵן. שֶׁכָּל בְּרָכָה שֶׁהֵשִׁיבוּ עָלֶיהָ אָמֵן, זוֹהִי בְּקִיּוּם כָּרָאוּי.</p>\n<p>וְכֵיוָן שֶׁהַבְּרָכָה הַזּוֹ עוֹלָה, כָּל הַדְּרָגוֹת שֶׁלְּמַעְלָה מְזֻמָּנוֹת לְאוֹתוֹ הָאוֹר שֶׁלֹּא מֵאִיר כְּדֵי לְהָאִיר לָהּ. וְכָל שֶׁכֵּן אִם הִיא בְּרָכָה שֶׁרַבִּים מְבָרְכִים אוֹתָהּ וּמְעַטְּרִים אוֹתָהּ בַּעֲטָרוֹת קְדוֹשׁוֹת בְּסוֹד שֶׁל אָמֵן. אָמֵן הוּא סוֹד הַקְּשָׁרִים שֶׁל כָּל יִחוּד וּקְדֻשָּׁה בַּסּוֹד שֶׁל רִבּוֹנוֹ, וּמְעַטֵּר אוֹתָהּ הַבְּרָכָה בַּעֲטָרוֹת עֶלְיוֹנוֹת כָּרָאוּי.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא מִתְרַצֶּה בָהֶם, בְּאוֹתָם שֶׁמְּבָרְכִים אוֹתוֹ, וּתְשׁוּקָתוֹ בַּבְּרָכָה שֶׁלְּמַטָּה, שֶׁאוֹתָהּ בְּרָכָה עוֹלָה, וּמֵאִיר הַמָּאוֹר שֶׁלֹּא מֵאִיר, וּמְחַזֵּק אוֹתָהּ בְּתֹקֶף חָזָק לַעֲלוֹת לְמַעְלָה. וְעַל הַסּוֹד הַזֶּה כָּתוּב, <Nonesmall>[שמואל א כ]</small> כִּי מְכַבְּדַי אֲכַבֵּד – אֵלֶּה אוֹתָם שֶׁמְּבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבֹזַי יֵקָלּוּ – אֵלֶּה אוֹתָם שֶׁלֹּא מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמוֹנְעִים בְּרָכָה מִפִּיהֶם.</p>\n<p>סוֹד הַסּוֹדוֹת לְאוֹתָם שֶׁיּוֹדְעִים חָכְמַת רִבּוֹנָם, לָדַעַת אֶת סוֹד הַבְּרָכוֹת בְּמִצְווֹת הַתּוֹרָה וּבְכָל הַהֲנָאוֹת וְהַכִּסּוּפִים שֶׁל הָעוֹלָם הַזֶּה, לְהוֹרִיק בְּרָכוֹת מִלְמַעְלָה לְמַטָּה.</p>\n<p>כַּאֲשֶׁר <Nonesmall>[פרט]</small> בִּרְכוֹת הַתְּפִלָּה, שֶׁהֵן תִּקּוּן שֶׁל רִבּוֹנָם מִלְּמַטָּה לְמַעְלָה וּמִלְמַעְלָה לְמַטָּה. הַבְּרָכוֹת שֶׁאֵינָן בַּתְּפִלָּה עוֹלוֹת מִלְּמַטָּה לְמַעְלָה, עַד שֶׁמַּגִּיעוֹת לְתוֹךְ הָאוֹר שֶׁלֹּא מֵאִיר, וּמִתְעוֹרְרִים <Nonesmall>[למעלה]</small> בְּתֹקֶף לְאוֹתוֹ הָאוֹר שֶׁלֹּא מֵאִיר בְּאוֹתָהּ הַבְּרָכָה, וְעוֹלָה הִתְעוֹרְרוּת לְמַעְלָה, עַד שֶׁמַּגִּיעִים לַכִּסֵּא הָעֶלְיוֹן, מְקוֹר כָּל הַחַיִּים. וְאָז יוֹצְאוֹת מֵאוֹתוֹ הַמָּקוֹר הָעֶלְיוֹן בְּרָכוֹת אֲחֵרוֹת, וּפוֹגְשׁוֹת אֵלֶּה בְאֵלֶּה, וְנוֹשְׁקוֹת אֵלֶּה לְאֵלֶּה, וּבָאוֹת וְשׁוֹרוֹת עַל רֹאשׁ הַצַּדִּיק לְהָרִיק לְמַטָּה. וּכְשֶׁיּוֹרְדוֹת, מִתְבָּרְכִים הָאָבוֹת וְהַבָּנִים וְכָל נֵרוֹתֵיהֶם.</p>\n<p>וְסוֹד הַבְּרָכוֹת הַלָּלוּ לְעוֹרֵר מִלְמַעְלָה לְמַטָּה בְּסוֹד זֶה: בָּרוּךְ: זֶה הַסּוֹד שֶׁל הַמָּקוֹר הָעֶלְיוֹן מֵהַכֹּל, לְהָרִיק וּלְהַמְשִׁיךְ וּלְהָאִיר אֶת כָּל הַמְּאוֹרוֹת. וְהוּא תָּמִיד בָּרוּךְ <Nonesmall>[מברך]</small>, שֶׁלֹּא פוֹסְקִים מֵימָיו. וּמִשָּׁם הָרֵאשִׁית שֶׁנִּקְרֵאת הָעוֹלָם הַבָּא, וְהוּא קְצֵה הַשָּׁמַיִם, שֶׁאוֹתוֹ קָצֶה הוּא קָצֶה עֶלְיוֹן. מִשּׁוּם שֶׁיֵּשׁ קָצֶה כְּמוֹ זֶה לְמַטָּה, וְהוּא הָעוֹלָם הַתַּחְתּוֹן. וְגַם הוּא נִקְרָא בָּרוּךְ, כְּנֶגֶד הַתַּחְתּוֹנִים, לְהָרִיק לְמַטָּה, וּלְהִתְעוֹרֵר מִלְּמַטָּה לְמַעְלָה בְּבִרְכוֹת הַתְּפִלָּה. וְהַבָּרוּךְ <Nonesmall>[הראשון]</small> הַזֶּה נִקְרָא כָּאן, בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה, שֶׁמְּמַלֵּא אוֹתוֹ הַמָּקוֹם, בִּשְׁבִיל אֶחָד דַּקִּיק שֶׁנִּכְנָס בּוֹ.</p>\n<p>אַתָּה, אַחַר כָּךְ מַתְחִיל לְהִתְגַּלּוֹת, שֶׁהֲרֵי הַבָּרוּךְ הַזֶּה הוּא נִסְתָּר, וְלָכֵן נִקְרָא בְּדֶרֶךְ נִסְתָּר בָּרוּךְ, הַמָּקוֹר הָעֶלְיוֹן שֶׁלֹּא הִתְגַּלָּה. אַתָּה: הָרֵאשִׁית לְהִתְגַּלּוֹת בַּחוּץ, וְלָכֵן נִקְרָא אַתָּה. וּמִיהוּ? זֶה סוֹד הַיָּמִין, וְנִקְרָא כֹּהֵן אֵצֶל אוֹתוֹ מָקוֹם. וְזֶה סוֹד <Nonesmall>[תהלים קי]</small> אַתָּה כֹהֵן לְעוֹלָם. מִי הַכֹּהֵן לְאוֹתוֹ עוֹלָם? אַתָּה. וְזֶהוּ הַיָּמִין הָעֶלְיוֹן, שֶׁהֲרֵי נִמְצָא לְהִ תְגַּלּוֹת.</p>\n<p>יְהֹוָה, זֶה סוֹד הָאֶמְצַע, סוֹד הָאֱמוּנָה בְּכָל הַצְּדָדִים. אֱלֹהֵינוּ: זֶה סוֹד הַשְּׂמֹאל שֶׁכָּלוּל בְּיָמִין, וְהַיָּמִין בּוֹ, וְנִכְלָלִים זֶה בָּזֶה לִהְיוֹת אֶחָד. וְעַד כָּאן נִקְשְׁרוּ הַבְּרָכוֹת, שֶׁכֵּיוָן שֶׁאֵלֶּה מִתְבָּרְכִים, כֻּלָּם שֶׁלְּמַטָּה מִתְבָּרְכִים.</p>\n<p>לְאַחַר שֶׁהֵם מִתְבָּרְכִים וְלוֹקְחִים בְּרָכוֹת לְעַצְמָם, חוֹזְרִים כְּלוּלִים כְּאֶחָד לְאוֹתוֹ הַמָּקוֹר, שֶׁהֵם לֹא יְכוֹלִים לַחֲזֹּר לְאוֹתוֹ הַמָּקוֹם עַד שֶׁמִּתְבָּרְכִים. כֵּיוָן שֶׁהִתְבָּרְכוּ בַתְּחִלָּה, חוֹזְרִים וְנִכְנָסִים לְאוֹתוֹ מָקוֹם, לָקַחַת בְּרָכוֹת יְתֵרוֹת אֲחֵרוֹת לְהָרִיק לְמַטָּה. וְעַד שֶׁהֵם מִתְבָּרְכִים, לֹא נִכְנָסִים וְלֹא תְאֵבִים אֵלָיו, וְזֶה סוֹד <Nonesmall>[שמות כג]</small> וְלֹא יֵרָאוּ פָנַי רֵיקָם.</p>\n<p>וּכְשֶׁשָּׁבִים לְאוֹתוֹ מָקוֹם וְנִכְנָסִים לְשָׁם, אָז אוֹתוֹ מָקוֹם נִקְרָא מֶלֶךְ. וּמֶלֶךְ לֹא נִקְרָא, רַק כְּשֶׁהֵם מִתְקָרְבִים אֵלָיו, וּמִתְבָּרְכִים. וּמֶלֶךְ מָתַי נִקְרָא מֶלֶךְ? כְּשֶׁגְּדוֹלָיו בָּאִים אֵלָיו עֲשִׁירִים, מְסֻפָּקִים בְּכָל מַה שֶּׁהִצְטָרְכוּ, בְּלֹא חִסָּרוֹן, וְאָז הוּא מֶלֶךְ. מֶלֶךְ לְמַטָּה, כְּשֶׁאֵלּוּ מְעַטְּרִים אוֹתוֹ בְּסִפּוּק בַּעֲטָרוֹת קְדוֹשׁוֹת. וְכָאן נִקְרָא מֶלֶךְ. וּמִיהוּ? הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ וְצִוָּנוּ. וּמִשּׁוּם שֶׁהוּא עוֹלָם שֶׁלֹּא הִתְגַּלָּה בַחוּץ, וְהוּא נִסְתָּר, קוֹרֵא לוֹ כָּךְ בְּדֶרֶךְ נִסְתָּר. וְעַל זֶה לֹא נִקְרָא, אֶלָּא בְּדֶרֶךְ נִסְתָּר.</p>\n<p>וּלְעוֹלָם אַתָּה זֶה יָמִין, כְּמוֹ שֶׁנִּתְבָּאֵר. וְעַל זֶה כֹּהֵן כָּפוּף לְאוֹתוֹ מָקוֹם בָּרֹאשׁ וּבַסּוֹף. וְהָעוֹלָם הַתַּחְתּוֹן, כְּשֶׁנִּקְשָׁר לְיָמִין וְנִדְבָּק בּוֹ, קוֹרֵא מִלְּמַטָּה לְמַעְלָה בָּרוּךְ, וְלֹא נִקְרָא בָּרוּךְ, רַק בְּסוֹד הַמָּקוֹר שֶׁדָּבֵק בּוֹ וְנִכְנָס בּוֹ וּמְמַלֵּא אוֹתוֹ. אַתָּה, הַסּוֹד שֶׁל אוֹתוֹ הַכֹּהֵן לְהִדָּבֵק אִתּוֹ, וְעַל זֶה בַּתְּפִלָּה הָאָדָם כּוֹרֵעַ בְּבָרוּךְ, שֶׁהוּא הָעוֹלָם שֶׁכָּפוּף אֶל מַעְלָה, וְזֶהוּ הַשִּׁנּוּי בֵּין בָּרוּךְ שֶׁל הַתְּפִלָּה וּבֵין בָּרוּךְ שֶׁל שְׁאָר בְּרָכוֹת. וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן, לְהָרִיק בְּרָכוֹת לְכָל הָעוֹלָמוֹת.</p>\n<p>בַּבָּרוּךְ שֶׁל הַתְּפִלָּה אָדָם כּוֹרֵעַ בְּבִרְכָּיו, וְגוֹחֵן רֹאשׁוֹ בְּאַתָּה, מִשּׁוּם שֶׁאַתָּה נִקְרָא רֹאשׁ. וְעַל זֶה כֹּהֵן לוֹקֵחַ בָּרֹאשׁ, וְהוּא תָּמִיד רֹאשׁ. וְלָכֵן כְּרִיעָה בְּבָרוּךְ, וּגְחִינַת הָרֹאשׁ בְּאַתָּה. וְהַכֹּהֵן, בְּכָל מָקוֹם שֶׁנִּקְרָא אַתָּה, גּוֹחֵן בַּתְּפִלָּה. הַמֶּלֶךְ אַחַר שֶׁגּוֹחֵן, שׁוּב לֹא זוֹקֵף, מָה הַטַּעַם? הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לַלְּבָנָה, לְכִי וְהַקְטִינִי אֶת עַצְמֵךְ, וְשׁוּב לֹא זָקְפָה. וְלָכֵן הַבְּרָכָה שֶׁל אָדָם לַקָּדוֹשׁ־בָּרוּךְ־הוּא מִתְעוֹרֶרֶת לְהוֹרִיק בְּרָכוֹת מִלְּמַעְלָה לָעוֹלָמוֹת כֻּלָּם, כְּמוֹ שֶׁנֶּאֱמַר. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>כָּתוּב <Nonesmall>[ישעיה סג]</small> כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם וְגוֹ'. שָׁנִינוּ, לֶעָתִיד לָבֹא אוֹמְרִים לְיִצְחָק וְכוּ', מִשּׁוּם שֶׁהַשְּׂמֹאל נִכְלָל בַּיָּמִין. אֲבָל הַיָּמִין מִנַּיִן לָנוּ שֶׁנִּקְרָא אָב? שֶׁכָּתוּב וַיְשִׂמֵהוּ לוֹ לְאָב וּלְכֹהֵן. וְאַף עַל גַּב שֶׁלְּמַעְלָה נִקְרָא אָב, וַאֲפִלּוּ לְאוֹר שֶׁלֹּא מֵאִיר בְּשָׁעָה שֶׁנִּדְבָּק בְּיָמִין נִקְרָא אַתָּה, כְּמוֹ שֶׁנֶּאֱמַר אַתָּה ה' אָבִינוּ גּוֹאֲלֵנוּ וְגוֹ'.</p>\n<p>בֵּין כָּךְ הִזְדַּמֵּן אֵלָיו זָקֵן וְאָמַר, רוֹעֶה הַנֶּאֱמָן, תַּקֵּן שֻׁלְחָן לְרִבּוֹנְךְ, לוֹ וְלַמַּלְכָּה, מִכָּל מִינֵי עִדּוּנִים, לְקַיֵּם בּוֹ <Nonesmall>[יחזקאל מא]</small> זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה', וַהֲרֵי עַד עַתָּה כֻּלָּם מִתְעַנְּגִים מִשֻּׁלְחַן הַמֶּלֶךְ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי ט]</small> לְכוּ לַחֲמוּ בְלַחְמִי. וְזֶה לֶחֶם הַתּוֹרָה שֶׁבִּכְתָב, וְיֵין הַתּוֹרָה שֶׁבְּעַל פֶּה. וְשָׁם כַּמָּה מַטְעַמִּים, מִינֵי טַעֲמֵי תוֹרָה, שֶׁמְּתוּקִים מִכָּל הַמַּאֲכָלִים וְהָעִדּוּנִים שֶׁל הָעוֹלָם וְשֶׁל הַמֶּלֶךְ.</p>\n<p>קָם הָרוֹעֶה הַנֶּאֱמָן, פָּתַח וְאָמַר, אַהֲרֹן הַכֹּהֵן קוּם מִשְּׁנָתְךְ לִזְבֹּחַ שְׁוָרִים וְצֹאן וּכְבָשִׂים וְעוֹפוֹת, וְכָל הַמִּינִים שֶׁצְּרִיכִים לִסְעוּדַת הַמֶּלֶךְ. וְלֶחֶם הַפָּנִים, שֶׁהֵם כְּנֶגֶד שְׁנֵי לוּחוֹת הַתּוֹרָה, שֶׁמִּזֶּה וּמִזֶּה הֵם כְּתֻבִים <Nonesmall>[שמות לב]</small>. זֶה – שְׁתֵּים עֶשְׂרֵה פָּנִים, שֶׁהֵם: <Nonesmall>[במדבר ו]</small> יְבָרֶכְךְ ה', יָאֵר ה', יִשָּׂא ה'. זֶה שֵׁנִי – אֲדנָ\"י אֲדֹנָ\"י אֲדֹנָ\"י. שֶׁהֵם שְׁתֵּים עֶשְׂרֵה חַיּוֹת, שֶׁבָּהֶן נֶאֱמַר <Nonesmall>[יחזקאל א]</small> וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם וּפְנֵי שׁוֹר מֵהַשְּׂמֹאול לְאַרְבַּעְתָּן וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וַעֲלֵיהֶם נֶאֱמַר אַרְבָּעָה פָנִים לְאֶחָת <Nonesmall>[להם]</small>. וְזֶהוּ <Nonesmall>[ישעיה ו]</small> וְקָרָא זֶה אֶל זֶה וְאָמַר, כְּנֶגֶד עֶשְׂרִים וְאַרְבָּעָה סִפְרֵי תוֹרָה. וְזֶהוּ זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. הַכֵּלִים שֶׁל שֻׁלְחַן הַמֶּלֶךְ הֵם בַּעֲלֵי הַמִּשְׁנָה, בַּעֲלֵי הַתְּפִלּוֹת, שֶׁתִּקְּנוּם כְּנֶגֶד הַקָּרְבָּנוֹת.</p>"],[9522012607,"<p>פָּתַח וְאָמַר, <Nonesmall>[שמות כה]</small> וְעָשִׂיתָ שֻׁלְחָן עֲצֵי שִׁטִּים וְגוֹ'. בּא רְאֵה, מִנְהָגִים טוֹבִים וְיָפִים הָיוּ נוֹהֲגִים בַּעֲלֵי הַסְּעוּדָה שֶׁל הַמֶּלֶךְ לְהַרְאוֹת שֶׁהֵם מִבְּנֵי שֻׁלְחַן הַמֶּלֶךְ. גָּדוֹל אֶחָד מִבְּנֵי הַסְּעוּדָה נוֹטֵל יָדָיו בִּזְמַן שֶׁיִּכָּנְסוּ לַסְּעוּדָה לְהָסֵב. הַגָּדוֹל מֵסֵב בָּרֹאשׁ, הַשֵּׁנִי תַּחְתָּיו, וְהַשְּׁלִישִׁי תַּחַת הַשֵּׁנִי. וְאֵלֶּה נִקְרְאוּ שְׁלֹשָׁה מִטּוֹת, כְּנֶגֶד שְׁלֹשָׁה אָבוֹת, וּכְנֶגֶד כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים. מִכָּאן וְאֵילָךְ אֵין לָהֶם סֵדֶר, אֶלָּא כָּל הַקּוֹדֵם זוֹכֶה.</p>\n<p>שֵׁנִית, בַּעַל הַבַּיִת בּוֹצֵעַ, כְּדֵי שֶׁיִּבְצַע בְּעַיִן יָפָה, וּמַשְׁלִים הַבְּרָכָה, וְאַחַר כָּךְ בּוֹצֵעַ. וּפֵרְשׁוּהָ רַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה, שֶׁאֵין הַמְּסֻבִּים רַשָּׁאִים לִטְעֹם עַד שֶׁיִּטְעֹם הַמְבָרֵךְ, וְאֵין הַבּוֹצֵעַ רַשַּׁאי לִטְעֹם עַד שֶׁיִּכְלֶה אָמֵן מִפִּי הַמְּסֻבִּים. וְאִם רְצוֹנוֹ לְחַלֵּק כָּבוֹד, הָרְשׁוּת בְּיָדוֹ. וְעוֹד פֵּרְשׁוּהָ שֶׁהָאוֹרֵחַ מְבָרֵךְ, בִּשְׁבִיל שֶׁיְּבָרֵךְ אֶת בַּעַל הַבַּיִת.</p>\n<p>וְדֶרֶךָ סוֹד, בַּעַל הַבַּיִת בּוֹצֵעַ – זֶה הָעַמּוּד הָאֶמְצָעִי, שֶׁהוּא קַו הָאֶמְצָעִי. וּבְשַׁבָּת צָרִיךְ לִבְצֹעַ מִשְּׁתֵּי כִּכָּרוֹת, שֶׁהֵן ה' ה'. בַּעַל הַבַּיִת – זֶה ו' שֶׁל הָאֶמְצַע. <Nonesmall>[ובצורה זו. ומשום זה]</small> וּכְדֵי שֶׁלֹּא יֵרָאֶה כְרַעַבְתָנוּת, יָכוֹל לִבְצֹעַ בָּהּ לְכָל אֶחָד וְאֶחָד כַּבֵּיצָה. מַה זֶּה כַּבֵּיצָה? י' וְי'. וְהֵן הַנְּקֻדּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, נִקְרָאִים פֵּרוּרִים שֶׁבְּכַזַּיִת. וְאֵלּוּ כְּנֶגֶד טִפּוֹת הַזֶּרַע. וּמִי שֶׁמְּזַלְזֵל בָּהֶן וְזוֹרְקָן בְּמָקוֹם שֶׁלֹּא צָרִיךְ, הָעֲנִיּוּת רוֹדֶפֶת אַחֲרָיו, וְהוֹלֵךְ נָע וָנָד. זֶהוּ שֶׁכָּתוּב <Nonesmall>[איוב טז]</small> נוֹדֵד הוּא לַלֶּחֶם אַיֵּה. וְאֵין לֶחֶם אֶלָּא תּוֹרָה, וְהוּא צוֹוֵחַ: אַיֵּה מִי שֶׁמְּרַחֵם עָלָיו? וְלֹא מוֹצֵא.</p>\n<p>וּפֵרוּרִים בְּכַזַּיִת, הֵם בְּצַדִּיק, וְהוּא כּוֹתֵשׁ כְּתִישׁוֹת מֵאוֹתָם הַזֵּיתִים. וְהָאוֹרֵחַ מְבָרֵךְ, <Nonesmall>[משלי ד]</small> וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. בְּרָכוֹת לְרֹאשׁ צַדִּיק חַי הָעוֹלָמִים, וְלָכֵן הָאוֹרֵחַ מְבָרֵךְ.</p>"],[9522012608,"<p>בֵּין כָּךְ הֲרֵי בָּא אֵלָיו הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, רוֹעֶה הַנֶּאֱמָן, יוֹם אֶחָד הָלַכְתִּי אֲנִי וְהַחֲבֵרִים לְאַכְסַנְיָה אַחַת, וְהָיָה שָׁם תִּינוֹק אֶחָד, קָם וְהִתְקִין לָנוּ מְנוֹרָה וְשֻׁלְחָן, הוּא מֵעַצְמוֹ כְּאִלּוּ הָיָה מֵעֶשְׂרִים שָׁנָה, וְלֹא הָיָה אֶלָּא מִבֶּן חָמֵשׁ שָׁנִים, וְהִתְקִין שֻׁלְחָן מִכָּל מִינֵי מַאֲכָל וּמִשְׁתֶּה. אָמַר, הֲרֵי פֵּרְשׁוּהָ רַבּוֹתֵינוּ שֶׁבַּעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ, אֲבָל <Nonesmall>[איוב לב]</small> צָעִיר אֲנִי לְיָמִים וְאַתֶּם יְשִׁישִׁים עַל כֵּן זָחַלְתִּי וָאִירָא מֵחַוּת דֵּעִי אֶתְכֶם, עַד שֶׁאֶטֹּל רְשׁוּת מִכֶּם. אָמַרְתִּי לוֹ, אֱמֹר בְּנִי מַלְאַךְ ה'.</p>\n<p>אָמַר לָנוּ, אַתֶּם רְצִיתֶם לֶחֶם תַּפְנוּקִים בְּלִי קְרָב, אוֹ לֶחֶם עִם קְרָב. שֶׁכָּךְ פֵּרְשׁוּהָ רַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה, שְׁעַת אֲכִילָה שְׁעַת מִלְחָמָה. וְאִם רְצִיתֶם שֶׁיִּהְיֶה עָלָיו קְרָב, אֵין אֶחָד אוֹכֵל. אֶלָּא מִי שֶׁיְּנַצַּח בַּקְּרָב, הוּא אוֹכֵל וּבוֹצֵעַ לְכֻלָּם. אָמְרוּ לוֹ הַחֲבֵרִים, בְּנִי, אַתָּה קָטָן, וַעֲדַיִן לֹא יָדַעְתִּי אֵיךְ נִלְחָמִים גְּבָרִים גְּדוֹלִים בְּחֶרֶב, בְּנִעְנוּעַ הַחֶרֶב, בְּרֹמַח, בְּקֶשֶׁת, בְּחִצֵי הַקֶּשֶׁת, בְּמַקְלֵעַ וּבְאַבְנֵי מַקְלֵעַ.</p>\n<p>אָמַר לָהֶם, <Nonesmall>[מלכים א כ]</small> אַל יִתְהַלֵּל חוֹגֵר כִּמְפַתֵּחַ. שֶׁהֲרֵי וַדַּאי בִּקְרִיאַת שְׁמַע פֵּרְשׁוּהָ, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע עַל מִטָּתוֹ, כְּאִלּוּ אוֹחֵז חֶרֶב פִּיפִיּוֹת, שֶׁכָּתוּב <Nonesmall>[תהלים קמט]</small> רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. וְנִעְנוּעַ הַחֶרֶב צָרִיךְ לְנַעְנְעָהּ לְשִׁשָּׁה צְדָדִים, כְּמוֹ שֶׁבֵּאֲרוּהָ, כְּדֵי שֶׁתַּמְלִיכוּהוּ עַל הַשָּׁמַיִם וְעַל הָאָרֶץ וְעַל אַרְבַּע רוּחוֹת הָעוֹלָם. וְזוֹ ו', גּוּף הַחֶרֶב. י' רֹאשׁ הַחֶרֶב. ה\"ה, שְׁתֵּי פִיפִיּוֹת. נַרְתִּיק הַחֶרֶב, אֲדנָי.</p>\n<p>רֹמַח, רמ\"ח בַּקְּרִיאַת שְׁמַע, עִם שֵׁשׁ תֵּבוֹת הַיִּחוּד, הֲרֵי רוֹמַ\"ח. מָגֵ\"ן עִם חֶרֶב, מִיכָאֵל גַּבְרִיאֵל נוּרִיאֵל, הַשַּׁמָּשִׁים שֶׁל שְׁלֹשֶׁת הָאָבוֹת. קֶשֶׁת שֶׁיּוֹרָה חִצִּים, וְכָל זֶרַע שֶׁאֵינוֹ יוֹרֶה כַּחֵץ אֵינוֹ מוֹלִיד. מַקְלֵעַ, זֶה קְרִיאַת שְׁמַע. חֲמִשָּׁה אַבְנֵי מַקְלֵעַ, <Nonesmall>[דברים ו]</small> שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה'. כְּנֶגְדָּם, וַיִּקַּח דָּוִד <Nonesmall>[שמואל א יז]</small> חֲמִשָּׁה חַלֻּקֵי אֲבָנִים מִן הַנַּחַל. וּכְשֶׁשָּׂם אוֹתָם בַּמַּקְלֵעַ, שֶׁהִיא שָׂפָה, וְהִיא שְׁכִינָה, נַעֲשׂוּ אֶחָד כָּל הַחֲמִשָּׁה, וְהָרַג אֶת הַפְּלִשְׁתִּי.</p>\n<p>וְעַד עַכְשָׁיו זָרַקְתִּי אֶבֶן זוֹ לְסָמָאֵל, שֶׁהוּא אֶבֶן מָצוֹר, וְהָרַסְתִּי אֶת הַמָּצוֹר שֶׁלּוֹ וְהִשְׁפַּלְתִּיו לְמַטָּה. וְלָכֵן אָמַרְתִּי לָכֶם, אַל יִתְהַלֵּל חוֹגֵר כִּמְפַתֵּחַ. כָּעֵת יִתְבָּרֵר לָכֶם שֶׁאֲנִי יוֹדֵעַ אֵיךְ נִלְחָמִים גְּבָרִים גְּדוֹלִים בַּחֲרָבוֹת, בְּרֹמַח, בְּקֶשֶׁת, בְּמַקְלֵעַ. תָּמַהְנוּ וְלֹא יָכֹלְנוּ לְדַבֵּר לְפָנָיו. אָמְרוּ לוֹ חֲכָמִים, כָּעֵת נִרְאֶה מִי יִהְיֶה מַרְוִיחַ אֶת הַלֶּחֶם, שֶׁהוּא לֶחֶם הַמּוֹצִיא.</p>\n<p>פָּתַח וְאָמַר, <Nonesmall>[במדבר טו]</small> וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ תָּרִימוּ תְרוּמָה לַה'. בַּמֶּה נִתְרֶמֶת שְׁכִינָה, שֶׁהִיא ה' שֶׁל הַמּוֹצִיא, שֶׁבֵּאֲרוּ עָלֶיהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל הַבּוֹצֵעַ צָרִיךְ לְדַקְדֵּק בַּהֵ\"א? אֶלָּא וַדַּאי הֲרֵי פֵּרְשׁוּהָ רַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה, מוֹץ וְתֶבֶן פְּטוּרִים מִן הַמַּעֲשֵׂר. וּכְשֶׁהִיא בְּמוֹץ וְתֶבֶן, הִיא בְּבֵית הָאֲסוּרִים, וְאֵין לָהּ רְשׁוּת לְהָרִים לְמ' לַעֲשׂוֹת עִמָּהּ מָ\"ה. וְזוֹהִי תְּרוּמָה, תּוֹרָ\"ה שֶׁהִיא חֲמִשָּׁה חֻמְשֵׁי תוֹרָה, שֶׁבָּהּ <Nonesmall>[שמות כד]</small> וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְגוֹ'.</p>\n<p>וּבְמוֹץ וְתֶבֶן שֶׁל חִטָּה, עָלֶיהָ בֵּאֲרוּ רַבּוֹתֵינוּ, אִילָן שֶׁאָכַל אָדָם הָרִאשׁוֹן חִטָּה הָיָה. קֵרַב ח\"ט, שֶׁהוּא מוֹץ וְתֶבֶן, לָאוֹת ה', וְהִסְתַּלְּקָה מִמֶּנּוּ י', שֶׁהוא עִשּׂוּר שֶׁלָּהּ. וְלָכֵן כְּשֶׁהוּא בְּמוֹץ וְתֶבֶן <Nonesmall>[שלה]</small>, שֵׁם כְּנֶגֶד עָרְלָה וּפְרִיעָה, פָּטוּר מִן הַמַּעֲשֵׂר. וְאֵין רְשׁוּת לָאוֹת י' לְחַבֵּר בָּאוֹת ה', שֶׁהֵם אִישׁ וְאִשָּׁה. וְלָכֵן כָּל הַבּוֹצֵעַ צָרִיךְ לְדַקְדֵּק בָּהּ. וְצָרִיךְ לִבְצֹעַ מֵהַמָּקוֹם שֶׁבִּשּׁוּלוֹ יָפֶה, מִשּׁוּם שֵׁבִּשּׁוּל הוּא גְּמַר הַפְּרִי, וְזֶה ו'.</p>"],[9522012609,"<p>וַעָֹשָׂרָה דְבָרִים צָרִיךְ אָדָם לַעֲשׂוֹת בִּסְעוּדָה: אֶחָד – נְטִילַת יָדַיִם. שֵׁנִי – לְתַקֵּן שְׁתֵּי כִּכְּרוֹת לְשַׁבָּת. שְׁלִישִׁי – לֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת, וּלְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ. רְבִיעִי – לְהָאִיר אֶת הַשֻּׁלְחָן בְּנֵר, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֻׁלְחָן בַּצָּפוֹן וּמְנוֹרָה בַדָּרוֹם. וְצָרִיךְ הֲסִבָּה, כְּמוֹ שֶׁבֵּאֲרוּהָ, הֵסֵבּוּ – אֶחָד מְבָרֵךְ לְכֻלָּם.</p>\n<p>וּבְשַׁבָּת, בְּכָל דְּבָרָיו צָרִיךְ לְהוֹסִיף מֵחֹל עַל קֹדֶשׁ, בֵּין בְּמַאֲכָלָיו וּמַשְׁקָיו, בֵּין בִּלְבוּשָׁיו, בֵּין בַּהֲסִבָּתוֹ, שֶׁצָּרִיךְ לְהַתְקִין לוֹ מְסִבָּה יָפָה, בְּכַמָּה כָרִים וּכְסָתוֹת מְרֻקָּמִים מִכָּל שֶׁיֵּשׁ בְּבֵיתוֹ, כְּמוֹ שֶׁמַּתְקִין חֻפָּה לַכַּלָּה, שֶׁשַּׁבָּת הִיא מַלְכָּה, וְהִיא כַּלָּה. וְלָכֵן הָיוּ יוֹצְאִים בַּעֲלֵי הַמִּשְׁנָה עֶרֶב שַׁבָּת לְקַדֵּם אֶת הָאוֹרַחַת, וְהָיוּ אוֹמְרִים: בֹּאִי כַלָּה, בֹּאִי כַלָּה. וּצְרִיכִים לְעוֹרֵר שִׁירָה וְחֶדְוָה לַשֻּׁלְחָן אֵלֶיהָ.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁיֵּשׁ סוֹד אַחֵר. כְּמוֹ שֶׁצָּרִיךְ לְקַבֵּל אֶת גְּבִרְתָּהּ בְּכַמָּה אוֹרוֹת שֶׁל נֵרוֹת שַׁבָּת, וּבְכַמָּה עִנּוּגִים וּלְבוּשִׁים יָפִים, וּבַיִת מְתֻקָּן בְּכַמָּה כֵלִים שֶׁל תִּקּוּן, בַּהֲסִבָּה יָפָה לְכָל אֶחָד וְאֶחָד, וּבְזֹּאת הַחֶדְוָה וְהַתִּקּוּן גּוֹרְמִים שֶׁנִּשְׁאֶרֶת שִׁפְחָה רָעָה בַּחֹשֶׁךְ, בִּרְעָבוֹן, בִּבְכִיָּה, בְּהֶסְפֵּד, בִּלְבוּשִׁים שְׁחֹרִים כְּאַלְמָנָה. שֶׁאִם מְלֵאָה זוֹ – חֲרֵבָה זוֹ.</p>\n<p>יֵצֶר טוֹב גְּבִירָה קְדוֹשָׁה, מַלְכוּת הַקֹּדֶשׁ שֶׁיּוֹרֶדֶת בְּשַׁבָּת, כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, מְעֻטָּרוֹת בְּשִׁבְעָה שֵׁמוֹת שֶׁאֵינָם נִמְחָקִים, בְּכַמָּה מֶרְכָּבוֹת שֶׁל חַיּוֹת וּבְכַמָּה חֲיָלוֹת וּמַחֲנוֹת. וְהַמֶּלֶךְ יוֹצֵא לְקַבְּלָהּ בְּכַמָּה מַחֲנוֹת, וְנִשְׁאָר יֵצֶר הָרָע, הַשִּׁפְחָה הָרָעָה בַּחֹשֶׁךְ, כְּאַלְמָנָה בְּלִי בַעְלָהּ, בְּלִי מֶרְכָּבוֹת.</p>\n<p>וְאֵלֶּה שֶׁנֶּאֱמַר עֲלֵיהֶם, לַמְזַבְּחִים וְלַמְקַטְּרִים לִמְלֶאכֶת הַשָּׁמַיִם וְלַמַּזָּלוֹת אֲשֶׁר לֹא צִוִּיתִי, הִיא עֲבוֹדָה שֶׁל הַשִּׁפְחָה הָרָעָה, שֶׁשּׁוֹלֶטֶת בְּעַרְבֵי שַׁבָּתוֹת וְעַרְבֵי לֵילוֹת רְבִיעִי, מֶה הָיוּ עוֹשִׂים אֵלֶּה? הָיוּ לוֹקְחִים לְבוּשִׁים שְׁחֹרִים, וּמַחֲשִׁיכִים אֶת הָאוֹרוֹת, וְעוֹשִׂים הֶסְפֵּד בְּלֵילֵי שַׁבָּתוֹת לְהִשְׁתַּתֵּף עִמָּהּ כְּמוֹ שֶׁהִיא שְׁרוּיָה, כִּי <Nonesmall>[קהלת ז]</small> גַּם [את] זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>\n<p>אַחַר שֶׁחָטְאוּ יִשְׂרָאֵל וְנֶחֱרַב בֵּית הַמִּקְדָּשׁ, נֶאֱמַר בַּשְּׁכִינָה הָאֵם הַקְּדוֹשָׁה, <Nonesmall>[איכה א]</small> אֵיכָה יָשְׁבָה בָדָד הָעִיר רַבָּתִי עָם הָיְתָה כְּאַלְמָנָה, וּמְכַבִּים בְּלֵיל תִּשְׁעָה בְּאָב אוֹרוֹת וְנֵרוֹת, וְעוֹשִׂים הֶסְפֵּד וְיוֹשְׁבִים כְּמוֹ אֲבֵלִים, לְהִשְׁתַּתֵּף בְּצַעַר הַשְּׁכִינָה, מִשּׁוּם שֶׁהֵם גָּרְמוּ לָהּ כָּל אוֹתוֹ הַשֶּׁבֶר.</p>\n<p>חֲמִישִׁי – כּוֹס שֶׁל וַיְכֻלּוּ. שִׁשִּׁי – לִהְיוֹת עַל הַשֻּׁלְחָן דִּבְרֵי תוֹרָה. שְׁבִיעִי – לְהַאֲרִיךְ עַל הַשֻּׁלְחָן כְּדֵי שֶׁעֲנִיִּים יָבֹאוּ לְשֻׁלְחָנוֹ. שְׁמִינִי – נְטִילַת יָדַיִם בְּמַיִם אַחֲרוֹנִים. תְּשִׁיעִי – בִּרְכַּת הַמָּזוֹן. עֲשִׂירִי – כּוֹס שֶׁל בְּרָכָה. וְצָרִיךְ לְחַזֵּר עֲלֵיהֶם וּלְתַקְּנָם בְּסוֹד קָדוֹשׁ, שֶׁהִיא כְּלוּלָה מֵעֶשֶׂר סְפִירוֹת, וְהוּא הַשֻּׁלְחָן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִצַּד הַגְּבוּרָה, וְלָכֵן פֵּרְשׁוּהָ רַבּוֹתֵינוּ שֻׁלְחָן בַּצָּפוֹן.</p>\n<p>אֶחָד – נְטִילַת יָדַיִם, שֶׁבֵּאֲרוּהָ רַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה, יָדַיִם מְזֹּהָמוֹת פְּסוּלוֹת לִבְרָכָה, מִשּׁוּם שֶׁהֵן שְׁנִיּוֹת לְטֻמְאָה, שֶׁהוּא אַב הַטֻּמְאָה, שֶׁהוּא רִאשׁוֹן כְּשֶׁהֵן טְמֵאוֹת, וּכְשֶׁהֵן טְהוֹרוֹת הֵן שְׁנִיּוֹת לַבְּרָכָה, שֶׁהַבְּרָכָה לא שׁוֹרָה אֶלָּא עַל טָהֳרָה. הַכֹּהֵן, שֶׁהוּא אִישׁ טָהוֹר, אִישׁ חֶסֶד, שׁוֹרָה עָלָיו בְּרָכָה. זֶהוּ שֶׁכָּתוּב <Nonesmall>[תהלים קלג]</small> כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ וְגוֹ'. וְלָכֵן, <Nonesmall>[במדבר ו]</small> דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל וְגוֹ'. וּפֵרְשׁוּהָ, כָּל כֹּהֵן הַמְבָרֵךְ – מִתְבָּרֵךְ. וְשֶׁאֵינוֹ מְבָרֵךְ – אֵין מִתְבָּרֵךְ. וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, כָּל בְּרָכָה שֶׁאֵין בָּהּ אַזְכָּרָה וּמַלְכוּת, אֵין שְׁמָהּ בְּרָכָה. מַלְכוּת אֲדנָי.</p>\n<p>וְעוֹד, נְטִילַת יָדַיִם צָרִיךְ לִטֹּל אוֹתָן עַד הַפֶּרֶק, שֶׁגָּזְרוּ עָלָיו י\"ד פְּרָקִים, בְּאוֹתָהּ שָׁעָה שׁוֹרָה עָלָיו יַד ה', וְהִיא יָד שֶׁל בְּרָכָה מִצַּד הַחֶסֶד שֶׁבּוֹ חָכְמָה בְּיַד יְמִינוֹ. וְהִיא יָד שֶׁל קְדֻשָּׁה מִצַּד הַגְּבוּרָה, וּשְׁרוּיָה בְדִין. <Nonesmall>[ויד שמאל]</small> וְהִיא יַד הַיִּחוּד מִצַּד הַתִּפְאֶרֶת, שֶׁשּׁוֹרָה בְּי\"ד פִּרְקֵי הַגּוּף, שֶׁהֵם שְׁנֵים עָשָׂר פְּרָקִים בִּשְׁתֵּי זְרוֹעוֹת וּשְׁתֵּי שׁוֹקַיִם, וּשְׁנַיִם בַּגּוּף וּבַבְּרִית.</p>\n<p>וְשָׁלֹש פְּעָמִים אַרְבָּעָה עָשָׂר הוּא אַרְבָּעִים וּשְׁנַיִם. יי\"י מִי\"ד י\"ד י\"ד, רָמוּז יְ\"בָרֶכְךְ יָ\"אֵר יִ\"שָּׂא, מֵהוי\"ה הוי\"ה הוי\"ה. ד' ד' ד' מִי\"ד י\"ד י\"ד, הֵם רְמוּזִים בַּאדנָ\"י אֲדנָ\"י אֲדנָ\"י. וְאָמַר הַנָּבִיא עֲלֵיהֶם, <Nonesmall>[ירמיה ז]</small> הֵיכַל ה' הֵיכַל ה' הֵיכַל ה' הֵמָּה. וְהַנְּטִילָה הַזּוֹ בַּיָּד שֶׁהִתְתַּקְּנָה.</p>\n<p>וְכָל צַד מִשְּׁלֹשֶׁת פְּנֵי הַחַיּוֹת, שֶׁהֵם יְיָ יְיָ יְיָ, וּמִשְּׁלֹשׁ כַּנְפֵי הַחַיּוֹת, שֶׁהֵן ד' ד' ד', כֻּלָּם צָרִיךְ לִהְיוֹת מִכֹּחַ אָדָם. וְהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַכֹּחַ שֶׁלּוֹ – יוֹ\"ד וָא\"ו דָּלֶ\"ת, הֵ\"א אָלֶ\"ף, וָא\"ו אָלֶ\"ף וָא\"ו, הֵ\"א אָלֶ\"ף. וְהַמַּלְכָּה לֹא שְׁרוּיָה בַּכֹּחַ שֶׁלּוֹ, בְּפִרְקֵי הָאֶצְבָּעוֹת, עַד שֶׁעוֹבֶרֶת מֵהֶם הַזֻּהֲמָה, הַשִּׁפְחָה הָרָעָה הַפְּסוּלָה, אֵשֶׁת הַפָּסוּל. וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, יָדַיִם מְזֹּהָמוֹת פְּסוּלוֹת לִבְרָכָה.</p>\n<p>וְהֵם מַיִם לְטַהֵר הַיָּד, שֶׁשּׁוֹרָה שָׁם יַד יְיָ. יַד יְיָ זֶה מַיִם שֶׁל הַתּוֹרָה. שֶׁעַמֵּי הָאָרֶץ הֵם שֶׁרֶץ, מַה מּוֹעִילָה לָהֶם טְבִילָה, וְהַשֶּׁרֶץ, שִׁפְחָה רָעָה בְּיָדָם, בַּגָּזֵל שֶׁבִּידֵיהֶם, בַּגָּזֵל שֶׁל הַבְּרָכוֹת שֶׁגּוֹזְלִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא יוֹדְעִים לְבָרֵךְ, וְלֹא יוֹדְעִים מַהִי בְּרָכָה וּמַהִי זֻהֲמָה.</p>\n<p>מִיָּד כְּשֶׁשָּׁמְעוּ הַחֲבֵרִים דְּבָרִים אֵלּוּ, וַאֲנִי עִמָּהֶם, לֹא יָכֹלְתִּי לִסְבֹּל שֶׁיַּשְׁלִים עֲשָׂרָה דְבָרִים שֶׁל בְּרָכָה, וְהִשְׁתַּטַּחְתִּי אֶצְלוֹ, וּבְוַדַּאי אֵין אִישׁ שֶׁיֹּאמַר דְּבָרִים אֵלּוּ אֶלָּא אַתָּה, שֶׁאַתָּה הוּא כְּמוֹ אַרְבַּע מְחִצּוֹת שֶׁל גַּן עֵדֶן. שֶׁהָאָדָם נִכְנָס בָּהֶן <Nonesmall>[שכאשר אתה]</small> בִּמְחִצַּת הַתִּינוֹקוֹת וְנַעֲשֶׂה תִינוֹק, וּבִמְחִצַּת נְעָרִים וְנַעֲשֶׂה נַעַר, וּבִמְחִצַּת בַּחוּרִים וְנַעֲשֶׂה בָּחוּר, וּבִמְחִצַּת זְקֵנִים וְנַעֲשֶׂה זָקֵן. וּלְכָךְ נֶאֱמַר עָלֶיךְ, <Nonesmall>[תהלים לג]</small> 'מִמְּכוֹן 'שִׁבְתּוֹ 'הִשְׁגִּיחַ אֶל כָּל יֹשְׁבֵי הָאָרֶץ. וְאַתָּה הוּא שֶׁנֶּאֱמַר עָלֶיךְ <Nonesmall>[בראשית ו]</small> בְּשַׁגַּם הוּא בָּשָׂר, בַּדּוֹר שֶׁל דּוֹר הַפְּלַגָּה הָיִיתָ, וּבְכָל דּוֹר וָדוֹר בְּגִלְגּוּל, כְּגַלְגַּל שֶׁמִּתְהַפֵּךְ לְכַמָּה גְוָנִים. וְלֹא נִגְלֵיתָ אֶלָּא בְּדוֹר שֶׁנִּתְּנָה בּוֹ תּוֹרָה עַל יָדְךְ.</p>\n<p>מִיָּד שֶׁהִתְכַּנַּסְתָּ מֵהָעוֹלָם, אַתָּה הוּא כַּשֶּׁמֶשׁ שֶׁמֵּאִיר בְּכָל דּוֹר וָדוֹר. שֶׁכְּשֶׁמִּתְכַּנֵּס הַשֶּׁמֶשׁ בַּלַּיְלָה, הוּא מֵאִיר בַּלְּבָנָה וּבְשִׁשִּׁים רִבּוֹא כּוֹכָבִים. כָּךְ אַתָּה, שֶׁאַתָּה מֵאִיר בְּשִׁשִּׁים רִבּוֹא בְּכָל דּוֹר וָדוֹר. וְזֶהוּ שֶׁרָמַז קֹהֶלֶת, <Nonesmall>[קהלת א]</small> דּוֹר הֹלֵךְ וְדוֹר בָּא. וּפֵרְשׁוּהָ רַבּוֹתֵינוּ, אֵין דּוֹר פָּחוֹת מִשִּׁשִּׁים רִבּוֹא. וְעוֹד פֵּרְשׁוּהָ, הַדּוֹר שֶׁהוֹלֵךְ הוּא שֶׁבָּא, לְקַיֵּם מַה שֶּׁהָיָה הוּא שֶׁיִּהְיֶה. מִכָּאן וְאֵילָךְ הַשְׁלֵם עֲשָׂרָה דְבָרִים שֶׁל הַשֻּׁלְחָן בְּגִלּוּי. אָמַר רוֹעֶה הַנֶּאֱמָן, הַמְּנוֹרָה הַקְּדוֹשָׁה אַשְׁרֵי חֶלְקְךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה לְךְ מַה שֶּׁלֹּא גִלָּה לְכָל נָבִיא וְחוֹזֶה, וְלֹא לְמִי וּלְמִי.</p>\n<p>שֵׁנִי – לִבְצֹעַ עַל שְׁתֵּי כִּכָּרוֹת בְּשַׁבָּת, שֶׁהֵן רְמוּזוֹת בִּשְׁנֵי לוּחוֹת הַתּוֹרָה, שֶׁנִּתְּנוּ בְשַׁבָּת זוּגוֹת. שֶׁבַּיּוֹם הַשְּׁלִישִׁי יָרְדוּ, שֶׁבּוֹ פַּעֲמַיִם טוֹב, וּבְשַׁבָּת נִתְּנָה, שְׁתֵּי נְקֵבוֹת לִשְׁנַיִם טוֹבִים. וְאַף עַל גַּב שֶׁבֵּאֲרוּהָ שֶׁהַשֵּׁדִים מְמֻנִּים עַל זוּגוֹת, כְּמוֹ שֶׁבֵּאֲרוּהָ שְׁתֵּי בֵיצִים, שְׁנֵי אֱגוֹזִים – הֲלָכָה לְמֹשֶׁה מִסִּינַי: שְׁלוּחֵי מִצְוָה אֵינָן נִזּוֹקִין.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי שָׁנִינוּ, אֵין מַתְחִילִין בַּשֵּׁנִי וְאֵין מְסַיְּמִים בָּרְבִיעִי, דְּהַיְנוּ בְּב' ד' עִם עֵרֶב רַב, שֶׁלֹּא הָיוּ שְׁלוּחֵי מִצְוָה, שֶׁלֹּא הִתְגַּיְּרוּ לְשֵׁם שָׁמַיִם, וּלְאַחַר שֶׁעָבְרוּ מִן הָעוֹלָם, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לִטֹּל <Nonesmall>[שמות לד]</small> שְׁנֵי לֻחֹת אֲבָנִים כָּרִאשֹׁנִים, וְאָמַר, וְכָתַבְתִּי עַל הַלֻּחֹת אֶת הַדְּבָרִים אֲשֶׁר הָיוּ עַל הַלֻּחֹת וְגוֹ'.</p>\n<p>וּשְׁתֵּי כִּכָּרוֹת בְּשַׁבָּת רוֹמְזוֹת לִשְׁנֵי יוֹדִי\"ם יְאֲהדוָנָהִי. שֶׁאֲדֹנָי הִיא יְחִידָה מִבַּעְלָהּ בְּשֵׁשֶׁת יְמוֹת הַחֹל, וּבְשַׁבָּת יוֹרֵד אֵלֶיהָ. וּמִשּׁוּם זֶה בְּשַׁבָּת כָּל הַנְּשָׁמוֹת וְהָרוּחוֹת וְהַנְּפָשׁוֹת יוֹצְאוֹת וְיוֹרְדוֹת זוּגוֹת, וְאֵין שָׂטָן וְאֵין מַזִּיק שׁוֹלֵט בְּיוֹם הַשַּׁבָּת. וַאֲפִלּוּ גֵיהִנֹּם לֹא שׁוֹלֵט וְלֹא בוֹעֵר בְּשַׁבָּת. וּמִשּׁוּם זֶה, <Nonesmall>[שמות לה]</small> לֹא תְבַעֲרוּ אֵשׁ בְּכֹל מֹשְׁבתֵיכֶם בְּיוֹם הַשַּׁבָּת. וְזוֹ אֵשׁ נָכְרִיָּה, אֶלָּא אֵשׁ הַקָּרְבָּן, אֵשׁ שֶׁל קְדֻשָּׁה. וְאֵין לְהַאֲרִיךְ בַּבְּצִיעָה שֶׁלָּהֶן, שֶׁהֲרֵי נִתְבָּאֵר לְמַעְלָה.</p>\n<p>שְׁלִישִׁי – לֶאֱכֹל שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת, כְּפִי שֶׁבֵּאֲרוּהָ רַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה, שֶׁאָמַר אֶחָד מֵהֶם: יְהֵא חֶלְקִי עִם גּוֹמְרֵי שָׁלֹשׁ סְעוּדוֹת בְּשַׁבָּת. שֶׁהֵן שְׁלֵמוּת שֶׁל שֶׁבַע בְּרָכוֹת שֶׁל הַתְּפִלָּה, לְהַשְׁלִים בָּהֶן לְעֶשֶׂר. וְהַסּוֹד שֶׁל עֹנֶג – <Nonesmall>[בראשית ב]</small> וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וּמִי שֶׁלֹּא מְקַיֵּם אוֹתָן וְיֵשׁ לוֹ רְשׁוּת לְקַיְּמָן, הוֹפֵךְ לוֹ לְנֶגַע צָרַעַת. וּכְדֵי שֶׁלֹּא יָבא לָזֶה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: לְווּ עָלַי וַאֲנִי פּוֹרֵעַ, <Nonesmall>[ישעיה נח]</small> אָז תִּתְעַנַּג עַל ה'.</p>\n<p>רְבִיעִי – לְהָאִיר שֻׁלְחָן בִּמְנוֹרָה, כְּמוֹ שֶׁבֵּאֲרוּהָ הַקַּדְמוֹנִים, שֻׁלְחָן בַּצָּפוֹן, מְנוֹרָה בַּדָּרוֹם. שֶׁשֻּׁלְחָנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ צָרִיךְ לִהְיוֹת. חֲמִישִׁי – כּוֹס שֶׁל וַיְכֻלּוּ. כּוֹ\"ס בְּחֶשְׁבּוֹן אֱלֹהִים. וַיְכֻלּוּ – ע\"ב, שֶׁכּוֹלֶלֶת אוֹתָם הַכַּלָּה הַקְּדוֹשָׁה. שֶׁהַכּוֹס הַזֹּאת הַמְּלֵאָה יַיִן שֶׁל תּוֹרָה, צְרִיכָה לְהָעִיד עַל מַעֲשֵׂה בְרֵאשִׁית.</p>\n<p>שִׁשִּׁי – לִהְיוֹת עַל הַשֻּׁלְחָן דִּבְרֵי תוֹרָה, שֶׁכָּךְ פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, <Nonesmall>[אבות פ\"ג]</small> שְׁלֹשָׁה שֶׁאָכְלוּ עַל שֻׁלְחָן אֶחָד וְלֹא אָמְרוּ עָלָיו דִּבְרֵי תוֹרָה וְכוּ'. וְסוֹד הַדָּבָר – מִשּׁוּם שֶׁהֲרֵי פֵּרְשׁוּהָ שֻׁלְחָן בַּצָּפוֹן, וְהַתּוֹרָה נִתְּנָה מִיָּמִין. לְחַבֵּר יָמִין, שֶׁהוּא רַחֲמִים, עִם שְׂמֹאל, שֶׁהוּא דִּין. שֶׁהַתּוֹרָה הִיא יְיָ מִיָּמִין, שֻׁלְחָן אֲדנָי מִשְּׂמֹאל, וְצָרִיךְ לְחַבֵּר אוֹתָם. מִשּׁוּם שֶׁהַשֻּׁלְחָן מִשְּׂמֹאל, פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, קָשִׁים מְזוֹנוֹתָיו שֶׁל אָדָם כִּקְרִיעַת יַם סוּף. וּמִשּׁוּם כָּךְ צָרִיךְ תַּלְמִיד חָכָם לְזַמֵּן עִמּוֹ, לְמִי שֶׁיִּשְׁתַּדֵּל בְּדִבְרֵי תוֹרָה.</p>\n<p>שְׁבִיעִי – לְהַאֲרִיךְ עַל הַשֻּׁלְחָן מִשּׁוּם הָעֲנִיִּים. וּמִשּׁוּם זֶה, כָּל הַמַּאֲרִיךְ עַל שֻׁלְחָנוֹ מַאֲרִיכִים לוֹ יָמָיו וּשְׁנוֹתָיו, וּמִשּׁוּם כָּךְ <Nonesmall>[משלי י]</small> וּצְדָקָה תַּצִּיל מִמָּוֶת. שֶׁעָנִי חָשׁוּב כְּמֵת, וְהוּא מְחַיֶּה אוֹתוֹ, גַּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְחַיֶּה אוֹתוֹ.</p>\n<p>וְעוֹד בְּדֶרֶךְ סוֹד, שֶׁכָּל הָעֲנִיִּים מִצַּד הָאוֹת ד', שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[תהלים קטז]</small> דַּלּוֹתִי וְלִי יְהוֹשִׁיעַ. וְאוֹת ד' שֶׁל אֶחָד שֶׁצָּרִיךְ לְהַאֲרִיךְ בָּהּ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים יז]</small> לְהַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ, וְלָכֵן צָרִיךְ לְהַאֲרִיךְ עַל הַשֻּׁלְחָן, שֶׁהִיא ד', כְּלוּלָה מֵאַרְבַּע רַגְלַיִם שֶׁל הַשֻּׁלְחָן. בִּשְׁבִיל כְּבוֹד הָאוֹת ד' צָרִיךְ לְהַאֲרִיךְ עַל הַשֻּׁלְחָן בִּשְׁבִיל הָעֲנִיִּים.</p>\n<p>וּבִשְׁבִילוֹ בֵּאֲרוּ רַבּוֹתֵינוּ, שֶׁבִּקֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא מִדָּה יָפָה לְיִשְׂרָאֵל וְלֹא מָצָא כְּמוֹ מִדַּת הַדַּלּוּת. וְהִקְשׁוּ עַל זֶה, מִשּׁוּם שֶׁבֵּאֲרוּהָ הָרִאשׁוֹנִים, כְּחֶשְׁבּוֹן מִינֵי מִיתוֹת שֶׁהֵם כְּחֶשְׁבּוֹן תּוֹצָאוֹת, וְחֶסְרוֹן כִּיס קָשֶׁה מִכֻּלָּם, וְאֵיךְ הֵם אוֹמְרִים שֶׁלֹּא נִמְצְאָה לְיִשְׂרָאֵל מִדָּה יָפָה כְּמוֹ עֲנִיּוּת?</p>\n<p>אֶלָּא מִשּׁוּם שֶׁכָּל עַם וְלָשׁוֹן, <Nonesmall>[ישעיה ח]</small> וְהָיָה כִי יִרְעַב וְהִתְקַצַּף וְקִלֵּל בְּמַלְכּוֹ וּבֵאלֹהָיו וּפָנָה לְמָעְלָה. אֲבָל יִשְׂרָאֵל הֵם קִיּוּם הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדָּה הַזּוֹ, וְלֹא מַכְחִישִׁים בּוֹ. וְלָכֵן בַּמִּדָּה הַזּוֹ הֵם יִגָּאֲלוּ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמואל ב כב]</small> וְאֶת עַם עָנִי תּוֹשִׁיעַ. וְעָנִי לְשׁוֹן וְעִנּוּי. שֶׁאֲפִלּוּ יֵשׁ לְאָדָם עֹשֶׁר וְהוּא בֶּחֳלָאִים וּבְמַכּוֹת, נִקְרָא עָנִי, אוֹ שֶׁמְּצַעֲרִים אוֹתוֹ בִּגְלָלוֹ, וּמְצַעֲרִים אוֹתוֹ בְּכָל יוֹם. כָּל שֶׁכֵּן מִי שֶׁהוּא רָשׁ מִמֶּנּוּ, וְהוּא הוֹלֵךְ מִמָּקוֹם לְמָקוֹם.</p>\n<p>וְעוֹד יֵשׁ עָנִי שֶׁהִסְתַּלְּקָה מִמֶּנּוּ דַעְתּוֹ, כְּמוֹ אִיּוֹב, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[איוב לד]</small> אִיּוֹב לֹא בְדַעַת יְדַבֵּר. גַּם כָּךְ הִיא ד', שֶׁהִיא הַשְּׁכִינָה, כְּשֶׁמִּסְתַּלֵּק מִמֶּנָּה א\"ח, שֶׁהוּא הָעַמּוּד הָאֶמְצָעִי שֶׁנִּקְרָא דַעַת. וְזֶה אֵין לוֹ חֲטָאִים בְּדָבָר שֶׁיֹּאמַר. וְעוֹד, א\"ח הוּא תּוֹרָה, כּוֹלֵל תרי\"ג מִצְווֹת, זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמות ג]</small> זֶה שְּׁמִי לְעֹלָם וְגוֹ'. שְׁמִ\"י עִם י\"ה – שס\"ה. זִכְרִי עִם ו\"ה – רמ\"ח. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ, אֵין עָנִי אֶלָּא מִן הַתּוֹרָה וּמִן הַמִּצְווֹת, שֶׁשְּׁאָר עָנִי אֵינוֹ אֶלָּא עִנּוּי. וְהָאוֹת ד' מִן אֲדנָי, גַּם כָּךְ הוּא עָנִי בְּלִי יְהֹוָ\"ה.</p>\n<p>שְׁמִינִי – מַיִם אַחֲרוֹנִים שֶׁתִּקְּנוּ לָהֶם מִשּׁוּם מֶלַח סְדוֹמִית הַמְסַמֵּא אֶת הָעֵינַיִם. לָמָּה נִקְרְאוּ חוֹבָה? אֶלָּא בְּדֶרֶךְ סוֹד, סַם הַמָּוֶת שׁוֹרֶה עַל יָדַיִם מְזֹּהָמוֹת, שֶׁעוֹשִׂים בָּהֶם בְּרָכָה. וְעַל כּוֹס שֶׁמְּבָרְכִים עָלֶיהָ בְּלִי טָהֳרָה נִקְרֵאת טְמֵאָה. וּמַה כּוֹס שֶׁשּׁוֹתִים בָּהּ טְמֵאָה לִבְרָכָה, עַד שֶׁהָיוּ מְטַהֲרִים אוֹתָהּ בַּהֲדחָה מִבִּפְנִים וּמִבַּחוּץ – כָּל שֶׁכֵּן יָדָיו. וּמִשּׁוּם זֶה מַיִם אַחֲרוֹנִים חוֹבָה. וְסוֹד הַדָּבָר, <Nonesmall>[ויקרא יא]</small> וְהִתְקַדִּשְׁתֶּם – אֵלּוּ מַיִם רִאשׁוֹנִים. וִהְיִיתֶם קְדשִׁים – אֵלּוּ מַיִם אַחֲרוֹנִים. כִּי קָדוֹשׁ – זֶה שֶׁמֶן עָרֵב. כְּנֶגֶד <Nonesmall>[ישעיה ו]</small> קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. וּמִשּׁוּם זֶה וְהִתְקַדִּשְׁתֶּם וְגוֹ', לְהוֹדִיעַ שֶׁאַתֶּם בָּנִים לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים יד]</small> בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם.</p>\n<p>תְּשִׁיעִי – כּוֹס שֶׁל בְּרָכָה, וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, עֲשָׂרָה דְבָרִים נֶאֶמְרוּ בְּכוֹס שֶׁל בְּרָכָה, וְאֵלּוּ הֵם: עִטּוּ\"ר. עִטּוּ\"ף. הֲדָחָ\"ה. שְׁטִיפָ\"ה. חַ\"י. מָלֵ\"א. וּמְקַבְּלוֹ בִּשְׁתֵּי יָדָיו. וְנוֹתְנוֹ בַיָּמִין. וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח. וְנוֹתֵן עֵינָיו בּוֹ. וּמְשַׁגְּרוֹ בְּמַתָּנָה לְאַנְשֵׁי בֵיתוֹ. וְעַכְשָׁו אֵין לָנוּ אֶלָּא אַרְבָּעָה, שֶׁהֵם: הֲדָחָה. וּשְׁטִיפָה. חַי. מָלֵא. וְיֵשׁ אוֹמְרִים חַי, מִן הֶחָבִית. וְיֵשׁ אוֹמְרִים חַי, הַכּוֹס שָׁלֵם. שֶׁשְּׁבִירָתוֹ זוֹ הִיא מִיתָתוֹ.</p>\n<p>כּוֹס עַל דֶּרֶךְ הַחָכְמָה הוּא אֱלֹהִים, וְהוּא <Nonesmall>[מלא בי\"ה והם]</small> וְכָאן שָׁלֵם. כֹּ\"ס בְּלִי ו', כְּמוֹ כֵּס, שֶׁהוּא פָּגוּם וְחָסֵר בְּלֹא אָלֶף, כֵּן הוּא חָסֵר בְּלִי וָי\"ו, וְהוּא פָּגוּם. הַכִּסֵּ\"א כֵּן עוֹלֶה בְגִימַטְרִיָּא כּוֹס.</p>\n<p>כּוֹס הִיא הֵ\"א, וְצָרִיךְ עֲשָׂרָה דְבָרִים כְּנֶגֶד י', וְהֵם: עִטּוּ\"ר בְּסוֹד הָעֲטָרָה, עֲטֶרֶת תִּפְאֶרֶת. וְזֶהוּ סוֹד עִטּוּר שֶׁאָמְרוּ זִכְרוֹנָם לִבְרָכָה, מְעַטְּרוֹ בְתַלְמִידִים, וְהִיא עֲטֶרֶת הַבְּרִית. עִטּוּ\"ף, <Nonesmall>[תהלים קב]</small> תְּפִלָּה לְעָנִי כִי יַעֲטֹף. שֶׁכָּל הַבְּרָכוֹת וְהַתְּפִלּוֹת מִתְעַטְּפִים עַד שֶׁתַּעֲלֶה תְפִלַּת הֶעָנִי.</p>\n<p>הֲדָחָ\"ה וּשְׁטִיפָ\"ה, כְּמוֹ <Nonesmall>[ויקרא טז]</small> וְטִהֲרוֹ וְקִדְּשׁוֹ. הַטָּהֳרָה מִימִין הַחֶסֶד, וְהַקְּדֻשָּׁה מִשְּׂמֹאל הַגְּבוּרָה. כּוֹס שֶׁל בְּרָכָה מַלְכוּת, מִצַּד בִּינָה הַנִּקְרֵאת אֱלֹהִים. וְנִקְרָא עֲטָרָה מִצַּד הַכֶּתֶר. חַ\"י מִצַּד יְסוֹד הַנִּקְרָא שָׁלוֹם, שֶׁנֶּאֱמַר <Nonesmall>[ישעיה נד]</small> וּבְרִיתִי שְׁלוֹמִי לֹא תָמוּט אָמַר מְרַחֲמֵךְ ה'. מָלֵא מִצַּד תִּפְאֶרֶת. מְקַבְּלוֹ בִּשְׁתֵּי יָדָיו, ה' ה'.</p>\n<p>וְנוֹתְנוֹ בַיָּמִין, כִּי ה' עֶלְיוֹנָה לְחֶסֶד, ה' שְׁנִיָּה לִגְבוּרָה. וּמְסַלְּקוֹ מִן הַקַּרְקַע טֶפַח, בְּסוֹד יוֹ\"ד, כִּי סִלּוּק ה' הוּא יוֹ\"ד. וְנוֹתֵן עֵינָיו בּוֹ, שֶׁהֵם בְּסוֹד יְאֲהדוָנָהִי. יְיָ מֵאִיר בְּבַת עַיִן. יֱהִֹוִ\"ה בִּשְׁלֹשָׁה צִבְעֵי הָעַיִן. אֲדֹנָי מְאִירָה בִּשְׁנֵי כְּרוּבֵי הָעַיִן וְאִישׁוֹנֵי עַפְעַפֵּי הָעַיִן. וּמְשַׁגְּ\"רוֹ בְמַתָּנָה לְאַנְשֵׁי בֵיתוֹ, הִיא בִּינָה, שֶׁנֶּאֱמַר בָּהּ יִשְׂמַח מֹשֶׁה בְּמַתְּנַת חֶלְקוֹ.</p>\n<p>עָשִׂירִי – בִּרְכַּת הַמָּזוֹן, הֲרֵי פֵּרְשׁוּהָ רַבּוֹתֵינוּ, בִּשְׁלֹשָׁה צָרִיךְ כּוֹס. וְסוֹד הַדָּבָר – מִשּׁוּם שֶׁהִיא <Nonesmall>[ירמיה ב]</small> אַהֲבַת כְּלוּלֹתָיִךְ, שֶׁהֵם הָאָבוֹת, בַּכֹּ\"ל מִכֹּ\"ל כֹּ\"ל. וְאֵין לְהַאֲרִיךְ יוֹתֵר.</p>\n<p>בִּרְכַּת הַמָּזוֹן מִן הַתּוֹרָה מִנַּיִן? שֶׁנֶּאֱמַר <Nonesmall>[דברים ח]</small> וְאָכַלְתָּ וְשָׂבָעְתָּ וְגוֹ'. וְשָׁנִינוּ בַּבָּרַיְתָא, וּבֵרַכְתָּ – זוֹ בִּרְכַּת הַזָּן. אֶת ה' אֱלֹהֶיךְ – זוֹ בִּרְכַּת הַמָּזוֹן. עַל הָאָרֶץ – זוֹ בִּרְכַּת הָאָרֶץ. הַטֹּבָה – זוֹ בּוֹנֵה יְרוּשָׁלָיִם. וְכֵן הוּא אוֹמֵר, <Nonesmall>[שם ג]</small> הָהָר הַטּוֹב הַזֶּה וְהַלְּבָנוֹן. אֵין לִי אֶלָּא לְאַחֲרָיו. לְפָנָיו מִנַּיִן? שֶׁנֶּאֱמַר אֲשֶׁר נָתַן לָךְ. מִשָּׁעָה שֶׁנָּתַן לָךְ, חַיָּב אַתָּה לְבָרְכוֹ.</p>\n<p>וְדָרְשׁוּ חֲכָמִים זִכְרוֹנָם לִבְרָכָה, מֹשֶׁה תִּקֵּן לָהֶם לְיִשְׂרָאֵל בִּרְכַּת הַזָּן בְּשָׁעָה שֶׁיָּרַד לָהֶם הַמָּן. יְהוֹשֻׁעַ תִּקֵּן לָהֶם בִּרְכַּת הָאָרֶץ בְּשָׁעָה שֶׁהִכְנִיסָן לָאָרֶץ. דָּוִד וּשְׁלֹמֹה תִּקְּנוּ בּוֹנֵה יְרוּשָׁלָיִם. עוֹד נִמְצָא בְּפָרָשַׁת הַמָּן רֶמֶז לְבִרְכַּת מָזוֹן בַּמָּן עַצְמוֹ, שֶׁנֶּאֱמַר <Nonesmall>[שמות טז]</small> וּבַבֹּקֶר תִּשְׂבְּעוּ לֶחֶם וִידַעְתֶּם כִּי אֲנִי ה' אֱלֹהֵיכֶם.</p>"],[9522012610,"<p>אָמַר רַבִּי שִׁמְעוֹן, הַסּוֹד שֶׁל אוֹתָן שֶׁבַע זַיְ\"נִים שֶׁרְשׁוּמוֹת בַּתְּפִלִּין, שֶׁהוּא שִׁבְעָה שִׁבְעָה, שֶׁרוֹמְזוֹת לְשֶׁבַע אוּנוֹת שֶׁל הָרֵאָה שֶׁל הָאָדָם, שֶׁבָּהֶן שׁוֹאֵב רוּחַ, וּמִמֶּנָּה מֵפִיק הִתְנוֹצְצוּת אֵשׁ שֶׁדּוֹלֶקֶת מִפִּיו. וְעוֹד, שֶׁהֵן רֶמֶז לְשִׁבְעָה יָמִים, וְהַשָּׁבוּעוֹת שֶׁמִּפֶּסַח לַעֲצֶרֶת. וְעוֹד, שֶׁהֵן רוֹמְזוֹת לְשִׁבְעָה קְנֵי הַמְּנוֹרָה שֶׁיֵּשׁ עֲלֵיהֶם שִׁבְעָה מְאוֹרוֹת קְדוֹשִׁים. וְעוֹד, שֶׁהֵן רוֹמְזוֹת לְשִׁבְעָה כּוֹכְבֵי לֶכֶת שֶׁהֵם מְאִירִים בָּרָקִיעַ. וְעוֹד, שֶׁהֵן רוֹמְזוֹת לְשֶׁבַע מַדְרֵגוֹת שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶן, וְהֵן יְסוֹד וְשֹׁרֶשׁ וְעִקַּר הַכֹּל, וַעֲלֵיהֶן אָמְרוּ הַחֲבֵרִים, כָּל מִי שֶׁרוֹצֶה לְהָנִיחַ תְּפִלִּין שֶׁל רֹאשׁ, צָרִיךְ לְהִסְתַּכֵּל בְּאוֹתָן שְׁתֵּי שִׁי\"נִים, שֶׁהֵם רוֹמְזוֹת לְאוֹתָן שֶׁבַע זַיְ\"נִים, שֶׁיֵּשׁ בָּהֶן רֶמֶז סוֹדוֹת נִסְתָּרִים, עֲמֻקִּים רְמוּזִים.</p>"],[9522012611,"<p>כִּי ה' אֱלֹהֵיכֶם הוּא אֱלֹהֵי הָאֱלֹהִים וַאֲדנֵי הָאֲדנִים הָאֵל הַגָּדל וְגוֹ' <Nonesmall>[דברים י]</small>. שָׁנִינוּ, <Nonesmall>[יחזקאל א]</small> וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, אֵלּוּ אֵינָם כְּאוֹתָם כְּרוּבִים. אֵלּוּ פָּנִים גְּדוֹלוֹת. הַכְּרוּבִים פָּנִים קְטַנּוֹת, כְּמוֹ תִּינוֹק. פְּנֵי אָדָם, כָּל דְּמוּת כְּלוּלִים בָּהֶם, מִשּׁוּם שֶׁהֵם פָּנִים גְּדוֹלוֹת, וּמִצְטַיְּרִים בָּהֶם צִיּוּרִים חֲקוּקִים בַּחֲקִיקוֹת הַשֵּׁם הַמְפֹרָשׁ בְּאַרְבָּעָה צְדָדִים, מִזְרָ\"ח מַעֲרָ\"ב צָפוֹ\"ן דָּרוֹ\"ם.</p>\n<p>מִיכָאֵ\"ל רָשׁוּם בְּרֹשֶׁם לְצַד דָּרוֹם, וְכָל הַפָּנִים מִסְתַּכְּלוֹת אֶל פְּנֵי אָדָ\"ם, פְּנֵי אַרְיֵ\"ה פְּנֵי נֶשֶׁ\"ר פְּנֵי שׁוֹ\"ר. אָדָם הוּא זָכָר וּנְקֵבָה, וְלֹא נִקְרָא אָדָם רַק כָּךְ. וּמִמֶּנּוּ מִצְטַיְּרִים צִיּוּרִים שֶׁל <Nonesmall>[תהלים סח]</small> רֶכֶב אֱלֹהִים רִבּתַיִם אַלְפֵי שִׁנְאָן.</p>\n<p>שִׁנְאָןֹ, הַכְּלָל שֶׁל כָּל הַצִּיּוּרִים – שׁוֹ\"ר, נֶשֶׁ\"ר, אַרְיֵ\"ה, ן' זֶהוּ אָדָם. פְּשִׁיטוּת שֶׁנִּכְלֶלֶת כְּאֶחָד בְּסוֹד שֶׁל זָכָר וּנְקֵבָה. וְכֻלָּם אֲלָפִים וּרְבָבוֹת, כֻּלָּם יוֹצְאִים מֵאֵלֶּה סוֹד שִׁנְאָן. מֵהַדְּמֻיּוֹת הַלָּלוּ נִפְרָדִים כָּל אֶחָד וְאֶחָד בְּצִדּוֹ כְּמוֹ שֶׁרָאוּי לָהֶם.</p>\n<p>אֵלֶּה אוֹתָם הַמְשֻׁלָּבִים אֶחָד בְּאֶחָד, וּכְלוּלִים אֶחָד בְּאֶחָד, לִהְיוֹת הַכֹּל אֶחָד כָּלוּל בַּחֲבֵרוֹ, שׁוֹ\"ר נֶשֶׁ\"ר אַרְיֵ\"ה אָדָ\"ם, מִתְנַהֲגִים בְּסוֹד אַרְבָּעָה שֵׁמוֹת חֲקוּקִים עוֹלִים לְהִתְנַהֵג וּלְהִסְתַּכֵּל.</p>\n<p>עוֹלֶה לְהִתְנַהֵג וּלְהִסְתַּכֵּל שׁוֹר לִפְנֵי אָדָם, עוֹלֶה שֵׁם אַחֵר מִתְעַטֵּר חָקוּק בְּסוֹד שְׁנֵי גְוָנִים, וְהוּא אֵל. אָז חוֹזֵר לְאָחוֹר, וְהַכִּסֵּא חוֹקֵק וְגוֹלֵף אוֹתוֹ, וְנִרְשָׁם לְהִתְנַהֵג בְּסוֹד הַשֵּׁם הַזֶּה.</p>\n<p>וְעוֹלֶה לְהִתְנַהֵג וּלְהִסְתַּכֵּל נֶשֶׁר לִפְנֵי אָדָם, עוֹלֶה שֵׁם אֶחָד מִתְעַטֵּר מִתְנַהֵג בְּסוֹד שְׁנֵי פָנִים וּגְוָנִים, לְהִתְנַהֵג לַעֲלוֹת בַּעֲלִיָּה בְּעִטּוּר, וְהוּא גָּדוֹל. אָז חוֹזֵר לְאָחוֹר, וְהַכִּסֵּא חוֹקֵק וְגוֹלֵף אוֹתוֹ, וְנִרְשָׁם לְהִתְנַהֵג בְּסוֹד הַשֵּׁם הַזֶּה.</p>\n<p>עוֹלֶה לְהִתְנַהֵג וּלְהִסְתַּכֵּל אַרְיֵה לִפְנֵי אָדָם, עוֹלֶה שֵׁם אֶחָד מִתְעַטֵּר חָקוּק בְּסוֹד שְׁנֵי פָנִים וּגְוָנִים, לְהִתְחַזֵּק וּלְהִתְקַשֵּׁר בְּתָקְפּוֹ, וְהוּא גִּבּוֹר. אָז חוֹזֵר לְאָחוֹר, וְהַכִּסֵּא חוֹקֵק וְגוֹלֵף אוֹתוֹ, וְנִרְשָׁם לְהִתְנַהֵג בְּסוֹד הַשֵּׁם הַזֶּה.</p>\n<p>אָדָם מִסְתַּכֵּל בְּכֻלָּם, וְכֻלָּם עוֹלִים וּמִסְתַּכְּלִים בּוֹ, אָז כֻּלָּם מִצְטַיְּרִים בְּחִקּוּקֵיהֶם בְּצִיּוּר זֶה, בְּסוֹד שֶׁל שֵׁם אֶחָד שֶׁנִּקְרָא נוֹרָא. וְאָז כָּתוּב עֲלֵיהֶם, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. כֻּלָּם כְּלוּלִים בַּדְּמוּת הַזּוֹ, וְהַדְּמוּת הַזּוֹ כּוֹלֶלֶת אוֹתָם.</p>\n<p>וְעַל סוֹד זֶה נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, שֶׁהֲרֵי שֵׁמוֹת אֵלֶּה חֲקוּקִים הֵם לְמַעְלָה בְּסוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, כְּלוּלָה בְּאַרְבַּע אוֹתִיּוֹת יהוה, שֶׁהוּא שֵׁם שֶׁכּוֹלֵל כָּל הַדְּמֻיּוֹת. אֵלֶּה חֲקוּקִים וּגְלוּפִים בַּכִּסֵּא, וְהַכִּסֵּא הַגָּלוּף מְרֻקָּם בָּהֶם, אֶחָד לְיָמִין, וְאֶחָד לִשְׂמֹאל, וְאֶחָד לְפָנִים, וְאֶחָד לְאָחוֹר. רָשׁוּם בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>הַכִּסֵּא כְּשֶׁעוֹלֶה, רָשׁוּם בְּאַרְבַּע דְּמֻיּוֹת אֵלּוּ. אַרְבָּעָה הַשֵּׁמוֹת הָעֶלְיוֹנִים הַלָּלוּ לוֹקְחִים אֶת הַכִּסֵּא, וְהַכִּסֵּא נִכְלָל בָּהֶם, עַד שֶׁלּוֹקֵחַ וְלוֹקֵט אוֹתָם עִנּוּגִים וְכִסּוּפִים, יוֹרֵד מָלֵא כְעֵץ שֶׁמָּלֵא עֲנָפִים לְכָל צַד וּמָלֵא פֵרוֹת. כֵּיוָן שֶׁיּוֹרֵד, יוֹצְאוֹת אַרְבַּע הַדְּמֻיּוֹת הַלָּלוּ מְצֻיָּרוֹת בְּצִיּוּרֵיהֶן, חֲקוּקוֹת וּנְאוֹרוֹת, נוֹצְצוֹת וְלוֹהֲטוֹת, וְהֵן זוֹרְעוֹת זֶרַע עַל הָעוֹלָם.</p>"],[9522012612,"<p>שֹׁפְטִים וְֹשטְרִים תִּתֶּן לְךְ בְּכָל שְׁעָרֶיךְ אֲשֶׁר ה' אֱלֹהֶיךְ נֹתֵן לְךְ וְגוֹ' <Nonesmall>[דברים טז]</small> בְּמִצְוָה זוֹ לְמַנּוֹת שׁוֹפְטִים וְשׁוֹטְרִיִם. וְעוֹד, <Nonesmall>[תהלים עה]</small> כי אלהים שפט. כי י' <Nonesmall>[מ', ממנּוּ]</small>, יו\"ד שחשבונו כ', אחר כאן, כי אלהים שפט, זה ישפיל, ה\"א ה\"א, וזה ירים, זה ו' ו'.</p>"],[9522012613,"<p>מִצְוָה אַחַר זוֹ – לָדוּן בְּסַיִף, לָדוּן בְּחֶנֶק, לָדוּן בְּדִין סְקִילָה, לָדוּן בְּדִין שְׂרֵפָה. לָדוּן בְּסַיִף לְמִי? לְסָמָאֵ\"ל. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה לד]</small> כִּי רִוְּתָה בַשָּׁמַיִם חַרְבִּי הִנֵּה עַל אֱדוֹם תֵּרֵד.</p>\n<p>חֶרֶב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא – י' רֹאשׁ הַחֶרֶב, ו' גּוּף הַחֶרֶב, הֵ\"א הֵ\"א שְׁתֵּי פִיפִיּוֹת שֶׁלָּהּ. צֶדֶק צֶדֶק תִּרְדּף, חוֹתְכִים שְׁנֵי דִינִים, דִּין מִפִּי בֵּית דִּין שֶׁל מַעְלָה וְדִין מִפִּי בֵּית דִּין שֶׁל מַטָּה. וּמִכָּאן נוֹדָע, אֵין אָדָם נוֹקֵף אֶצְבָּעוֹ מִלְּמַטָּה עַד שֶׁנִּתֶּנֶת לוֹ רְשׁוּת מִלְמַעְלָה.</p>\n<p>נַרְתִּיק שֶׁל הַחֶרֶב – אֲדֹנָ\"י, שָׁם נִמְצָא דִין. בִּקְרִיאַת שְׁמַע – יְהֹוָ\"ה. חֶרֶב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עָלֶיהָ נֶאֱמַר <Nonesmall>[תהלים קמט]</small> רוֹמְמוֹת אֵל בִּגְרוֹנָם וְחֶרֶב פִּיפִיּוֹת בְּיָדָם. בְּצַדִּיק חַי הָעוֹלָמִים, כּוֹלֵל חַ\"י בְּרָכוֹת, שֶׁבּוֹ אֲדנָי שְׂפָתַי תִּפְתָּח וּפִי, בּוֹ נִכְנֶסֶת הַחֶרֶב בְּנַרְתִּיקָהּ, <Nonesmall>[אסתר ז]</small> וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וּמִתְחַבְּרִים שְׁנֵי שֵׁמוֹת – יְאֲהֹדוָנָהי.</p>\n<p>לָדוּן בְּחֶנֶק – זַרְקָא. שָׁם קַו, י' כְּרוּכָה בוֹ, וְקַו, אוֹת ו' שֶׁמִּתְפַּשֶּׁטֶת מִמֶּנָּה. בּוֹ תּוֹפֵס לְסָמָאֵ\"ל, <Nonesmall>[במדבר יג]</small> וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. מַהוּ מוֹט שֶׁל אוֹתוֹ רָשָׁע? אָדָם, שֶׁהוּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, מ\"ה, וְאַרְבַּע אוֹתִיּוֹת יהוה – הֲרֵי אַרְבָּעִים וָתֵשַׁע, כְּחֶשְׁבּוֹן תֵּשַׁע וְאַרְבָּעִים אוֹתִיּוֹת שֶׁהֵן בְּשֵׁשׁ תֵּבוֹת שֶׁל הַיִּחוּד הָעֶלְיוֹן וּבְשֵׁשׁ תֵּבוֹת שֶׁל הַיִּחוּד הַתַּחְתּוֹן, שֶׁהֵן אוֹתִיּוֹת ו' ו'. וְזֶהוּ וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, בְּנִפְרָד מֵהֶם, בְּלִי א' בְּאֶמְצַע וָ\"ו, שֶׁאֵין יִחוּד לַצַּד הָאַחֵר, אֶלָּא וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, סָמָאֵ\"ל וּבַת זוּגוֹ, עוֹלַם הַנִּפְרָדִים.</p>\n<p>בַּחֶבֶל שֶׁיֵּחָנֵק בָּהּ אֲחוּזוֹת הֵ\"א הֵ\"א בְּחָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין וּבְחָמֵשׁ שֶׁל יַד שְׂמֹאל. ו' – הַחֶבֶל. י' – הַחֲנִיקָה שֶׁלָּהֶם. שֵׁם יְהֹוָ\"ה – מִיתָה לְסָמָאֵ\"ל וְהַנָּחָשׁ, וְחַיִּים לְיִשְׂרָאֵל, וּמִשּׁוּם זֶה <Nonesmall>[דברים לב]</small> רְאוּ עַתָּה כִּי אֲנִ\"י אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, אֲנִי אָמִית – לֵאלֹהִים אֲחֵרִים בִּשְׁמִי וּלְכָל שֶׁלֹּא הֶאֱמִינוּ בוֹ, וַאֲחַיֶּה – לְאֵלּוּ שֶׁמַּאֲמִינִים וְשׁוֹמְרִים מִצְווֹת שֶׁלִּי.</p>\n<p>לָדוּן בִּסְקִילָה – לְסָמָאֵ\"ל, בְּאֶבֶן שֶׁהִיא י' זוֹרֵק לָהּ <Nonesmall>[צדיק]</small> אֶצְלָהּ בְּחָמֵשׁ אֶצְבָּעוֹת שֶׁהֵם ה', וּבַקָּנֶה שֶׁל הַזְּרוֹעַ שֶׁהוּא ו', וּבַכָּתֵף שֶׁשָּׁם ה'. וְזוֹרֵק אוֹתָהּ אֶל הַמַּחֲשָׁבָה, שֶׁהוּא שֵׁם הַמְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א.</p>\n<p>לָדוּן בִּשְׂרֵפָה – לְסָמָאֵ\"ל, עֵצִים לְהַדְלִיק בָּהֶם אֵשׁ. אַשְׁרָיו הַגּוּף שֶׁהוּא עֵץ, וְאֵיבָרִים שֶׁלּוֹ עֵץ, לְהַדְלִיק בָּהֶם אֵשׁ, שֶׁהוּא נֵר מִצְוָה, בְּכָל אֵיבָר, לְהַבְעִיר אֶת סָמָאֵ\"ל בַּשְּׁכִינָה הָעֶלְיוֹנָה בְּעֵץ, שֶׁהוּא תִפְאֶרֶת, וּבְכָל עֵצִים שֶׁאֲחוּזִים בּוֹ. שֶׁבִּזְמַן שֶׁאֵשׁ שֶׁל גָּבוֹהַּ הָיָה יוֹרֵד עַל גַּבֵּי הָעֵצִים שֶׁל הַקָּרְבָּן, <Nonesmall>[במדבר א]</small> וְהַזָּר הַקָּרֵב יוּמָת, שֶׁנִּשְׂרָף בּוֹ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ויקרא ו]</small> וְהָאֵשׁ עַל הַמִּזְבֵּחַ תּוּקַד בּוֹ. אַשְׁרָיו מִי שֶׁאָחוּז בְּאִילַן הַחַיִּים בְּגוּפוֹ, בָּאֵיבָרִים שֶׁלּוֹ, נֵר – כָּל עָנָף וְעָנָף נֵר מִצְוָה בְּמָאתַיִם וְאַרְבָּעִים וּשְׁמוֹנֶה מִצְווֹת שֶׁלּוֹ.</p>\n<p>כַּאֲשֶׁר אֲחוּזִים בּוֹ שְׁנֵיהֶם, יִתְקַיֵּם <Nonesmall>[שמות ג]</small> וַיַּרְא וְהִנֵּה הַסְּנֶה בֹּעֵר בָּאֵשׁ וְהַסְּנֶה אֵינֶנּוּ אֻכָּל. וְסָמָאֵ\"ל וְהַנָּחָשׁ וְכָל הַמְמֻנִּים שֶׁלּוֹ, שֶׁהֵם קוֹצִים, נִשְׂרְפוּ. וְהָעֲנָפִים שֶׁל הַסְּנֶה, וְהַפְּרִי שֶׁלּוֹ, וְהֶעָלִים שֶׁלּוֹ, לֹא נִשְׂרְפוּ. זֶה הֶרְאָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, וַדַּאי יִשְׂרָאֵל הֵם עֵצִים יְבֵשִׁים בַּתּוֹרָה, מִשּׁוּם שֶׁאֲחוּזִים בְּאֵשׁ שֶׁל הֶדְיוֹט, אֵינָם כְּמוֹ שֶׁרָאוּי לַעֲשׂוֹת לָהֶם נֵס. מִיָּד שֶׁאַתָּה יוֹרֵד עֲלֵיהֶם בַּתּוֹרָה, בִּגְלָלְךְ יָרַד עֲלֵיהֶם עֵץ הַחַיִּים, וּמִצְוָה שֶׁהִיא נֵר ה', וְאוֹחֶזֶת בָּהֶם וְיִהְיוּ חַיִּים. וְאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם נִשְׂרָפִים בְּאוֹתוֹ נֵר. וְזֶהוּ שֶׁאָמַר הַנָּבִיא, <Nonesmall>[ירמיה מו]</small> וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי אִתְּךְ אָנִי וְגוֹ'.</p>"],[9522012614,"<p>לֹא יָקוּם עֵד אֶחָד בְּאִישׁ לְכָל עָוֹן וְגוֹ', עַל פִּי שְׁנֵי עֵדִים אוֹ עַל פִּי שְׁלֹשָׁה עֵדִים יָקוּם דָּבָר <Nonesmall>[דברים יט]</small>. מִצְוָה זוֹ לְהָעִיד עֵדוּת בְּבֵית דִּין, שֶׁלֹּא יַפְסִיד חֲבֵרוֹ מָמוֹן בִּגְלָלוֹ אִם יֵשׁ לוֹ עֵדוּת עִמּוֹ. וְאֵין עֵדוּת פָּחוֹת מִשְּׁנַיִם, זֶהוּ שֶׁכָּתוּב עַל פִּי שְׁנַיִם [שני] עֵדִים וְגוֹ' יָקוּם דָּבָר, לֹא יָקוּם עַל פִּי עֵד אֶחָד. וּמִשּׁוּם זֶה בֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, מִי מֵעִיד עַל הָאָדָם? קִירוֹת בֵּיתוֹ. וְלֹא עוֹד, אֶלָּא אַנְשֵׁי בֵיתוֹ מְעִידִין עָלָיו. מָהֵם קִירוֹת בֵּיתוֹ? אֵלּוּ קִירוֹת לִבּוֹ. <Nonesmall>[ישעיה לח]</small> וַיַּסֵּב חִזְקִיָּהוּ פָנָיו אֶל הַקִּיר. וּבֵאֲרוּהוּ רַבּוֹתֵינוּ, מְלַמֵּד שֶׁהִתְפַּלֵּל חִזְקִיָּהוּ מִקִּירוֹת לִבּוֹ.</p>\n<p>אַנְשֵׁי בֵיתוֹ, אֵלּוּ מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים שֶׁלּוֹ. שֶׁכָּךְ בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, רָשָׁע, עֲוֹנוֹתָיו חֲקוּקִים עַל עַצְמוֹתָיו. וְכָךְ צַדִּיק, זְכֻיּוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. וּמִשּׁוּם זֶה אָמַר דָּוִד, <Nonesmall>[תהלים לה]</small> כָּל עַצְמֹתַי תֹּאמַרְנָה. וּבִגְלָלוֹ נֶאֱמַר, וּמִי מְעִידִין עַל הָאָדָם? קוֹרוֹת בֵּיתוֹ. עֲצָמוֹת בְּנוּיוֹת עַל הַמֹּחַ, שֶׁהוּא מַיִם. וַעֲלֵיהֶם הוּא רוֹמֵז, <Nonesmall>[תהלים קד]</small> הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. הַמְקָרֶה, לְשׁוֹן קוֹרוֹת.</p>\n<p>וּמַדּוּעַ בָּעֲצָמוֹת יוֹתֵר מִבָּשָׂר וְגִידִים וְעוֹר? מִשּׁוּם שֶׁעֲצָמוֹת הֵן לְבָנוֹת, וּכְתִיבָה שְׁחֹרָה לֹא נוֹדַעַת אֶלָּא מִתּוֹךְ לֹבֶן, כְּדֻגְמַת הַתּוֹרָה, שֶׁהִיא לְבָנָה מִבִּפְנִים וּשְׁחֹרָה מִבַּחוּץ. שָׁחֹר וְלָבָן, חֹשֶׁךְ וְאוֹר. וְיֵשׁ חֹשֶׁךְ תְּכֵלֶת, וְנֶאֱמַר בּוֹ <Nonesmall>[תהלים קלט]</small> גַּם חֹשֶׁךְ לֹא יַחְשִׁיךְ מִמֶּךָּ. וּתְכֵלֶת שָׁחֹר הִיא נְקֵבָה לְגַבֵּי הַלֹּבֶן.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁהַגּוּף עַל הָעֲצָמוֹת עָתִיד לַעֲמֹד, וּמִשּׁוּם זֶה זְכֻיּוֹתָיו וְחוֹבוֹתָיו חֲקוּקוֹת עַל הָעֲצָמוֹת שֶׁלּוֹ, וְאִם יִזְכֶּה, יָקוּם הַגּוּף עַל הָעֲצָמוֹת שֶׁלּוֹ. וְאִם לֹא, לֹא יָקוּם וְלֹא יִהְיֶה לוֹ תְּחִיַּת הַמֵּתִים. וְלֹא עוֹד, אֶלָּא שְׁנֵי עֵדִים הֵם עַל הָאָדָם – עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת, וּבֵית דִּין סוֹפֵר וְדָן חוֹבוֹתָיו. וְלֹא עוֹד, אֶלָּא שֶׁמֶשׁ וְיָרֵחַ מְעִידִים עַל הָאָדָם, כְּמוֹ שֶׁבֵּאֲרוּהוּ <Nonesmall>[תהלים פא]</small> תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. מַהוּ בַכֶּסֶה? בַּיּוֹם שֶׁהַלְּבָנָה מִתְכַּסָּה. וּמַדּוּעַ מִתְכַּסֵּית? מִשּׁוּם שֶׁכַּאֲשֶׁר מַגִּיעַ רֹאשׁ הַשָּׁנָה, מַגִּיעַ סָמָאֵ\"ל לִתְבֹּעַ דִּין לְבָנָיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא אוֹמֵר לוֹ שֶׁיָּבִיא עֵדִים. וְהוּא מֵבִיא לַשֶּׁמֶשׁ עִמּוֹ. הוֹלֵךְ לְהָבִיא הַלְּבָנָה, וְהִיא מִתְכַּסָּה. בְּאֵיזֶה מָקוֹם מִתְכַּסֵּית? אֶלָּא עוֹלָה לַמָּקוֹם הַהוּא שֶׁנֶּאֱמַר בּוֹ בַּמְכֻסֶּה מִמָּךְ אַל תַּחְקֹר, לְפַיֵּס לוֹ עַל בָּנֶיהָ.</p>\n<p>וְזְהִוּ שֶׁאָמַר הַפָּסוּק, תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. לַמָּקוֹם שֶׁבּוֹ עוֹלָה הַשְּׁכִינָה, שֶׁנֶּאֱמַר בּוֹ וּבַמְכֻסֶּה מִמָּךְ אַל תַּחְקֹר. וַחֲטָאִים בְּכִסּוּי, שָׁם צָרִיךְ לָדוּן בֵּינוֹ לְבֵין קוֹנוֹ. וַעֲבֵרוֹת בְּגָלוּי שֶׁעָשָׂה אוֹתָם, נֶאֱמַר <Nonesmall>[משלי כח]</small> מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ. שֶׁהַשְּׁכִינָה מִצַּד הַכֶּתֶר הִיא עוֹלָם הַנֶּעְלָם, וּבֵאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה שֶׁצָּרִיךְ אָדָם לְחַבֵּר אוֹתָהּ לַמָּקוֹם הַהוּא. בַּזְּמַן הַהוּא מַגִּיעַ זְמַן הָרַחֲמִים וְעוֹבֵר הַדִּין. וּמִשּׁוּם זֶה לַחֲבֵרוֹ אָמַר לְזַכּוֹת אוֹתוֹ בְּעֵדוּתוֹ, אֲבָל לְרָשָׁע אֵין מְזַכִּין לוֹ.</p>\n<p>וְעוֹד, הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ עֵדִים עַל הָאָדָם, זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים ל]</small> הַעִידתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אֶת הַשָּׁמַיִם – אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[מלכים א ח]</small> וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. וְאֶת הָאָרֶץ – אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[ישעיה סו]</small> וְהָאָרֶץ הֲדם רַגְלָי. וְעוֹד, שְׁנֵי עֵדִים – הָעַמּוּד הָאֶמְצָעִי וְצַדִּיק. וְהֵם אוֹתִיּוֹת ע\"ד מִשְּׁמַע אֶחָד. עֵ\"ד – מִבָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>\n<p>עֵל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה עֵדִים יוּמַת הַמֵּת. זֶה סָמָאֵ\"ל, מֵת מֵעִקָּרוֹ, <Nonesmall>[במדבר יג]</small> וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. לֹא יוּמַת עַל פִּי עֵד אֶחָד, שֶׁלֹּא יִהְיֶה לוֹ חֵלֶק בְּאֵל אֶחָד.</p>\n<p>כִּי יָקוּם עֵד חָמָס בְּאִישׁ וְגוֹ' וְדָרְשׁוּ הַשּּׁפְטִים הֵיטֵב וְגוֹ', וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם וְגוֹ'. מִצְוָה זוֹ לִדְרֹשׁ וְלַחְקֹר הָעֵדִים בְּשֶׁבַע חֲקִירוֹת קֹדֶם שֶׁיָּדוּן לוֹ בְּעֹנֶשׁ מִיתָה. בְּשֶׁבַע חֲקִירוֹת, שֶׁבַע כְּנֶגֶד <Nonesmall>[זכריה ד]</small> שִׁבְעָה אֵלֶּה עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים בְּכָל הָאָרֶץ. בָּהֶם <Nonesmall>[ויקרא כו]</small> וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי שֶׁבַע.</p>"],[9522012615,"<p>מִצְוָה אַחַר זוֹ – לַעֲשׂוֹת לְעֵד זוֹמֵם כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו. שְׁנֵי עֵדֵי שֶׁקֶר, שֶׁהֵם סָמָאֵ\"ל וְנָחָשׁ, אִם יָבוֹאוּ לְהָעִיד עֵדוּת שֶׁל שֶׁקֶר עַל יִשְׂרָאֵל, שֶׁטָּעוּ בֵּין שֵׁשׁ לְשֶׁבַע, שֶׁהֵם אוֹתִיּוֹת ז\"וּ. וְזֶהוּ <Nonesmall>[ישעיה מג]</small> עַם זוּ יָצַרְתִּי לִי תְּהִלָּתִי יְסַפֵּרוּ.</p>\n<p>וְלֹא יִתְיַחֵד ו' עִם ז' אֶלָּא בִּשְׂרֵפַת חָמֵץ, שֶׁבֵּין שָׁעָה שִׁשִּׁית לִשְׁבִיעִית. וְאַף עַל גַּב שֶׁמֵּהַתּוֹרָה הוּא עַד סוֹף שֵׁשׁ, גָּזְרוּ רַבּוֹתֵינוּ, אוֹכְלִין כָּל אַרְבַּע, וְתוֹלִין כָּל חָמֵשׁ, וְשׂוֹרְפִין בִּתְחִלַּת שֵׁשׁ. וּמְלַמְּדִים בַּעֲלֵי הַמִּשְׁנָה מֵעֵדוּת שֶׁל שְׁעוֹת הֶחָמֵץ לָעֵדוּת שֶׁל בְּדִיקוֹת הָעֵדִים שֶׁל אוֹתוֹ שֶׁהָרַג אֶת הַנֶּפֶשׁ. וְהַכֹּל מְפֹרָשׁ בַּמִּשְׁנָה. וִיקֻיַּם בָּהֶם, כִּי בַדָּבָר שֶׁחָשְׁבוּ מִצְרַיִם לָדוּן וְכוּ'. וְזֶהוּ וַעֲשִׂיתֶם לוֹ כַּאֲשֶׁר זָמַם. <Nonesmall>[דף ער\"ה ע\"ב]</small></p>"],[9522012616,"<p>מִצְוָה אַחַר זוֹ – לְקַבֵּל בֵּית דִּין הַגָּדוֹל עֲלֵיהֶם. בִּינָה, מִצַּד הַגְּדֻלָּה נִקְרֵאת אֱלֹהִים, בֵּין דִּין הַגָּדוֹל, גָּדוֹל בְּדִינָיו, וְגָדוֹל בִּזְכֻיּוֹתָיו, כְּמוֹ שֶׁנֶּאֱמַר שׂוֹם תָּשִׂים עָלֶיךְ מֶלֶךְ, בְּמִצְוָה. שׂוֹם – לְמַעְלָה, תָּשִׂים – לְמַטָּה. כָּךְ לְקַבֵּל עָלָיו בֵּית דִּין הַגָּדוֹל, אַף עַל גַּב שֶׁקִּבֵּל עָלָיו בֵּית דִּין הַקָּטָן. בֵּין דִּין הַקָּטָן, בֵּית דִּין שֶׁל שְׁלֹשָׁה, מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה. בֵּין דִּין הַגָּדוֹל, מֵאֵלּוּ סַנְהֶדְרִין גְּדוֹלָה.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, שִׁבְעִים אִישׁ הָיוּ בְסַנְהֶדְרִין גְּדוֹלָה, וְאַתָּה הַגָּדוֹל עַל כֻּלָּם, <Nonesmall>[שמות יח]</small> וְהָיָה כָּל הַדָּבָר הַגָּדל יָבִיאוּ אֵלֶיךְ וְכָל הַדָּבָר הַקָּטֹן יִשְׁפְּטוּ הֵם. אֵלּוּ <Nonesmall>[הם סנהדרין גדולה, סנהדרין קטנה]</small>. סַנְהֶדְרִין גְּדוֹלָה מִצַּד הַשְּׁכִינָה הָעֶלְיוֹנָה, סַנְהֶדְרִין קְטַנָּה מִצַּד הַשְּׁכִינָה הַתַּחְתּוֹנָה.</p>\n<p>מֹשֶׁה שׁוֹשְׁבִין הַמֶּלֶךְ, אַהֲרֹן שׁוֹשְׁבִין הַמַּלְכָּה. וְעִמָּהֶם שִׁבְעִים וּשְׁנַיִם סַנְהֶדְרִין, כְּמִנְיַן חֶסֶד, וּמִכָּאן סַנְהֶדְרִין גְּדוֹלָה. סַנְהֶדְרִין קְטַנָּה מִצַּד הַשְּׂמֹאל, <Nonesmall>[בראשית א]</small> אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה.</p>\n<p>וּמִשּׁוּם זֶה, תִּפְאֶרֶת – אֶת הַמָּאוֹר הַגָּדל לְמֶמְשֶׁלֶת הַיּוֹם, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[תהלים מב]</small> יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. אֶת הַמָּאוֹר הַקָּטֹן לְמֶמְשֶׁלֶת הַלַּיְלָה, <Nonesmall>[שם]</small> וּבַלַּיְלָה שִׁירֹה עִמִּי. שִׁיר הַלְוִיִּם, וְזֶה יְסוֹד. <Nonesmall>[שמואל א כ]</small> בֶּן יִשַׁי חַי עַל הָאֲדָמָה, שֶׁתִּקֵּן עֲשָׂרָה מִינֵי תְהִלִּים בְּשִׁירָה. וְהוּא צַדִּיק לִשְׂמֹאל, אֶת הַמָּאוֹר הַקָּטֹן, וְזוֹ שְׁכִינָה, שֶׁנּוֹטֶלֶת מֵהַשְּׂמֹאל.</p>"],[9522012617,"<p>וְעָנְשׁוּ אֹתוֹ מֵאָה כֶסֶף וְגוֹ' <Nonesmall>[דברים כב]</small>. מִצְוָה זוֹ לָדוּן בְּדִין מוֹצִיא שֵׁם רָע, זֶהוּ שֶׁכָּתוּב וְעָנְשׁוּ אֹתוֹ מֵאָה כֶסֶף וְנָתְנוּ לַאֲבִי הַנַּעֲרָה כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל. רַבּוֹתֵינוּ, וְזֶהוּ אַחַר נִשּׂוּאִין, שֶׁאָמַר לֹא מָצָאתִי לְבִתְּךְ בְּתוּלִים. וְלֹא כָּל שֵׁם רָע שָׁקוּל, שֶׁמְּרַגְּלִים שֶׁהוֹצִיא שֵׁם רָע עַל הָאָרֶץ נֶעֶנְשׁוּ בִגְלָלָהּ וּמֵתוּ, וְלֹא זָכוּ בָהּ. וְאִשָּׁה הִיא קַרְקַע בָּאָרֶץ, כְּמוֹ שֶׁבֵּאֲרוּהָ, אֶסְתֵּר קַרְקַע עוֹלָם הָיְתָה.</p>\n<p>וְאִם תֹּאמְרוּ, שֵׁם רָע עָלֶיהָ, שֶׁנִּטְמְאָה בַאֲחַשְׁוֵרוֹשׁ, וְזָכְתָה לְהִתְלַבֵּשׁ בָּהּ רוּחַ הַקֹּדֶשׁ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[אסתר ה]</small> וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. הֲרֵי אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, <Nonesmall>[ישעיה מב]</small> אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים. וְרוּחַ הַקֹּדֶשׁ שְׁכִינָה הָיְתָה, שֶׁהִיא שֵׁם שֶׁהִתְלַבְּשָׁה בְאֶסְתֵּר.</p>\n<p>אֲבָל רַבּוֹתֵינוּ, אוֹי לְאוֹתָם שֶׁאוֹכְלִים תֶּבֶן תְּבֶל שֶׁל הַתּוֹרָה <Nonesmall>[חמו\"ר של התורה שנחשב ח'כם מ'פלא ו'רב ר'בנן]</small> וְלֹא יוֹדֵעַ בְּסִתְרֵי תוֹרָה, אֶלָּא קַלִּים וַחֲמוּרִים שֶׁל הַתּוֹרָה. קַלִּים תֶּבֶן שֶׁל הַתּוֹרָה. וְחֻמְרָה שֶׁל הַתּוֹרָה חִטָּה, חֵט ה', עֵץ שֶׁל טוֹב וָרָע.</p>\n<p>אֵין דֶּרֶךְ שֶׁל מֶלֶךְ וּמַלְכָּה לִרְכֹּב עַל חֲמוֹר, אֶלָּא עַל סוּסִים, זֶהוּ שֶׁכָּתוּב <Nonesmall>[חבקוק ג]</small> כִּי תִרְכַּב עַל סוּסֶיךְ מַרְכְּבֹתֶיךְ יְשׁוּעָה. שֶׁאֵין מְזַלְזְלִים בַּמַּלְכוּת לְהַרְכִּיב הַמַּלְכָּה עַל חֲמוֹר. כָּל שֶׁכֵּן מֶלֶךְ, אֵין זֶה מְקוֹם הֶדְיוֹט עֶבֶד, שֶׁדַּרְכּוֹ לִרְכַּב עַל חֲמוֹר. וְלָכֵן כָּתוּב בַּמָּשִׁיחַ <Nonesmall>[זכריה ט]</small> עָנִי וְרוֹכֵב עַל חֲמוֹר. עָנִי הוּא שָׁם בְּסִימָן: עֵרוּבִין, נִדָּה, יְבָמוֹת. וּשְׁאָר מִשְׁנָיוֹת בִּכְלָל. וְלֹא נִקְרָא שָׁם מֶלֶךְ, עַד שֶׁרוֹכֵב בְּסוּסָה שֶׁלּוֹ, כְּנֶסֶת יִשִׂרָאֵל.</p>\n<p>כְּשֶׁהַקָּדוֹשׁ בָּרוּךָֹ הוּא מִחוּץ לִמְקוֹמוֹ, אֵינוֹ מֶלֶךְ. וּכְשֶׁחוֹזֵר לִמְקוֹמוֹ, <Nonesmall>[זכריה יד]</small> וְהָיָה ה' לְמֶלֶךְ. וְכָךְ יִשְׂרָאֵל, נֶאֱמַר בָּהֶם, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים. כְּמוֹ שֶׁהָאָב, הֵם בָּנָיו. אֵינָם בְּנֵי מְלָכִים, עַד שֶׁיַּחְזְרוּ לְאֶרֶץ יִשְׂרָאֵל. וְאִם תֹּאמַר שֶׁהֶדְיוֹט זֶה, אַף עַל גַּב שֶׁהוּא הֶדְיוֹט לְרִבּוֹנוֹ, בְּרָכָה עָלָיו נֶאֱמַר אַל תְּהִי בִּרְכַּת הֶדְיוֹט קַלָּה בְּעֵינֶיךְ. וְהֶדְיוֹט זֶה לְגַבֵּי הַמֶּלֶךְ עֶבֶד מְטַטְרוֹן. וְאָדָם הָרִאשׁוֹן שֶׁלֹּא שָׁמַר אֶת הַכָּבוֹד שֶׁנָּתְנוּ לוֹ, הוֹרִידוּ אוֹתוֹ לֶאֱכֹל עִם חֲמוֹרִים, וְאָמַר, אֲנִי וַחֲמוֹרִי נֹאכַל בְּאֵבוּס אֶחָד. וְיִשָּׂשכָר זָכָה לְהִקָּרֵא בַּחֲמוֹר הַזֶּה, <Nonesmall>[בראשית מט]</small> יִשָּׂשכָר חֲמוֹר גָּרֶם.</p>\n<p>וְרַבּוֹתֵינוּ בַּעֲלֵי הַמִּשְׁנָה, בַּמַּלְכָּה נֶאֱמַר <Nonesmall>[תהלים קג]</small> וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. אַחַר שֶׁהִתְלַבְּשָׁה בָּהּ אֶסְתֵּר, שָׁלְטָה אֶסְתֵּר עַל אֲחַשְׁוֵרוֹשׁ וְאֻמָּתוֹ, וְנֶאֱמַר בָּהֶם <Nonesmall>[אסתר ט]</small> וְהָרוֹג בְּשׁנְאֵיהֶם. וְאִם תֹּאמַר שֶׁהִתְיַחֵד עִמָּהּ, אַף עַל גַּב שֶׁהָיוּ בְּבַיִת אֶחָד – חַס וְשָׁלוֹם, אֶלָּא כְּמוֹ יוֹסֵף, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[בראשית לט]</small> וַתַּנַּח בִּגְדוֹ אֶצְלָהּ, וְלֹא לְבוּשׁוֹ, אֶלָּא בִּגְדוֹ, לְשׁוֹן <Nonesmall>[ישעיה כד:טז]</small> בּוֹגְדִים בָּגָדוּ.</p>\n<p>וְכָאן סוֹד גָּדוֹל. וּמִשּׁוּם זֶה אֶסְתֵּר, לְשׁוֹן הַסְתָּרָה, <Nonesmall>[תהלים לב]</small> אַתָּה סֵתֶר לִי. הַשְּׁכִינָה הִסְתִּירָה אוֹתָהּ מֵאֲחַשְׁוֵרוֹשׁ, וְנָתְנָה לוֹ שֵׁדָה בִּמְקוֹמָהּ, וְהִיא חָזְרָה לִזְרוֹעוֹת מָרְדְּכַי. וּמָרְדְּכַי שֶׁיָּדַע אֶת שֵׁם הַמְפֹרָשׁ וְשִׁבְעִים לָשׁוֹן, עָשָׂה כָּל זֶה בְּחָכְמָה. וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁאֲפִלּוּ בְּלִי זֶה יֵשׁ לָאָדָם לִפְנֵי שֶׁיִּתְיַחֵד עִם אִשְׁתּוֹ לְדַבֵּר עִמָּהּ, מִשּׁוּם שֶׁשֶּׁמָּא הִתְחַלְּפָה שֵׁדָה בְּאִשְׁתּוֹ.</p>\n<p>וְזְהִ בְּאִשָּׁה מֵעֵץ טוֹב וָרָע. אֲבָל אִם הִיא מִשְּׁכִינָה, אֵין לָהּ שִׁנּוּי, זֶהוּ שֶׁכָּתוּב <Nonesmall>[מלאכי ג]</small> אֲנִי ה' לֹא שָׁנִיתִי. אֲנִי – זוֹ הַשְּׁכִינָה. וְאֵין לָהּ פַּחַד מִכָּל הַצְּדָדִים הָאֲחֵרִים, זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה מ]</small> כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ.</p>\n<p>וּבְמָקוֹם שֶׁיֵּשׁ שָׁם שְׁכִינָה, כַּמָּה סְגֻלּוֹת יֵשׁ שָׁם. וּמִשּׁוּם שֶׁאֶסְתֵּר הִתְלַבְּשָׁה בָּהּ הַשְּׁכִינָה, רְאוּיָה הָיְתָה לַעֲשׂוֹת לָהּ כַּמָּה סְגֻלּוֹת <Nonesmall>[צומות]</small>. כְּמוֹ שָׂרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַר אוֹתָהּ, מִשּׁוּם הַשְּׁכִינָה שֶׁהָיְתָה עִמָּהּ שָׁמַר אוֹתָהּ מִפַּרְעֹה, וַאֲפִלּוּ לְבוּשָׁהּ וְתַכְשִׁיטֶיהָ, בְּכֻלָּם שָׂם הַקָּדוֹשׁ בָּרוּךְ הוּא סְגֻלּוֹת מִשּׁוּם הַשְּׁכִינָה. וּמִשּׁוּם זֶה בָּא פַּרְעֹה לְסַנְדָּלָהּ, הִכָּה אוֹתוֹ בּוֹ. וְכָךְ גַּם בְּכָל תַּכְשִׁיטֶיהָ. בְּכָל תַּכְשִׁיט וְתַכְשִׁיט שֶׁהָיָה נוֹגֵעַ בּוֹ, הָיָה מַכֶּה אוֹתוֹ, עַד שֶׁאוֹתוֹ הַטָּמֵא נִפְרָד מִמֶּנָּה, וְהֶחֱזִירָהּ לְבַעְלָהּ.</p>\n<p>וְאִם בְּתַכְשִׁיטֶיהָ כָּךְ, כָּל שֶׁכֵּן מִי שֶׁנּוֹגֵעַ בְּגוּפָהּ, וַאֲפִלּוּ בְּאֶצְבַּע שֶׁלָּהּ, לְצַד הַיִּחוּד, <Nonesmall>[במדבר א]</small> וְהַזָּר הַקָּרֵב יוּמָת. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נָתַן לוֹ רְשׁוּת לִקְרַב אֵלֶיהָ, זֶהוּ שֶׁכָּתוּב אֲני ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן.</p>\n<p>וּמִשּׁוּם זֶה לֹא כָּל שֵׁם רָע שָׁקוּל. מְרַגְּלִים שֶׁהוֹצִיאוּ שֵׁם רָע עַל אֶרֶץ יִשְׂרָאֵל, מֵתוּ. מִי שֶׁמּוֹצִיא שֵׁם רָע עַל הַשְּׁכִינָה, כָּל שֶׁכֵּן שֶׁלּוֹקִים בְּנִשְׁמָתָם. שֶׁאֵלֶּה שֶׁהוֹצִיאוּ שֵׁם רָע עַל הָאָרֶץ, לָקוּ בְגוּפָם, וּמִיתַת עַצְמָם מֵתוּ. אֲבָל מִי שֶׁמּוֹצִיא שֵׁם רָע עַל הַשְּׁכִינָה, נִשְׁמָתָם לוֹקָה. וְזֶה לְמִי שֶׁיּוֹדֵעַ סוֹד זֶה וְעֵינָיו פְּתוּחוֹת. אֲבָל מִי שֶׁעֵינָיו סְתוּמוֹת, אֵין לוֹ כָּל כָּךְ עֹנֶשׁ.</p>\n<p>וּמַה שֶּׁרַבּוֹתֵינוּ שֶׁל הַמִּשְׁנָה שָׂמוּ לִפְנֵיהֶם, שֶׁאִשָּׁה אֲנוּסָה מֻתֶּרֶת לְבַעְלָהּ, וַדַּאי אִסּוּר וְהֶתֵּר שֶׁל הַמִּשְׁנָה לֹא מְדַבֵּר אֶלָּא בִּדְבָרִים שֶׁל הָאָדָם, וְאִשָּׁה שֶׁהִיא מֵעֵץ הַדַּעַת טוֹב וָרָע. אֲבָל אִשָּׁה שֶׁהִיא מֵעֵץ הַחַיִּים, אֵין דִּינָהּ כְּאֵלֶּה. <Nonesmall>[שהם מאילן עץ הדעת טוב ורע]</small> שֶׁאוֹתוֹ עֵץ הַחַיִּים צַדִּיק וְטוֹב לוֹ, וּבִשְׁבִילוֹ נֶאֱמַר <Nonesmall>[משלי יב]</small> לֹא יְאֻנֶּה לַצַּדִּיק כָּל אָוֶן, וְלֹא לְבַת זוּגוֹ הַצַּדֶּקֶת. וְלָמַדְנוּ מִשָּׂרָה בְּבֵית פַּרְעֹה, שֶׁלֹּא הָיְתָה לוֹ רְשׁוּת לְהִתְקָרֵב אֵלֶיהָ.</p>\n<p>וּמִי שֶׁהוּא צַדִּיק וְרַע לוֹ, זֶה שֶׁהוּא מֵעֵץ שֶׁל טוֹב וָרָע, שֶׁכֵּיוָן שֶׁרַע עִמּוֹ, אֵין צַדִּיק אֲשֶׁר לֹא יֶחֱטָא בְּאוֹתוֹ רַע, מֵאַחַר שֶׁהוּא עִמּוֹ. רָשָׁע וְטוֹב לוֹ, שֶׁהִתְגַּבֵּר יֵצֶר הָרָע עַל יֵצֶר הַטּוֹב, נֶאֱמַר וְטוֹב לוֹ. טוֹב הוּא תַּחַת רְשׁוּתוֹ, וּמִשּׁוּם שֶׁהָרַע שׁוֹלֵט עַל הַטּוֹב, הוּא רָשָׁע, שֶׁאוֹתוֹ שֶׁהִתְגַּבֵּר לָקַח אֶת הַשֵּׁם. רָשַׁע וְרַע לוֹ, אֵל אַחֵר, סָמָאֵל. וְרַע לוֹ, סַם הַמָּוֶת שֶׁלּוֹ עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, <Nonesmall>[תהלים לד]</small> תְּמוֹתֵת רָשָׁע רָעָה. וּמִשּׁוּם זֶה אֵינָהּ אֲנוּסָה, אֶלָּא יֵשׁ בָּהּ תַּעֲרֹבֶת בְּאוֹתָהּ נְשָׁמָה שֶׁל טוֹב וָרָע.</p>\n<p>וְהַתּוֹרָה שֶׁנִּבְרְאָה <Nonesmall>[שנתנה]</small>, נִשְׁבְּרוּ לוּחוֹתֶיהָ, שֶׁמְּשׁוּלִים לַבְּתוּלִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָזַר וְנָתַן אוֹתָם לְיִשְׂרָאֵל לִשְׁמֹר אוֹתָהּ. תּוֹרָה שֶׁבְּעַל פֶּה נִקְרֵאת הֲלָכָה לְמֹשֶׁה מִסִּינַי, וְהֶחָתָן שֶׁלָּהּ שָׁבַר אֶת בְּתוּלֶיהָ. וּמִי שֶׁמּוֹצִיא עָלֶיהָ שֵׁם רָע, שֶׁיֹּאמַר שֶׁהַתּוֹרָה הִיא אֵינֶנָּה זוֹ, שֶׁהֲרֵי לוּחוֹתֶיהָ נִשְׁבְּרוּ – הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא אֲבִי הַנַּעֲרָה, יֹאמַר לוֹ: בַּת, שֶׁהִיא בְּתֵבַת בְּרֵאשִׁית, הִיא בַּת הַמֶּלֶךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר: <Nonesmall>[דברים כב]</small> וּפָרְשׂוּ הַשִּׂמְלָה, וְנִפְתַּחַת יְרִיעָה מִסֵּפֶר תּוֹרָה, וְיִרְאוּ שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[שמות לד]</small> פְּסָל לְךְ שְׁנֵי לֻחֹת אֲבָנִים כָּרִאשּנִים וְכָתַבְתִּי עַל הַלֻּחֹת אֶת הַדְּבָרִים אֲשֶׁר הָיוּ עַל הַלֻּחֹת הָרִאשֹׁנִים אֲשֶׁר שִׁבַּרְתָּ.</p>\n<p>מִיָּד קָם אֵלִיָּהוּ וְכָל בַּעֲלֵי הַיְשִׁיבָה, וּבֵרְכוּ אוֹתוֹ וְאָמְרוּ: סִינַי סִינַי, כָּךְ רָאוּי לִשְׁמֹעַ דְּבָרִים שֶׁלְּךְ וְלִשְׁתֹּק, אֲבָל בִּרְשׁוּת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ אֲנִי רוֹצֶה לְדַבֵּר דָּבָר אֵלֶיךְ, לִכְבוֹדְךְ. אָמַר לוֹ, אֱמֹר.</p>\n<p>פָּתַח וְאָמַר, רוֹעֶה הַנֶּאֱמָן, הַכַּלָּה הַזּוֹ שֶׁלְּךְ נָתַן אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם לְגַדְּלָהּ אֵלֶיךְ, וּמִשּׁוּם שֶׁהוּא שָׁמַר אוֹתָהּ, נִקְרְאָה בִתּוֹ, זֶהוּ שֶׁכָּתוּב בַּת הָיְתָה לוֹ לְאַבְרָהָם וּבַכֹּל שְׁמָהּ. וּבָהּ קִיֵּם כָּל הַתּוֹרָה כֻּלָּהּ, וַאֲפִלּוּ עֵרוּבֵי תַבְשִׁילִין, זֶהוּ שֶׁכָּתוּב <Nonesmall>[בראשית כו]</small> וַיִּשְׁמֹר מִשְׁמַרְתִּי וְגוֹ'. וְהוּא הָיָה אוֹמֵן אֵלֶיהָ, כְּמוֹ <Nonesmall>[אסתר ב]</small> וַיְהִי אֹמֵן אֶת הֲדַסָּה. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ אוֹתוֹ בִּגְלָלָהּ, זֶהוּ שֶׁכָּתוּב <Nonesmall>[בראשית כד]</small> וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְגִדְּלָהּ מִכָּל טוֹבוֹת טוֹבוֹת, וְגָמַל עִמָּהּ חֶסֶד, וְהֶעֱלָה אוֹתוֹ בִּגְדֻלָּה בְּמִדַּת חֶסֶד שֶׁל אַבְרָהָם, וְהָיָה בֵּיתוֹ בִּגְלָלָהּ פָּתוּחַ לִרְוָחָה, לִגְמֹל חֶסֶד עִם כָּל בָּאֵי עוֹלָם.</p>\n<p>וּמִשּׁוּם שֶׁהוּא גָּמַל עִמָּהּ חֶסֶד, כְּשֶׁבְּנֵי אַבְרָהָם הָיוּ מְמֻשְׁכָּנִים בְּכַמָּה חֲטָאִים בְּמִצְרַיִם, אָמַר לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא: רוֹעֶה הַנֶּאֱמָן, לֵךְ וּגְמֹל טוֹבוֹת לְמִי שֶׁגָּמַל עִמְּךְ, שֶׁהֲרֵי הַכַּלָּה שֶׁלְּךְ נָתַתִּי לוֹ אוֹתָהּ לְגַדְּלָהּ בְּמִדּוֹת טוֹבוֹת, וְהוּא גִּדְּלָהּ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת הָרַחֲמִים שֶׁרְמוּזוֹת בְּשָׁלֹשׁ תֵּבוֹת וָה\"וּ אֲנִ\"י וָה\"וּ, שֶׁהֵן וָא\"ו, שֶׁכְּלוּלִים בָּהֶן שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת כְּמִנְיַן חֶסֶד, שֶׁבָּהֶם הָיָה מִתְגַּבֵּר אַבְרָהָם עַל שִׁבְעִים וּשְׁתַּיִם אֻמּוֹת, וּבַכַּלָּה שֶׁלְּךְ הָיָה לוֹ סְגֻלָּה בְּשִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וְהָיָה מְנַצֵּחַ כָּל אֻמָּה וְלָשׁוֹן.</p>\n<p>וּמִשּׁוּם זֶה, <Nonesmall>[ישעיה סג]</small> מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ. וּבוֹקֵעַ מַיִם, שֶׁקָּרַעְתָּ לוֹ אֶת הַיָּם לִפְנֵי בָנָיו לִשְׁנֵים עָשָׂר קְרָעִים, בְּחֶשְׁבּוֹן וָ\"ו, וּבִזְכוּת א' <Nonesmall>[ובגללה]</small> עָבַרְתָּ <Nonesmall>[עשית]</small> אֶת הַיָּם לְיַבָּשָׁה, וּבָהּ טֻבְּעוּ הַמִּצְרִים שֶׁלֹּא מַאֲמִינִים בְּוָא\"ו, שֶׁהוּא אֶחָד. וְלֶעָתִיד לָבא, <Nonesmall>[מיכה ז]</small> כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת, יִתְקַיֵּם בְּיִשְׂרָאֵל, זַרְעוֹ שֶׁל אַבְרָהָם. וּבְךְ יִתְקַיֵּם, מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ <Nonesmall>[זרע אברהם]</small> וּבוֹקֵעַ מַיִם שֶׁל הַתּוֹרָה לִפְנֵיהֶם לִהְיוֹת לְךְ שֵׁם עוֹלָם. וְשָׁם תַּרְוִיחַ אֶת הַכַּלָּה שֶׁלְּךְ.</p>\n<p>וּמִשּׁוּם שֶׁבַּת זוֹ נִתְּנָה לְיִשְׂרָאֵל, שֶׁהִיא הֲלָכָה שֶׁלְּךְ מִצַּד הַשְּׂמֹאל, הֲלָכָה לְמֹשֶׁה מִסִּינַי, שֶׁהֲרֵי מִצַּד הַיָּמִין ה' הֲלָכָה שֶׁלְּךְ, מִצַּד הַשֵּׁם שֶׁל אַבְרָהָם. י' שֶׁל יִצְחָק. וְהַכֹּל הֵ\"י מֵאֱלֹהִים. וְאַתָּה וָא\"ו, מָלֵא שֶׁלָּהּ, שְׁלֵמוּת שֶׁלָּהּ, כּוֹס מָלֵא. בַּתְּחִלָּה כֵּ\"ס יָ\"הּ, וּלְבַסּוֹף כּוֹס מָלֵא בִּרְכַּת ה'.</p>\n<p>וּמִשּׁוּם שֶׁנִּתְּנָה לְיִשְׂרָאֵל עַל יָדְךְ, שֶׁהֵם מִצַּד הָעַמּוּד הָאֶמְצָעִי, יֵשׁ לְגַלּוֹת לָמָּה נִתְּנָה לָהֶם, שֶׁהֲרֵי וַדַּאי אַבְרָהָם הֲרֵי נֶאֱמַר לָמָּה נִתְּנָה לוֹ, וְאַתָּה גָּמַלְתָּ חֶסֶד עִם בָּנָיו, כְּמוֹ שֶׁהוּא גָּמַל לְךְ. לְיִצְחָק נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לוֹ וּלְזַרְעוֹ לִשְׁמֹר <Nonesmall>[לעטר]</small> אוֹתָהּ מֵעֵץ טוֹב וָרָע, וְעָשׂוּ לָהּ כַּמָּה גְדֵרִים, וְחָתְכוּ לָהּ כַּמָּה לְבוּשִׁים, שֶׁהֵם לְבוּשֵׁי זָהָב, בְּכַמָּה פְסָקוֹת. וְהָיוּ חוֹלְקִים וּמַקְשִׁים עֲלֵיהֶם, עַל הַפְּסָקוֹת הַלָּלוּ, לְתַקְּנָהּ בְּכַמָּה פֵרוּקִים, לְקַשֵּׁט אוֹתָהּ בְּכַמָּה מִינֵי קִשּׁוּטִים לְשַׁבָּתוֹת וְיָמִים טוֹבִים, לִהְיוֹת מְקֻשֶּׁטֶת אֵלֶיךְ בִּזְמַן שֶׁתָּבא אֵלֶיהָ בַּגְּאֻלָּה הָאַחֲרוֹנָה, שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[קהלת א]</small> מַ\"ה שֶּׁ\"הָיָה ה\"וּא.</p>\n<p>וּמִשּׁוּם שֶׁהֵם גָּרְמוּ לְךְ וְעָשׂוּ עִמְּךְ טוֹבוֹת, אַתָּה סָבַלְתָּ בִּגְלָלָם כַּמָּה מַכּוֹת כְּדֵי שֶׁלֹּא יֵהָרֵג מָשִׁיחַ בֶּן יוֹסֵף, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[יחזקאל א]</small> וּפְנֵי הַשּׁוֹר מֵהַשְּׂמֹאל, מִזֶּרַע יוֹסֵף שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[דברים לג]</small> בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. וּבִשְׁבִיל שֶׁלֹּא יִתְחַלֵּל הוּא וְזַרְעוֹ בֵּין עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בַּחֵטְא שֶׁל יָרָבְעָם שֶׁעָשָׂה עֲבוֹדָה זָרָה, הָיָה הוּא לְהִתְחַלֵּל בְּעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת הוּא וְזַרְעוֹ, מִשּׁוּם שֶׁיָּרָבְעָם בֶּן נְבָט הוּא מִזַּרְעוֹ, וּבִגְלָלוֹ נֶאֱמַר בְּךְ, <Nonesmall>[ישעיה נג]</small> וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ וְגוֹ' וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ.</p>\n<p>וְיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם כְּלוּלִים יָמִין וּשְׂמֹאל, שָׁם הֵ\"י שֶׁלְּךְ הָיְתָה בִשְׁלֵמוּת, יֵשׁ לְךְ לְהִתְיַחֵד עִמָּהּ בֵּינֵיהֶם. וּמִשּׁוּם שֶׁבְּךְ נֶאֱמַר כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל, נֶאֱמַר בְּךְ וְלוֹ תִהְיֶה לְאִשָּׁה לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו. בַּגָּלוּת לֹא יָכוֹל לִפְרשׁ אוֹתוֹ מִמֶּנָּה כָּל יָמָיו.</p>\n<p>וְאֵיךָ הוּא שֵׁם רָע שֶׁהוֹצֵאתָ עָלֶיהָ? אֶלָּא אַחַר שֶׁהִיא נִתְּנָה לְיִשְׂרָאֵל, כָּל מִי שֶׁמּוֹצִיא שֵׁם רָע עַל יִשְׂרָאֵל, כְּאִלּוּ הוֹצִיא עָלֶיהָ. וְהַשֵּׁם רָע הָיָה, שֶׁאָמַרְתָּ לַקָּדוֹשׁ בָּרוּךְ הוּא, <Nonesmall>[שמות לב]</small> לָמָה ה' יֶחֱרֶה אַפְּךְ בְּעַמֶּךְ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, וְכִי אַתָּה הוֹצֵאתָ שֵׁם רָע עַל יִשְׂרָאֵל שֶׁעָשׂוּ אֶת הָעֵגֶל? לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ. וַדַּאי עֵרֶב רַב שֶׁאַתָּה גִּיַּרְתָּ אוֹתָם עָשׂוּ אֶת הָעֵגֶל, וּמִשּׁוּם זֶה – כִּי הוֹצִיא שֵׁם רָע עַל בְּתוּלַת יִשְׂרָאֵל וְלוֹ תִהְיֶה לְאִשָּׁה.</p>\n<p>קָם הָרוֹעֶה הַנֶּאֱמָן, נָשַׁק לוֹ בְּפָנָיו וְעַל עֵינָיו וּבֵרַךְ אוֹתוֹ, וְאָמַר לוֹ: תִּהְיֶה מְבֹרָךְ מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל מִדָּה וּמִדָּה שֶׁלּוֹ, וּבְעֶשֶׂר הַסְּפִירוֹת שֶׁלּוֹ, וּבְכָל הַשֵּׁמוֹת שֶׁלּוֹ, וּבְכָל בַּעֲלֵי הַיְשִׁיבוֹת וּבְכָל הַמַּלְאָכִים. וְעָנוּ כֻלָּם וְאָמְרוּ אָמֵן. וְהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ הוֹדוּ בְּבִרְכָתוֹ. אֵלִיָּהוּ, קוּם פְּתַח פִּיךְ בְּמִצְווֹת עִמִּי, שֶׁאַתָּה הוּא עוֹזֵר שֶׁלִּי מִכָּל צַד, שֶׁהֲרֵי עָלֶיךְ נֶאֱמַר בַּתְּחִלָּה, <Nonesmall>[במדבר כה]</small> פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. בֶּן אַהֲרֹן וַדַּאי, בֶּן אָח שֶׁלִּי הוּא, <Nonesmall>[משלי יז]</small> וְאָח לְצָרָה יִוָּלֵד.</p>"],[9522012618,"<p>כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה אֲשֶׁר לֹא אֹרָשָׂה וְגוֹ'. מִצְוָה זוֹ לָדוּן בַּמְפַתֶּה חֲמִשִּׁים כֶּסֶף, זֶהוּ שֶׁכָּתוּב כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה אֲשֶׁר לֹא אֹרָשָׂה. אֵלּוּ יִשְׂרָאֵל, מִצַּד הַשְּׁכִינָה נִקְרְאוּ בַת. וּתְפָשָׂהּ וְשָׁכַב עִמָּהּ וְנִמְצָאוּ. וְנָתַן [וגו'] לַאֲבִי הַנַּעֲרָ [ה] חֲמִשִּׁים כָּסֶף וְלוֹ תִהְיֶה לְאִשָּׁה [וגו'] לֹא יוּכַל [ל] שַׁלְּחָהּ כָּל יָמָיו. רַבּוֹתֵינוּ וְכָל בַּעֲלֵי הַיְשִׁיבָה, אִישׁ – אֵלֶּה יִשְׂרָאֵל מִצַּד הַקָּדוֹשׁ בָּרוּךְ הוּא. וּתְפָשָׂהּ, בְּקֶשֶׁר שֶׁל תְּפִלִּין, וּתְפָשָׂהּ בְּכַנְפֵי מִצְוָה. אֲשֶׁר לֹא אֹרָשָׂה, בַּת יְחִידָה, זוֹ הַנְּשָׁמָה. וְשָׁכַב עִמָּהּ, בִּתְפִלַּת שְׁכִיבָה, בְּהַשְׁכִּיבֵנוּ. וְנָתַן לַאֲבִי הַנַּעֲרָה חֲמִשִּׁים כָּסֶף, כ\"ה כ\"ה אוֹתִיּוֹת הַיִּחוּד.</p>\n<p>קוּם רוֹעֶה נֶאֱמָן, שֶׁוַּדַּאי מִי שֶׁמִּשְׁתַּדֵּל בַּהֲלָכָה שֶׁלֹּא לִשְׁמָהּ וְהִרְוִיחַ הֲלָכָה, וַדַּאי הִיא בִּתְפִיסָה אֵלָיו. וְעִם כָּל זֶה פֵּרְשׁוּהָ, לְעוֹלָם יַעֲסֹק אָדָם בַּתּוֹרָה אֲפִלּוּ שֶׁלֹּא לִשְׁמָהּ, שֶׁמִּתּוֹךְ שֶׁלֹּא לִשְׁמָהּ בָּא לִשְׁמָהּ, וַהֲלָכָה זוֹ מִצַּד שֶׁל נַעַר טוֹב, שֶׁנִּפְרָד מֵעֵץ שֶׁל טוֹב וָרָע, שֶׁהוּא אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, כָּשֵׁר וּפָסוּל. וְעַל שֵׁם נַעַר נִקְרֵאת הִיא נַעֲרָה, שֶׁעָתִיד לְקַיֵּם בָּהּ, <Nonesmall>[איוב לח]</small> וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה, שֶׁהֵם אִסּוּר טָמֵא וּפָסוּל, סָמָאֵל וּמַרְכְּבוֹתָיו.</p>\n<p>דָּבָר אַחֵר כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה – אֵלּוּ יִשְׂרָאֵל, שֶׁכָּתוּב <Nonesmall>[הושע יא]</small> כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ. נַעַר מִצַּד מְטַטְרוֹ\"ן. וְאֵין אִישׁ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר <Nonesmall>[שמות טו]</small> ה' אִישׁ מִלְחָמָה. כִּי יִמְצָא אִישׁ נַעֲרָה בְתוּלָה, בְּתוּלַת יִשְׂרָאֵל, שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[עמוס ה]</small> נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. <Nonesmall>[הושע ב]</small> הִנֵּה אָנֹכִי מְפַתֶּיהָ וְהוֹלַכְתִּיהָ הַמִּדְבָּר. וְאַחַר כָּךְ פָּתַח לָהֶם חֲמִשִּׁים שַׁעֲרֵי חֵרוּת, שֶׁהֵם חֲמִשִּׁים שַׁעֲרֵי רַחֲמִים מִצַּד שֶׁל אַבְרָהָם אֲבִיהֶם. וְזֶהוּ וְנָתַן לַאֲבִי הַנַּעֲרָה חֲמִשִּׁים כָּסֶף, וְכֶסֶף מִדַּרְגַּת הַחֶסֶד, דַּרְגַּת אַבְרָהָם.</p>\n<p>שֶׁבִּיצִיאַת מִצְרַיִם פָּתַח לָהֶם חֲמִשִּׁים שַׁעֲרֵי חֵרוּת מִצַּד דִּין הַשְּׂמֹאל, שֶׁהוּא אֲדנָי, שֶׁשָּׁם דָּן אָנֹכִי. קֹדֶם דִּין – <Nonesmall>[בראשית טו]</small> דָּן אָנֹכִי, וְאַחַר כָּךְ יָצְאוּ. אֲבָל בַּגְּאֻלָּה הָאַחֲרוֹנָה, <Nonesmall>[ישעיה נד]</small> וּבְרַחֲמִים גְּדוֹלִים, מִצַּד אַבְרָהָם, וּגְאֻלָּה דַּרְגָּה שֶׁל אַבְרָהָם. שֶׁבִּינָה, שָׁם הִיא הַיָּד הַגְּדוֹלָה, שָׁם הִיא חֲמִשִּׁים כָּסֶף. וְאַחַר כָּךְ לֹא יוּכַל שַׁלְּחָהּ בַּגָּלוּת כָּל יָמָיו, מִשּׁוּם שֶׁלּוֹ תִהְיֶה לְאִשָּׁה, כְּמוֹ שֶׁנֶּאֱמַר <Nonesmall>[הושע ב]</small> וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם. וְכָתוּב אַחֵר, <Nonesmall>[ישעיה נד]</small> כִּי בֹעֲלַיִךְ עֹשַׂיִךְ ה' צְבָאוֹת שְׁמוֹ. <Nonesmall>[שם סב]</small> לֹא יֵאָמֵר לָךְ עוֹד עֲזוּבָה. שֶׁאַף עַל גַּב שֶׁשְּׁכִינָה בַּגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא זָז מִמֶּנָּה.</p>"],[9522012619,"<p>מִצְוָה אַחַר זוֹ, לִשָּׂא אֲנוּסָתוֹ. שֶׁוַּדִּי אֲנוּסָה יֵשׁ מִשְּׁנֵי צְדָדִים: אֲנוּסָה בְּאַהֲבָתוֹ אֵלֶיהָ, וְהִיא לֹא אוֹהֶבֶת אוֹתוֹ. וְיֵשׁ אֲנוּסָה שֶׁהִיא אוֹהֶבֶת אוֹתוֹ, וּפוֹחֶדֶת לְהִזְדַּוֵּג עִמּוֹ בְּלִי קִדּוּשִׁין וּבְרָכָה, וְהִיא לֹא רוֹצָה אִם הִיא פְּשׁוּטָה אֵלָיו, וְלוֹ תִהְיֶה לְאִשָּׁה.</p>\n<p>בְּסִתְרֵי תוֹרָה יֵשׁ לָנוּ לְהַמְשִׁיל מָשָׁל. יֵשׁ נְשָׁמָה שֶׁהִיא מַלְכָּה, וְיֵשׁ נְשָׁמָה שֶׁהִיא אָמָה, כְּמוֹ <Nonesmall>[שמות כא]</small> וְכִי יִמְכֹּר אִישׁ אֶת בִּתּוֹ לְאָמָה. וְיֵשׁ נְשָׁמָה שֶׁהִיא שִׁפְחָה פְּשׁוּטָה שֶׁל הָאָדָם. גַּם כָּךְ, יֵשׁ שֶׁהוּא עֶבֶד שִׁפְחָה אֶל הַנְּשָׁמָה, וְלִפְעָמִים הַנְּשָׁמָה הוֹלֶכֶת בְּסוֹד הַגִּלְגּוּל, זֶהוּ שֶׁכָּתוּב <Nonesmall>[בראשית ח]</small> וְלֹא מָצְאָה הַיּוֹנָה מָנוֹחַ לְכַף רַגְלָהּ. וְיֵצֶר הָרָע רוֹדֵף אַחֲרֶיהָ לְהִכָּנֵס בַּגּוּף, שֶׁהִיא שִׁפְחָה לַיֵּצֶר הָרָע. הוּא שֵׁד יְהוּדִי. וּנְשָׁמָה י', אָמָה הָעִבְרִיָּה. וּבָהּ אוֹתוֹ הַשֵּׁד וְחוֹזֵר לְשַׁדַּי, שֶׁשּׁוֹמֵר אֶת אוֹתָהּ הַנְּשָׁמָה, וְשָׁב בָּהּ בִּתְשׁוּבָה, וּמְבָרֵךְ בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל יוֹם בְּבָרוּךְ, וּמְקַדֵּשׁ בָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּקָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּמְיַחֵד עִמָּהּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּקְרִיאַת שְׁמַע.</p>\n<p>מַה שֶּׁהָיָה אוֹתוֹ שֵׁד, חוֹזֵר מַלְאָךְ שֶׁלּוֹ מְטַטְרוֹ\"ן <Nonesmall>[רוח ממנו]</small>, וְחוֹזֵר לִהְיוֹת שַׁדַּי, שֶׁכָּךְ עוֹלֶה מְטַטְרוֹן בְּחֶשְׁבּוֹן שַׁדַּי. וּמִיָּד יִתְקַיֵּם בּוֹ, וְלוֹ תִהְיֶה לְאִשָּׁה לֹא יוּכַל לְשַׁלְּחָהּ כָּל יָמָיו. וְאִם לֹא חָזַר בִּתְשׁוּבָה, הִיא מִשְׁתַּעְבֶּדֶת אֵלָיו בַּחֲטָאִים שֶׁעָשְׂתָה, וְיִתְקַיֵּם בָּהּ, הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדנֶיהָ. וְנֶאֱמַר בְּאוֹתוֹ שֵׁד בַּעַל חוֹבוֹ, וְהוּא יֵצֵא בְּגַפּוֹ. וְהַשֵּׁד הַזֶּה הוּא כְּמוֹ הַמַּטֶּה שֶׁל מֹשֶׁה, שֶׁהִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ, וּמִנָּחָשׁ לְמַטֶּה. כָּךְ הַשֵּׁד הַזֶּה, מִתְהַפֵּךְ מִשֵּׁד לְמַלְאָךְ, וּמִמַּלְאָךְ לְשֵׁד, כְּפִי מַעֲשֵׂי הָאָדָם. וּמִכָּאן נוֹדָע יוֹסֵף הַשֵּׁד לָמָּה נִקְרָא כָּךְ.</p>\n<p>וְעַל שֵׁם שֵׁדִים שֶׁבָּאוּ מִזֶּה, פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁיֵּשׁ מֵהֶם כְּמוֹ מַלְאֲכֵי הַשָּׁרֵת, וְהֵם תַּלְמִידֵי חֲכָמִים שֶׁיּוֹדְעִים מַה שֶּׁהָיָה וּמַה שֶּׁעָתִיד לִהְיוֹת. וְהֵם בִּדְמֻיּוֹתֵיהֶם בָּאָרֶץ, אֵלּוּ בַּעֲלֵי פִּילוֹסוֹפְיָה, אִצְטַגְנִינֵי יִשְׂרָאֵל, שֶׁיּוֹדְעִים מַה שֶּׁהָיָה וּמַה שֶּׁעָתִיד לִהְיוֹת מֵאוֹתוֹת הַחַמָּה וְהַלְּבָנָה, מִלִּקּוּי שֶׁלָּהֶם, וְכָל כּוֹכָב וּמַזָּל, וּמַה הוּא מַרְאֶה בָעוֹלָם.</p>\n<p>וְיִשִׁ מֵהֶם כְּמוֹ בְּהֵמָה, פָּרִים וְרָבִים כַּבְּהֵמָה, דְּמוּתָם לְמַטָּה הֵם עַמֵּי הָאָרֶץ, וּפֵרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁהֵם שֶׁקֶץ וּבְנוֹתֵיהֶם שֶׁרֶץ. וְעַל בְּנוֹתֵיהֶם נֶאֱמַר, <Nonesmall>[דברים כז]</small> אָרוּר שֹׁכֵב עִם כָּל בְּהֵמָה. וְהֵם שׂוֹנְאִים אֶת תַּלְמִידֵי הַחֲכָמִים בַּעֲלֵי הַמִּשְׁנָה, שֶׁהֵם מַמָּשׁ מַלְאֲכֵי הַשָּׁרֵת. וּמִשּׁוּם זֶה פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה עַל אָדָם, אִם יִהְיֶה כְּמוֹ מַלְאַךְ ה' צְבָאוֹת – תּוֹרָה יְבַקְשׁוּ מִפִּיהוּ, וְאִם לֹא – לֹא יְבַקְשׁוּ תוֹרָה מִפִּיהוּ.</p>"],[9522012620,"<p>וְיִשִׁ אֲחֵרִים בַּעֲלֵי סִתְרֵי תוֹרָה, בַּעֲלֵי מִדּוֹת, שֶׁהֵם יוֹרְשִׁים נְשָׁמוֹת מִצַּד הַמַּלְכוּת הַקְּדוֹשָׁה שֶׁכְּלוּלָה מֵעֶשֶׂר סְפִירוֹת. שֶׁמִּי שֶׁיּוֹרֵשׁ אוֹתָהּ וְזוֹכֶה בָּהּ, זוֹכֶה לְעֶשֶׂר סְפִירוֹת בְּלִי פֵרוּד, עֶשֶׂר וְלֹא תֵשַׁע. שֶׁאִם הָיוּ יוֹרְשִׁים אֶת הַמַּלְכוּת הַיְחִידָה, הָיוּ תֵשַׁע בְּפֵרוּד מִמֶּנָּה. מִשּׁוּם שֶׁאֵין שָׁם פֵּרוּד, אָמַר בַּעַל סֵפֶר יְצִירָה עֶשֶׂר וְלֹא תֵשַׁע.</p>\n<p>וְאִם תֹּאמַר שֶׁעוֹלָה לְמַעְלָה מֵעֶשֶׂר – שֵׁם הַמְפֹרָשׁ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, הֲרֵי עֶשֶׂר. יוֹ\"ד שֶׁמִּתְיַחֵד עִמָּהּ, וְלֹא עוֹלֶה לְמַעְלָה מֵעֶשֶׂר. וּמִשּׁוּם זֶה י', וְלֹא י\"א. אֲבָל מִי שֶׁמְּחַבֵּר יוֹ\"ד, שֶׁהִיא אוֹת בְּרִית, בְּשִׁפְחָה, וְהַמַּלְכָּה כְלוּלָה מִי', בְּשֵׁד שֶׁל עֲבוֹדָה זָרָה סָמָאֵ\"ל, נִדּוֹן בַּגֵּיהִנֹּם.</p>\n<p>שֶׁמִּי שֶׁיּוֹרֵשׁ בַּת הַמֶּלֶךְ מַלְכוּת, לֹא זוֹכֶה בָּהּ, אֶלָּא בֶּן הַמֶּלֶךְ, שֶׁנִּקְרָא <Nonesmall>[שמות ד]</small> בְּנִי בְכֹרִי יִשְׂרָאֵל, שֶׁמִּצַּד זֶה נִקְרְאוּ יִשְׂרָאֵל בָּנִים לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים יד]</small> בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. וּמַלְכוּת זוֹ שֶׁל אֲצִילוּת.</p>\n<p>וְיִשִׁ כְּנֶגְדָּהּ מַלְכוּת שֶׁל בְּרִיאָה, וְהִיא מַלְכוּת לַמַּלְאָכִים שֶׁל הַבְּרִיאָה. וְהִיא נַעֲרַת הַמַּלְכָּה, מְשַׁמֶּשֶׁת שֶׁלָּהּ, וְהִיא דְּמוּת הַגְּבִירָה שֶׁלָּהּ, כְּלוּלָה מִי'. זוֹ בַּחֲטָאֵי יִשְׂרָאֵל יְכוֹלָה לְהִתְחַלֵּל בֵּין אֻמּוֹת הָעוֹלָם. אֲבָל מַלְכוּת שֶׁל אֲצִילוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עָלֶיהָ נֶאֱמַר <Nonesmall>[ישעיה מב]</small> אֲנִי ה' הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים. לֹא נוֹתֵן אוֹתָהּ לְמִי שֶׁמְּחַלֵּל שַׁבָּתוֹת וְיָמִים טוֹבִים, אֶלָּא לְמִי שֶׁהוּא בֶּן הַמֶּלֶךְ וְשׁוֹמֵר תּוֹרָה וּמִצְווֹת בְּיִרְאַת וְאַהֲבַת רִבּוֹנוֹ, וְלֹא עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא כְּבֵן שֶׁהוּא מְחֻיָּב לַעֲשׂוֹת צִוּוּי אָבִיו, שֶׁעָלָיו נֶאֱמַר <Nonesmall>[שמות כ]</small> כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ. אֶת אָבִיךְ – זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאֶת אִמֶּךְ – זוֹ שְׁכִינָה. וְעִם כָּל זֶה, מִי שֶׁמְּחַלֵּל נַעֲרַת הַמֶּלֶךְ, נֶחְשָׁב לוֹ כְּאִלּוּ חִלֵּל אֶת הַמַּלְכָּה שֶׁלּוֹ.</p>\n<p>וְרַבּוֹתֵינוּ, כָּל הַשֵּׁדִים אֵינָם שְׁקוּלִים, וְלֹא כָּל הָעֲבָדִים שֶׁל הַשְּׁכִינָה, שֶׁכָּתוּב בָּהּ <Nonesmall>[תהלים קג]</small> וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. יֵשׁ לָהּ כַּמָּה נְעָרוֹת עִבְרִיּוֹת וּשְׁפָחוֹת עִבְרִיּוֹת, וְיֵשׁ לָהּ עֲבָדִים וּשְׁפָחוֹת נָכְרִיּוֹת, כְּדֵי שֶׁלֹּא תִמָּצֵא מַלְכוּת אַחֶרֶת בָּעוֹלָם בִּזְמַן שֶׁהִיא שׁוֹלֶטֶת.</p>"],[9522012621,"<p>וְהַשְּׁפָחוֹת הַנָּכְרִיּוֹת הַלָּלוּ מִצַּד שֶׁל סַם הַמָּוֶת, נְקֵבָה שֶׁל סָמָאֵל. שֶׁשִּׁפְחָה הָיְתָה לַמַּלְכָּה. נְקֵבָה וְסָמָאֵל אֵל אַחֵר, הָיָה עֶבֶד לַקָּדוֹשׁ בָּרוּךְ הוּא לְאַחַר שֶׁעָשׂוּ עַצְמָם אֱלָהוּת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַעֲבִירָם מֵהָעוֹלָם וְלִמְחוֹת אוֹתָם.</p>\n<p>וְאִם תֹּאמְרוּ, אִם בְּנֵי אָדָם עוֹשִׂים לָהֶם אֱלָהוּת, וְלֹא בִרְצוֹנָם, לָמָּה נֶעֶנְשׁוּ? אֶלָּא כְּשֶׁהָיוּ דּוֹר הַמַּבּוּל וְדוֹר הַפְּלַגָּה יוֹדְעִים בָּהֶם, וְהָיוּ מְקַטְרְגִים <Nonesmall>[מקטרים]</small> לָהֶם וּמִשְׁתַּחֲוִים לָהֶם, וּבְאוֹתוֹ כֹּחַ שֶׁהָיוּ מְקַטְרְגִים <Nonesmall>[מקטרים]</small> לָהֶם וּמִשְׁתַּחֲוִים לָהֶם, הָיוּ יוֹרְדִים אֲלֵיהֶם וְעוֹשִׂים רְצוֹנָם, וּמְדַבְּרִים עִמָּם בְּאוֹתָם צְלָמִים, הֲרֵי נַעֲשׂוּ אֱלָהוּת וַעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. מִשּׁוּם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְהַעֲבִירָם, וְיִמְחֶה אוֹתָם מֵהָעוֹלָם צְלָמִים שֶׁלָּהֶם שֶׁהָיוּ עוֹבְדִים בָּהֶם, וְנִשְׁאֲבוּ מֵהֶם רוּחוֹת וּצְלָמִים.</p>\n<p>וּכְשֶׁיִּשִׁ בָּעוֹלָם עֵרֶב רַב, יוֹרְדִים לְהִתְגַּשֵּׁם בָּהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲבִירֵם מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב <Nonesmall>[זכריה יג]</small> וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאִם תֹּאמְרוּ, בִּזְמַן שֶׁל הַגָּלוּת הָאַחֲרוֹנָה אֵין עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת – מִשּׁוּם שֶׁבְּנֵי הָעוֹלָם לֹא יוֹדְעִים בָּהֶם. וְאֵלּוּ שֶׁיּוֹדְעִים בְּעֵרֶב רַב שָׁם, נִמְצָא לָהֶם שֶׁמַּכְעִיסִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְיִשְׂרָאֵל בֵּינֵיהֶם, וְעֵרֶב רַב מַצְלִיחִים בָּהֶם, לְקַיֵּם מַה שֶּׁכָּתוּב <Nonesmall>[דברים ז]</small> וּמְשַׁלֵּם לְשּנְאָיו אֶל פָּנָיו לְהַאֲבִידוֹ.</p>\n<p>קָמוּ כָּל הַתַּנָּאִים וְהָאָמוֹרָאִים וּבֵרְכוּ אֶת הָרוֹעֶה הַנֶּאֱמָן וְאָמְרוּ לוֹ, סִינַי סִינַי, מִי יָכוֹל לְדַבֵּר לְפָנֶיךְ, שֶׁאַתָּה בִּדְמוּת רִבּוֹנְךְ. שֶׁבִּזְמַן שֶׁדִּבֵּר בְּהַר סִינַי, כָּל חַיּוֹת הַמַּלְאָכִים, וְחַיּוֹת הַכִּסֵּא, וְעֶלְיוֹנִים וְתַחְתּוֹנִים שָׁתְקוּ, וְלֹא נִמְצָא דִבּוּר אַחֵר, אֶלָּא שֶׁלּוֹ. וּבִשְׁבִיל שֶׁאַתָּה בְּנוֹ בִּדְמוּתוֹ, צְרִיכִים כָּל בַּעֲלֵי הַיְשִׁיבָה לִשְׁמֹעַ דְּבָרִים מִפִּיךְ, אַל תִּתֵּן שְׁתִיקָה לִדְבָרֶיךְ.</p>"],[9522012622,"<p>כִּי יִקַּח אִישׁ אִשָּׁה חֲדָשָׁה לֹא יֵצֵא בַּצָּבָא וְגוֹ'. וְשִׂמַּח אֶת אִשְׁתּוֹ אֲשֶׁר לָקָח <Nonesmall>[דברים כח]</small>. מִצְוָה <Nonesmall>[טו]</small> זוֹ שֶׁחָתָן יִשְׂמַח בְּאִשְׁתּוֹ שָׁנָה אַחַת, שֶׁכָּתוּב נָקִי יִהְיֶה לְבֵיתוֹ שָׁנָה אֶחָת. וְאוֹתָם שְׁנֵים עָשָׂר חֳדָשִׁים הֵם מִשֶּׁלָּהּ, שֶׁהֲרֵי שָׁנָה הִיא כַּלָּה, וְאֵין כַּלָּה פְּרָט בִּשְׁנֵים עָשָׂר חֳדָשִׁים, שֶׁכָּתוּב <Nonesmall>[מלכים א ז]</small> עֹמֵד עַל שְׁנֵי [ם] עָשָׂר בָּקָר. וְהוֹאִיל וְאֵין תִּקּוּן הַכַּלָּה, רַק בִּשְׁנֵים עָשָׂר, צָרִיךְ הֶחָתָן לְשַׂמְּחָהּ וּלְבֵיתָהּ, לָהּ וּלְתִקּוּנֶיהָ, כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה כָּתוּב בְּיַעֲקֹב <Nonesmall>[בראשית כח]</small> וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. אַבְנֵי הַמָּקוֹם הָיוּ שְׁתֵּים עֶשְׂרֵה, וּמִי שֶׁמְּשַׂמֵּחַ כַּלָּה מְשַׂמֵּחַ אֶת עַלְמוֹתֶיהָ, וְעַלְמוֹתֶיהָ הָיוּ שְׁתֵּים עֶשְׂרֵה. וְהַכֹּל הוּא סוֹד שֶׁל שָׁנָה. לָכֵן צָרִיךְ חָתָן לִשְׂמֹחַ בְּאִשְׁתּוֹ שָׁנָה אֶחָת.</p>\n<p>וַהֲרֵי בֵּאֲרוּ, שֶׁחֶדְוָה זוֹ אֵינָהּ שֶׁלּוֹ, אֶלָּא שֶׁלָּהּ, שֶׁכָּתוּב וְשִׂמַּח אֶת אִשְׁתּוֹ. וְיִשְׂמַח אֶת אִשְׁתּוֹ לֹא כָתוּב, אֶלָּא וְשִׂמַּח, יְשַׂמַּח אֶת הַכַּלָּה. כְּמוֹ זֶה אֵין שִׂמְחָה לַכַּלָּה אֶלָּא בְּגוּפָהּ וְתִקּוּנֶיהָ. וּמִי מְשַׂמֵּחַ אוֹתָם? צַדִּיק. וְעַל זֶה נָקִי יִהְיֶה לְבֵיתוֹ. נָקִי, שֶׁלֹּא יַעֲמֹל בְּדִבְרֵי הָעוֹלָם, שֶׁיִּהְיֶה בּוֹ רָצוֹן לְשַׂמֵּחַ אוֹתָהּ. נָקִי מֵהַכֹּל. נָקִי מִמִּסִּים וּמֵאַרְנוֹנִיּוֹת וּמִמַּס גֻּלְגֹּלֶת. נָקִי, שֶׁלֹּא יֵצֵא לַצָּבָא לְהִלָּחֵם בִּקְרָבוֹת. לְהִמָּצֵא חֶדְוָה מַעְלָה וּמַטָּה, וּלְעוֹרֵר חֶדְוָה לְמַעְלָה. אַשְׁרֵי הָעָם הַקָּדוֹשׁ שֶׁרִבּוֹנָם שָׂמֵחַ בָּהֶם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה, וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא.</p>"],[9522012623,"<p>בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְגוֹ' <Nonesmall>[דברים כד]</small>. פָּתַח רוֹעֶה הַנֶּאֱמָן וְאָמַר, מִצְוָה אַחַר זוֹ לָתֵת שְׂכַר שָׂכִיר בִּזְמַנּוֹ. זֶהוּ שֶׁכָּתוּב בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ וְלֹא תָבֹא עָלָיו הַשֶּׁמֶשׁ. בַּעֲלֵי הַיְשִׁיבוֹת עֶלְיוֹנִים וְתַחְתּוֹנִים שִׁמְעוּ, מְטַטְרוֹן הוּא שְׂכַר שָׂכִיר מֵחַ\"י הָעוֹלָמִים, שָׁלִיחַ שֶׁלּוֹ, כְּנֶגֶד חַ\"י בִּרְכוֹת הַתְּפִלָּה בְּכָל יוֹם שָׁלֹשׁ פְּעָמִים. וְלָכֵן בְּיוֹמוֹ תִתֵּן שְׂכָרוֹ – זוֹ תְּפִלַּת שַׁחֲרִית. וְלֹא תָבא עָלָיו הַשֶּׁמֶשׁ – זוֹ תְּפִלַּת מִנְחָה, שֶׁאִם עָבַר יוֹמוֹ, בָּטֵל קָרְבָּנוֹ. כִּי עָנִי הוּא <Nonesmall>[של צדיק]</small> וַדַּאי. עָנִי הוּא בַּגָּלוּת. אֵין לוֹ מִשֶּׁלּוֹ אֶלָּא מַה שֶּׁנּוֹתְנִים לוֹ בַּתְּפִלָּה, מִשּׁוּם זֶה תְּפִלָּה הִיא תְּפִלָּה שֶׁלּוֹ, <Nonesmall>[תהלים קב]</small> תְּפִלָּה לְעָנִי כִי יַעֲטֹף, בַּעֲטִיפַת צִיצִית, תְּפִלָּה שֶׁל יָד הִיא.</p>\n<p>וְאֵלָיו הוּא נֹשֵׂא אֶת נַפְשׁוֹ – זוֹ תְּפִלַּת עַרְבִית, שֶׁהִיא אֵמוּרִים וּפְדָרִים, שְׁיָרֵי קָרְבְּנוֹת הַיּוֹם. וְהֵם כְּמוֹ פֶּרֶט הַכֶּרֶם וּפְאַת שָׂדְךְ, שֶׁעֲלֵיהֶם נֶאֱמַר, שְׁיָרֵי מִצְוָה מְעַכְּבִים אֶת הַפֻּרְעָנוּת. <Nonesmall>[ויקרא יט]</small> לֶעָנִי וְלַגֵּר תַּעֲזֹב אֹתָם, שֶׁהָעַמּוּד הָאֶמְצָעִי מִחוּץ לִמְקוֹמוֹ נִקְרָא גֵר. וּמִשּׁוּם זֶה, אֲנִי שֶׁדַּרְגָּתִי עַמּוּדּ הָאֶמְצָעִי, קוֹרֵא לְעַצְמִי גֵּר בְּגָלוּת הָרִאשׁוֹנִים. זֶהוּ שֶׁכָּתוּב <Nonesmall>[שמות ב]</small> גֵּר הָיִיתִי בְּאֶרֶץ נָכְרִיָּה, שֶׁהוּא בְּגָלוּת רְבִיעִית בִּגְלָלָם.</p>\n<p>שָׁאֲלוּ אוֹתוֹ בַּעֲלֵי הַמִּשְׁנָה, רוֹעֶה הַנֶּאֱמָן, הֲרֵי מִצְוָה זוֹ הָיוּ מְקַיְּמִים יִשְׂרָאֵל בְּאֶרֶץ יִשְׂרָאֵל <Nonesmall>[או לא]</small>. אָמַר לָהֶם, כְּדֵי לְעוֹרֵר רַחֲמִים עַל אֵלּוּ שֶׁגֹּרְשׁוּ מִמְּקוֹמָם. שֶׁהָאָדָם, כְּשֶׁהוּא מִחוּץ לִמְקוֹמוֹ, נִקְרָא גֵר, כָּל שֶׁכֵּן עַל נְשָׁמוֹת שֶׁהוֹלְכוֹת מְעֻרְטָלוֹת מֵאוֹתוֹ עוֹלָם וּבָאוֹת לָעוֹלָם הַזֶּה. בִּגְלָלָם זֶהוּ מַה שֶּׁאָמַר הַכָּתוּב, <Nonesmall>[משלי כז]</small> כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ, זוֹ הַנְּשָׁמָה שֶׁשְּׁכִינָה לֹא זָזָה מִמֶּנָּה. כֵּן אִישׁ, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[שמות טו]</small> ה' אִישׁ מִלְחָמָה, נוֹדֵד מִמְּקוֹמוֹ, שֶׁהוּא נָע וָנָד מִמְּקוֹמוֹ, שֶׁהוּא עוֹלָם הַבָּא בִּינָה, וְנָד אַחֲרֶיהָ בָּעוֹלָם הַזֶּה, עַד שֶׁתַּשְׁלִים יָמִים שֶׁהִתְחַיְּבָה לָלֶכֶת מִחוּץ לִמְקוֹמָהּ, וְהוּא שׁוֹמֵר אוֹתָהּ עַד שֶׁיַּחֲזִירֶנָּה לִמְקוֹמָהּ, וְנִשְׁבַּע שֶׁהוּא לֹא יַחֲזֹר לִמְקוֹמוֹ עַד שֶׁיַּחֲזִירֶנָּה לִמְקוֹמָהּ. וּמִי שֶׁחוֹזֵר בִּתְשׁוּבָה, כְּמִי שֶׁהֶחֱזִיר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַשְּׁכִינָה לִמְקוֹמָהּ. וְזֶה סוֹד הַגְּאֻלָּה, שֶׁאָמַר <Nonesmall>[תהלים צה]</small> הַיּוֹם אִם בְּקֹלוֹ תִשְׁמָעוּ.</p>\n<p>אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁל הַיְשִׁיבָה הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה, רוֹעֶה הַנֶּאֱמָן, אָנוּ שְׁלוּחֵי רִבּוֹן הָעוֹלָם אֵלֶיךְ, אַשְׁרֵי חֶלְקְךְ שֶׁאַתָּה בַּעַל תְּשׁוּבָה, שָׁקוּל לְשִׁשִּׁים רִבּוֹא יִשְׂרָאֵל, וְאַתָּה הֶחֱזַרְתָּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ לִמְקוֹמוֹ, מַעְלָה וּמַטָּה. וּבִגְלָלְךְ יִגָּאֲלוּ יִשְׂרָאֵל וְיַחְזְרוּ לִמְקוֹמָם, וְאֵין כֹּחַ לַמְּשִׁיחִים לִגְאֹל אֶת יִשְׂרָאֵל חוּץ מִמְּךְ, וּבִגְלָלְךְ הֵם מִתְעַכְּבִים. הַשְׁלֵם דְּבָרִים נִכְבָּדִים הַלָּלוּ, שֶׁעֲלֵיהֶם נֶאֱמַר <Nonesmall>[תהלים יט]</small> הַנֶּחֱמָדִים מִזָּהָב וּמִפַּז רָב וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת צוּפִים.</p>\n<p>אָמַר לָהֶם, בַּעֲלֵי הַיְשִׁיבָה, בִּגְלַל הַשָּׂכִיר הַזֶּה, שֶׁהוּא עֶבֶד, שֶׁבָּא לְקַבֵּל שָׁלֹשׁ תְּפִלּוֹת, תִּקְּנוּ בַּעֲלֵי הַמִּשְׁנָה שֶׁלָּכֶם לִהְיוֹת הָאָדָם בְּשָׁלֹשׁ בְּרָכוֹת רִאשׁוֹנוֹת כְּעֶבֶד שֶׁמְּסַדֵּר שְׁבָחִים לִפְנֵי רִבּוֹנוֹ, וּבָאֶמְצָעִיּוֹת כְּמוֹ עֶבֶד שֶׁמְּקַבֵּל פְּרָס מֵרִבּוֹנוֹ, וּבָאַחֲרוֹנוֹת כְּמוֹ עֶבֶד שֶׁנּוֹטֵל פְּרָס מֵרִבּוֹנוֹ וְהוֹלֵךְ לוֹ.</p>\n<p>וּמִשּׁוּם זֶה עֶבֶד אַבְרָהָם וְרִבְקָה הוּא מָשָׁל לָזֶה. כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׁלַח אֶת מְטַטְרוֹן, שֶׁהוּא עַבְדּוֹ, בִּגְלַל תְּפִלָּה, הוּא יֹאמַר אֵלָיו: <Nonesmall>[בראשית כד]</small> אוּלַי לֹא תֹאבֶה הָאִשָּׁה לָלֶכֶת אַחֲרַי. כְּלוֹמַר, אוּלַי הַתְּפִלָּה לֹא רוֹצֶה לָלֶכֶת אַחֲרַי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: וְנִקִּיתָ מִשְּׁבֻעָתִי זֹּאת. שֶׁחָכְמָה הִיא אַבָּא, שֶׁיּוֹרֶדֶת בְּצַדִּיק, לִשְׁמֹר שְׁכִינָה בַּגָּלוּת, וּמִשָּׁם שָׁלַח בִּגְלָלָהּ.</p>\n<p>אָמַר לוֹ אוֹתוֹ שָׁלִיחַ: תֵּן לִי סִימָנִים לָדַעַת בַּתְּפִלָּה, שֶׁשָּׁם הַבַּת. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: וְהָיָה הַנַּעֲרָ [ה] אֲשֶׁר אֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה וְאָמְרָה שְׁתֵה. וְאִם לֹא, אֶלָּא שֶׁאֶמְצָא כָּל אֵיבְרֵי הַגּוּף מְלֵאִים חֲטָאִים וְלֹא נִמְצָא בּוֹ אֵיבָר <Nonesmall>[בפני אברהם]</small> לִשְׁרוֹת בּוֹ תּוֹרָה, שֶׁהִיא בִּדְמוּת הָעַמּוּד הָאֶמְצָעִי, וְלֹא מִצְוָה, שֶׁהִיא דְּמוּת שֶׁל רִבְקָה, שֶׁהָיְתָה שׁוֹשַׁנָּה בֵּין הַחוֹחִים, שֶׁהֵם רְשָׁעִים גְּמוּרִים – צִוָּה לִמְטַטְרוֹן עַבְדּוֹ: הִשָּׁמֵר לְךְ פֶּן תָּשִׁיב אֶת בְּנִי שָׁמָּה, שֶׁהִיא רוּחַ הַקֹּדֶשׁ. שֶׁהֲרֵי מִצְוָה הִיא נֶפֶשׁ, רוּחַ הִיא תּוֹרָה.</p>"],[9522012624,"<p>וְלָכֵן פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, לֹא הַמִּדְרָשׁ הוּא הָעִקָּר אֶלָּא הַמַּעֲשֶׂה. וּבְמָקוֹם אַחֵר אָמְרוּ, כֹּל שֶׁיִּרְאַת חֶטְאוֹ קוֹדֶמֶת לְחָכְמָתוֹ, חָכְמָתוֹ מִתְקַיֶּמֶת וְכוּ'. יִרְאַת חֶטְאוֹ – הָאֵם הָעֶלְיוֹנָה, תְּשׁוּבָה. חָכְמָה – הָאָב הָעֶלְיוֹן. כְּשֶׁמַּקְדִּים ה' קְטַנָּה, שֶׁהִיא מִצְוָה, שׁוֹרָה עָלָיו תּוֹרָה, שֶׁהִיא ו'. וּכְשֶׁמַּקְדִּים יִרְאָה לְחָכְמָה, שֶׁהִיא ה' הָעֶלְיוֹנָה, שׁוֹרָה עָלָיו חָכְמָה, שֶׁהִיא י', וְנִקְרָא בֵּן. וּמִכָּאן <Nonesmall>[דברים יד]</small> בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם.</p>\n<p>וְזְהִוּ <Nonesmall>[שמות ג]</small> זֶה שְּׁמִי – י\"ה – לְעֹלָם, וְזֶה זִכְרִי – ו\"ה. שְׁמִי עִם י\"ה – שס\"ה. זִכְרִי עִם ו\"ה – רמ\"ח. וְכֻלָּם תרי\"ג, שֶׁהַיְנוּ תרי\"ג מִצְווֹת שֶׁנִּתְּנוּ לְבָנִים קְדוֹשִׁים לִהְיוֹת לָהֶם חֵלֶק בִּשְׁמוֹ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[דברים לב]</small> כִּי חֵלֶק ה' עַמּוֹ.</p>\n<p>וּכְשֶׁמַּקְדִּים תּוֹרָה לְמִצְוָה אוֹ חָכְמָה לְיִרְאָה, מִתְהַפֵּךְ שְׁמוֹ עָלָיו לִנְקֵבָה, מִדַּת הַדִּין, כְּמוֹ זֶה – הוה\"י. שֶׁמִּתְהַפֵּךְ לוֹ הַכֹּל לְדִין, וְקָשִׁים מְזוֹנוֹתָיו בַּתּוֹרָה כְּמוֹ קְרִיעַת יַם סוּף. וּכְמוֹ זֶה הַגְּאֻלָּה, אִם זָכוּ – יֵצְאוּ בְרַחֲמִים, זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה סו]</small> בְּטֶרֶם יָבוֹא חֵבֶל לָהּ וְהִמְלִיטָה זָכָר, וְיֵצְאוּ בְרַחֲמִים. וְאִם לֹא – מַקְדִּים הָרַחֲמִים, וְיֵצְאוּ בְצַעַר. וְיָפֶה שֶׁהִקְדִּים צַעַר וְדִין לְרַחֲמִים. וְלָכֵן פֵּרְשׁוּהָ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בַּעֲלֵי הַמִּשְׁנָה, לְפוּם צַעְרָא אַגְרָא.</p>\n<p>וִיצִיאַת הַנֶּפֶשׁ, מִקֹּדֶם שֶׁיּוֹצֵאת יֵשׁ לָהּ צַעַר, לְאַחַר שֶׁיּוֹצֵאת בְּרַחֲמִים. וְסוֹד הַדָּבָר – <Nonesmall>[ירמיה לא]</small> בִּבְכִי יָבאוּ, אַחַר כָּךְ – וּבְתַחֲנוּנִים אוֹבִילֵם. וְלָכֵן, <Nonesmall>[שם ל]</small> וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּה יִוָּשֵׁעַ, וְיֵצְאוּ בְרַחֲמִים. וּכְמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אֶת הַיּוֹנָה וְלֹא מָצְאָה מָקוֹם לִשְׁרוֹת, כָּךְ שָׁלַח אוֹתְךְ, רוֹעֶה הַנֶּאֱמָן, בַּהַתְחָלָה.</p>\n<p>וּמַה כָּתוּב בָּהֶם? <Nonesmall>[שמות ב]</small> וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ. שֶׁכֻּלָּם רְשָׁעִים, וְלֹא מָצָאתָ בָּהֶם אִישׁ זוֹכֶה לְהוֹצִיאָם מֵהַגָּלוּת. וְלָכֵן סֵרַבְתָּ לָלֶכֶת לְשָׁם, וְאָמַרְתָּ שְׁלַח נָא בְּיַד תִּשְׁלָח. וַהֲרֵי אַתָּה כְּמוֹ בְּאוֹתוֹ זְמַן, בְּךְ יִתְקַיֵּם עִם יִשְׂרָאֵל, <Nonesmall>[מיכה ז]</small> כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. וּבַגָּלוּת הָאַחֲרוֹנָה יִשְׁלַח עִמְּךְ שְׁנֵי מְשִׁיחִים, כְּנֶגֶד שְׁתֵּי כַנְפֵי יוֹנָה. שֶׁאַתָּה כְּמוֹ גוּף בַּגָּלוּת הָרְבִיעִית, אֵין לְךְ כְּנָפַיִם. וְלֹא עוֹד, אֶלָּא בַּהַתְחָלָה הָיוּ יִשְׂרָאֵל כְּמוֹ גוּף, וְאַתָּה וְאַהֲרֹן כִּשְׁתֵּי כַנְפֵי יוֹנָה, וּבָהֶן פָּרְחוּ יִשְׂרָאֵל.</p>"],[9522012625,"<p>אֵין מִצְוָה שֶׁלֹּא נִכְלְלוּ שָׁם עֶשֶׂר סְפִירוֹת. בַּתֵּבָה – <Nonesmall>[בראשית ו]</small> תַּחְתִּיִּם שְׁנִיִּם וּשְׁלִישִׁים תַּעֲשֶׂהָ, לְהַכְלִיל בָּהּ כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים. תֵּבָה שְׁכִינָה עִמָּהֶם, תּוֹרַת ה', הִיא רְבִיעִית הַהִין, ה' רְבִיעִית. וּמְשֻׁלֶּשֶׁת בְּיה\"ו, לְהַשְׁלִים בּוֹ יֱהִֹוִ\"ה. וְעֶשֶׂר דְּרָגוֹת שֶׁנִּכְלְלוּ בוֹ, שֶׁהֵן יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. לְהִתְקַיֵּם בָּהֶם בְּיִשְׂרָאֵל, <Nonesmall>[דברים ד]</small> וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגוֹ', <Nonesmall>[שם יד]</small> בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. שֵׁם זֶה שִׁלְטוֹנוֹ בְצֶלֶם הָאָדָם, וְעַל כָּל אֵיבָר וְאֵיבָר שֶׁלּוֹ.</p>"],[9522012626,"<p>מִצְוָה אַחַר זוֹ לָדוּן בְּדִינֵי חֲגָבִים, שֶׁנֶּאֱמַר דָּגִים וַחֲגָבִים אֵינָם טְעוּנִים שְׁחִיטָה, אֶלָּא אֲסִיפָתָם הִיא הַמַּתֶּרֶת אוֹתָם. כָּךְ בַּעֲלֵי הַמִּשְׁנָה, אֵינָם צְרִיכִים שְׁחִיטָה, אֶלָּא שֶׁנֶּאֱמַר בָּהֶם <Nonesmall>[בראשית מט]</small> וַיִּגְוַע וַיֵּאָסֶף אֶל [על] עַמָּיו. מַה דְּגֵי הַיָּם חַיּוּתָם בַּיָּם, אַף תַּלְמִידֵי חֲכָמִים בַּעֲלֵי הַמִּשְׁנָה חַיּוּתָם בַּתּוֹרָה, וְאִם נִפְרָדִים מִמֶּנָּה, מִיָּד מֵתִים. הַתַּנִּין <Nonesmall>[התנאים]</small> שֶׁל הַמִּשְׁנָה, שֶׁבָּהּ הִתְרַבּוּ תַּנִּינֵי הַיָּם. וְאִם אֵלּוּ שֶׁבַּיַּבָּשָׁה יַעֲלוּ <Nonesmall>[יפלו]</small> לַמַּיִם וְלֹא יוֹדְעִים לִשְׂחוֹת, הֵם מֵתִים. אֲבָל אָדָם שֶׁהֵם בַּעֲלֵי קַבָּלָה, הֵם לְמַעְלָה מִכֻּלָּם, בָּהֶם נֶאֱמַר <Nonesmall>[בראשית א]</small> וְיִרְדּוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם, שֶׁהֵם בַּעֲלֵי הַמִּשְׁנָה, תַּנִּינִים, <Nonesmall>[יחזקאל כט]</small> הַתַּנִּים [ן] הַגָּדוֹל, נָחָשׁ בָּרִיחַ, כְּנֶגֶד <Nonesmall>[שמות כו]</small> וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים.</p>\n<p>בִּזְמַן שֶׁתַּנִּינִים בַּעֲלֵי הַמִּשְׁנָה יֵשׁ בָּהֶם מַחֲלֹקֶת וּמַקְשִׁים זֶה עַל זֶה, בּוֹלֵעַ אֶת חֲבֵרוֹ. וְזֶהוּ תַּלְמִיד קָטָן שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה, חַיָּב מִיתָה. וְאִם הֵם שָׁוִים זֶה לָזֶה וְיֵשׁ בָּהֶם מַחֲלֹקֶת וְקֻשְׁיָה, נֶאֱמַר בָּהֶם בַּסּוֹף, <Nonesmall>[במדבר כא]</small> וְאֶת וָהֵב בְּסוּפָה, וּפֵרְשׁוּהָ אַהֲבָה בְּסוֹפָהּ.</p>"],[9522012627,"<p>בֵּין כָּךְ הֲרֵי דָּג גָּדוֹל הִזְדַּמֵּן אֵלָיו וְאָמַר, רוֹעֶה הַנֶּאֱמָן, <Nonesmall>[שם כד]</small> אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ. תַּנְיָא שֶׁמְּסַיֵּעַ לְךְ, שֶׁהֲרֵי דָּגִים בְּסֶלַע הַקֵּן שֶׁלָּהֶם, אֵיתָן בְּהִפּוּךְ – תַּנְיָא. אֵיתָנִים בְּהִפּוּךְ אוֹתִיּוֹת – תַּנָּאִים. הִשָּׁמֵר מֵהֶם, שֶׁהֲרֵי אַתָּה כְּבַד פֶּה וּכְבַד לָשׁוֹן, וּמִי שֶׁרוֹצֶה לְהַחֲזִיק בַּסֶּלַע שֶׁל דְּגֵי הַיָּם, שֶׁל בַּעֲלֵי הַמִּשְׁנָה, שֶׁהֵם תַּנָּאִים, צָרִיךְ לִהְיוֹת תַּקִּיף, לָשׁוֹן מְחֻדֶּדֶת חֲרִיפָה, לִנְקֹב עַד שֶׁמַּגִּיעָה לַתְּהוֹם הַגְּדוֹלָה שֶׁשָּׁם.</p>\n<p>כִּי עוֹד חָזוֹן לַמּוֹעֵד וְיָפֵחַ לַקֵּץ וְלֹא יְכַזֵּב <Nonesmall>[חבקוק ב]</small>. וּפֵרְשׁוּהָ שֶׁפָּסוּק זֶה נוֹקֵב וְיוֹרֵד עַד תְּהוֹם רַבָּה. מִיהוּ שֶׁיּוֹרֵד לִתְהוֹם רַבָּה לִמְצֹא זְמַן זֶה? אֶלָּא אַתָּה, שֶׁנֶּאֱמַר בְּךְ <Nonesmall>[תהלים לו]</small> צִדְקָתְךְ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךְ תְּהוֹם רַבָּה. כַּמָּה בַּעֲלֵי מִשְׁנָה שֶׁרָצוּ לָרֶדֶת לְעֹמֶק הַהֲלָכָה לִמְצֹא שָׁם אֶת קֵץ הַגְּאֻלָּה, וְיָרְדוּ שָׁם וְלֹא עָלוּ. וְאַף עַל גַּב שֶׁלְּשׁוֹנָם הָיְתָה כְּפַטִּישׁ יְפוֹצֵץ סֶלַע, חָלַשׁ הַפַּטִּישׁ שֶׁלָּהֶם לִנְקֹב בְּאוֹתוֹ סֶלַע. וּמִי שֶׁנֶּקֶב שֶׁלּוֹ בְּאוֹתוֹ סֶלַע בְּלֹא רְשׁוּת, בָּא נָחָשׁ לִנְשֹׁךְ אוֹתוֹ. וְיֵשׁ אֲחֵרִים שֶׁנָּקְבוּ אוֹתוֹ, עַד שֶׁהִגִּיעוּ לִתְהוֹם רַבָּה, וְלֹא עָלוּ מִשָּׁם.</p>"],[9522012628,"<p>וּבִזְמַן שֶׁהַנֶּקֶב פָּתוּחַ, כָּל מִי שֶׁהָיָה נוֹפֵל שָׁם, לֹא הָיָה עוֹלֶה. וּמָשִׁיחַ בֶּן דָּוִד נָפַל שָׁם עִם מָשִׁיחַ בֶּן יוֹסֵף. שֶׁאֶחָד הוּא <Nonesmall>[זכריה ט]</small> עָנִי וְרֹכֵב עַל חֲמוֹר, וְאֶחָד הוּא <Nonesmall>[דברים לג]</small> בְּכוֹר שׁוֹרוֹ, זֶה מָשִׁיחַ בֶּן יוֹסֵף. וְזֶהוּ <Nonesmall>[שמות כא]</small> כִּי יִכְרֶה אִשׁ בּוֹר וְלֹא יְכַסֶּנּוּ וְנָפַל שָׁמָּה שּׁוֹר אוֹ חֲמוֹר. וְלָכֵן נִקְרָא הַמָּשִׁיחַ בַּר נַפְלֵי. וְהִיא נָפְלָה אַחֲרֵיהֶם, וְנֶאֱמַר עָלֶיהָ, <Nonesmall>[עמוס ה]</small> נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. וְאַתָּה הוּא בַּעַל הַבּוֹר יְשַׁלֵּם כֶּסֶף יָשִׁיב לִבְעָלָיו <Nonesmall>[שמות שם]</small>. וְהַמֵּת יִהְיֶה לּוֹ – זֶה מָשִׁיחַ בֶּן יוֹסֵף שֶׁעָתִיד לְהֵהָרֵג.</p>\n<p>יָרַד בִּגְלָלוֹ. שֶׁוַּדַּאי אַרְבַּע גָּלֻיּוֹת הָיוּ. שָׁלֹשׁ כְּנֶגֶד שְׁלֹשׁ קְלִפּוֹת הָאֱגוֹז, שֶׁהֵם: תֹּהוּ – קַו יָרֹק, קְלִפָּה יְרֻקָּה שֶׁל הָאֱגוֹז. שֵׁנִי בּהוּ – אֲבָנִים מְפֻלָּמוֹת, שֶׁהֵם סְלָעִים חֲזָקִים, שֶׁבַּעֲלֵי הַמִּשְׁנָה פָּסְקוּ מֵהֶם כַּמָּה פְסָקוֹת, וְלָקְחוּ אוֹתָם לְהוֹצִיא מַיִם שֶׁל הַתּוֹרָה, וְלָכֵן נִקְרְאוּ אֲבָנִים מְפֻלָּמוֹת, שֶׁמֵּהֶם יוֹצְאִים מַיִם. קְלִפָּה שְׁלִישִׁית, דַּקִּיקָה, גָּלוּת שְׁלִישִׁית, שֶׁהָיְתָה קְטַנָּה, וְזֶהוּ וְחֹשֶׁךְ. גָּלוּת רְבִיעִית – תְּהוֹם רַבָּה, חֲלַל הָאֱגוֹז. וְזֶהוּ <Nonesmall>[בראשית א]</small> וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם.</p>\n<p>וְנִקְרָא בּוֹר, שֶׁנָּפַל שָׁמָּה שׁוֹר, זֶה שֶׁכָּתוּב בְּיוֹסֵף <Nonesmall>[דברים לג]</small> בְּכוֹר שׁוֹרוֹ הָדָר לוֹ, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[בראשית לז]</small> וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה, נְקֵבָה רָעָה. וְהַבּוֹר רֵק – זָכָר <Nonesmall>[דבור]</small>, רֵק בְּלִי תוֹרָה, אֲבָל נְחָשִׁים וְעַקְרַבִּים יֵשׁ בּוֹ. וְזוֹ הַגָּלוּת הָרְבִיעִית, דּוֹר שֶׁל רְשָׁעִים מָלֵא נְחָשִׁים וְעַקְרַבִּים, רַמָּאִים כִּנְחָשִׁים וְעַקְרַבִּים, שֶׁעוֹקְרִים דִּבְרֵי רַבּוֹתֵינוּ וְדָנִים לְשֶׁקֶר, עֲלֵיהֶם נֶאֱמַר <Nonesmall>[איכה א]</small> הָיוּ צָרֶיהָ לְרֹאשׁ.</p>\n<p>וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ <Nonesmall>[שמות ב]</small>, שֶׁל יִשְׂרָאֵל הַמְעֹרָבִים בָּרְשָׁעִים הַלָּלוּ, עֵרֶב רַב, וְזֶה בְּסוֹף הַגָּלוּת. וּמִשּׁוּם כָּךְ קֵץ הַגָּלוּת נוֹקֵב עַד תְּהוֹם רַבָּה. וְרוֹעֶה הַנֶּאֱמָן, תְּהוֹם הוּא הַמָּוֶת בְּהִפּוּךְ אוֹתִיּוֹת, וְאֵין מָוֶת אֶלָּא עֲנִיּוּת, אַתָּה יָרַדְתָּ שָׁם. וַהֲרֵי זֶה הִתְבָּרֵר לְמַעְלָה לִפְנֵי הַתַּנָּאִים וְהָאָמוֹרָאִים, וְכֻלָּם יוֹרְדִים בִגְלָלְךְ לַתְּהוֹם לְסַיֵּעַ לְךְ.</p>"],[9522012629,"<p>וְאַתָּה תַּנְיָא שֶׁמְּסַיֵּעַ לְךְ יוֹתֵר מִכֻּלָּם, מִשּׁוּם שֶׁאַתָּה לִוְיָתָן <Nonesmall>[נחש בריח]</small> שֶׁל יָם הַתּוֹרָה, בַּעַל כָּל הַדָּגִים נִקְרָא לִוְיָתָן, עַל שֵׁם הַתּוֹרָה שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[משלי א]</small> כִּי לִוְיַת חֵן הֵם לְרֹאשֶׁךְ, וּבְךְ <Nonesmall>[תהלים לו]</small> אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. אָדָם – שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[במדבר יט]</small> אָדָם כִּי יָמוּת בְּאֹהֶל, וּבֵאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, אֵין הַתּוֹרָה מִתְקַיֶּמֶת אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ, וְאֵין מִיתָה אֶלָּא עֲנִיּוּת. וּבְהֵמָה – אֵלּוּ עַמֵּי הָאָרֶץ, שֶׁהֵם נִכְפִּים כְּמוֹ סוּס וּפֶרֶד תַּחַת בַּעֲלֵי הַמִּשְׁנָה.</p>\n<p>בֵּין כָּךְ הֲרֵי <Nonesmall>[בא]</small> הַמְּנוֹרָה הַקְּדוֹשָׁה. פָּתַח הָרוֹעֶה הַנֶּאֱמָן וְאָמַר, בַּעֲלֵי הַמִּשְׁנָה, מַהוּ לִוְיָתָן? אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, זֶהוּ שֶׁדַּרְגָּתוֹ עַמּוּד הָאֶמְצָעִי, וְצַדִּיק, שֶׁנֶּאֱמַר בּוֹ גּוּף וּבְרִית נֶחְשָׁבִים לְאֶחָד. וְהִתְגַּדֵּל בְּיָם זֶה, שֶׁהִיא הָאֵם הָעֶלְיוֹנָה, יָם, שֶׁבָּהּ מְיַחֲדִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כ\"ה כ\"ה אוֹתִיּוֹת, שֶׁהֵם יָם בְּחֶשְׁבּוֹן, וְהוּא בָּהּ. אָמַר רוֹעֶה הַנֶּאֱמָן, וַדַּאי שֶׁלִּוְיָתָן שֶׁעוֹמֵד עַל שְׂפַת הַיָּם וְהָעוֹלָם עוֹמֵד עַל סְנַפִּירָיו, זֶה צַדִּיק יְסוֹד עוֹלָם, שֶׁכָּל הָעוֹלָם עוֹמֵד עָלָיו. אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, אַשְׁרֵי חֶלְקְךְ רוֹעֶה הַנֶּאֱמָן.</p>"],[9522012630,"<p>בַּת קוֹל בַּגָּלוּת, עַד שֶׁתָּבֹא אַתָּה אֵלֶיהָ, שֶׁאַתָּה קוֹל שֶׁלָּהּ, שֶׁכָּל אִשָּׁה בַּת בַּעְלָהּ, כְּמוֹ שֶׁנֶּאֱמַר וַתְּהִי לוֹ לְבַת. מְאֹרֶשֶׂת הִיא לְךְ, וַעֲדַיִן לֹא עָשִׂיתָ <Nonesmall>[נכנסת]</small> עִמָּהּ לַחֻפָּה.</p>\n<p>נֶאֱמַר <Nonesmall>[דברים כב]</small> צָעֲקָה הַנַּעֲרָ [ה] הַמְאֹרָשָׂה וְאֵין מוֹשִׁיעַ לָהּ. כָּךְ הַשְּׁכִינָה, הָאֵם שֶׁלָּהּ <Nonesmall>[העליונה]</small>, צוֹעֶקֶת עַל בְּנָהּ וְאֵין מוֹשִׁיעַ לָהּ, עַד שֶׁיָּבֹא הָעַמּוּד הָאֶמְצָעִי בִּשְׁבִילָהּ, שֶׁהוּא מוֹשִׁיעַ, שֶׁבִּגְלָלָהּ נֶאֱמַר <Nonesmall>[זכריה ט]</small> הִנֵּה מַלְכֵּךְ יָבא לָךְ צַדִּיק וְנוֹשָׁע. הוּא מוֹשִׁיעַ לְמַעְלָה, וְאַתָּה לְמַטָּה. וּמִשּׁוּם שֶׁאַתָּה בִדְמוּתוֹ, נֶאֱמַר בְּךְ, <Nonesmall>[דברים ה]</small> וְאַתָּה פֹּה עֲמֹד עִמָּדִי. שֶׁכָּל יִשְׂרָאֵל חָזְרוּ לְאָהֳלֵיהֶם, וְאַתָּה לֹא, עַד הַגְּאֻלָּה הָאַחֲרוֹנָה. וּמִי גָרַם אֶת זֶה? עֵרֶב רַב, שֶׁבִּגְלָלָם <Nonesmall>[שמות לב]</small> וַיַּשְׁלֵךְ מִיָּדָו אֶת הַלֻּחֹת. וּמֵאוֹתָהּ שָׁעָה נָפְלָה וְלֹא נִגְאֲלָה מֵעֵרֶב רַב, שֶׁבָּהֶם נֶאֱמַר <Nonesmall>[שם יב]</small> וְגַם עֵרֶב רָב עָלָה אִתָּם. בְּכָל זֶה לֹא נִפְרְדוּ מִיִּשְׂרָאֵל, וְשִׁפְחָה מִגְּבִרְתָּהּ, עַד הַגְּאֻלָּה הָאַחֲרוֹנָה.</p>\n<p>אַתָּה בֶּן הַמֶּלֶךְ, כְּמוֹ שֶׁלְּךְ נֶאֱמַר בָּעַמּוּד הָאֶמְצָעִי בַּכֹּל, חֶדְוָה שֶׁלְּךְ כַּחֶדְוָה שֶׁלּוֹ תִּהְיֶה כְּשֶׁיָּבֹא לִגְאֹל אֶת כַּלָּתוֹ, <Nonesmall>[תהלים יט]</small> וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ וְגוֹ'. שֶׁהֲרֵי לְבוּשֶׁיהָ בַּגָּלוּת חֲשׁוּכִים, וּבִזְמַן שֶׁהִיא מִתְלַבֶּשֶׁת בָּהֶם, הִיא אוֹמֶרֶת, <Nonesmall>[שיר השירים א]</small> אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת. וְהַקְּלִפּוֹת הַלָּלוּ הֵם מַשְׁחִית אַף וְחֵמָה, נְקֵבָה רָעָה, שִׁפְחָה רָעָה, שַׁבְּתַאי, <Nonesmall>[משלי ל]</small> וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ, שֶׁהִיא שַׁבַּת הַמַּלְכָּה. מַשְׁחִית אַף וְחֵמָה סוֹבְבִים אֶת שְׁלֹשֶׁת הָאָבוֹת.</p>"],[9522012631,"<p>וְלֹא עוֹד, אֶלָּא מַה שֶּׁהָיְתָה בַּת הַמֶּלֶךְ, י' עַל הו\"ה, שֶׁכְּלוּלִים בָּאָבוֹת – ה' רִאשׁוֹנָה בְּאַבְרָהָם, ה' שְׁנִיָּה בְּיִצְחָק, ו' בְּיַעֲקֹב, וְהָיְתָה י' רֹאשׁ עֲלֵיהֶם. נֶאֱמַר <Nonesmall>[איכה ה]</small> נָפְלָה עֲטֶרֶת רֹאשֵׁנוּ. וְהִמְשִׁילוּ רַבּוֹתֵינוּ מָשָׁל לְמֶלֶךְ שֶׁהָיְתָה לוֹ עֲטָרָה עַל רֹאשׁוֹ, וְאִילָן יָפֶה לְפָנָיו. בָּאָה לוֹ שְׁמוּעָה רָעָה – הֵרִים הָעֲטָרָה מֵעַל רֹאשׁוֹ, וּמַה שֶּׁהָיָה י' עַל הו\"ה, י' לְמַעְלָה, חָזַר הוה\"י, י' לְמַטָּה. וְלָכֵן אָמַר דָּוִד, <Nonesmall>[תהלים קיח]</small> אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה מֵאֵת ה' הָיְתָה זֹּאת.</p>"],[9522012632,"<p>קוּם רוֹעֶה הַנֶּאֱמָן, קַח אֶבֶן זוֹ בְּיָדְךְ, שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[זכריה ג]</small> עַל אֶבֶן אַחַת שִׁבְעָה עֵינָיִם, לִשְׁבֹּר קְלִפַּת הָאֱגוֹז. שֶׁהֲרֵי כַּמָּה רוֹעִים פַּרְנְסֵי הַדּוֹר הִתְכַּנְּסוּ עַל הָאֶבֶן הַזֹּאת, שֶׁהִיא סֶלַע שֶׁלְּךְ לְהוֹצִיא מַיִם מִשָּׁם, שֶׁכַּלָּה שֶׁלְּךְ מַעְיַן הַחָכְמָה בַּסֶּלַע הַזֶּה, שֶׁנְּבִיעָתוֹ בַּתּוֹרָה בְּסוֹדוֹת נִסְתָּרִים אֵין סוֹף, וְעָלֶיהָ נֶאֱמַר <Nonesmall>[איוב כח]</small> וְהַחָכְמָה מֵאַיִן תִּמָּצֵא.</p>\n<p>וְכָל תֹּקֶף שֶׁלָּהֶם לְהַעֲבִיר אֶת הַקְּלִפָּה שֶׁלְּמַעְלָה, וּכְשֶׁמַּגִּיעִים לַקְּלִפָּה הַשְּׁנִיָּה, שֶׁהִיא חֲזָקָה, הִיא קָשָׁה לָהֶם, וּמַכִּים בָּהּ כָּל יְמֵיהֶם כֻּלָּם בִּלְשׁוֹנָם, שֶׁהִיא חֲזָקָה כְּמוֹ פַּטִּישִׁים, וְאֵין לָהֶם רְשׁוּת לְהוֹצִיא מִמֶּנָּה מַיִם, אֶלָּא הַטִּפּוֹת הַלָּלוּ שֶׁיָּצְאוּ עַל יָדְךְ בִּזְמַן שֶׁנֶּאֱמַר בָּהּ <Nonesmall>[במדבר כ]</small> וַיַּךְ אֶת הַסֶּלַע בְּמַטֵּהוּ פַּעֲמָיִם. וּבַמַּכָּה הַשְּׁנִיָּה יָצְאוּ הַטִּפּוֹת הַלָּלוּ, וְאֵלּוּ הֵם רְמָזִים שֶׁל חָכְמָה, רְמָזִים שֶׁל קַבָּלָה, שֶׁהֵם בַּחֲגִיגָה, וּשְׁאָר הַמִּשְׁנָיוֹת. וּמֵהָאֶבֶן הַזֹּאת אֵין מִי שֶׁיּוֹצִיא חָכְמָה, שֶׁהִיא מִבִּפְנִים, שֶׁאֵין לָהּ סוֹף, <Nonesmall>[שהוא המח מבפנים]</small> חוּץ מִמְּךְ, שֶׁנֶּאֱמַר בְּךְ הֲלָכָה לְמֹשֶׁה מִסִּינַי.</p>\n<p>פָּתַח רוֹעֶה הַנֶּאֱמָן וְאָמַר, סָבָא סָבָא, יֵשׁ סֶלַע וְיֵשׁ סֶלַע, יֵשׁ אֶבֶן וְיֵשׁ אֶבֶן. יֵשׁ אֶבֶן שֶׁל שֵׁם שֶׁל יְהֹוָ\"ה, וְעָלֶיהָ נֶאֱמַר <Nonesmall>[דניאל ב]</small> וְהָאֶבֶן שֶׁהִכְּתָה אֶת הַצֶּלֶם נַעֲשֵׂית לְהַר גָּדוֹל. וְיֵשׁ אֶבֶן שֶׁהִיא <Nonesmall>[ויקרא כו]</small> אֶבֶן מַשְׂכִּית, שֶׁאֵין שָׁם נְבִיעַת מֵי הַחָכְמָה וְלֹא דִבּוּר.</p>\n<p>אֶלָּא אֶבֶן שֶׁהִיא סֶלַע שֶׁל מֹשֶׁה, עָלֶיהָ נֶאֱמַר <Nonesmall>[במדבר כ]</small> וְדִבַּרְתֶּם אֶל הַסֶּלַע לְעֵינֵיהֶם וְנָתַן מֵימָיו, שֶׁהִיא בַּת קוֹל, וְלֹא תָלוּי בָּהּ אֶלָּא דִּבּוּר וּפִיּוּס. אֲבָל שִׁפְחָה סֶלַע אַחֵר, שֶׁנִּקְרְאָה <Nonesmall>[קלפה]</small> מִשְׁנָה נְקֵבָה שֶׁל עֶבֶד נַעַר. עָלֶיהָ נֶאֱמַר, <Nonesmall>[משלי כט]</small> בִּדְבָרִים לֹא יִוָּסֶר עָבֶד. אֶלָּא שֶׁמַּכִּים וּמְשַׁבְּרִים מִמֶּנָּה כַּמָּה פְסָקוֹת, וּמְלַקְּטִים אוֹתָם, וְנִקְרְאוּ לְקוּטוֹת. וְעַל שֶׁמְּלַקְּטִים אוֹתָם נִקְרְאוּ לְקוּטוֹת, בְּלִי נְבִיעַת חָכְמָה וְקַבָּלָה.</p>\n<p>אֲבָל סֶלַע שֶׁלִּי הִיא בַּת הַמֶּלֶךְ, בִּשְׁבִילָהּ נֶאֱמַר וְדִבַּרְתֶּם אֶל הַסֶּלַע לְעֵינֵיהֶם וְנָתַן מֵימָיו, בְּדִבּוּר וּפִיּוּס, כְּמוֹ בַּת הַמֶּלֶךְ. וּמִשּׁוּם שֶׁהִכִּיתִי בָהּ, לָקִיתִי עָלֶיהָ, וְנִגְזַר עָלֵינוּ מָוֶת. שֶׁמִּי שֶׁמְּסָרֵב לַמַּלְכָּה, חַיָּב מִיתָה. כָּל שֶׁכֵּן לְמִי שֶׁמַּכֶּה אֶת בַּת הַמֶּלֶךְ. וְלָכֵן נִגְזַר עָלַי שֶׁלֹּא אֶכָּנֵס לְאֶרֶץ יִשְׂרָאֵל, וַאֲנִי קָבוּר בְּאֶרֶץ נָכְרִיָּה וְנֶעֶבְרָה מִמֶּנִּי. וְנֶאֱמַר <Nonesmall>[שמואל ב כג]</small> וַיֵּרֶד אֵלָיו בַּשָּׁבֶט. וְהַשֵּׁבֶט הַזֶּה הוּא אֶחָד מִן הַשְּׁבָטִים שֶׁלִּי, שֶׁאֲנִי עָתִיד לָרֶדֶת לְשָׁם לִהְיוֹת עִם יִשְׂרָאֵל בַּגָּלוּת. וְהַכֹּל נִרְמַז, וּבְמָקוֹם אַחֵר פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה.</p>"],[9522012633,"<p>שֶׁבֵּית הַמִּקְדָּשׁ וְשֵׁם הַמָּשִׁיחַ נִקְרְאוּ בְשֵׁם יֱהִֹוִ\"ה. וְזֶה אַרְבַּע פְּנֵי אָדָם, וְהֵם שֵׁבֶט לֵוִי, הֵם יָצְאוּ מֵחַיּוֹת שֶׁהֵם שְׁאָר הַשְּׁבָטִים, וְנִכְנְסוּ בְחֶלְקוֹ שֶׁל אָדָם, שֶׁהֵם אַרְבַּע פָּנִים שֶׁלּוֹ. וּמֹשֶׁה הוּא אָדָם בִּדְמוּת שֶׁל אוֹתוֹ אָדָם הָרִאשׁוֹן שֶׁלְּמַעְלָה. <Nonesmall>[משלי ל]</small> מַה שְּׁמוֹ וּמַה שֵּׁם בְּנוֹ. וּמִשּׁוּם זֶה כֹּהֲנִים וּלְוִיִּם, מְזוֹנָם עַל יְדֵי שֶׁהַמֶּלֶךְ אוֹכֵל בְּשֻׁלְחָן, וּשְׁאָר חֵילוֹת הַמֶּלֶךְ, לְכָל אֶחָד נוֹתְנִים לוֹ לֶאֱכֹל בְּבֵית מוֹשָׁבוֹ. וְרוֹעֶה הַנֶּאֱמָן הוּא כְּמוֹ בֶּן הַמֶּלֶךְ, קָרוֹב לַמֶּלֶךְ יוֹתֵר מֵאֵלּוּ שֶׁאוֹכְלִים לְשֻׁלְחָנוֹ, שֶׁאֵין מִי שֶׁמִּתְקָרֵב לַמֶּלֶךְ מִכָּל בְּנֵי הַמַּלְכוּת כְּמוֹ בְּנוֹ.</p>\n<p>קָם הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, סָבָא סָבָא, בַּדְּבָרִים שֶׁלְּךְ נוֹדָע מִי אַתָּה. אַתָּה הוּא אָדָם הָרִאשׁוֹן. מַה שְּׁמוֹ, נֶאֱמַר עָלֶיךְ. מַה שֵּׁם בְּנוֹ, נֶאֱמַר עַל רוֹעֶה הַנֶּאֱמָן. וּמִשּׁוּם שֶׁהוּא חִדֵּשׁ כַּמָּה חִדּוּשִׁים בַּתּוֹרָה, מְעֻתֶּדֶת לְךְ חֶדְוָה, שֶׁבֵּן חָכָם יְשַׂמַּח אָב <Nonesmall>[משלי י]</small>.</p>\n<p>רוֹעָה הַנֶּאֱמָן, בְּפָרָשָׁה זוֹ נִזְכְּרָה הִתְכַּנְּסוּת שֶׁלְּךְ לְאוֹתוֹ הָעוֹלָם, שֶׁכָּתוּב <Nonesmall>[דברים לב]</small> עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה הַר נְבוֹ וְגוֹ'. וְרָאִיתָ אוֹתָהּ וְנֶאֱסַפְתָּ אֶל עַמֶּךְ וְגוֹ'. כַּאֲשֶׁר נֶאֱסַף אַהֲרֹן אָחִיךְ וְגוֹ' <Nonesmall>[שם]</small>. וּבְפָרָשָׁה זוֹ יֵשׁ לְךְ לַחֲזֹר לָעוֹלָם, וּלְהֵחָיוֹת, וּלְהִכָּנֵס לְאֶרֶץ יִשְׂרָאֵל, וּלְהִתְחַבֵּר בְּפָרָשָׁה זוֹ בַּכַּלָּה שֶׁלְּךְ, שֶׁכָּתוּב בָּהּ <Nonesmall>[במדבר כה]</small> הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וְלָכֵן לֹא אָמַר לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן רֵד, אֶלָּא עֲלֵה. שֶׁמִּמֶּנּוּ אַתָּה תִּכָּנֵס לְאֶרֶץ יִשְׂרָאֵל.</p>\n<p>וּמַה שֶּׁאָמַר בְּךְ, <Nonesmall>[דברים לד]</small> וְלֹא יָדַע אִישׁ אֶת קְבֻרָתוֹ עַד הַיּוֹם הַזֶּה, אוֹי לְאוֹתָם אֲטוּמֵי לֵב, סְתוּמֵי עֵינַיִם, שֶׁלֹּא יוֹדְעִים קְבוּרָתְךְ, שֶׁהָיִיתָ אַתָּה מְבַקֵּשׁ רַחֲמִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יַכְנִיס אוֹתְךְ לְאוֹתָהּ קְבוּרָה שֶׁבָּהּ אַתָּה נִקְרָא מֵת. זֶהוּ שֶׁכָּתוּב <Nonesmall>[יהושע א]</small> מֹשֶׁה עַבְדִּי מֵת. וְאוֹתָם טִפְּשִׁים אוֹמְרִים, וְכִי מֹשֶׁה הָיָה מְפַחֵד מִמִּיתָה, לָצֵאת מֵהָעוֹלָם הַזֶּה לָעוֹלָם הַבָּא, כִּשְׁאָר הַבְּרִיּוֹת?! וְהֵם לֹא יוֹדְעִים שֶׁקִּבוּרָתְךְ וּמִיתָתְךְ אֵיךְ הִיא.</p>\n<p>שֶׁכָּךָֹ פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה, שֶׁמֵּתֵי חוּץ לָאָרֶץ אֵינָם חַיִּים. לֹא אָמְרוּ שֶׁאֵינָם עֲתִידִים לְהֵחָיוֹת, שֶׁאִלְמָלֵא כָּךְ הָיוּ כוֹפְרִים בִּתְחִיַּת הַמֵּתִים. אֶלָּא כָּאן סוֹד גָּדוֹל. קְבוּרָתוֹ בְצֶלֶם שֶׁאֵינוֹ הָגוּן לוֹ, שֶׁהִיא <Nonesmall>[תהלים סג]</small> אֶרֶץ צִיָּה וְעָיֵף בְּלִי מַיִם, וְאֵין מַיִם אֶלָּא תּוֹרָה, וּבָהּ <Nonesmall>[ישעיה נג]</small> לֹא תֹאַר לוֹ וְלֹא הָדָר. וּמִי שֶׁרוֹאֶה אוֹתוֹ בְּאוֹתוֹ צֶלֶם – וְנִרְאֵהוּ וְלֹא מַרְאֶה וְנֶחְמְדֵהוּ. וְלָכֵן נְבוּאַת יְשַׁעְיָה <Nonesmall>[שם נב]</small> הִנֵּה יַשְׂכִּיל עַבְדִּי, רוֹמֵז עָלָיו.</p>\n<p>וּמִשּׁוּם אוֹתָהּ קְבוּרָה הָיָה מְבַקֵּשׁ רַחֲמִים שֶׁלֹּא יָמוּת שָׁם בְּחוּץ לָאָרֶץ, לְפִי שֶׁהָיָה בְּאֶרֶץ צִיָּה רָעֵב וְעָיֵף וְצָמֵא בְּלִי מַיִם, שֶׁהִיא הַתּוֹרָה. וְלָכֵן נֶאֱמַר עָלָיו, עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה. מִשִּׁפְלוּתוֹ הֶרְאָה לוֹ אֶת מַעֲלָתוֹ. אַף עַל גַּב שֶׁאַתָּה קָבוּר בְּמָקוֹם שֶׁלֹּא הָגוּן לְךְ, עָרֹם בְּלִי לְבוּשִׁים שֶׁלְּךְ, שֶׁהֵם עוֹר וּבָשָׂר <Nonesmall>[תלבישני]</small>, נָע וָנָד מִמְּקוֹמְךְ וּמְטֻלְטָל וְגוֹלֶה, הֲרֵי פִּנְחָס שֶׁעָשִׂיתָ עִמּוֹ טוֹב, שֶׁעָלֶיךְ נֶאֱמַר <Nonesmall>[במדבר כה]</small> הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, הֲרֵי הוּא יַעֲשֶׂה עִמְּךְ טוֹבָה, וּבוֹ תִסְתַּלֵּק, בַּפָּרָשָׁה שֶׁלּוֹ. שֶׁבָּהּ הַכַּלָּה שֶׁלְּךְ, שָׁם תִּתְיַחֵד עִמָּהּ כְּחָתָן עִם כַּלָּתוֹ.</p>\n<p>שֶׁהֲרֵי אַתָּה <Nonesmall>[תועלת גדולה לישראל בקבורתך]</small>, אִם לֹא הָיִיתָ קָבוּר מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, מִחוּץ לַכַּלָּה שֶׁלְּךְ, לֹא הָיוּ יִשְׂרָאֵל יוֹצְאִים מֵהַגָּלוּת, וּבִגְלָלְךְ נֶאֱמַר <Nonesmall>[ישעיה נג]</small> וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ. נַעֲשֵׂיתָ חֹל מִשּׁוּם חֵטְא וָפֶשַׁע שֶׁל יִשְׂרָאֵל בַּקְּבוּרָה שֶׁלְּךְ, שֶׁנֶּאֱמַר בְּךְ <Nonesmall>[דברים לד]</small> וַיִּקְבֹּר אֹתוֹ בַגַּי. וּמַה כָּתוּב בִּקְבוּרָתְךְ? <Nonesmall>[ישעיה מ]</small> וְכָל גֶּיא יִנָּשֵׂא. כָּל שָׁפֵל וְנָמוּךְ יִנָּשֵׂא בִּגְלָלְךְ, שֶׁהֵם יִשְׂרָאֵל, שֶׁהֵם שְׁפָלִים מִכָּל אֻמָּה וְלָשׁוֹן. וְכַל הַר וְגִבְעָה יִשְׁפָּלוּ, שֶׁהֵם הָרְשָׁעִים וְגַסֵּי הָרוּחַ.</p>\n<p>וְזְהִוּ וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ. בַּחִבּוּר שֶׁהִתְחַבֵּר עִמָּנוּ בַגָּלוּת, נִרְפָּא לָנוּ. שֶׁאַתָּה הוּא כְּשֶׁמֶשׁ שֶׁמֵּאִיר, שֶׁאַף עַל גַּב שֶׁמִּתְכַּנֵּס בַּלַּיְלָה, מֵאִיר הוּא לַלְּבָנָה וּלְכָל הַכּוֹכָבִים וְהַמַּזָּלוֹת. כָּךְ אַתָּה מֵאִיר בְּכָל בַּעֲלֵי הֲלָכוֹת וְקַבָּלוֹת. וּלְךְ נִשְׁקִים בְּנִסְתָּר, כְּמוּ מַבּוּעַ שֶׁמַּשְׁקֶה אֶת הָאִילָנוֹת תַּחַת שָׁרְשֵׁיהֶם בְּנִסְתָּר עַד שֶׁהִתְבַּקְּעוּ מֵימָיו בְּגִלּוּי. זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי ה]</small> יָפוּצוּ מַעְיְנֹתֶיךְ חוּצָה.</p>\n<p>שֶׁאַתָּה הוּא גַּם כָּךְ, כְּמוֹ שֶׁמֶשׁ שֶׁהוֹלֵךְ בִּימֵי הַחֹרֶף תַּחת הַמַּבּוּעִים, וּכְשֶׁמַּגִּיעָה הַגְּאֻלָּה, תִּהְיֶה כְּמוֹ שֶׁמֶשׁ שֶׁהוֹלֵךְ בַּקַּיִץ לְמַעְלָה מֵהַמַּבּוּעִים, וְיִהְיוּ צוֹנְנִים בְּרַחֲמִים. שֶׁכְּשֶׁאַתָּה תַחְתֵּיהֶם, הֵם חַמִּים בְּדִין. בָּא רוֹעֶה הַנֶּאֱמָן וּבֵרַךְ אֶת הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, וַדַּאי אַתָּה הוּא שֶׁמֵּאִיר לִי בִּזְמַן שֶׁנֶּאֱמַר עָלַי <Nonesmall>[בראשית כח]</small> כִּי בָא הַשֶּׁמֶשׁ. כָּבָה הַשֶּׁמֶשׁ, שֶׁהֶחְשִׁיךְ אֶת אוֹרוֹ. יְהִי רָצוֹן שֶׁה' יָאִיר שְׁמוֹ עָלֶיךְ.</p>"],[9522012634,"<p>וְעוֹד אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, וַדַּאי אַתָּה הוּא הַכֹּל, שֶׁאָמַר <Nonesmall>[במדבר יב]</small> אִם יִהְיֶה נְבִיאֲכֶם וְגוֹ'. וְלָכֵן כְּשֶׁהִתְגַּלְּתָה הָאֵם הָעֶלְיוֹנָה לְךְ, אָמַרְתָּ <Nonesmall>[שמות ג]</small> אָסֻרָה נָּא וְאֶרְאֶה אֶת הַמַּרְאֶה הַגָּדֹל הַזֶּה מַדּוּעַ לֹא יִבְעַר הַסְּנֶה. מִשּׁוּם שֶׁהִיא רַחֲמִים, נֶאֱמַר בָּהּ לֹא יִבְעַר הַסְּנֶה.</p>\n<p>וַחֲמִשָּׁה אוֹרוֹת יֵשׁ לָהּ, שֶׁנִּקְרְאוּ קַרְנֵי הַחַמָּה, עַד הוֹד. וּמִשָּׁם וְעַד הוֹד הָיוּ מְאִירִים בְּךְ, רוֹעֶה הַנֶּאֱמָן. וְזֶהוּ וְנָתַן הוֹד לְמֹשֶׁה, לְהוֹדִיעַ שֶׁכֻּלָּם נִתְּנוּ לְךְ, אֲפִלּוּ עַד הוֹד. וְלָכֵן פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. וַחֲמִשָּׁה אֵלֶּה עוֹלִים לַחֲמִשִּׁים שַׁעֲרֵי בִינָה.</p>\n<p>וּבַחֲמִשָּׁה אֵלֶּה נֶאֱמַר שֶׁהֵם חֲמִשָּׁה אוֹר שֶׁל יוֹם הָרִאשׁוֹן, שֶׁהֵם כְּנֶגֶד חָמֵשׁ אֶצְבָּעוֹת שֶׁל הַיָּמִין נִרְאוּ לְךְ בַּסְּנֶה. מִשּׁוּם שֶׁאַתָּה עָתִיד לְהוֹצִיא אֶת זֶרַע אַבְרָהָם מֵהַגָּלוּת, שֶׁהוּא דַּרְגַּת <Nonesmall>[אברהם]</small> יָמִין. וּמִשָּׁם בִּינָה, הִיא רַחֲמִים גְּמוּרִים, הַיָּד הַגְּדוֹלָה. <Nonesmall>[אבל]</small> מִצַּד הַגְּבוּרָה, הַיָּד הַחֲזָקָה, חֲמִשָּׁה רָקִיעַ בְּיוֹם שֵׁנִי, כְּנֶגֶד חֲמֵשׁ אֶצְבְּעוֹת הַשְּׂמֹאל. אֲבָל מִצַּד דַּרְגָּתְךְ – <Nonesmall>[שמות יד]</small> וּבְנֵי יִשְׂרָאֵל יצְאִים בְּיָד רָמָה. שֶׁגּוּף וּשְׁתֵּי זְרוֹעוֹת וּשְׁתֵּי שׁוֹקַיִם כְּנֶגֶד חָמֵשׁ אֶצְבָּעוֹת, ה' ה' ה'. חָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין, וְחָמֵשׁ שֶׁל יַד שְׂמֹאל, וּשְׁתֵּי זְרוֹעוֹת וּשְׁתֵּי שׁוֹקַיִם וְגוּף, שֶׁהֵם חָמֵשׁ שֶׁעוֹלִים יָ\"הּ.</p>\n<p>אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לָאֵם הָעֶלְיוֹנָה, אֲבָל הַי\"ה הַזֶּה שָׂם לְי\"ה ה', מִשּׁוּם מַטֵּה הָאֱלֹהִים, שֶׁהוּא ו'. וְאָמַר, וַדַּאי כָּךְ הוּא. אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, הַמְּנוֹרָה הַקְּדוֹשָׁה, לְחַזֵּק אֶת דְּבָרֶיךְ, שֶׁמַּרְאֶה הוּא לְיָמִין, חָשׁוּב בַּמַּרְאָה, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[במדבר יב]</small> בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. וְתִמְצָא מָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה, שֶׁעוֹלֶה בְחֶשְׁבּוֹן אַבְרָהָם. אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, בַּהַתְחָלָה נִרְאָה לְךְ מַרְאֶה זֶה שֶׁנֶּאֱמַר בּוֹ בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, וּלְאַחַר שֶׁאָמַרְתָּ <Nonesmall>[שמות ג]</small> אָסֻרָה נָּא וְאֶרְאֶה אֶת הַמַּרְאֶה הַגָּדֹל הַזֶּה, שֶׁהִזְכִּיר בּוֹ חָמֵשׁ פְּעָמִים הַסְּנֶה – כָּעֵת הִתְגַּלֶּה לְךְ הַמַּרְאֶה הַזֶּה בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנֶה מִצְווֹתָיו, שֶׁהֵם בַּחֲמִשָּׁה חֻמְשֵׁי תוֹרָה. קָם רוֹעֶה הַנֶּאֱמָן וּנְשָׁקוֹ וּבֵרְכוֹ.</p>\n<p>אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, הַמַּרְאֶה הַזֶּה לִפְעָמִים הוּא בָּאוֹת ה' – הַמַּרְאֶה הַגָּדל, וְלִפְעָמִים הוּא בְּאוֹת ב' – בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, וְלִפְעָמִים בְּמֵ\"ם – <Nonesmall>[יחזקאל א]</small> מִמַּרְאֵה מָתְנָיו וּלְמַטָּה, וְלִפְעָמִים בְּכ' – כְּמַרְאֵה אָדָם עָלָיו, וְלִפְעָמִים בְּו' – <Nonesmall>[שמות כד]</small> וּמַרְאֵה כְּבוֹד ה', וְלִפְעָמִים לְמַרְאֶה. לֹא הָיָה לוֹ לִהְיוֹת תּוֹסֶפֶת אוֹת כְּלָל חוּץ מִב', מִבַּמַּרְאָה. אֶלָּא וַדַּאי הַמַּרְאֶה הַזֶּה כָּלוּל הוּא מֵעֶשֶׂר סְפִירוֹת, וְכָל אוֹת מַרְאָה סְפִירָה שֶׁלָּהּ, כְּמוֹ כְּמַרְאֵה בְּאוֹת כ' מַרְאֶה עַל כֶּתֶר, וְכָךְ שְׁאָר הָאוֹתִיּוֹת, כָּל אַחַת מַרְאָה עַל סְפִירָה שֶׁלָּהּ. וְלֹא צָרִיךְ כָּאן לְהַאֲרִיךְ, וּלְחָכָם בִּרְמִיזָה.</p>\n<p>וְכַמָּה חֶזְיוֹנוֹת יֵשׁ לָהּ, וְדִמְיוֹנוֹת וּמַרְאוֹת יֵשׁ לָהּ. וְהַכֹּל נוֹדָע בְּעֵין הַשֵּׂכֶל שֶׁל הַלֵּב, שֶׁנֶּאֱמַר בָּהּ, הַלֵּב יוֹדֵעַ הַלֵּב מֵבִין. וּמַה שֶּׁאָמַר <Nonesmall>[הושע יב]</small> וּבְיַד הַנְּבִיאִים אֲדַמֶּה, הַדִּמְיוֹן אֵינוֹ אֶלָּא בְּשֵׂכֶל הַלֵּב, וְלֹא בְדִמְיוֹן הָעַיִן. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ישעיה מ]</small> וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה. וְאֶל מִי תְּדַמְּיוּן אֵל. וְיֵשׁ חֶזְיוֹנוֹת כְּמוֹ הַחוֹזִים בַּכּוֹכָבִים, אֲבָל חֶזְיוֹן הַנְּבוּאָה הוּא כְּחֶזְיוֹן לַיְלָה.</p>\n<p>דִּמְיוֹנוֹת וְחֶזְיוֹנוֹת, כְּמוֹ הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר, וְהַמְדַמֶּה דָּבָר לְדָבָר. אֲבָל מַרְאֶה, שֶׁהוּא בְּעֵין הַשֵּׂכֶל, הוּא כְּאוֹר שֶׁמֵּאִיר בְּבַת עַיִן. שֶׁבַּת הִיא עַיִן שְׁחֹרָה. <Nonesmall>[שיר השירים א]</small> שְׁחוֹרָה אֲנִי וְנָאוָה, אוֹר שֶׁמֵּאִיר בָּהּ אוֹתוֹ לֹבֶן שֶׁלִּפְנִים. וּבַת עַיִן זוֹ הִיא נֵר מִצְוָה, אוֹר שֶׁמֵּאִיר לָהּ מִבִּפְנִים, וְתוֹרָה אוֹר.</p>\n<p>אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, הַיְנוּ מַה שֶּׁאָמַרְתִּי, שֶׁכָּעֵת בַּתּוֹרָה הִתְגַּלָּה לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, וְזֶהוּ יְהֹוָ\"ה. בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. בַּמַּרְאָה – אִמָּא הָעֶלְיוֹנָה. נוֹדָע לְךְ בְּדַעַת. בֶּן יָ\"הּ. בַּחֲלוֹם אֲדַבֶּר בּוֹ, אוֹת הֵ\"א אַחֲ רוֹנָה.</p>\n<p>חֲלוֹם – בְּסִתּוּם עֵינַיִם, וּמִשּׁוּם זֶה נִקְרֵאת אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. נְבוּאָה הִיא מַרְאֶה בִּפְתִיחַת עֵינַיִם. וּשְׁלֹשָׁה גְוָנִים בָּעַיִן כְּנֶגֶד שְׁלֹשֶׁת הָאָבוֹת, שֶׁבָּהֶם מְאִירָה בַּת יְחִידָה, שְׁתֵּי כַנְפֵי הָעַיִן, נֵצַח וְהוֹד. הַמַּרְאֶה לֹא נִרְאֶה אֶלָּא בָּהֶם, כְּשֶׁהֵם פְּתוּחִים, הוּא מַרְאֶה בְהָקִיץ. וּכְשֶׁהֵם סְגוּרִים, הוּא מַרְאֶה בַחֲלוֹם.</p>\n<p>אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לַקָּדוֹשׁ בָּרוּךְ הוּא, קוּם הַשְׁלֵם מִצְווֹת לְהָאִיר בָּהֶן מַרְאֶה איה\"ו עֶלְיוֹן בָּהֶם לַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה, י' הִיא בַּת עַיִן, <Nonesmall>[משלי י]</small> כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. ה\"ו שֶׁמֵּאִיר בָּהּ ה', שְׁלֹשֶׁת גּוֹנֵי הָעַיִן וּשְׁתֵּי כַנְפֵי הָעַיִן. חֲמִשָּׁה אוֹר מְאִירִים בָּהּ מִבַּחוּץ, ה' עֶלְיוֹנָה שֶׁהִיא אוֹר הַמַּרְאֶה.</p>"],[9522012635,"<p>אַרְבָּעִים יַכֶּנּוּ לֹא יסִיף וְגוֹ' <Nonesmall>[דברים כה]</small>. מִצְוָה זוֹ לְהַלְקוֹת הָרָשָׁע, שֶׁהוּא סָמָאֵל, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכּוֹתוֹ חֲמִשִּׁים מַכּוֹת, מִשּׁוּם שֶׁעָשָׂה עַצְמוֹ אֱלוֹהַּ. יָבא הַיִּחוּד שֶׁמְּיַחֲדִים בּוֹ יִשְׂרָאֵל בְּכָל יוֹם בְּכ\"ה אוֹתִיּוֹת, וְיַכֶּה בָהֶם אֶת מִי שֶׁשָּׂם עַצְמוֹ אֱלוֹהַּ. וְאֵינוֹ אֶלָּא עֶבֶד מְטֻנָּף. וְאֵלּוּ שֶׁסָּרְחוּ בְה', תִּקֵּן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא <Nonesmall>[להכות]</small> בְּיוֹ\"ד הֵ\"א וָא\"ו, שֶׁהֵם אַרְבָּעִים חָסֵר אַחַת. וּבְשֵׁם זֶה מַכֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא עֶשֶׂר מַכּוֹת אֶת הָאָדָם וְעֶשֶׂר לְחַוָּה, עֶשֶׂר לַנָּחָשׁ וְתֵשַׁע לָאָרֶץ, מִשּׁוּם שֶׁכֻּלָּם סָרְחוּ בָּאוֹת ה'. וְלָכֵן <Nonesmall>[בראשית ג]</small> כִּי עָשִׂיתָ זֹּאת.</p>"],[9522012636,"<p>כִּי יֵשְׁבוּ אַחִים יַחְדָּו וּמֵת אַחַד מֵהֶם וּבֵן אֵין לוֹ וְגוֹ', יְבָמָהּ יָבֹא עָלֶיהָ וּלְקָחָהּ לוֹ לְאִשָּׁה וְיִבְּמָהּ <Nonesmall>[דברים שם]</small>. מִצְוָה זוֹ לְיַבֵּם אֵשֶׁת אָח. שֶׁאֵשֶׁת אָח הִיא ד', וְעִם א\"ח הִיא אֶחָד. וְאִם חַס וְשָׁלוֹם שלִבּוֹ אֵינוֹ לְהָבִיא אָח עַל ד', שֶׁהִיא אִשְׁתּוֹ וּבַת זוּגוֹ שֶׁל א\"ח, הוּא עוֹשֶׂה פֵרוּד, וְנִכְנָס סָמָאֵל, אֵל אַחֵר, בָּאֶמְצַע, וְנֶאֱמַר בּוֹ <Nonesmall>[בראשית לח]</small> וְשִׁחֵת אַרְצָה לְבִלְתִּי וְגוֹ', שֶׁהִסְתַּלֵּק קוֹץ שֶׁל אוֹת ד' מִן אֶחָד. וּמִשּׁוּם זֶה, וְהָיָה אִם בָּא אֶל אֵשֶׁת אָחִיו וְשִׁחֵת אַרְצָה לְבִלְתִּי נְתָן זֶרַע לְאָחִיו. וְהַשְׁחָתַת הַזֶּרַע מָנְעָה מִמֶּנּוּ כַּמָּה בְרָכוֹת וּפֵרוּד הַיִּחוּד. וְלָכֵן וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה' וַיְמִתֵהוּ ה'.</p>\n<p>וְיִחוּד שֶׁל אָח עִם ד' בְּצַדִּיק. וּבֹעַז מִשּׁוּם שֶׁהִתְגַּבֵּר עַל יִצְרוֹ נִקְרָא צַדִּיק. וְזֶהוּ בּוֹעַ\"ז, בּ\"ו עֹ\"ז, תַּקִּיף בְּיִצְרוֹ. <Nonesmall>[איוב לג]</small> הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלוֹשׁ עִם גָּבֶר, וְזֶה יה\"ו שֶׁכְּלוּלוֹת שָׁלֹשׁ אוֹתִיּוֹת <Nonesmall>[אבות]</small> בְּצַדִּיק, לְיַבֵּם ה'.</p>\n<p>וּבִינָה – בֶּן יָ\"הּ, בִּגְלָלָהּ נֶאֱמַר <Nonesmall>[רות ד]</small> וְזֹּאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָּה וְעַל הַתְּמוּרָה לְקַיֵּם כָּל דָּבָר. כָּאן רוֹמֵז שִׁנּוּי הַשֵּׁם, וְזֶה מצפ\"ץ כָּאן, וְזֹּאת לְפָנִים בְּיִשְׂרָאֵל. וְזֶה שִׁנּוּי מָקוֹם, אֶהְיֶ\"ה, אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ. יה\"ו הוּא אֶהְיֶ\"ה, וְזֶה שִׁנּוּי מָקוֹם. שִׁנּוּי מַעֲשֶׂה, אֲדֹנָ\"י, א' אֶהְיֶ\"ה, י' יהוה, שְׁנֵיהֶם מִשְׁתַּנִּים בַּאדנָ\"י.</p>"],[9522012637,"<p>וְזֹאת הַתְּעוּדָה בְּיִשְׂרָאֵל. הַתְּעוּדָה – אֵם הָעֶלְיוֹנָה, <Nonesmall>[ישעיה ח]</small> צוֹר תְּעוּדָה חֲתוֹם תּוֹרָה בְּלִמֻּדָי. הוּא חוֹתַם הָעוֹלָם, חוֹתַם הַשָּׁמַיִם וְהָאָרֶץ. עַל הַתְּמוּרָה – שְׁכִינָה תַחְתּוֹנָה. בְּאֵיזֶה מָקוֹם הִתְחַבְּאָה? בָּעֶלֶם שֶׁלָּהּ, מְטַטְרוֹ\"ן, וַיְשַׁנֶּהָ, שָׁם הִיא מִשְׁתַּנָּה. וְאָדָם שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[שם מד]</small> כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת, <Nonesmall>[איוב יד]</small> מְשַׁנֶּה פָנָיו וַתְּשַׁלְּחֵהוּ.</p>\n<p>וְלָכֵן פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה, לֹא כְשֶׁאֲנִי נִכְתָּב אֲנִי נִקְרָא. בָּעוֹלָם הַזֶּה נִכְתָּב יהוה, וְנִקְרָא אֲדֹנָ\"י. וַהֲרֵי כָּתוּב <Nonesmall>[מלאכי ג]</small> אֲנִי ה' לֹא שָׁנִיתִי. בִּכְתִיבָה לֹא מִשְׁתַּנֶּה, אֲבָל בִּקְרִיאָה מִשְׁתַּנֶּה. שֶׁכְּתִיבָה שֶׁהוּא מְקוֹמוֹ, לֹא מִשְׁתַּנֶּה. בִּקְרִיאָה שֶׁהִיא מִחוּץ לִמְקוֹמוֹ, מִשְׁתַּנֶּה. <Nonesmall>[שמות כג]</small> הִשָּׁמֶר מִפָּנָיו וּשְׁמַע בְּקֹלוֹ אַל תַּמֵּר בּוֹ. מִשּׁוּם שֶׁשִּׁפְחָה שֶׁלּוֹ אֲדנָ\"י, שְׁמָהּ כְּשֵׁם הַמַּלְכָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ מִשְׁתַּנֶּה, מִשּׁוּם שֶׁהוּא נַעַר. בּוֹ סוֹד <Nonesmall>[רוח]</small> <Nonesmall>[איוב לג]</small> יָשׁוּב לִימֵי עֲלוּמָיו.</p>\n<p>אֲבָל שְׁכִינָה אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִשְׁתַּנָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מִשְׁתַּנֶּה אֵלֶיהָ, זֶהוּ שֶׁכָּתוּב אֲנִי ה' לֹא שָׁנִיתִי. אֲנִי – הַשְּׁכִינָה. ה' – הָעַמּוּד הָאֶמְצָעִי. שָׁלַף אִישׁ נַעֲלוֹ – זֶה סַנְדַּלְפוֹן, סַנְדָּל הוּא לַקָּדוֹשׁ בָּרוּךְ הוּא, וְנַעַל לַשְּׁכִינָה. אֲבָל תִּפְאֶרֶת, שֶׁכּוֹלֵל שֵׁשׁ סְפִירוֹת, הוּא גּוּף לַיהֹוָ\"ה. וּמַלְכוּת גּוּף לַשְּׁכִינָה, שֶׁהוּא אֲדנָי.</p>\n<p>וְנִגְּשָׁה יְבִמְתּוֹ אֵלָיו לְעֵינֵי הַזְּקֵנִים וְחָלְצָה נַעֲלוֹ מֵעַל רַגְלוֹ וְגוֹ'. מִצְוָה זוֹ לַחֲלֹץ, וְזוֹהִי חֲלִיצַת רוּחַ מֵאוֹתוֹ גּוּף, שֶׁצָּרִיךְ לִנְהֹג עִמּוֹ כְּאָח, וְאוֹתוֹ קֶשֶׁר הָאַחֲוָה שֶׁעִם אָחִיו מַתִּיר מִמֶּנּוּ, וְאוֹתָהּ רוּחַ הוֹלֶכֶת נָע וָנָד עַד שֶׁמּוֹצֵאת גּוֹאֵל. זֶהוּ שֶׁכָּתוּב <Nonesmall>[ויקרא כה]</small> אוֹ דדוֹ אוֹ בֶן דֹּדוֹ יִגְאָלֶנּוּ אוֹ מִשְּׁאֵר בְּשָׂרוֹ וְגוֹ'. וְאִם לֹא מָצָא – וְהִשִּׂיגָה יָדוֹ וְנִגְאָל. כְּאוֹרֵחַ שֶׁהוֹלֵךְ מִמָּקוֹם לְמָקוֹם, אוֹ כְּעֶבֶד שֶׁהוֹלֵךְ בְּשַׁלְשֶׁלֶת עַל צַוָּארוֹ עַד שֶׁמּוֹצֵא פִדְיוֹן מֵאֲדוֹנוֹ עַל חֶטְאוֹ. אוֹי לְמִי שֶׁלֹּא הִנִּיחַ בֵּן לִגְאֹל אוֹתוֹ.</p>\n<p>וְאֵלִיָּהוּ וְחַכְמֵי וּבַעֲלֵי הַיְשִׁיבוֹת, כָּאן רָמוּז אֵין חָבוּשׁ מַתִּיר עַצְמוֹ מִבֵּית הָאֲסוּרִים. שֶׁהוּא קָשׁוּר בְּקֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד, וְאָסוּר בִּתְפִלִּין שֶׁל רֹאשׁ, כְּשֶׁאֵין <Nonesmall>[לו]</small> בֵּן לִגְאֹל אוֹתוֹ מִצַּד שֶׁל בֶּן יָ\"הּ. בְּאוֹתוֹ קֶשֶׁר הוּא אָח חָבוּשׁ וְאָסוּר, שֶׁאֵין לוֹ רְשׁוּת לִגְאֹל אֶת עַצְמוֹ, שֶׁהוּא ד' עַצְמוֹ שֶׁל אָח. <Nonesmall>[בראשית ב]</small> עֶצֶם מֵעֲצָמַי קָרָא לָהּ אֵלָיו בַּקַּרְקֶפֶת שֶׁל תְּפִלִּין שֶׁל רֹאשׁ, וּבָשָׂר מִבְּשָׂרִי קָרָא לָהּ מִצַּד הַלֵּב.</p>"],[9522012638,"<p>וְלֹא לְחִנָּם אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל הָעוֹסֵק בַּתּוֹרָה וּבִגְמִילוּת חֲסָדִים וּמִתְפַּלֵּל עִם הַצִּבּוּר, מַעֲלֶה אֲנִי עָלָיו כְּאִלּוּ פְּדָאַנִי לִי וּלְבָנַי מִבֵּין הָעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וְכַמָּה בְּנֵי אָדָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְעוֹשִׂים גְּמִילוּת חֲסָדִים וּמִתְפַּלְלִים, וְלֹא נִגְאָל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וְיִשְׂרָאֵל. אֶלָּא שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה לְחַבֵּר אוֹתָהּ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וּגְמִילוּת חֶסֶד הֲרֵי פֵּרְשׁוּהָ, שֶׁהֲרֵי אֵין חָסִיד אֶלָּא הַמִּתְחַסֵּד עִם קוֹנוֹ, שֶׁכָּל הַמִּצְווֹת שֶׁעָשָׂה, לִגְאֹל בּוֹ שְׁכִינָתוֹ, וּבָזֶה עוֹשֶׂה חֶסֶד עִם הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מִי שֶׁגּוֹמֵל חֶסֶד עִם שְׁכִינָתוֹ, הוּא גּוֹמֵל עִם הַקָּדוֹשׁ בָּרוּךְ הוּא. מִשּׁוּם שֶׁכְּשֶׁחָטְאוּ יִשְׂרָאֵל וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה רוֹצֶה לְיַסְּרָם, הָאֵם הָיְתָה רוֹבֶצֶת עֲלֵיהֶם, עַד שֶׁיָּצְאוּ לְתַרְבּוּת רָעָה. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? גֵּרַשׁ אֶת בְּנֵי הַמֶּלֶךְ וְהַמַּלְכָּה, וְנִשְׁבַּע שֶׁלֹּא יַחֲזֹר לִמְקוֹמוֹ עַד שֶׁהַמַּלְכָּה תַּחֲזֹר לִמְקוֹמָהּ. וּמִי שֶׁחוֹזֵר בִּתְשׁוּבָה וְגוֹמֵל חֶסֶד עִם הַשְּׁכִינָה וּבְכָל הַתּוֹרָה וּבְמִצְווֹתֶיהָ, וְלֹא הִיא <Nonesmall>[הוא]</small> אֶלָּא לִגְאֹל אֶת הַשְּׁכִינָה, זֶה עוֹשֶׂה חֶסֶד עִם קוֹנוֹ, וּכְאִלּוּ גָאַל אוֹתוֹ וְאֶת שְׁכִינָתוֹ וְאֶת בָּנָיו.</p>\n<p>אָמַר אֵלִיָּהוּ וְכָל רָאשֵׁי הַיְשִׁיבוֹת, רוֹעֶה הַנֶּאֱמָן, אַתָּה הוּא הָאִישׁ הַזֶּה, אַתָּה הוּא בֵּן מֵהַמֶּלֶךְ וְהַמַּלְכָּה, שֶׁהִשְׁתַּדְּלוּתְךְ לַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כְמִי שֶׁעוֹשֶׂה חֶסֶד עִם קוֹנוֹ, אֶלָּא כְּמוֹ בֵן שֶׁמְּחֻיָּב לָשִׂים עַצְמוֹ וְכֹחוֹ לִפְדּוֹת אַבָּא וְאִמָּא וּמָסַר עַצְמוֹ לְמִיתָה עֲלֵיהֶם. שֶׁמִּי שֶׁאֵינוֹ בֶּן הַמֶּלֶךְ וְעוֹשֶׂה טוֹבָה עִם הַמֶּלֶךְ וְהַמַּלְכָּה, וַדַּאי זֶה נֶחְשָׁב שֶׁעוֹשֶׂה חֶסֶד עִם קוֹנוֹ.</p>\n<p>קָם רוֹעֶה הַנֶּאֱמָן וְהִשְׁתַּטַּח לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָכָה וְאָמַר, כֵּן יְהִי רָצוֹן שֶׁלּוֹ שֶׁיַּחֲשִׁיב אוֹתִי כְּבֵן, שֶׁהַמַּעֲשִׂים שֶׁלִּי לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ יִהְיוּ אֵלָיו כְּמוֹ בֵן שֶׁמִּשְׁתַּדֵּל בָּהֶם אַחַר אָבִיו וְאִמּוֹ, שֶׁאוֹהֵב אוֹתָם יוֹתֵר מֵעַצְמוֹ וְנַפְשׁוֹ, רוּחוֹ וְנִשְׁמָתוֹ, וְכָל מַה שֶּׁהָיָה לוֹ, הָיָה חוֹשֵׁב לָהֶם לְאַיִן לַעֲשׂוֹת בָּהֶם רָצוֹן שֶׁל אַבָּא וְאִמָּא וְלִפְדּוֹת אוֹתָם בָּהֶם. וְאַף עַל גַּב שֶׁיָּדַעְתִּי שֶׁהַכֹּל בִּרְשׁוּתוֹ, הָרַחֲמָן רוֹצֶה אֶת הַלֵּב. בְּאוֹתוֹ זְמַן בָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִשֵּׁק אוֹתוֹ, וְאָמַר, רוֹעֶה הַנֶּאֱמָן, וַדַּאי שֶׁאַתָּה הוּא בֵּן שֶׁלִּי וְשֶׁל הַשְּׁכִינָה. רַבָּנָן וּמַלְאָכִים נַשְּׁקוּ בֵן! קָמוּ כֻלָּם וְנָשְׁקוּ לוֹ, וְקִבְּלוּ אוֹתוֹ לְרַב וּמֶלֶךְ עֲלֵיהֶם.</p>"],[9522012639,"<p>וְהָיָה בְּהָנִיחַ ה' אֱלֹהֶיךְ וְגוֹ', תִּמְחֶה אֶת זֵכֶר עֲמָלֵק וְגוֹ' <Nonesmall>[דברים כה]</small>. מִצְוָה זוֹ לְהַכְרִית אֶת זַרְעוֹ שֶׁל עֲמָלֵק, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא נִשְׁבַּע שֶׁלֹּא יַחֲזֹר לְכִסְאוֹ עַד שֶׁיִּקַּח נְקָמָה מִמֶּנּוּ. פָּתַח רוֹעֶה הַנֶּאֱמָן וְאָמַר, וַדַּאי מִשּׁוּם זֶה הָיוּ הוֹלְכִים בַּמִּדְבָּר וְעַל הַיָּם, וְלֹא יִכָּנְסוּ בְאֶרֶץ יִשְׂרָאֵל, עַד שֶׁיִּטֹּל נְקָמָה מֵעֲמָלֵק.</p>\n<p>עָמָלֵק מַהוּ לְמַעְלָה? שֶׁהֲרֵי רָאִינוּ שֶׁבִּלְעָם וּבָלָק הָיוּ נִשְׁמוֹתֵיהֶם מִשָּׁם, וּמִשּׁוּם זֶה שָׂנְאוּ אֶת יִשְׂרָאֵל יוֹתֵר מִכָּל אֻמָּה וְלָשׁוֹן, וְלָכֵן עֲמָלֵק רָשׁוּם בִּשְׁמָם – ע\"ם מִבִּלְעָם, ל\"ק מִבָּלָק. וְזָכָר וּנְקֵבָה הֵם עֲמָלֵקִים, וַעֲלֵיהֶם נֶאֱמַר <Nonesmall>[במדבר כג]</small> לֹא הִבִּיט אָוֶן בְּיַעֲקֹב וְלֹא רָאָה עָמָל בְּיִשְׂרָאֵל.</p>\n<p>כְּמוֹ שֶׁיֵּשׁ בְּיִשְׂרָאֵל אַרְבַּע פָּנִים: יַעֲקֹב, יִשְׂרָאֵל, רָחֵל, לֵאָה. יִשְׂרָאֵל עִם לֵאָה, יַעֲקֹב עִם רָחֵל, כְּנֶגֶד <Nonesmall>[יחזקאל א]</small> וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן – כָּךְ יֵשׁ אַרְבַּע פָּנִים לַעֲמָלֵק: קֶסֶם, וְנַחַשׁ, עָמָל, וָאָוֶן. עָמָל רָשׁוּם בַּעֲמָלֵק, וְהָמָן שֶׁהָיָה מִצַּד עֲמָלֵק – <Nonesmall>[תהלים ז]</small> יָשׁוּב עֲמָלוֹ בְרֹאשׁוֹ. וְכָל אַלּוּפֵי עֵשָׂו מֵעֲמָלֵק הָיוּ. וּלְמַעְלָה עֲמָלֵק, סָמָאֵל. עָמָל, נַחַשׁ, אָוֶן, וּמִרְמָה. שֶׁמְּפַתֶּה אֶת הָאָדָם לַחֲטֹא לַקָּדוֹשׁ בָּרוּךְ הוּא. קֶסֶ\"ם – ק' מֵעֲמָלֵק, ס\"ם מִסָּמָאֵל. נַחַ\"שׁ, אֵ\"ל מִסָּמָאֵל <Nonesmall>[כאן חסר]</small>.</p>"],[9522012640,"<p>עָלָיו נֶאֱמַר לְאַבְרָהָם, <Nonesmall>[בראשית יב]</small> לֶךְ לְךְ מֵאַרְצְךְ וּמִמּוֹלַדְתְּךְ וּמִבֵּית אָבִיךְ. בֵּית מוֹלָד שֶׁלְּךְ מִבָּתֵּי הַלְּבָנָה הַלָּלוּ, אוֹ בָּתֵּי שַׁבְּתַאי, אוֹ בָּתֵּי מַאְדִּים. שֶׁעַל בָּתֵּי מַאְדִּים וּבָתֵּי שַׁבְּתַאי וּלְבָנָה נֶאֱמַר, אֵין מַתְחִילִים בְּשֵׁנִי וּרְבִיעִי, <Nonesmall>[ואין מתחילין בשני ואין מסימים ברביעי]</small> שֶׁמַּאְדִּים אֹדֶם הַחַמָּה, גֵּיהִנֹּם אֵם שֶׁל עֵשָׂו, שֶׁנּוֹלְדָה בַּיּוֹם הַשֵּׁנִי. וְהַלְּבָנָה הִיא טוֹב וָרָע. טוֹב בְּמִלּוּאָהּ, וָרָע בְּחֶ סְרוֹנָהּ.</p>\n<p>וּמִשּׁוּם שֶׁהִיא כְּלוּלָה מִטּוֹב וָרָע, מוֹנִים בָּהּ יִשְׂרָאֵל וּמוֹנִים בָּהּ בְּנֵי יִשְׁמָעֵאל. וּכְשֶׁלּוֹקָה בְמִלּוּאָהּ, סִימָן לֹא טוֹב לְיִשְׂרָאֵל. וּכְשֶׁלּוֹקָה בְחֶסְרוֹנָהּ, סִימָן רָע לַיִּשְׁמְעֵאלִים. וּבָזֶה <Nonesmall>[ישעיה כט]</small> וְאָבְדָה חָכְמַת חֲכָמָיו, חָכְמָה שֶׁל יִשְׁמְעֵאלִים. וּבִינַת נְבוֹנִים תִּסְתַּתָּר, שֶׁהֵם לֹא יוֹדְעִים בִּבְרִיאָתָם, אֶלָּא בְּשִׁמּוּשָׁם, כְּפִי שִׁנּוּי הָעוֹלָם בַּהֲלִיכָתָם וּבְשִׁמּוּשָׁם. וְהַלְּבָנָה נִבְרְאָה בַּיּוֹם הָרְבִיעִי, וּבְחֶסְרוֹנָהּ עֲנִיּוּת, נִבְרָאָה לִילִית, שַׁבְּתַאי, שֶׁהוּא רָעָב וְצִמָּאוֹן וְלִקּוּי הַמְּאוֹרוֹת. עָלֶיהָ נֶאֱמַר יְהִי מְאֹרֹת חָסֵר. <Nonesmall>[משלי ג]</small> מְאֵרַת ה' בְּבֵית רָשָׁע. <Nonesmall>[קהלת ז]</small> וְחוֹטֵא יִלָּכֶד בָּהּ, בְּבֵית הַסֹּהַר שֶׁלָּהּ, וְצַדִּיק יִמָּלֵט מִמֶּנָּה.</p>\n<p>וְיִשִׁ כּוֹכָב אַחֵר, נְקֻדָּה קְטַנָּה, נָקוּד עַל שִׁפְחָה <Nonesmall>[הלבנה]</small>, שֶׁהוּא מְאֹרֹת, וְזֶה חוֹלָם, בַּת מֶלֶךְ, שַׁבָּת הַמַּלְכָּה. שֶׁשִּׁלְטוֹן שְׁנֵיהֶם בַּיּוֹם הַשְּׁבִיעִי, שֶׁנֶּאֱמַר בּוֹ <Nonesmall>[דברים ה]</small> לְמַעַן יָנוּחַ עַבְדְּךְ וַאֲמָתְךְ. שֶׁסֵּדֶר בְּרִיאָתָם לֹא כְסֵדֶר שִׁמּוּשָׁם. וְלָכֵן חַמָּ\"ה וּמַאְדִּי\"ם, אֲדֻמִּים שֶׁל הַגֵּיהִנֹּם, נִבְרְאוּ בְּיוֹם שֵׁנִי. לְבָנָה שַׁבְּתַאי נִבְרְאוּ בְּיוֹם רְבִיעִי, רָעָב וְחֹשֶׁךְ. וְלָכֵן אֵין מַתְחִילִים בְּשֵׁנִי וּרְבִיעִי, מִשּׁוּם שֶׁגֵּיהִנֹּם נִבְרָא בְּיוֹם שֵׁנִי, וְלִקּוּי מְאוֹרוֹת בְּיוֹם רְבִיעִי.</p>\n<p>כֹּכָ\"ב, עָלָיו נֶאֱמַר <Nonesmall>[במדבר כד]</small> דָּרַךְ כּוֹכָב מִיַּעֲקֹב. שֶׁדַּרְגָּתוֹ בְּיוֹם שְׁלִישִׁי, וּבוֹ <Nonesmall>[שמות יט]</small> וַיְהִי בַיּוֹם הַשְּׁלִישִׁי בִּהְיוֹת הַבֹּקֶר, שֶׁבּוֹ יָרַד הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת אֶת הַתּוֹרָה לְיִשְׂרָאֵל, בַּת יְחִידָה, לִהְיוֹת עִמּוֹ שַׁבָּת הַמַּלְכָּה, שֶׁהוּא יוֹם שְׁלִישִׁי, כּוֹלֵל שְׁלֹשֶׁת עַנְפֵי הָאָבוֹת, ש', הַבַּת <Nonesmall>[המלכה]</small> הַיְחִידָה, שֶׁשִּׁלְטוֹנָהּ בְּלֵיל שַׁבָּת, בּוֹ נַעֲשֵׂית שַׁבָּת.</p>\n<p>וְלָכֵן חוֹלְקִים חַכְמֵי הַמִּשְׁנָה עַל מַתַּן תּוֹרָה, בַּת יְחִידָה. זֶה אָמַר בַּשְּׁלִישִׁי נִתְּנָה תוֹרָה, וְזֶה אָמַר בַּשְּׁבִיעִי נִתְּנָה תוֹרָה. וְהִיא בַּת יְחִידָה שֶׁאוֹחֶזֶת בָּעַמּוּד הָאֶמְצָעִי, שְׁלִישִׁי לָאָבוֹת. וּבְצַדִּיק, שְׁבִיעִית לוֹ בַּת יְחִידָה. וּכְשֶׁהִיא עֲטָרָה עַל רֹאשׁוֹ, נִקְרָא בוֹ שְׁבִיעִי, שֶׁהוּא הָיָה שִׁשִּׁי, שֶׁכּוֹכָבוֹ צֶדֶק, וּבַת יְחִידָה שַׁבָּת הַמַּלְכָּה נִקְרֵאת צֶדֶק. וּמִשּׁוּם זֶה תּוֹרָה אֲחוּזָה בּוֹ בֵּין יוֹם ג' וְז'.</p>\n<p>וְהוּא כ\"ב מִן כּוֹכָ\"ב, כ\"ו – <Nonesmall>[תהלים פד]</small> כִּי שֶׁמֶשׁ וּמָגֵן יְהֹוָ\"ה צְבָאוֹת, שְׁכִינָה מַלְכוּת הַקֹּדֶשׁ, <Nonesmall>[בראשית מח]</small> בְּךְ יְבָרֵךְ יִשְׂרָאֵל, כ\"ב אוֹתִיּוֹת הַתּוֹרָה. כּוֹכָב כָּלוּל מִשָּׁלֹשׁ דְּרָגוֹת: כ' כֶּתֶר, ב' בִּינָה, יְהֹוָ\"ה כּוֹלֵל שְׁנֵיהֶם – חָכְמָה. וְכוֹכָ\"ב כּוֹלֵל הַכֹּל, דַּרְגַּת הָעַמּוּד הָאֶמְצָעִי וּשְׁכִינָה.</p>"],[9522012641,"<p>וְהַשְּׁכִינָה הִיא לְבָנָה, לִבּוּן הַהֲלָכָה, רַחֲמִים, בְּצַד הַחֶסֶד. וְנִקְרֵאת חַמָּה, בָּרָה כַּחַמָּה, מִצַּד הַגְּבוּרָה, פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. הַלְּבָנָה אֲפֵלָה, מִעוּט הַלְּבָנָה, שִׁפְחָה שֶׁלָּהּ גֵּיהִנֹּם, חַמָּה רָעָה. שִׁפְחָה שֶׁלָּהּ שַׁבְּתַאי, לִקּוּי הַמְּאוֹרוֹת, חִלּוּל שַׁבָּת. שִׁפְחָתָהּ, שֶׁמַּחֲזִירָה עֹרֶף לִגְבִרְתָּהּ בְּכָל יוֹם וָיוֹם, וּמִתְגַּבֶּרֶת עָלֶיהָ בַּחֲטָאֵי יִשְׂרָאֵל בָּנֶיהָ. זֶהוּ שֶׁכָּתוּב <Nonesmall>[משלי ל]</small> וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. שֶׁשִּׁלְטוֹן הַשִּׁפְחָה לֹא הָיָה אֶלָּא בַּיּוֹם הַשֵּׁנִי בַּגֵּיהִנֹּם. וּבָרְבִיעִי בְּלִקּוּי הַמְּאוֹרוֹת, וְחָזְרָה לִשְׁלֹט בְּכָל יוֹם וָיוֹם.</p>\n<p>וּבַת מֶלֶךְ אֲסוּרָה בִסְרָכוֹת, בְּבֵית הַסֹּהַר, בְּגָלוּתָהּ. וְהִיא קֵן שֶׁל סָמָאֵל בֵּין הַכּוֹכָבִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִשְׁבַּע, <Nonesmall>[עובדיה א]</small> אִם תַּגְבִּיהַּ כַּנֶּשֶׁר וְאִם בֵּין כּוֹכָבִים שִׂים קִנֶּךְ מִשָּׁם אוֹרִידְךְ נְאֻם ה'. וּשְׁכִינָה נֹגַהּ, וְנֹגַהּ לָאֵשׁ <Nonesmall>[יחזקאל א]</small>, וּמִכָּאן קָרְאוּ לְבֵית הַכְּנֶסֶת אֵשׁ נֹגַהּ.</p>\n<p>אֵשׁ מַאְדִּים לְשׁוֹן שֶׁל אֹדֶם, <Nonesmall>[שמות כח]</small> טוּר אֹדֶם פִּטְדָה. נֹגַהּ, אֵשׁ לְבָנָה. וּשְׁנֵיהֶם פְּנֵי חַמָּה וּפְנֵי לְבָנָה. נֵצַח וְהוֹד, אוֹתָם שֶׁלָּקְחוּ לֹבֶן מֵחֶסֶד וְאֹדֶם מִגְּבוּרָה, אַהֲרֹן וְדָוִד מִשָּׁם הָיוּ. אֶחָד לָקַח רַחֲמִים, וְאֶחָד לָקַח דִּין. דָּוִד מִצַּד הַשְּׂמֹאל, <Nonesmall>[שמואל א טז]</small> וְהוּא אַדְמוֹנִי. אַהֲרֹן אִישׁ חֶסֶד. וּשְׁנֵיהֶם נְבִיאֵי אֱמֶת מִשָּׁם. פְּנֵי מֹשֶׁה הָיוּ מְאִירִים בִּנְבוּאָה שֶׁל בִּינָה, הִיא חַמָּה <Nonesmall>[אמא]</small> עֶלְיוֹנָה, מִשָּׁם נְבוּאָתוֹ.</p>\n<p>בָּהֶם עֵשָׂו הָרָשָׁע עֶבֶד אֱדוֹם, וּנְקֵבָה שֶׁלּוֹ מַאְדִּים, הִיא שְׁפִיכוּת דָּמִים שֶׁל יִשְׂרָאֵל, וְגָרְמָה שֶׁבַּמַּלְכָּה הִתְקַיֵּם, <Nonesmall>[איכה א]</small> נְתָנַנִי ה' בִּידֵי לֹא אוּכַל קוּם. <Nonesmall>[שם]</small> נְתָנַנִי שּמֵמָה כָּל הַיּוֹם דָּוָה. הוֹד הָפַךְ לְדָוָה, שֶׁנֵּצַח וְהוֹד כְּנֶגְדָּם. יָכִין וּבעַז. שְׁתֵּיהֶן אֲשֶׁר הַבַּיִת נִשְׁעָן עֲלֵיהֶם. שֶׁבֵּית הַכְּנֶסֶת נִקְרָא עַל שְׁמָם אֵשׁ נֹגַהּ כְּמוֹ שֶׁאָמַ רְנוּ.</p>\n<p>וְשִׁפְחָה רָעָה הִיא קְבוּרָה, וּבָהּ אֲסוּרָה לַגְּבֶרֶת. וְהִיא שַׁבְּתַאי, קָרָה וִיבֵשָׁה, בִּקְבוּרַת הֶעָפָר, וְהִיא מָוֶת שֶׁל עֲנִיּוּת שֶׁל הַתּוֹרָה, וְהִיא קְבוּרַת עָנִי, מְכֻסֶּה בָּהּ בְּשִׁבְעָה מִינֵי מְדוֹרוֹת, שֶׁהִיא כְּלוּלָה מִשִּׁבְעָה כּוֹכָבִים, כְּמוֹ שֶׁשַּׁבָּת הַמַּלְכָּה כְּלוּלָה מִשֶּׁבַע. וְהֵם שִׁבְעָה כּוֹכָבִים מִצַּד שֶׁל הַגְּבוּרָה <Nonesmall>[הגבירה]</small>, <Nonesmall>[בראשית מא]</small> שֶׁבַע שְׁנֵי הַשָּׂבָע. מִצַּד שֶׁל שִׁפְחָה, שֶׁבַע שְׁנֵי הָרָעָב. שֶׁעֲלֵיהֶם אָמַר הַנָּבִיא, <Nonesmall>[עמוס ח]</small> לֹא רָעָב לַלֶּחֶם וְלֹא צָמָא לַמַּיִם כִּי אִם לִשְׁמֹעַ אֶת דִּבְרֵי ה'.</p>\n<p>גְּבִרְתָּהּ גַּן. שִׁפְחָה אַשְׁפָּה מְטֻנֶּפֶת, מִצַּד שֶׁל עֵרֶב רַב אַשְׁפָּה מְעֹרֶבֶת בַּגָּן לְגַדֵּל זְרָעִים, מִצַּד שֶׁל עֵץ הַדַּעַת טוֹב וָרָע. מִצַּד שֶׁל עֲבוֹדָה זָרָה נִקְרֵאת שַׁבְּתַאי, לִילִית, אַשְׁפָּה מְטֻנֶּפֶת, מִשּׁוּם שֶׁצּוֹאָה מְעֹרֶבֶת מִכָּל מִינֵי טִנּוּף וְשֶׁרֶץ, שֶׁזּוֹרְקִים בָּהּ כְּלָבִים מֵתִים וַחֲמוֹרִים מֵתִים. בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל קְבוּרִים בָּהּ. עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם כְּלָבִים מֵתִים, קְבוּרִים בָּהּ. וְהִיא קֶבֶר שֶׁל עֲבוֹדָה זָרָה שֶׁקּוֹבְרִים בָּהּ עֲרֵלִים, שֶׁהֵם כְּלָבִים מֵתִים, שֶׁקֶץ וְרֵיחַ רַע, מְטֻנָּף, מְסֹרָח, מִשִּׁפְחָה רָעָה הִיא סִרְכָה, שֶׁאֲחוּזָה בְּעֵרֶב רַב מְעֹרָבִים בְּיִשְׂרָאֵל. וַאֲחוּזָה בְּעֶצֶם וּבָשָׂר, שֶׁהֵם בְּנֵי עֵשָׂו וְיִשְׁמָעֵאל, עֶצֶם מֵת וּבָשָׂר טָמֵא, בָּשָׂר בַּשָּׂדֶה טְרֵפָה, שֶׁעָלֶיהָ נֶאֱמַר <Nonesmall>[שמות כב]</small> לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ.</p>\n<p>וּכְמוֹ שֶׁיֵּשׁ שְׁנֵים עָשָׂר מַזָּלוֹת מִצַּד שֶׁל הַטּוֹב, כָּךְ יֵשׁ שְׁנֵים עָשָׂר מַזָּלוֹת מִצַּד הָרַע. זֶהוּ שֶׁכָּתוּב <Nonesmall>[בראשית כה]</small> שְׁנֵים עָשָׂר נְשִׂיאִם לְאֻמֹּתָם. שֶׁזֶּה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים <Nonesmall>[קהלת ז]</small>, וְהָרְשָׁעִים הֵם אֲבִי אֲבוֹת הַטֻּמְאָה, שֶׁהֵם טְמֵא מֵת וְשֶׁרֶץ, שֶׁמְּטַמֵּא אֶת הָאָדָם מֵאֲוִירוֹ וּמִתּוֹכוֹ וּמִגַּבּוֹ. וַאֲפִלּוּ תּוֹךְ תּוֹכוֹ שֶׁל הַכֹּהֵן נִטְמָא בָהֶם. וְלָכֵן <Nonesmall>[ויקרא כא]</small> [ו] עַל כָּל נַפְשּת מֵת לֹא יָבא. שֶׁרָשָׁע קָרוּי מֵת. וּהַמְּנוֹרָה הַקְּדוֹשָׁה, לְאָבִיו וּלְאִמּוֹ לֹא יִטַּמָּא.</p>"],[9522012642,"<p>כָּאן מָצָאנוּ רְפוּאָה אֵלַי, שֶׁנֶּאֱמַר בִּי <Nonesmall>[ישעיה נג]</small> וַיִּתֵּן אֶת רְשָׁעִים קִבְרוֹ. אַחַר שֶׁקְּבוּרָה זוֹ מִשּׁוּם אַבָּא וְאִמָּא, שֶׁהֵם בַּגָּלוּת עִם יִשְׂרָאֵל, הִתְקַיֵּם בִּי הַכָּתוּב וְלֹא יִטַּמָּא. אֵלִיָּהוּ, לֹא תִתְעַכֵּב מִלָּרֶדֶת, שֶׁאַף עַל גַּב שֶׁאַתָּה כֹּהֵן, לְאָבִיו וּלְאִמּוֹ <Nonesmall>[לא]</small> יִטַּמָּא. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בַגָּלוּת, שֶׁהִיא קְבוּרָה לָהֶם, וַאֲנִי קָבוּר בֵּינֵיהֶם. בִּשְׁבוּעָה עָלֶיךְ בְּשֵׁם ה' חַי וְקַיָּם, אַל תִּתְעַכֵּב מִלָּרֶדֶת. מַלְאָכִים קְדוֹשִׁים בַּעֲלֵי כְנָפַיִם, בִּשְׁבוּעָה עֲלֵיכֶם, קְחוּ שְׁבוּעָה זוֹ וְהַעֲלוּהָ עַל כַּנְפֵיכֶם, שְׁבוּעַת ה' בְּחַ\"י צַדִּיק וְקַיָּם עַמּוּד הָאֶמְצָעִי, קְחוּ שְׁבוּעָה זוֹ וְהַעֲלוּ אוֹתָהּ עַל כַּנְפֵיכֶם בַּמַּלְכָּה, בַּכָּבוֹד שֶׁלָּהּ, לַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מַלְאָכִים עֶלְיוֹנִים, שְׁלִיחֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיָּמִין, וּמַלְאָכִים שְׁלוּחָיו מִשְּׂמֹאל, וּמַלְאָכִים שֶׁל אַבָּא וְאִמָּא, יִהְיוּ מַסְתִּירִים לָהּ לְמַעְלָה וּלְמַטָּה, וּמְכַסִּים אוֹתָהּ בָּאוֹת ו' בְּשֵׁשׁ כְּנָפָיו, שֶׁבּוֹ נֶאֱמַר <Nonesmall>[ישעיה ו]</small> שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם וְגוֹ'. שֶׁשְּׁבוּעָה שֶׁלּוֹ, שֶׁהִיא ה', רְבִיעִית. וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו שֶׁלָּהּ, וּבִשְׁתַּיִם מְעוֹפְפִים אוֹתָהּ.</p>\n<p>וְאַתָּה אֵלִיָּהוּ, שֶׁעָלִיתָ לְמַעְלָה לְעִלַּת הָעִלּוֹת, וְהוּא טוֹעֵן אוֹתְךְ מִכָּל טוּב, רֵד אֵלֶיהָ, וְתִהְיֶה כְרוּב תַּחְתֶּיהָ לְהוֹרִידָהּ בְּךְ מְלֵאָה כָּל טוּב. וּמַלְאָכִים שֶׁל אַבָּא וְאִמָּא, שֶׁהֵם יָ\"הּ, <Nonesmall>[הסתירו אותה]</small> סוֹבְבוּ אוֹתְךְ בִּירִידָתָהּ. וּמַלְאָכִים שֶׁל בַּעְלָהּ, בֶּן אַבָּא וְאִמָּא, ו', כִּסּוּ אוֹתָהּ, וּמְעוֹפְפִים אוֹתָהּ בְּשֵׁשׁ כְּנָפַיִם – אב\"ג ית\"ץ, וּבְל\"ו שֶׁתְּלוּיִים מֵהֶם כְּחֶשְׁבּוֹן ל\"ו. וַדַּאי זֶה שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ. וְיוֹרֶדֶת ה' <Nonesmall>[י\"ה]</small> שֶׁלּוֹ, טְמִירָה מְכֻסָּה בָהֶם. וּמַלְאָכִים שֶׁהֵם שֶׁל צַדִּיק חַ\"י הָעוֹלָמִים, הִסְמִיכוּ אוֹתָהּ עֲלֵיכֶם כְּמוֹ הַחַיּוֹת שֶׁסּוֹמְכוֹת אֶת הַכִּסֵּא.</p>\n<p>שֶׁאַף עַל גַּב שֶׁהֵ\"א שֶׁל אֲצִילוּת שֶׁל שֵׁם שֶׁל יהו\"ה הִיא תּוֹמֶכֶת לְכֻלָּם, אֵין לָכֶם לִפְרֹחַ לְמַעְלָה וְלָרֶדֶת לְמַטָּה חוּץ מִמֶּנָּה, כְּאֵיבְרֵי הַגּוּף שֶׁאֵין לָהֶם תְּנוּעָה, חוּץ מֵהַנְּשָׁמָה, שֶׁהָאֵיבָרִים שֶׁיֵּשׁ לָהּ הִתְפַּשְּׁטוּ עֲלֵיכֶם לִתְמֹךְ אֶתְכֶם בָּהֶם. שֶׁכָּךְ הִיא ה', כְּמוֹ יָם. אִם יֵשׁ לָהּ כֵּלִים, מִתְמַלְּאִים מִמֶּנָּה וּמִתְפַּשְּׁטִים בָּהֶם כְּמוֹ נְחָלִים שֶׁמִּתְפַּשְּׁטִים מֵהַיָּם עַל הָאָרֶץ. וְאִם לֹא, הִיא ה' בְּעֶצֶם יְחִידִי, בְּלִי הִתְפַּשְּׁטוּת הַנְּחָלִים.</p>\n<p>כָּךְ כְּלֵי הַשְּׁכִינָה, הֵם מַלְאָכִים קְדוֹשִׁים לְמַעְלָה, וְיִשְׂרָאֵל לְמַטָּה, אִם יֵשׁ בָּהֶם בַּעֲלֵי מִדּוֹת, בַּעֲלֵי חֶסֶד חֲסִידִים, גִּבּוֹרִים בַּעֲלֵי תוֹרָה נְבִיאִים וּכְתוּבִים, צַדִּיקִים אַנְשֵׁי מַלְכוּת, שֶׁנֶּאֱמַר בָּהֶם <Nonesmall>[דניאל א]</small> וַאֲשֶׁר כֹּחַ בָּהֶם לַעֲמֹד בְּהֵיכַל הַמֶּלֶךְ, בַּעֲמִידַת הַתְּפִלָּה, בְּהֵיכַל הַמֶּלֶךְ אֲדנָ\"י, מֶלֶךְ שֶׁלָּהּ יְהֹוָ\"ה. וְהֵם חֲכָמִים וּנְבוֹנִים רָאשֵׁי יִשְׂרָאֵל, וְלֹא רָאשֵׁי עֵרֶב רַב שֶׁנֶּאֱמַר בָּהֶם <Nonesmall>[איכה א]</small> הָיוּ צָרֶיהָ לְרֹאשׁ. הִיא הִתְפַּשְּׁטָה עֲלֵיהֶם בְּעֶשֶׂר סְפִירוֹת שֶׁלָּהּ. בְּאוֹתוֹ זְמַן יָרַד עִלַּת הָעִלּוֹת בְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, לָרֶדֶת עֲלֵיהֶם וּלְהָקִים שְׁכִינָה עֲלֵיהֶם.</p>\n<p>וּבִזְמַן שֶׁל <Nonesmall>[שמות ב]</small> וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ, הִיא אוֹמֶרֶת: <Nonesmall>[שיר השירים א]</small> שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה, מְעֻטֶּפֶת בְּעַצְמָהּ שֶׁלֹּא הִתְפַּשְּׁטָה עֲלֵיהֶם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא צוֹוֵחַ עָלָיו וְאוֹמֵר: אֵיכָה יָשְׁבָה בָדָד.</p>\n<p>בֵּין כָּךְ קָם הַמְּנוֹרָה הַקְּדוֹשָׁה וְאָמַר, רִבּוֹן הָעוֹלָם, הֲרֵי כָּאן רוֹעֶה הַנֶּאֱמָן, שֶׁבּוֹ נֶאֱמַר <Nonesmall>[במדבר יב]</small> וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד, עַד כָּעֵת <Nonesmall>[שמות ב]</small> וַיַּרְא כִּי אֵין אִישׁ. הֲרֵי כָּאן וְהָאִישׁ מֹשֶׁה, שֶׁשָּׁקוּל לְשִׁשִּׁים רִבּוֹא שֶׁל יִשְׂרָאֵל, וּבוֹ <Nonesmall>[תהלים לג]</small> מִמְּכוֹן שִׁבְתּוֹ הִשְׁגִּיחַ. שֶׁבּוֹ נֶאֱמַר עַל דּוֹר הַגָּלוּת הָאַחֲרוֹנָה, <Nonesmall>[ישעיה נג]</small> וַה' הִפְגִּיעַ בּוֹ אֵת עֲוֹן כֻּלָּנוּ. וְהוּא כָּלוּל בְּעֶשֶׂר מִדּוֹת, שֶׁבִּגְלָלָן אָמַרְתָּ <Nonesmall>[בראשית יח]</small> לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה. רֵד עָלָיו לְהַשְׁגִּיחַ עַל הָעוֹלָם וְקַיֵּם דְּבָרֶיךְ, שֶׁאַתָּה אֱמֶת וְכָל דְּבָרֶיךְ אֱמֶת.</p>\n<p>שֶׁהוּא גָּמַל חֶסֶד עִם הַשְּׁכִינָה, וְקָשַׁר שִׁפְחָתָהּ בִּגְבוּרָה, לִהְיוֹת שִׁפְחָה אֲסוּרָה תַּחַת גְּבִרְתָּהּ בְּקֶשֶׁר שֶׁל תְּפִלִּין, וְהִשְׁתַּדֵּל בִּגְלָלָהּ בְּתוֹרַת אֱמֶת, <Nonesmall>[מלאכי ב]</small> תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ. וְהִשְׁתַּדֵּל בָּהּ בַּנְּבִיאִים וּבַכְּתוּבִים. בַּנְּבִיאִים בְּכַמָּה נֶחָמוֹת. בַּכְּתוּבִים בַּעֲשָׂרָה מִינֵי תְהִלִּים. בְּצַדִּיק בִּשְׁמוֹנֶה עֶשְׂרֵה בִּרְכוֹת הַתְּפִלָּה.</p>\n<p>וּבַעָלֵי הַמִּשְׁנָה לֹא נוֹדְעוּ לָרוֹעֶה הַנֶּאֱמָן. אֵלִיָּהוּ, בִּשְׁבוּעָה עָלֶיךְ בְּשֵׁם יְהָו\"ה וּבִשְׁמוֹ הַמְפֹרָשׁ, גַּלֵּה אוֹתוֹ לְכָל רָאשֵׁי בַּעֲלֵי הַמִּשְׁנָה שֶׁיֵּדְעוּ אוֹתוֹ וְלֹא יִתְחַלֵּל יוֹתֵר, שֶׁבּוֹ נֶאֱמַר <Nonesmall>[לגבי העולם]</small> <Nonesmall>[ישעיה נג]</small> וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ. אֵין לְךְ צֹרֶךְ לָקַחַת רְשׁוּת, שֶׁהֲרֵי אֲנִי שָׁלִיחַ שֶׁל רִבּוֹן הָעוֹלָם, וְיָדַעְתִּי שֶׁאִם אַתָּה עוֹשֶׂה כֵּן, שֶׁיּוֹדֶה לְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָיו, וְיַעֲלוּ בָנֶיךְ בִּגְלָלוֹ, מַעְלָה וּמַטָּה. וְלֹא תִתְעַכֵּב לַעֲשׂוֹת לֹא שָׁבוּעַ, וְלֹא חֹדֶשׁ, וְלֹא שָׁנָה, אֶלָּא מִיָּד.</p>"]]});
